%         &\tgap( \bx^T) = \sum_{i=1}^n \max_{x_i\in \times \Delta^{d_i}} u_i(x_i, \bx^T_{-i}) - u_i(\bx^T)\\
%         =&\sum_{i=1}^n \max_{x_i\in\Delta^{d_i}} \sum_{j: (i,j)\in E} \frac{1}{T} \sum_{t=1}^T \left(x_i^{\top} A_{i,j} x_j^t-x_i^{t\top} A_{i,j}x_j^t\right)= \frac{1}{T} \sum_{i=1}^n \reg_i(T).
