\section{Proof of \Cref{lemma:average-iterate}}\label{sec:proof average-iterate}
\begin{proof}
By the zero-sum property and the linearity of the utility, we have
    \begin{align*}
        &\max_{x\in \times \Delta^{d_i}}\sum_{i=1}^n u_i(x_i, \bx^T_{-i}) - u_i(\bx^T) \\
        &= \sum_{i=1}^n  \max_{x_i\in \Delta^{d_i}}u_i(x_i, \bx^T_{-i}) \tag{$\sum_{i=1}^n u_i(\bx^T) = 0$} \\
        & =  \frac{1}{T} \sum_{i=1}^n \max_{x_i\in \Delta^{d_i}} \sum_{t=1}^T u_i(x_i, x^t_{-i}) \tag{Linearity of $u_i$ and $\bx^T_{-i} = \frac{1}{T}\sum_{t=1}^T x^t_{-i}$} \\
        & =\frac{1}{T}  \sum_{i=1}^n \InParentheses{ \max_{x_i\in \Delta^{d_i}} \sum_{t=1}^T u_i(x_i, x^t_{-i}) - \sum_{t=1}^T u_i(x^t) } \tag{$\sum_{i=1}^n u_i(x^t) = 0$ for all $t$} \\
        &= \frac{1}{T}  \sum_{i=1}^n \reg_i(T).
    \end{align*}
    This completes the proof. 
\end{proof}

\section{Last-Iterate Convergence with Gradient Feedback}\label{sec:proof last-gradient}
\subsection{Proof of \Cref{thm:last-gradient}}
\begin{proof}
    Let $\{x^t\}$ be the iterates of \OMWU dynamics with $\eta$.  Recall that we denote $u^t_i := u_i(\cdot, x^t_{-i})$. By \Cref{thm:RVU}, we have
    \begin{align*}
        \sum_{i=1}^n \reg_i(T) &\le \frac{\sum_{i=1}^n \log d_i}{\eta} + \eta \sum_{i=1}^n \sum_{t=1}^T \InParentheses{ \InNorms{u^t_i - u^{t-1}_i}^2_\infty - \frac{1}{4\eta} \InNorms{x^t_i -x^{t-1}_i}_1^2 } \\
        & \le \frac{\sum_{i=1}^n \log d_i}{\eta},
    \end{align*}
    where we use \Cref{lemma:utility to action} and $\eta \le \frac{1}{2(n-1)}$ in the last inequalty. Invoking \Cref{lemma:average-iterate}, the average-iterate has total gap bounded by $\tgap(\bx^T) \le \frac{\sum_{i=1}^n \log d_i}{\eta T}$ for all $T$. By the \AL reduction guarantee in \Cref{thm:reduction}, we conclude the proof.
\end{proof}

\subsection{Proof of \Cref{corollary:dynamic}}
\begin{proof}
    By \Cref{thm:last-gradient}, we know $\bx^t$ is an  $\frac{\sum_{i=1}^n \log d_i}{\eta t}$-approximate Nash equilibrium for any $t \ge 1$. Thus, the dynamic regret of any player $i \in [n]$ is bounded by 
    \begin{align*}
        \Dreg^T_i = \sum_{t=1}^T \InParentheses{ \max_{x_i \in \Delta^{d_i}} u_i(x_i, \bx^t_{-i}) - u_i(\bx^t)} \le \sum_{t=1}^T  \frac{\sum_{i=1}^n \log d_i}{\eta t} = O\InParentheses{ \frac{\sum_{i=1}^n \log d_i}{\eta} \log T}. 
    \end{align*}
    This completes the proof.
\end{proof}

\section{Last-Iterate Convergence with Bandit Feedback}\label{sec:proof bandit}

\subsection{Analysis of Regret with Estimation Error}
We first analyze the sequence $\{x^t\}$ generated in the subroutine (\Cref{line:OMWU update}) of \Cref{alg:bandit}, which is updated according to \OMWU with the estimated utility sequence $\{\hu^t\}$. 

We define $\Delta^t := \hU^t - \bu^t$ as the error of estimation in \Cref{line:sample}. The error of estimation for $u^t$, denoted as $\delta^t:= \hu^t - u^t$ is
\begin{align*}
   \delta^t =  t \cdot \hU^t - (t-1)\cdot \hU^{t-1} - t \cdot \bu^t + (t-1) \cdot \bu^{t-1} = t \Delta^t - (t-1) \Delta^{t-1}.
\end{align*}
In the following, we show that the regret against the original utility sequence $\{u^t\}$ can be bounded by RVU terms with an additional summation of second-order error terms. We remark that a naive analysis would lead to a summation of first-order terms, which gives a suboptimal convergence rate. 
\begin{lemma}\label{lemma:regret with error}
    Let $\{x^t\}$ be the iterates of \OMWU with step size $\eta > 0$ and utilities $\{ \hu^t\}$, we have 
    \begin{align*}
        \max_{x \in \Delta^d} \sum_{t=1}^T \InAngles{u^t, x^t - x} &\le \frac{\log d}{\eta} + 4\eta \sum_{t=1}^T \InNorms{u^t - u^{t-1}}^2_\infty - \frac{1}{8\eta}\sum_{t=1}^T \InNorms{x^t - x^{t-1}}^2_1 \\
        & \quad + 2\InNorms{T\Delta^T}_\infty + 18\eta \sum_{t=1}^{T-1} \InNorms{t \Delta^t}^2_\infty.
    \end{align*}
\end{lemma}

\textbf{Analysis}  By RVU property of \OMWU (\Cref{thm:RVU}), we can bound the regret for the estimated utilities $\{\hu^t\}$: $\forall x \in \Delta^d$,
\begin{align*}
    \sum_{t=1}^T \InAngles{\hu^t, x^t - x} \le \frac{\log d}{\eta} + \eta \sum_{t=1}^T \InNorms{\hu^t - \hu^{t-1}}^2_\infty - \frac{1}{4\eta}\sum_{t=1}^T \InNorms{x^t - x^{t-1}}^2_1
\end{align*}
Then by definition of $\hu^t = u^t + \delta^t$, we can bound the regret for the true utilities $\{u^t\}$ by
\begin{align}
    \sum_{t=1}^T \InAngles{u^t, x^t - x} &\le \frac{\log d}{\eta} + 4\eta \sum_{t=1}^T \InNorms{u^t - u^{t-1}}^2_\infty - \frac{1}{4\eta}\sum_{t=1}^T \InNorms{x^t - x^{t-1}}^2_1 \nonumber \\
     &\quad +\underbrace{\sum_{t=1}^T \InAngles{\delta^t, x^t -x}}_{\texttt{I}} + \underbrace{4\eta \sum_{t=1}^T \InParentheses{\InNorms{\delta^t}^2_\infty + \InNorms{\delta^{t-1}}^2_\infty}}_{\texttt{II}}.\label{RVU with error I and II}
\end{align}
We note that the first three terms can be bounded by $O(\log d)$ using existing RVU analysis~\citep{syrgkanis2015fast}. We focus on the error terms \texttt{I} and \texttt{II}. The term \texttt{II} is a summation of second-order terms in $\InNorms{\delta^t}_\infty^2$ and we can bound it by 
\begin{align}
    \texttt{II} = 4\eta \sum_{t=1}^T \InParentheses{\InNorms{\delta^t}^2_\infty + \InNorms{\delta^{t-1}}^2_\infty} \le 16\eta \sum_{t=1}^T \InNorms{t \Delta^t}^2_\infty. \label{eq: error II}
\end{align}

However, a naive analysis of term \texttt{I} leads to a summation of first-order terms: by Cauchy-Schwarz, we have $ \texttt{I} \le \sum_{t=1}^T\InNorms{\delta_t}_\infty \InNorms{x^t-x}_1 \le 2\sum_{t=1}^T\InNorms{\delta_t}_\infty \le 4 \sum_{t=1}^T \InNorms{t \Delta^t}_\infty$. If we tune the parameters optimally, the existence of the first-order error term $O(\sum_{t=1}^T \InNorms{t \Delta^t}_\infty)$ would result in an $O(T^{-\frac{1}{7}})$ rate, worse than the claimed $O(T^{-\frac{1}{5}})$ rate. 

\textbf{Improved Analysis of Term \texttt{I}} In the following, we give an improved analysis that bounds term $\texttt{I}$ by second-order error terms. The key is to rewrite term $\texttt{I}$ and use the negative term $-\sum_{t=1}^T \InNorms{x^t - x^{t-1}}_1^2$. By definition, we have $\delta^t = \hu^t - u^t = t \Delta^t - (t-1) \Delta^{t-1}$ and thus
\begin{align*}
    \texttt{I} = \sum_{t=1}^T \InAngles{\delta^t, x^t - x}  &= \sum_{t=1}^T \InAngles{t\Delta^t - (t-1)\Delta^{t-1}, x^t - x}  \\
    &= \InAngles{T \Delta^T, x^T - x} + \sum_{t=1}^{T-1} \InAngles{t \Delta^t, x^t - x^{t+1}} \\
    &\le 2\InNorms{T\Delta^T}_\infty + \sum_{t=1}^{T-1} \InNorms{t \Delta^t}_\infty \InNorms{x^t - x^{t+1}}_1. 
\end{align*}
As a result, we can combine $-\frac{1}{8\eta}\sum_{t=1}^T\InNorms{x^t -x^{t-1}}_1^2$ and using basic inequality $\InAngles{a,b} - \InNorms{b}^2 \le \frac{1}{4} \InNorms{a}^2$ to get 
\begin{align}
    \texttt{I} -\frac{1}{8\eta}\sum_{t=1}^T\InNorms{x^t -x^{t-1}}_1^2 &\le 2\InNorms{T\Delta^T}_\infty + \sum_{t=1}^{T-1} \InNorms{t \Delta^t}_\infty \InNorms{x^t - x^{t+1}}_1 -\frac{1}{8\eta}\sum_{t=1}^T\InNorms{x^t -x^{t-1}}_1^2 \nonumber \\
    &\le 2\InNorms{T\Delta^T}_\infty + 2\eta \sum_{t=1}^{T-1} \InNorms{t \Delta^t}^2_\infty. \label{eq:error I}
\end{align}

Combining \eqref{RVU with error I and II}, \eqref{eq: error II}, and \eqref{eq:error I}, we get 
\begin{align*}
    \reg(T) &\le \frac{\log d}{\eta} + 4\eta \sum_{t=1}^T \InNorms{u^t - u^{t-1}}^2_\infty - \frac{1}{8\eta}\sum_{t=1}^T \InNorms{x^t - x^{t-1}}^2_1  + 2\InNorms{T\Delta^T}_\infty + 18\eta \sum_{t=1}^{T-1} \InNorms{t \Delta^t}^2_\infty.
\end{align*}

\subsection{Proof of \Cref{thm:last-bandit}}

Recall that $d_{\max} = \max_{i\in[n]} d_i$. By \Cref{lemma:regret with error}, we can bound the social regret of all players with respect to the iterates $\{x^t\}$ and utilities $\{u^t\}$ by 
\begin{align*}
    \sum_{i=1}^n \reg_i(T, \{x^t_i\}, \{u^t_i\}) &\le \frac{n\log  d_{\max}}{\eta} + \underbrace{ \sum_{i=1}^n \sum_{t=1}^T \InParentheses{4\eta \InNorms{u^t_i - u^{t-1}_i}^2 - \frac{1}{8\eta} \InNorms{x^t_i - x^{t-1}_i}^2}}_{\texttt{I}} \\
    & \quad + \underbrace{\sum_{i=1}^n \InParentheses{ 2 \InNorms{T \Delta^T_i}_\infty + 18 \eta \sum_{t=1}^{T-1} \InNorms{t \Delta^t_i}^2} }_{\texttt{II}}. 
\end{align*}
By \Cref{lemma:utility to action} and the fact that $\eta \le \frac{1}{6n}$, we have $\texttt{I} \le 0$. 

For term \texttt{II},  by \Cref{lemma: all T estimation error} and union bound, we have with probability $1 - O(nd\delta)$, 
\begin{align*}
    \max_{i\in[n]} \InNorms{\Delta^t_i}_\infty \le  2\sqrt{\frac{2d_{\max} \log\InParentheses{\frac{B_t t^2}{\delta}}}{B_t \varepsilon_t}}, \forall t \ge 1.
\end{align*}
Using $\eta \le  \frac{1}{6n}$, we can bound term \texttt{II} by
\begin{align*}
    \texttt{II} \le 4nT\sqrt{\frac{d_{\max} \log\InParentheses{\frac{B_T T^2}{\delta}}}{B_T \varepsilon_T}} + 24 \sum_{t=1}^{T-1} \frac{t^2 \cdot d_{\max} \log\InParentheses{\frac{B_t t^2}{\delta}}}{B_t \varepsilon_t}.
\end{align*}

Combining the above inequalities,  we get 
\begin{align*}
    \sum_{i=1}^n \reg_i(T, \{x^t_i\}, \{u^t_i\}) \le \underbrace{6n^2 \log d_{\max} + 4nT\sqrt{\frac{ d_{\max} \log\InParentheses{\frac{B_T T^2}{\delta}}}{B_T \varepsilon_T}} + 24 \sum_{t=1}^{T-1} \frac{t^2 \cdot d_{\max} \log\InParentheses{\frac{B_t t^2}{\delta}}}{B_t \varepsilon_t}}_{\texttt{III}}
\end{align*}
By \Cref{lemma:average-iterate}, we have the average iterate $\bx^T:= \frac{1}{T} \sum_{t=1}^T x^t$ is an $\frac{\texttt{III}}{T}$-approximate Nash equilibrium. Then we know $\bx^T_\varepsilon := (1-\varepsilon_T) \bx^T + \varepsilon_T \mathrm{Uniform}(d)$ is an $(\frac{\texttt{III}}{T} + \varepsilon_T)$-approximate Nash equilibrium for any $T \ge 1$. 

By the choice of $B_t = d_{\max}\log(1/\delta)  \cdot t^4$ and $\varepsilon_t = t^{-1} $, we get 
\begin{align*}
    \frac{\texttt{III}}{T} + \varepsilon_T &\le \frac{1}{T} \cdot \InParentheses{ 6n^2 \log d_{\max}  +    4n \sqrt{\frac{\log\InParentheses{\frac{B_T T^2}{\delta}}}{T} } + 24\log T\cdot  \log\InParentheses{\frac{B_T T^2}{\delta}} +1 } \\
    & = O\InParentheses{n^2 \log^2\InParentheses{\frac{T \cdot d_{\max}}{\delta}} \cdot T^{-1} }.
\end{align*}
By the choice of the epoch length $B_t = d_{\max}\log(1/\delta)  \cdot t^4$ , we have that the actual sequence $\{\by^k\}$ generated by \AL-\OMWU-\Bandit satisfies $\by^k_\varepsilon = \bx^{t_k}_\varepsilon$ where $t_k = \Theta ((d_{\max}\log(1/\delta))^{-\frac{1}{5}}k^{\frac{1}{5}})$.  Thus we can conclude that with probability at least $1 - O(nd\delta)$, it holds for all $k \ge 1$ that $\by^k$ is a $\beta_k$-approximate Nash equilibrium with 
\begin{align*}
    \beta_k = O\InParentheses{n^2  \log^{\frac{11}{5}}\InParentheses{\frac{k \cdot d_{\max}}{\delta}} \cdot d_{\max}^{\frac{1}{5}}k^{-\frac{1}{5}} }.
\end{align*}
This completes the proof.

\subsection{Estimation}\label{sec:estimation}
In this subsection, we analyze the estimation error. With high probability, we have each action receives at least $\Omega(\frac{B_t \varepsilon_t}{d})$ samples. Define $\Delta^t := \hU^t - \bu^t$ as the error vector. We have with high probability that $|\Delta^t[a]| \le \Tilde{O}(\frac{\sqrt{d}}{\sqrt{B_t \varepsilon_t}})$ for all action $a$, which implies $\InNorms{\Delta^t}_\infty \le \Tilde{O}(\sqrt{\frac{d}{B_t \varepsilon_t}})$. The formal guarantees are as follows.

\begin{lemma}
\label{lemma:estimation error}
    In \Cref{alg:bandit}, with probability $1 - \frac{d\delta}{t^2} - d\exp\InParentheses{-\frac{B_t\varepsilon_t^2}{2d^2}}$, we have 
    \begin{align*}
        \InNorms{\Delta^t}_\infty = \InNorms{\hU^t - \bu^t}_\infty \le 2\sqrt{\frac{2d \log\InParentheses{\frac{B_t t^2}{\delta}}}{B_t \varepsilon_t}}.
    \end{align*}
\end{lemma}
\begin{proof}
    Define $N^t_a :=\sum_{k=1}^{B_t} \mathbb{I}[a^k  = a]$ to be the number of samples for action $a$.  By Hoeffding's inequality, we have 
    \begin{align*}
        \Pr\InBrackets{N^t_a \le \frac{B_t \varepsilon_t}{2d}} \le \exp\InParentheses{-\frac{B_t\varepsilon_t^2}{2d^2}}.
    \end{align*}
    Thus with probability $1 - d\exp\InParentheses{-\frac{B_t\varepsilon_t^2}{2d^2}}$, every action has been sampled at least $\frac{B_t \varepsilon_t}{2d}$ times. 

    Note that the number of samples $N^t_{a}$ for action $a$ is a random variable, so we can not directly use Azuma-Hoeffding's inequality to argue $| \hU^t[a] - \bu^t[a]| \le \sqrt{\frac{d\log(1/\delta)}{B_t\varepsilon_t}}$ with probability $1 - \delta$.  We define a sequence of random variables where $a^k_{-i} \sim \bx^t_{\varepsilon, -i}$ and $r^k = u_i(a, a^k_{-i})$, and define $\hU^t_m[a] := \frac{1}{m}\sum_{k=1}^m r^k$. Thus $\hU^t_m$ is an unbiased estimator for $\bu^t[a]$ for all $m \in [1, B_t]$. Then we can use Azuma-Hoeffding's inequality to get that 
    \begin{align*}
       &\Pr\InBrackets{|\hU^t[a] - \bu^t[a]| \ge 2\sqrt{\frac{\log\InParentheses{\frac{B_t t^2}{\delta}}}{N^t_a}} } \\
       &\le \Pr\InBrackets{\exists m \in [B_t], |\hU^t_m[a] - \bu^t[a]| \ge 2\sqrt{\frac{\log\InParentheses{\frac{B_t t^2}{\delta}}}{m}}  } \\
        & \le \sum_{m=1}^{B_t} \Pr\InBrackets{|\hU^t_m[a] - \bu^t[a]| \ge 2\sqrt{\frac{\log\InParentheses{\frac{B_t t^2}{\delta}}}{m}}  }\\
       & \le \frac{\delta}{t^2}.
    \end{align*}
    Since $N^t_a \ge \frac{B_t\varepsilon_t}{2d}$ with high probability, we get with probability $1 - \frac{d\delta}{t^2} - d\exp\InParentheses{-\frac{B_t\varepsilon_t^2}{2d^2}}$, 
    \begin{align*}
        \InNorms{\hU^t - \bu^t}_\infty \le 2\sqrt{\frac{2d \log\InParentheses{\frac{B_t t^2}{\delta}}}{B_t \varepsilon_t}}.
    \end{align*}
\end{proof}
\begin{lemma}\label{lemma: all T estimation error}
    Consider a polymatrix game where the maximum number of actions to either player is $d_{\max}$. When every player runs \AL-\OMWU-\Bandit with $B_t = d_{\max}\log(1/\delta)  \cdot t^4$ and $\varepsilon_t =  t^{-1}$, it holds with probability $1 - O(nd^{\frac{3}{2}}_{\max}\delta)$ that for all $i \in [n]$ and all $t \ge 1$, 
    \begin{align*}
        \InNorms{\Delta^t_i}_\infty \le 2\sqrt{\frac{2d_{\max} \log\InParentheses{\frac{B_t t^2}{\delta}}}{B_t \varepsilon_t}}.
    \end{align*}
\end{lemma}
\begin{proof}
    By \Cref{lemma:estimation error} and union bound over $i \in [n]$ and $t \ge 1$, we have the claim holds with probability at least
    \begin{align*}
        1 - nd_{\max}\delta \sum_{t=1}^\infty \frac{1}{t^2} - nd_{\max}\sum_{t=1}^\infty \exp\InParentheses{- \frac{t^2 \log (\frac{1}{\delta})}{2d_{\max}}} = 1 - O(nd^{\frac{3}{2}}_{\max}\delta).
    \end{align*}
 \end{proof}

