\section{Decoding quasi-twisted codes}\label{sec:quasi-twisted codes}
In this section, we formulate a Hartmann-Tzeng(HT)-like bound on the minimum distance of quasi-twisted codes, $d^* $. %$= min\big(\delta + s, d_\mathbb{C}\big)$. 
Furthermore, we describe a syndrome-based decoding algorithm of quasi-twisted codes that corrects up to $\varepsilon \left(\leq \frac{d^*-1}{2}\right)$ errors in $\mathcal{O}(n^2)$ time. Here, $n$ is the length of the quasi-twisted code. 

\subsection{HT-like bound on minimum distance of quasi-twisted codes}\label{Bound on QT}
%\vspace{-2mm}
The HT bound on the minimum distance of cyclic codes is presented in definition \ref{thm.HT}. Similar bounds have been defined for constacyclic as well as quasi-cyclic codes. Here, we present an HT-like bound on the minimum distance of quasi-twisted codes. This HT-like bound can be deduced from \cite[Remark 5]{Spec-QT}, following the motivation behind the HT-like bound for quasi-cyclic codes (\cite[Theorem 1]{Dec-QC}). However, to the best of our knowledge, this is the first instance of a formal proof for this bound.
%however, to the best of our knowledge, this lower bound is not formally written anywhere. 

\begin{theorem}[\textbf{HT-like Bound}]\label{HT-like Bound-Th} 
Consider an $[m\ell, k, d]_q$ $(\lambda ,l)$-quasi-twisted code $\mathcal{C}$. For positive integers $ a, n_1, n_2, s$ and  $\delta \geq 2$ with $gcd(m,n_1) = 1$ and $gcd(m,n_2) < \delta,$ define the set,
\begin{align*}
    D := & \{ a, a+n_1, \ldots, a+ (\delta -2)n_1, \\
    & a + n_2, a+ n_2 +n_1, \ldots, a+n_2 + (\delta -2)n_1, \\
    & \hspace{6mm} \vdots \hspace{15mm} \vdots \hspace{8mm} \hdots \hspace{11mm} \vdots \\
    & a + sn_2, a+ sn_2 +n_1, \ldots, a+sn_2 + (\delta -2)n_1\}. \\
\end{align*}
%$D := \{ a, a+n_1, \ldots, a+ (\delta -2)n_1,$ \\
%\hspace{11mm} $a + n_2, a+ n_2 +n_1, \ldots, a+n_2 + (\delta -2)n_1,$\\
%\hspace{17mm}$\vdots$ \hspace{15mm} $\vdots$ \hspace{8mm} $\hdots$ \hspace{11mm} $\vdots$\\
%\hspace{13mm}$a + sn_2, a+ sn_2 +n_1, \ldots, a+sn_2 + (\delta -2)n_1\}$\\

For some $a \geq 0$, the eigenvalues of the quasi-twisted code $\mathcal{C}$ are $\beta_i = \alpha \xi ^i, \forall i \in D$. 
Let the corresponding eigenspaces be denoted by $\mathcal{V}_i, \forall i \in D.$ Consider the intersection of these eigenspaces, $\mathcal{V} := \bigcap\limits_{i\in D} \mathcal{V}_i$ and an eigenvector $\mathbf{v} = (v_0, v_1, \ldots, v_{\ell-1}) \in \mathcal{V}.$
Let the eigencode given by $\mathcal{V}$ (that is, the direct sum of eigencodes defined by $\mathcal{V}_i$) be $\mathbb{C}$ with minimum distance $d_\mathbb{C}$.
If 
\vspace{.5mm}
\begin{equation}\label{Th-eqn}
    c(\alpha \xi^{a+i_1n_1+i_2n_2})\mathbf{v}^\intercal = 0, \hspace{2mm} \forall i_1 \in [\delta -1], i_2 \in [s+1] 
\end{equation}
\vspace{.5mm}
holds true %for an eigenvector $\textbf{v} = (v_0, v_1, \ldots, v_{\ell-1}) \in \mathcal{V}$ and 
for all $c(X) = \big(c_0(X), c_1(X), \ldots, c_{\ell-1}(X)\big) \in R^\ell$, then the HT-like bound on the minimum distance, $d$ of the quasi-twisted code, $\mathcal{C}$ is 
\begin{equation}
\label{eq:HT.like.bound.QT}
d \geq d^* = min\big\{\delta + s, d_\mathbb{C}\big\}.
\end{equation}
\end{theorem}

\begin{proof}
Recall that an eigenspace, $\mathcal{V}_i$ of an eigenvalue, $\beta_i$ is defined as, 
\begin{equation}
    \mathcal{V}_{i} := \Big\{\mathbf{v}\in \mathbb{F}^\ell : \Tilde{G}(\beta_i)\mathbf{v}^\intercal = \mathbf{0}\Big\}.
\end{equation}
Since $\mathcal{V} := \bigcap\limits_{i\in D} \mathcal{V}_i$ is the intersection of the eigenspaces $\mathcal{V}_i$, we can conclude that 
\vspace{-1mm}
\begin{equation}\label{eqn5.2}
    \Tilde{G}(\beta_i)\mathbf{v}^\intercal = \mathbf{0}, \hspace{2mm} \forall i \in D, \forall \mathbf{v} \in \mathcal{V}.
\end{equation}
Recall that for any codeword, its corresponding codeword polynomial $c(X)\in R^\ell$ can be written as $c(X) = a(X)\Tilde{G}(X).$ Now, the LHS of condition \eqref{Th-eqn} can be simplified as follows. 
\vspace{-1mm}
\begin{equation}
\begin{split}
    c(\alpha \xi^{a+i_1n_1+i_2n_2})\mathbf{v}^\intercal = & c(\alpha \xi^{i})\mathbf{v}^\intercal, \hspace{2mm} \forall i \in D\\
    = & a(\alpha \xi^{i}))\Tilde{G}(\alpha \xi^{i})\mathbf{v}^\intercal, \hspace{2mm} \forall i \in D\\
    = & 0 \text{ (using equation \eqref{eqn5.2})}
\end{split}
\end{equation}
Let $\overline{\Omega}$ denote the set of all eigenvalues of the $(\lambda,\ell)$-quasi-twisted code $\mathcal{C}.$ The set ${\Omega} = \{\beta_i : i \in D\}$ is a subset of $\overline{\Omega}.$ In other words, %the premise of this theorem can be considered as a special case of theorem \ref{spec.bound.QT}, where $P = \overline{\Omega}.$ 
the premise of this theorem is same as that of theorem \ref{spec.bound.QT}. Therefore, the minimum distance of the $(\lambda,\ell)$-quasi-twisted code $\mathcal{C}$ is $d_\mathcal{C} \geq min\{d_{\Omega},d_{\mathbb{C}_{\Omega}}\},$ where we have the following observations on $d_{\Omega}$ and $d_{\mathbb{C}_{\Omega}}.$ 

\cite[Corollary 2.ii]{Spec-QT2} gives a bound on the minimum distance of a $\lambda$-constacyclic code. Therefore, we have $d_{\Omega} \geq \delta+s.$ 

Since ${\Omega} = \{\beta_i : i \in D\}, \mathbb{C}_{\Omega}$ is same as $\mathbb{C},$ the eigencode corresponding to the common eigenspace of eigenvalues in ${\Omega}$, the minimum distance of a $(\lambda,\ell)$-quasi-twisted code $\mathcal{C}$ is given by, $d \geq d^* = min\big\{\delta + s, d_\mathbb{C}\big\}.$
\qed 


\subsection{A syndrome-based decoding algorithm}\label{subsec:dec-algo}

We begin by defining some polynomials and matrices that are necessary to develop our syndrome-based decoding algorithm for quasi-twisted codes.

Consider an $[m\ell, k, d]_q$ $(\lambda ,\ell)$-quasi-twisted code $\mathcal{C}$. 
Let $r(X) \in R^\ell$ be a polynomial corresponding to a received word, $r \in \mathbb{F}_q^n$ (under the $R$-module isomorphism defined in equation \eqref{eq.4.1}) and $e(X) \in R^\ell$ be a polynomial corresponding to an error vector, $e \in \mathbb{F}_q^n$. A received word, $r$ can be written as a summation of some codeword, $c$, and an error vector, $e$. Thus, we can write the corresponding polynomial, $r(X)$ as a sum of the corresponding codeword polynomial, $c(X)$ and the corresponding error polynomial, $e(X)$ as defined in equation \eqref{eq:rcd.word.poly}. 

\begin{equation}\label{eq:rcd.word.poly}
\begin{split}
    r(X) & = \big(r_0(X), r_1(X), \ldots, r_{\ell-1}(X) \big)\\
    & = \big(c_0(X)+e_0(X), c_1(X)+e_1(X), \ldots, c_{\ell-1}(X)+e_{\ell-1}(X) \big)\\
\end{split}
\end{equation}
Let $\mathcal{E} = \{i_1, i_2, \ldots, i_\varepsilon\}$ be a set of error locations. Note that $\mathcal{E}$ is also a union of all the error locations $\mathcal{E}_i$ in each polynomial $r_i(X) \in R$, as defined in equation \eqref{eq:err.loc.poly}.
\begin{equation}\label{eq:err.loc.poly}
    \mathcal{E} := \bigcup_{i=0}^{\ell-1}\mathcal{E}_i.
\end{equation}

We can therefore establish an upper bound on the number of error locations, $\varepsilon$. 
\begin{equation}
    |\mathcal{E}| = \varepsilon \leq \sum_{i=0}^{\ell-1}|\mathcal{E}_i|.
\end{equation}

For quasi-twisted code, 
\begin{equation}
    c_j(X) = \sum_{i \in [m]}c_{i,j}X^i \text{ and }
    e_j(X) = \sum_{i \in \mathcal{E}_i }e_{i,j}X^i, \hspace{2mm} \forall j \in [\ell].
\end{equation}

\newpage
\textbf{\underline{Syndrome Polynomials:}}

\vspace{2mm}
Let $\mathcal{V} = \bigcap\limits_{i_1\in [\delta-1],i_2\in [s+1]}\mathcal{V}_{a+i_1n_1+i_2n_2}$. Consider an eigenvector $\mathbf{v}=(v_0,v_1,\hdots,v_{\ell-1})\in \mathcal{V}$. The $(s+1)$ syndrome polynomials are defined as follows.
\begin{equation}
\begin{split}
    S_t(X) & := \sum\limits_{i=0}^{\infty}\left(\sum\limits_{j=0}^{\ell-1} r_j(\alpha \xi^{a+in_1+tn_2})v_j\right)X^i \hspace{2mm} \text{mod } X^{\delta-1} \\
    & = \sum\limits_{i=0}^{\delta-2}\left(\sum\limits_{j=0}^{\ell-1} r_j(\alpha \xi^{a+in_1+tn_2})v_j\right)X^i, \hspace{2mm} \forall t \in [s+1]. \label{S(X)}
\end{split}
\end{equation}
Using equation \eqref{Th-eqn} from theorem \ref{HT-like Bound-Th} for all $t \in [s+1]$, we can simplify $S_t(X)$.
\begin{equation}
    S_t(X) = \sum\limits_{i=0}^{\delta-2}\left(\sum\limits_{j=0}^{\ell-1} e_j(\alpha \xi^{a+in_1+tn_2})v_j\right)X^i.
\end{equation}


\textbf{\underline{Error locator polynomial:}}

\vspace{2mm}
We use the generalized Berlekamp-Massey algorithm \cite{Gen.BM-Algo} in the decoding procedure. Using this algorithm, we get the error locator polynomial to be a polynomial with $\xi^{-in_1}, \forall i \in \mathcal{E}$ as its roots. Therefore, we define the error locator polynomial as follows.
\begin{equation}\label{Lambda_poly}
    \begin{split}
        \Lambda(X) := & \prod_{i\in \mathcal{E}}(1-X\xi^{in_1})\\
        = & 1 - \Lambda_1X + \Lambda_2X^2 - \ldots \pm \Lambda_{\varepsilon}X^\varepsilon 
    \end{split}
\end{equation}


\textbf{\underline{Error evaluator polynomials:}}

\vspace{2mm}
For all $t \in [s+1]$, let $\Omega_t(X)$ denote error evaluator polynomials defined by a linear system of equations. 
\begin{equation}\label{Omega}
    \Lambda(X) \cdot S_t(X) \equiv \Omega_t(X) \hspace{2mm} \text{mod} \hspace{1mm} X^{\delta-1},\hspace{2mm} \forall t \in [s+1]
\end{equation}


\begin{remark}\label{Key-Eqns.}
    The $(s+1)$ equations in the linear system of equations \eqref{Omega} form the `Key Equations'. 
    Solving these equations jointly is equivalent to applying the generalized Berlekamp-Massey algorithm (\cite{Gen.BM-Algo}) 
    or the generalized expanded Euclidean algorithm (\cite{Gen.EA-Algo}) on $(X^{\delta-1}, S_0(X), S_1(X), \ldots, S_s(X))$. We use the former one for our analysis.
    %This gives us, as output, the error locator polynomial with roots $\xi^{-in_1}, \forall i \in \mathcal{E}$.
\end{remark}

Let us now look at a matrix representation of the syndrome polynomial and its decomposition carried out in accordance with a matrix operation $*$, which was introduced in \cite{*multi.}. A more detailed explanation can be found in \cite[Section VI.A]{Gen.BM-Algo}. 

The syndrome matrix, $S$ is defined as follows.
\vspace{-5mm}
\begin{equation}
\begin{split}
    & \\
    S := &  \big(S^{\left<0\right>} \hspace{2mm} S^{\left<1\right>} \hspace{2mm} . . . \hspace{2mm} S^{\left<s\right>}\big)^\intercal,\\
\end{split}    
\end{equation}
\begin{equation*}
%\begin{split}
    %& 
    \text{where} \hspace{2mm} S^{\left<t\right>} := \big( S_{i+j}^{\left<t\right>} \big) _{i \in [\delta-1-\varepsilon]}^{j \in [\varepsilon+1]}, \hspace{2mm} \forall t \in [s+1] %\\
    %& 
    \text{ and} \hspace{2mm} S_{k}^{\left<t\right>} = \sum_{j=0}^{\ell-1} r_j(\alpha\xi^{a+kn_1+tn_2})v_j, \hspace{2mm} \forall k \in [\delta - 1], t \in [s+1]. %\\
%\end{split}    
\end{equation*}
That is,
\begin{equation}\label{S}
    S = 
    \begin{bmatrix}
    S_{0}^{\left<0\right>} & S_{1}^{\left<0\right>} & \ldots & S_{\varepsilon}^{\left<0\right>}\\
    S_{1}^{\left<0\right>} & S_{2}^{\left<0\right>} & \ldots & S_{\varepsilon+1}^{\left<0\right>}\\
    \vdots & \vdots & \hdots & \vdots\\
    S_{\delta-2-\varepsilon}^{\left<0\right>} & S_{\delta-1-\varepsilon}^{\left<0\right>} & \ldots & S_{\delta-2}^{\left<0\right>}\\
    \hdashline[2pt/2pt]
    S_{0}^{\left<1\right>} & S_{1}^{\left<1\right>} & \ldots & S_{\varepsilon}^{\left<1\right>}\\
    S_{1}^{\left<1\right>} & S_{2}^{\left<1\right>} & \ldots & S_{\varepsilon+1}^{\left<1\right>}\\
    \vdots & \vdots & \hdots & \vdots\\
    S_{\delta-2-\varepsilon}^{\left<1\right>} & S_{\delta-1-\varepsilon}^{\left<1\right>} & \ldots & S_{\delta-2}^{\left<1\right>}\\
    \hdashline[2pt/2pt]
    \vdots & \vdots & \hdots & \vdots\\
    \vdots & \vdots & \hdots & \vdots\\
    \hdashline[2pt/2pt]
    S_{0}^{\left<s\right>} & S_{1}^{\left<s\right>} & \ldots & S_{\varepsilon}^{\left<s\right>}\\
    S_{1}^{\left<s\right>} & S_{2}^{\left<s\right>} & \ldots & S_{\varepsilon+1}^{\left<s\right>}\\
    \vdots & \vdots & \hdots & \vdots\\
    S_{\delta-2-\varepsilon}^{\left<s\right>} & S_{\delta-1-\varepsilon}^{\left<s\right>} & \ldots & S_{\delta-2}^{\left<s\right>}\\

    \end{bmatrix}_{(\delta-1-\varepsilon)(s+1)\times(\varepsilon+1)}
\end{equation}

Let $S = XY\Tilde{X}$ be the decomposition of $S$. Here, the matrix $X$ is defined in equation \eqref{eq:S.decomposition.X},

\begin{equation}
\label{eq:S.decomposition.X}
