\end{equation}
where $X^{\left<t\right>} := \big( \xi^{(n_1i+n_2t)j} \big)_{i \in [\delta-1-\varepsilon]}^{j \in \{1,2,\ldots,\varepsilon\}}$ for all $t \in [s+1].$ That is,
\begin{equation}\label{X}
    X = 
