\subsection{Review on subresultants of several polynomials}

For generalizing the classical Habicht's theorem to more than two polynomials,
we need the notions/notations of generalized subresultants for several
polynomials. In \cite{Hong_Yang-2023}, the authors present a natural extension
of the classical subresultant for two polynomials to multiple polynomials. For
the readers' convenience, we reproduce them here.

\begin{notation}
\label{notation1} \

\begin{itemize}
\item $d=(d_{0},\ldots,d_{n})\in\mathbb{N}^{n+1}$;

\item $a_{i}=\left(  a_{i0},\ldots,a_{id_{i}}\right)  $ be indeterminates (parameters);

\item $F=(F_{0},\ldots,F_{n})$ where $F_{i}=\sum_{j=0}^{d_{i}}a_{ij}x^{j}%
\in\mathbb{Z}[a_{i}][x]$;

\item $P(d_{0},n)=\{(\delta_{1},\ldots,\delta_{n})\in\mathbb{N}^{n}%
:\,|\delta|=\delta_{1}+\cdots+\delta_{n}\leq d_{0}\}$;

\item $\mathcal{F}_{k}=x^{\delta_{k}-1}F_{k},\ldots,x^{0}F_{k}$ where
$\delta_{k}\in\mathbb{N}$;

\item $c\left(  \delta\right)  =\#\operatorname{col}\operatorname{cm}\left(
\mathcal{F}_{1},\ldots,\mathcal{F}_{n}\right)  . $
\end{itemize}
\end{notation}

\begin{example}
Let $d=(3,3,4)$. Then
\[
P(d_{0}%
,n)=\{\ (3,0),\ (2,1),\ (1,2),\ (0,3),\ (2,0),\ (1,1),\ (0,2),\ (1,0),\ (0,1),\ (0,0)\ \}
\]
Choose $\delta=(1,1)\in P(3,2)$. We have
\[
\mathcal{F}_{1}=x^{0}F_{1},\quad\mathcal{F}_{2}=x^{0}F_{2}
\]
Thus
\begin{align*}
\operatorname{cm}\left(  \mathcal{F}_{1},\mathcal{F}_{2}\right)   &
=\operatorname{cm}\ (x^{0}F_{1},x^{0}F_{2}) =%
\begin{bmatrix}
& a_{13} & a_{12} & a_{11} & a_{10}\\
a_{24} & a_{23} & a_{22} & a_{21} & a_{20}%
\end{bmatrix}
\\
c\left(  \delta\right)   &  =\#\operatorname{col}%
\begin{bmatrix}
& a_{13} & a_{12} & a_{11} & a_{10}\\
a_{24} & a_{23} & a_{22} & a_{21} & a_{20}%
\end{bmatrix}
=5
\end{align*}

\end{example}

\begin{definition}
[Subresultant]\label{def:sres_npoly} Let $\delta\in P(d_{0},n)$.

\begin{itemize}
\item The $\delta$-\emph{subresultant} of $F$, written as $R_{\delta}\left(
F\right)  $, is defined by
\[
R_{\delta}\left(  F\right)  ={\operatorname*{dp}}\operatorname{cm}\left(
\mathcal{F}_{0},\ldots,\mathcal{F}_{n}\right)
\]
where again%
\begin{equation}
\label{eqs:delta0}\delta_{0}=\left\{
\begin{array}
[c]{ll}%
c\left(  \delta\right)  -d_{0} & \text{if\ \ }c\left(  \delta\right)  \geq
d_{0}\\
1 & \text{else}%
\end{array}
\right.
\end{equation}


\item The \emph{principal} \emph{coefficient} of $R_{\delta}\left(  F\right)
$, written as $r_{\delta}(F)$, is defined by
\[
r_{\delta}(F)=\operatorname*{coeff}\nolimits_{x^{d_{0}-\left\vert
\delta\right\vert }}\left(  R_{\delta}\left(  F\right)  \right)
\]

\end{itemize}
\end{definition}

\begin{remark}
In the above, the particular expression for $\delta_{0}$ is chosen because it
naturally extends the formulation of subresultants for two polynomials.
Roughly speaking, such choice of $\delta_{0}$ makes the submatrix of
$\operatorname{cm}\left(  \mathcal{F}_{0},\ldots,\mathcal{F}_{n}\right)  $
involving the coefficients of $F_{0}$ the widest block while keeping the size
of the matrix $\operatorname{cm}\left(  \mathcal{F}_{0},\ldots,\mathcal{F}%
_{n}\right)  $ as small as possible.
\end{remark}

\begin{example}
Let $d=(3,3,4)$ and $\delta=\left(  1,1\right)  $. Note%
\[
c\left(  \delta\right)  =\#\operatorname{col}\operatorname{cm}\left(
\mathcal{F}_{1},\mathcal{F}_{2}\right)  =5\geq d_{0},\ \ \ \delta_{0}=5-3=2
\]
Therefore
\begin{align*}
R_{(1,1)}(F)  &  ={\operatorname*{dp}}%
\begin{bmatrix}
a_{03} & a_{02} & a_{01} & a_{00} & \\
& a_{03} & a_{02} & a_{01} & a_{00}\\
& a_{13} & a_{12} & a_{11} & a_{10}\\
a_{24} & a_{23} & a_{22} & a_{21} & a_{20}%
\end{bmatrix}
=\det%
\begin{bmatrix}
a_{03} & a_{02} & a_{01} & a_{00}\\
& a_{03} & a_{02} & a_{01}\\
& a_{13} & a_{12} & a_{11}\\
a_{24} & a_{23} & a_{22} & a_{21}%
\end{bmatrix}
x+\det%
\begin{bmatrix}
a_{03} & a_{02} & a_{01} & \\
& a_{03} & a_{02} & a_{00}\\
& a_{13} & a_{12} & a_{10}\\
a_{24} & a_{23} & a_{22} & a_{20}%
\end{bmatrix}
\\
r_{(1,1)}(F)  &  =\det%
\begin{bmatrix}
a_{03} & a_{02} & a_{01} & a_{00}\\
& a_{03} & a_{02} & a_{01}\\
& a_{13} & a_{12} & a_{11}\\
a_{24} & a_{23} & a_{22} & a_{21}%
\end{bmatrix}
\end{align*}

\end{example}

\section{Main Result}

\label{sec:main_result} In this section, we describe a generalization of
Habicht's theorem for several polynomials. For this purpose, we need the
following notation.

\begin{notation}
Let $e_{i}\in\{0,1\}^{n}$ be the $i$-th unit vector of length $n$, that is,
the vector whose $i$-th element is 1 and the remaining elements are all zeros.
We choose the convention that $e_{0}= \left(  0,\ldots,0\right)  $.
\end{notation}

\begin{assumption}
From now on, we will assume that $d_{0}\leq d_{1},\ldots,d_{n}$ and $F_{0}$ is
monic, i.e., $a_{0d_{0}}=1$.
\end{assumption}

\begin{theorem}
[Main Result]\label{thm:main} We have
\begin{equation}
r_{w_{0}}^{\epsilon}(F_{0},\ldots,F_{n})\ \;R_{u}(F_{0},\ldots,F_{n}%
)\ \ \ =\ \ \ R_{v}(R_{w_{0}}(F_{0},\ldots,F_{n}),\ldots,R_{w_{n}}%
(F_{0},\ldots,F_{n})) \label{eq:main_result}%
\end{equation}
if $u\in P\left(  d_{0},n\right)  ,v,w_{0},\ldots,w_{n},\epsilon$ satisfy the
following conditions
\[
\left\{
\begin{array}
[c]{rcl}%
w_{1} & = & w_{0}+e_{1}\\
& \vdots & \\
w_{n} & = & w_{0}+e_{n}\\
v & = & (k,\ldots,k)+e_{i}\\
u & = & w_{0}+v\\
\epsilon & = & |v+e_{i}|+k-2
\end{array}
\right.
\]
for some $k\geq1$ and $0\leq i\leq n$.
\end{theorem}

\begin{example}
Let $d=(5,5,6)$.

\begin{itemize}
\item Let $w_{0}=(1,1)$, $k=1$ and $i=0$. Then
\[
\omega_{1}=(2,1),\ \ \omega_{2}=(1,2),\ \ v=(1,1),\ \ u=(2,2),\ \ \epsilon
=|(1,1)|+1-2=1
\]
Thus we have
\[
r_{(1,1)}^{1}(F)\ R_{(2,2)}(F)\ \ \ =\ \ R_{(1,1)} \ (\ R_{(1,1)}%
(F),\;R_{(2,1)}(F),\;R_{(1,2)}(F)\ )
\]
%where $c= r_{\delta}(F)$.


\item Let $w_{0}=(1,1)$, $k=1$ and $i=1$. Then
\[
\omega_{1}=(2,1),\ \ \omega_{2}=(1,2),\ \ v=(2,1),\ \ u=(3,2),\ \ \epsilon
=|(3,1)|+1-2=3
\]
Thus we have
\[
r_{(1,1)}^{3}(F)\ R_{(3,2)}(F)\ \ \ =\ \ R_{(2,1)} \ (\ R_{(1,1)}%
(F),\;R_{(2,1)}(F),\;R_{(1,2)}(F)\ )
\]
%where $c= r_{\delta}^3(F)$.


\item Let $w_{0}=(1,1)$, $k=1$ and $i=2$. Then
\[
\omega_{1}=(2,1),\ \ \omega_{2}=(1,2),\ \ v=(1,2),\ \ u=(2,3),\ \ \epsilon
=|(1,3)|+1-2=3
\]
Thus we have
\[
r_{(1,1)}^{3}(F)\ R_{(2,3)}(F)\ \ \ =\ \ R_{(1,2)} \ (\ R_{(1,1)}%
(F),\;R_{(2,1)}(F),;R_{(1,2)}(F)\ )
\]
%where $c= r_{\delta}^3(F)$.

\end{itemize}
\end{example}

