\subsection{Some useful properties of determinant polynomials}
\label{ssec:detp_properties} In this subsection, we derive or recall several
properties of determinant polynomials, which will be used in the following two subsections.

\begin{proposition}
\label{prop:ci} Let $P=(P_{1},\ldots,P_{t})$ where $P_{i}=\sum_{0\le j\le
p_{i}}b_{ij}x^{j}$ and $p_{i}=\deg P_{i}$. Let $m=\max_{1\le i\le t} p_{i}$.
If $t \leq m+1$, then we have
\[
{\operatorname*{dp}}(P_{1},\ldots,P_{t})=\sum_{i=1}^{t}c_{i}P_{i}
\]
where
\begin{align*}
c_{i}=\left\{
\begin{array}
[c]{ll}%
1 & \text{if}\ \ t=1;\\
0 & \text{if}\ \ t>1 \ \wedge\ \underset{j\neq i}{\forall}p_{j}< p_{i};\\
(-1)^{t+i}{\operatorname*{pcdp}}(P_{1},\ldots,P_{i-1},P_{i+1},\ldots,P_{t}) &
\text{else}%
\end{array}
\right.
\end{align*}

\end{proposition}

\begin{proof}
If $t=1$, it is clear that ${\operatorname*{dp}}(P_{1})=c_{1}P_{1}$ where
$c_{1}=1$. Next we consider the case where $t>1$. By the multi-linearity of
determinant, we have
\begin{align*}
\operatorname*{dp}(P_{1},\dots,P_{t}) =\sum_{i=0}^{m-t+1}\det\left[
\setlength\arraycolsep{3pt}
\begin{array}
[c]{cccc}%
b_{1m} & \cdots & b_{1(m-t+2)} & b_{1i}\\
\vdots &  & \vdots & \vdots\\
b_{tm} & \cdots & b_{t(m-t+2)} & b_{ti}%
\end{array}
\right]  x^{i} =\det\left[
\begin{array}
[c]{cccc}%
b_{1m} & \cdots & b_{1(m-t+2)} & \sum\limits_{i=0}^{m-t+1}b_{1i}x^{i}\\
\vdots &  & \vdots & \vdots\\
b_{tm} & \cdots & b_{t(m-t+2)} & \sum\limits_{i=0}^{m-t+1}b_{ti}x^{i}%
\end{array}
\right]
\end{align*}
where $b_{ij}:=0$ for $j>p_{i}$. Adding the $i$-th column multiplied by
$x^{m+1-i}$ to the last column, we get
\begin{align*}
\operatorname*{dp}(P_{1},\dots,P_{t}) =\det\left[
\begin{array}
[c]{cccc}%
b_{1m} & \cdots & b_{1(m-t+2)} & \sum\limits_{i=0}^{m}b_{1i}x^{i}\\
\vdots &  & \vdots & \vdots\\
b_{tm} & \cdots & b_{t(m-t+2)} & \sum\limits_{i=0}^{m}b_{ti}x^{i}%
\end{array}
\right]  =\det\left[
\begin{array}
[c]{cccc}%
b_{1m} & \cdots & b_{1(m-t+2)} & P_{1}\\
\vdots &  & \vdots & \vdots\\
b_{tm} & \cdots & b_{t(m-t+2)} & P_{t}%
\end{array}
\right]
\end{align*}
Then the expansion of the matrix along the last column results in
\begin{align*}
{\operatorname*{dp}}(P_{1},\ldots,P_{t})=\sum_{i=1}^{t}(-1)^{t+i}\det
(M^{(i)})\cdot P_{i}%
\end{align*}
where
\begin{align}
\label{eq:M_i}M^{(i)}=\left[
\begin{array}
[c]{ccc}%
b_{1m} & \cdots & b_{1(m-t+2)}\\
\vdots &  & \vdots\\
b_{(i-1)m} & \cdots & b_{(i-1)(m-t+2)}\\
b_{(i+1)m} & \cdots & b_{(i+1)(m-t+2)}\\
\vdots &  & \vdots\\
b_{tm} & \cdots & b_{t(m-t+2)}%
\end{array}
\right]
\end{align}


Let $c_{i}=(-1)^{t+i}\det(M^{(i)})$, then ${\operatorname*{dp}}(P_{1}%
,\ldots,P_{t})=\sum_{i=1}^{t}c_{i}P_{i}$. Now we consider the following two
cases for $c_{i}$, depending on whether $\underset{j\neq i}{\forall}p_{j}<
p_{i}$ holds or not.

\begin{itemize}
\item[C1:] $\underset{j\neq i}{\forall}p_{j}< p_{i}$.

In this case, we have $b_{jm}=0$ for $j=1,\ldots,i-1,i+1,\ldots,t$. By
\eqref{eq:M_i},
\begin{align*}
c_{i}=\sum_{i=1}^{t}(-1)^{t+i}\det(M^{(i)})=0
\end{align*}


\item[C2:] $\underset{j\neq i}{\exists}p_{j}\geq p_{i}$. In this case,
$\det(M^{(i)})={\operatorname*{pcdp}}\left(  P_{1},\ldots,P_{i-1}%
,P_{i+1},\ldots,P_{t}\right)  $. Then
\begin{align*}
c_{i}=\sum_{i=1}^{t}(-1)^{t+i}\det(M^{(i)})=(-1)^{t+i}{\operatorname*{pcdp}%
}\left(  P_{1},\ldots,P_{i-1},P_{i+1},\ldots,P_{t}\right)
\end{align*}

\end{itemize}

The proof is completed.
\end{proof}

