\begin{lemma}
\label{lemma:002} Let $P=(P_{1},\ldots,P_{t_{1}})$, $Q=(Q_{1},\ldots,Q_{t_{2}%
})$ with $\deg P_{i}=p_{i}$ and $\deg Q_{i}=q_{i}$ be such that $t_{1}%
,t_{2}\ge1$ and $m_{1}=\max\limits_{1\le i\le t_{1}} p_{i}\ge m_{2}%
=\max\limits_{1\le i\le t_{2}} q_{i}$. If $t_{1}+t_{2}\leq m_{1}+1$ and
$m_{2}\le m_{1}-t_{1}+1$, then we have the following:%

\[
\operatorname*{dp}(P,Q)=\left\{
\begin{array}
[c]{ll}%
\text{$(1)$}\ \ \operatorname*{dp}(\operatorname*{dp}(P),Q) & \text{if}%
\ \ m_{2}=m_{1}-t_{1}+1;\\
\text{$(2)$}\ \ {\operatorname*{pcdp}}(P)\cdot\operatorname*{dp}(Q) &
\text{if}\ \ m_{2}=m_{1}-t_{1}\ \ \text{or}\ \ m_{2}< m_{1}-t_{1} \wedge
t_{2}= 1;\\
\text{$(3)$}\ \ 0 & \text{else}%
\end{array}
\right.
\]

\end{lemma}

\begin{proof}
Assume $P_{i}=\sum_{0\le j\le p_{i}}b_{ij}x^{j}$, $Q_{i}=\sum_{0\le j\le
q_{i}}b_{ij}^{*}x^{j}$. Let $M^{(1)}={\operatorname*{cm}}(P_{1},\ldots
,P_{t_{1}},Q_{1},\ldots,Q_{t_{2}})$, that is
\begin{align*}
M^{(1)}=\left[
\begin{array}
[c]{cccccc}%
b_{1m_{1}} & \cdots & b_{1(m_{1}-t_{1}+1)} & b_{1(m_{1}-t_{1})} & \cdots &
b_{10}\\
\vdots &  & \vdots & \vdots &  & \vdots\\
b_{t_{1}m_{1}} & \cdots & b_{t_{1}(m_{1}-t_{1}+1)} & b_{t_{1}(m_{1}-t_{1})} &
\cdots & b_{t_{1}0}\\
&  & b_{1(m_{1}-t_{1}+1)}^{*} & b_{1(m_{1}-t_{1})}^{*} & \cdots & b_{10}^{*}\\
&  & \vdots & \vdots &  & \vdots\\
&  & b_{t_{2}(m_{1}-t_{1}+1)}^{*} & b_{t_{2}(m_{1}-t_{1})}^{*} & \cdots &
b_{t_{2}0}^{*}%
\end{array}
\right]
\end{align*}
where $b_{ij}:=0$ when $j>p_{i}$ and $b_{ij}^{*}:=0$ when $j>q_{i}$. Next we
simplify $\operatorname*{dp} (M^{(1)})$. For this purpose, let $U_{1}%
=\operatorname*{dp}(P_{1},\ldots,P_{t_{1}})$. By Proposition \ref{prop:ci}, we
have
\begin{align*}
U_{1}=\operatorname*{dp}(P_{1},\ldots,P_{t_{1}})=c_{1}P_{1}+\cdots+c_{t_{1}%
}P_{t_{1}}%
\end{align*}
where
\begin{align*}
c_{i}=\left\{
\begin{array}
[c]{ll}%
1 & \text{if}\ \ t_{1}=1;\\
0 & \text{if}\ \ t_{1}>1\ \wedge\underset{j\neq i}{\forall}p_{j}< p_{i};\\
(-1)^{t_{1}+i}{\operatorname*{pcdp}}(P_{1},\ldots,P_{i-1},P_{i+1}%
,\ldots,P_{t_{1}}) & \text{else}%
\end{array}
\right.
\end{align*}
\noindent Now we proceed to analyze $\operatorname*{dp}(M^{(1)})$ separately
under the two conditions of $t_{1}>1$ and $t_{1}=1$.

\begin{itemize}
[leftmargin=15mm]

\item[\textbf{Case(i)}] : $t_{1}=1$.

In this case, $U_{1}=\operatorname*{dp}(P_{1})=P_{1}$. Then we have
\begin{align*}
\operatorname*{dp}(M^{(1)})=\operatorname*{dp}(P_{1},Q_{1},\ldots,Q_{t_{2}%
})=\operatorname*{dp}(U_{1},Q_{1},\ldots,Q_{t_{2}})
\end{align*}


\item[\textbf{Case(ii)}] $:t_{1}>1$.

Without loss of generality, we suppose that $p_{t_{1}}=\min\limits_{1\le i\le
t_{1}} p_{i}$, i.e., $c_{t_{1}}\neq0$. It follows that
\begin{align}
\label{equ:001}c_{t_{1}}\operatorname*{dp}(M^{(1)})  &  =\operatorname*{dp}%
(P_{1},\ldots,P_{t_{1}-1},c_{t_{1}}P_{t_{1}},Q_{1},\ldots,Q_{t_{2}%
})\nonumber\\
&  =\operatorname*{dp}(P_{1},\ldots,P_{t_{1}-1},U_{1},Q_{1},\ldots,Q_{t_{2}})
\end{align}
Consider $M^{(2)}=\operatorname*{cm}(P_{1},\ldots,P_{t_{1}-1},U_{1}%
,Q_{1},\ldots,Q_{t_{2}})$. We partition $M^{(2)}$ in the following way:
\begin{align*}
M^{(2)}=\left[
\begin{array}
[c]{cc}%
N^{(1)} & N^{(2)}\\
& N^{(3)}%
\end{array}
\right]
\end{align*}
where
\begin{align*}
N^{(1)}=\left[
\begin{array}
[c]{ccc}%
b_{1m_{1}} & \cdots & b_{1(m_{1}-t_{1}+2)}\\
\vdots &  & \vdots\\
b_{(t_{1}-1)m_{1}} & \cdots & b_{(t_{1}-1)(m_{1}-t_{1}+2)}\\
&  &
\end{array}
\right]  , N^{(2)}=\left[
\begin{array}
[c]{ccc}%
b_{1(m_{1}-t_{1}+1)} & \cdots & b_{10}\\
\vdots &  & \vdots\\
b_{(t_{1}-1)(m_{1}-t_{1}+1)} & \cdots & b_{(t_{1}-1)0}%
\end{array}
\right]
\end{align*}
and
\[
N^{(3)}=\operatorname*{dp}(U_{1},Q_{1},\ldots,Q_{t_{2}})=\left[
\begin{array}
[c]{ccc}%
u_{m_{1}-t_{1}+1} & \cdots & u_{0}\\
b_{1(m_{1}-t_{1}+1)}^{*} & \cdots & b_{10}^{*}\\
\vdots &  & \vdots\\
b_{t_{2}(m_{1}-t_{1}+1)}^{*} & \cdots & b_{t_{2}0}^{*}%
\end{array}
\right]
\]
where $u_{i}$ is the coefficient of $U_{1}$ in the term $x^{i}$. Next we show
that when $m_{2}\le m_{1}-t_{1}+1$, $\operatorname*{dp}(M^{(1)}%
)=\operatorname*{dp} (N^{(3)})$.

Let $M_{i}^{(2)}$, $N_{i}^{(1)}$, $N_{i}^{(2)}$ and $N_{i}^{(3)}$ be the
$i$-th column of $M^{(2)}$, $N^{(1)}$, $N^{(2)}$ and $N^{(3)}$, respectively.
By the definition of determinant polynomial, we have
\begin{align*}
\operatorname*{dp}(M^{(2)})  &  =\sum_{i=t_{1}+t_{2}}^{m_{1}+1}\det\left[
\begin{array}
[c]{cccc}%
M_{1}^{(2)} & \cdots & M_{t_{1}+t_{2}-1}^{(2)} & M_{i}^{(2)}%
\end{array}
\right]  \cdot x^{m_{1}+1-i}\\
&  =\sum_{i=t_{2}+1}^{m_{1}-t_{1}+2}\det\left[
\begin{array}
[c]{cccllll}%
N_{1}^{(1)} & \cdots & N_{t_{1}-1}^{(1)} & N_{1}^{(2)} & \cdots & N_{t_{2}%
}^{(2)} & N_{i}^{(2)}\\
&  &  & N_{1}^{(3)} & \cdots & N_{t_{2}}^{(3)} & N_{i}^{(3)}%
\end{array}
\right]  \cdot x^{m_{1}-t_{1}+2-i}%
\end{align*}
Since $N^{(1)}=%
\begin{bmatrix}
N_{1}^{(1)} & \cdots & N_{t_{1}-1}^{(1)}%
\end{bmatrix}
$ is a square matrix of order $t_{1}-1$, we have
\begin{align}
\label{equ:002}\operatorname*{dp}(M^{(2)})  &  =\det N^{(1)}\cdot\sum
_{i=t_{2}+1}^{m_{1}-t_{1}+2} \det\left[
\begin{array}
[c]{cccc}%
N_{1}^{(3)} & \cdots & N_{t_{2}}^{(3)} & N_{i}^{(3)}\\
&  &  &
\end{array}
\right]  x^{m_{1}-t_{1}+2-i}\nonumber\\
&  =\det(N^{(1)})\cdot\operatorname*{dp}(N^{(3)})
\end{align}
The substitution of \eqref{equ:002} into \eqref{equ:001} yields
\begin{align*}
c_{t_{1}}\cdot\operatorname*{dp}(M^{(1)})=\operatorname*{dp}(M^{(2)}%
)=\det(N^{(1)})\cdot\operatorname*{dp}(N^{(3)})
\end{align*}
Noting that $c_{t_{1}}={\operatorname*{pcdp}}(P_{1},\ldots,P_{t_{1}-1}%
)=\det(N^{(1)})$, we have
\begin{align*}
\operatorname*{dp}(M^{(1)})=\operatorname*{dp}(N^{(3)})
\end{align*}

\end{itemize}

\noindent Therefore, we can deduce that for both the scenarios where $t_{1}=1$
and $t_{1}>1$, the following equation holds:
\begin{align}
\label{lem:result1}\operatorname*{dp}(M^{(1)})=\operatorname*{dp}(U_{1}%
,Q_{1},\ldots,Q_{t_{2}})=\operatorname*{dp}(N^{(3)})
\end{align}


\medskip

\noindent Next, we consider the following four cases for $m_{2}\le m_{1}%
-t_{1}+1$ and specialize the above results for these cases.

\begin{itemize}
[leftmargin=15mm]

\item[Case (1):] $m_{2}=m_{1}-t_{1}+1$.

In this case, $N^{(3)}=\operatorname*{cm}(U_{1},Q_{1},\ldots,Q_{t_{2}%
})=\operatorname*{cm}(\operatorname*{dp} (P),Q_{1},\ldots,Q_{t_{2}})$. By
\eqref{lem:result1},
\[
\operatorname*{dp} (P,Q)=\operatorname*{dp}( M^{(1)})=\operatorname*{dp}%
(\operatorname*{dp} (P),Q_{1},\ldots,Q_{t_{2}})
\]


\item[Case (2):] $m_{2}=m_{1}-t_{1}$.

Let $U_{1}=\operatorname*{dp}(P_{1},\ldots,P_{t_{1}})$. Since $u_{i}$ is the
coefficient of $U_{1}$ in the term $x^{i}$, we have $u_{m_{1}-t_{1}%
+1}={\operatorname*{pcdp}}(P)$. Since $m_{2}=m_{1}-t_{1}$, $b_{j(m-t_{1}%
+1)}^{*}=0$ for $j=1,\ldots,t_{2}$, Equation \eqref{lem:result1} can be
simplified into the following:
\begin{align*}
\operatorname*{dp}(M^{(1)})=\operatorname*{dp}\left[
\setlength{\arraycolsep}{0.5pt}
\begin{array}
[c]{cccc}%
u_{m_{1}-t_{1}+1} & u_{m_{1}-t_{1}} & \cdots & u_{0}\\
& b_{1(m_{1}-t_{1})}^{*} & \cdots & b_{10}^{*}\\
& \vdots &  & \vdots\\
& b_{t_{2}(m_{1}-t_{1})}^{*} & \cdots & b_{t_{2}0}^{*}%
\end{array}
\right]  =u_{m_{1}-t_{1}+1}\cdot\operatorname*{dp}(Q)=\,{\operatorname*{pcdp}}
(P)\cdot\operatorname*{dp}(Q)
\end{align*}


\item[Case (3)] $m_{2}< m_{1}-t_{1}\wedge t_{2}= 1$.

Since $t_{2}=1$ and $m_{2}< m_{1}-t_{1}$, by \eqref{lem:result1},
\begin{align}
\label{equ:006}\operatorname*{dp}(M^{(1)})=\operatorname*{dp}\left[
\begin{array}
[c]{cccc}%
u_{m_{1}-t_{1}+1} & u_{m_{1}-t_{1}} & \cdots & u_{0}\\
& b_{1(m_{1}-t_{1})}^{*} & \cdots & b_{10}^{*}%
\end{array}
\right]  =u_{m_{1}-t_{1}+1}\cdot\sum_{i=0}^{m_{1}-t_{1}} b_{1i}^{*}\cdot x^{i}%
\end{align}
where $b_{ij}^{*}:=0$ when $j>q_{i}$. Noting that $u_{m_{1}-t_{1}%
+1}={\operatorname*{pcdp}} (P)$ and $\sum_{i=0}^{m_{1}-t_{1}} b_{1i}^{*}\cdot
x^{i}=Q_{1}=\operatorname*{dp} (Q)$, we easily attain
\[
\operatorname*{dp}(M^{(1)})={\operatorname*{pcdp}} (P)\cdot\operatorname*{dp}%
(Q)
\]


\item[Case (4)] $m_{2}<m_{1}-t_{1} \wedge t_{2}\geq2$.

Let $m_{2}=m_{1}-t_{1}-k$. Hence $b_{j(m_{1}-t_{1}+1)}^{*}=\cdots
=b_{j(m_{1}-t_{1}-k+1)}^{*}=0$ for $j=1,\ldots, t_{2}$. It follows that
\begin{align*}
\operatorname*{dp}(M^{(1)})=\,  &  \operatorname*{dp}(N^{(3)})\\
=\,  &  \operatorname*{dp}\left[
\begin{array}
[c]{cccc}%
u_{m_{1}-t_{1}+1} & u_{m_{1}-t_{1}} & \cdots & u_{0}\\
b_{1(m_{1}-t_{1}+1)}^{*} & b_{1(m_{1}-t_{1})}^{*} & \cdots & b_{10}^{*}\\
\vdots & \vdots &  & \vdots\\
b_{t_{2}(m_{1}-t_{1}+1)}^{*} & b_{t_{2}(m_{1}-t_{1})}^{*} & \cdots &
b_{t_{2}0}^{*}%
\end{array}
\right] \\
=\,  &  \operatorname*{dp}\left[
\begin{array}
[c]{ccccccc}%
u_{m_{1}-t_{1}+1} & u_{m_{1}-t_{1}} & \cdots & u_{m_{1}-t_{1}-k+1} &
u_{m_{1}-t_{1}-k} & \cdots & u_{0}\\
0 & 0 & \cdots & 0 & b_{1(m_{1}-t_{1}-k)}^{*} & \cdots & b_{10}^{*}\\
\vdots & \vdots &  & \vdots & \vdots &  & \vdots\\
0 & 0 & \cdots & 0 & b_{t_{2}(m_{1}-t_{1}-k)}^{*} & \cdots & b_{t_{2}0}^{*}%
\end{array}
\right] \\
=\,  &  u_{m_{1}-t_{1}+1}\cdot\operatorname*{dp}\left[
\begin{array}
[c]{ccccccccc}%
0 & \cdots & 0 & b_{1(m_{1}-t_{1}-k)}^{*} & \cdots & b_{10}^{*} &  &  & \\
\vdots &  & \vdots & \vdots &  & \vdots &  &  & \\
0 & \cdots & 0 & b_{t_{2}(m_{1}-t_{1}-k)}^{*} & \cdots & b_{t_{2}0}^{*} &  &
&
\end{array}
\right] \\
=\,  &  0
\end{align*}

\end{itemize}

\noindent The proof is completed.
\end{proof}

\subsection{Induction base (i.e. $k=1$)}

\label{subsec:base}

Note that when $k=1$, $v$ and $\epsilon$ can be explicitly written as
\begin{align}\label{equ:v:denpen:i}
v=\left\{
\begin{array}[c]{ll}
            (k,\ldots,k)+e_{0}=(k,\ldots,k)      & \text{if}\ \ i=0; \\
        (k,\ldots,k)+e_{i}=(k,\ldots,k,k+1,k\ldots,k) & \text{else}
\end{array}
\right.
\end{align}
and
\begin{align}\label{equ:epsilon:denpen:i}
\epsilon=\left\{
\begin{array}[c]{ll}
        |v+e_{0}|+k-2=(nk)+k-2=(n+1)k-2 & \text{if}\ \ i=0; \\
        |v+e_{i}|+k-2=(nk+2)+k-2=(n+1)k & \text{else}
\end{array}
\right.
\end{align}
respectively,  depending on whether $i$ is zero or not. For the sake of simplicity, let $k^{\prime}=(k,\ldots,k)$. By using \eqref{equ:v:denpen:i} and \eqref{equ:epsilon:denpen:i}, we can  provide an equivalent theorem of Main Result (Theorem
\ref{thm:main}) for $k=1$, which facilitates the proof.


\begin{theorem}
[Main Result for $k=1$]\label{thm:k=1} Let $w_{0}\in\mathbb{N}^{n}$ and
$i\in\left[  0,\ldots,n \right]  $ be such that $w_{0}+1^{\prime}+e_{i}\in
P(d_{0},n)$. Then we have
\begin{numcases}{\centering\hspace{-25mm}}\label{equ:base_step}
r_{w_{0}}^{n-1}(F) R_{w_{0}+1^{\prime}}(F) = R_{1^{\prime}}(R_{w_{0}+e_{0}}(F),R_{w_{0}+e_{1}}(F),\ldots,R_{w_{0}+e_{n}}(F))  \label{k=1:conclusion1}\\
r_{w_{0}}^{n+1}(F) R_{w_{0}+1^{\prime}+e_{i}}(F) = R_{1^{\prime}+e_{i}}(R_{w_{0}+e_{0}}(F),R_{w_{0}+e_{1}}(F),\ldots,R_{w_{0}+e_{n}}(F)) \ \ \ \text{if}\ i>0\label{k=1:conclusion2}
\end{numcases}

\end{theorem}

Here we give a sketch of the main idea adopted in the proof of induction base.
We start with a subresultant of the input polynomials with higher order (i.e.,
$w_{0}+1^{\prime}+e_{i}$). First, we use the multi-linearity of determinant
polynomial to rewrite it into a determinant polynomial of a polynomial set
consisting of the given polynomials and the subresultants with lower orders.
The tool we adopt in the rewriting process is the observation that every
subresultant belongs to the ideal generated by the input polynomials. Then we
employ the notable properties of determinant polynomials discovered in
Subsection \ref{ssec:detp_properties} to further simplify the determinant
polynomial obtained in the previous step, which will produce the result we want.

\subsubsection{Proof of Eq. \eqref{k=1:conclusion1}}

\begin{proof}
[Proof of Eq. \eqref{k=1:conclusion1}] Note that
\begin{align*}
R_{1^{\prime}}(R_{w_{0}+e_{0}},R_{w_{0}+e_{1}},\ldots,R_{w_{0}+e_{n}})
={\operatorname*{dp}}\ (R_{w_{0}+e_{1}},\ldots,R_{w_{0}+e_{n}})
\end{align*}
Let $\delta=w_{0}=(\delta_{1},\ldots,\delta_{n})$. Thus we only need to show
\begin{align*}
r_{\delta}^{n-1} \ R_{\delta+1^{\prime}} ={\operatorname*{dp}}\ (R_{\delta
+e_{1}},\ldots,R_{\delta+e_{n}})
\end{align*}
Let $G_{k,j}=x^{j}F_{k}$ and $H_{k,j}=(G_{k,j},\ldots,G_{k,0}).$ Then we have
\begin{align*}
R_{\delta+1^{\prime}}\ =\  &  \operatorname*{dp}(x^{\delta_{0}}F_{0}%
,\ldots,x^{0}F_{0},\ \ldots,\ x^{\delta_{n}}F_{n},\ldots,x^{0}F_{n})\\
=\  &  \operatorname*{dp}(H_{0,\delta_{0}},\ \ldots,\ H_{n,\delta_{n}})
\end{align*}
and for $i\ge1$,
\begin{align*}
R_{\delta+e_{i}}=  &  \left\{
\begin{array}
[c]{rl}%
{{\operatorname*{dp}}}(G_{0,\delta_{0}},H_{0,\delta_{0}-1},\ldots
,H_{i-1,\delta_{i-1}-1},H_{i,\delta_{i}},H_{i+1,\delta_{i+1}-1},\ldots
,H_{n,\delta_{n}-1}) & \text{if}\ \ d_{i}+\delta_{i}=d_{0}+\delta_{0};\\
{{\operatorname*{dp}}}(\ \ \ \ \ \ \ \ H_{0,\delta_{0}-1},\ldots
,H_{i-1,\delta_{i-1}-1},H_{i,\delta_{i}},H_{i+1,\delta_{i+1}-1},\ldots
,H_{n,\delta_{n}-1}) & \text{otherwise}%
\end{array}
\right.
\end{align*}
%Note that $\overline{\delta+e_{i}}=\overline{\delta%
%}+(1,e_{i})$ or $\overline{\delta}+(0,e_{i})$, which depends on the
%actual value of $\overline{\delta}$ and $d$.
By Proposition \ref{prop:ci} and Corollary \ref{cor:dp}, $R_{\delta+e_{i}}$
can be written as the linear combination of $G_{i,j}$'s, i.e.,
\begin{align}
\label{equ:coeff_S+ei}R_{\delta+e_{i}}\ =\ \sum_{\substack{0\le t\le n}%
}^{}\sum_{j=0}^{\delta_{t}-1}c_{tj}^{(i)}G_{t,j}+c_{i\delta_{i}}%
^{(i)}G_{i,\delta_{i}}+\left\{
\begin{array}
[c]{ll}%
c_{0\delta_{0}}^{(0)}G_{0,\delta_{0}} & \text{if}\ \ d_{i}+\delta_{i}%
=d_{0}+\delta_{0};\\
0 & \text{otherwise}%
\end{array}
\right.
\end{align}
where
\begin{align}
\label{equ:015}c_{i\delta_{i}}^{(i)}=\left\{
\begin{array}
[c]{ll}%
(-1)^{\sigma_{i}+1}{\operatorname*{pcdp}}(G_{0,\delta_{0}},H_{0,\delta_{0}%
-1},\ldots,H_{n,\delta_{n}-1}) & \text{if}\ \ d_{i}+\delta_{i}=d_{0}%
+\delta_{0};\\
(-1)^{\sigma_{i}+1}{\operatorname*{pcdp}}(\ \ \ \ \ \ \ \ H_{0,\delta_{0}%
-1},\ldots,H_{n,\delta_{n}-1}) & \text{otherwise}%
\end{array}
\right.
\end{align}
and $\sigma_{i}=\delta_{i}+\cdots+\delta_{n}$. From the definition of
subresultant, we have
\begin{align*}
r_{\delta}={\operatorname*{pcdp}}(H_{0,\delta_{0}-1},\ldots,H_{n,\delta_{n}%
-1})
\end{align*}
Since $\deg G_{0,\delta_{0}}>\deg G_{i,j}$ for $i\ge0$ and $0\le j\le
\delta_{i}-1$, we simplify the first case of \eqref{equ:015} and obtain
\begin{align}
\label{equ:016}{\operatorname*{pcdp}}(G_{0,\delta_{0}},H_{0,\delta_{0}%
-1},\ldots,H_{n,\delta_{n}-1})\ =\ {\operatorname*{pcdp}}(G_{0,\delta_{0}%
})\cdot{\operatorname*{pcdp}}(H_{0,\delta_{0}-1},\ldots,H_{n,\delta_{n}-1})
=a_{0d_{0}}\cdot r_{\delta}=r_{\delta}%
\end{align}
Then substituting \eqref{equ:016} into the \eqref{equ:015}, we have
\begin{align}
c_{i\delta_{i}}^{(i)}=(-1)^{\sigma_{i}+1}r_{\delta}%
\end{align}
Hence
\begin{align*}
\prod_{i=1}^{n}c_{i\delta_{i}}^{(i)} =\prod_{i=1}^{n}(-1)^{\sigma_{i}+1}
r_{\delta} =r_{\delta}^{n}\prod_{i=1}^{n}(-1)^{\sigma_{i}+1}%
\end{align*}


\bigskip

\noindent We introduce the short-hands $\psi=\prod_{i=1}^{n}(-1)^{\sigma
_{i}+1}$ and $\rho=r_{\delta}^{n}$. Then $\prod_{i=1}^{n}c_{i\delta_{i}}%
^{(i)}=\psi\cdot\rho$. Now we consider the product of $\psi$, $\rho$ and
$R_{\delta+1^{\prime}}$ and carry out the following simplification:
\begin{align*}
&  \psi\ \rho\ R_{\delta+1^{\prime}}\\
=\  &  \prod_{i=1}^{n}c_{i\delta_{i}}^{(i)}{\operatorname*{dp}} (H_{0,\delta
_{0}},H_{1,\delta_{1}},\ldots,H_{n,\delta_{n}})\\
=\  &  \prod_{i=1}^{n}c_{i\delta_{i}}^{(i)}{\operatorname*{dp}}(H_{0,\delta
_{0}},\underset{H_{1,\delta_{1}}}{\underbrace{G_{1,\delta_{1}},H_{1,\delta
_{1}-1}}},\ldots,\underset{H_{n,\delta_{n}}}{\underbrace{G_{n,\delta_{n}%
},H_{n,\delta_{n}-1}}})\\
=\  &  \psi\ \prod_{i=1}^{n}c_{i\delta_{i}}^{(i)}{\operatorname*{dp}}
(H_{0,\delta_{0}},H_{1,\delta_{1}-1},\ldots,H_{n,\delta_{n}-1},G_{1,\delta
_{1}},\ldots,G_{n,\delta_{n}})\ \ \ \,\text{by reordering the arguments
of}\ {\operatorname*{dp}}\\
=\  &  \psi\ {\operatorname*{dp}} (H_{0,\delta_{0}},H_{1,\delta_{1}-1}%
,\ldots,H_{n,\delta_{n}-1},c_{1\delta_{1}}^{(1)}G_{1,\delta_{1}}%
,\ldots,c_{n\delta_{n}}^{(n)}G_{n,\delta_{n}}) \ \ \ \ \text{by\ pushing}%
\ c_{i\delta_{i}}^{(i)}\ \text{into} \ {\operatorname*{dp}}\\
=\  &  \psi\ {\operatorname*{dp}}(H_{0,\delta_{0}},H_{1,\delta_{1}-1}%
,\ldots,H_{n,\delta_{n}-1},R_{\delta+e_{1}},\ldots,R_{\delta+e_{n}})
\ \ \ \ \text{using}\ \text{}\ \eqref{equ:coeff_S+ei}\\
=\  &  \psi\ {\operatorname*{dp}}(\underset{H_{0,\delta_{0}}%
}{\underbrace{G_{0,\delta_{0}},H_{0,\delta_{0}-1}}},H_{1,\delta_{1}-1}%
,\ldots,H_{n,\delta_{n}-1},R_{\delta+e_{1}},\ldots,R_{\delta+e_{n}})\\
=\  &  \psi\ a_{0d_{0}}\ {\operatorname*{dp}}(H_{0,\delta_{0}-1}%
,H_{1,\delta_{1}-1},\ldots,H_{n,\delta_{n}-1},R_{\delta+e_{1}},\ldots
,R_{\delta+e_{n}}) \ \ \ \ \text{by}\ \text{Lemma\ \ref{lemma:002}-(2)}\\
=\  &  \psi\ {\operatorname*{dp}}(H_{0,\delta_{0}-1},H_{1,\delta_{1}-1}%
,\ldots,H_{n,\delta_{n}-1},R_{\delta+e_{1}},\ldots,R_{\delta+e_{n}})
\ \ \ \ \text{since}\ a_{0d_{0}}=1\
\end{align*}
The cancellation of $\psi$ from the first and last expressions yields
\begin{align*}
\rho\ R_{\delta+1^{\prime}} \ =\ {\operatorname*{dp}}(H_{0,\delta_{0}%
-1},H_{1,\delta_{1}-1},\ldots,H_{n,\delta_{n}-1},R_{\delta+e_{1}}%
,\ldots,R_{\delta+e_{n}})
\end{align*}
Partitioning the polynomial matrix in the right-hand side of the above
equation, we have $\rho R_{\delta+1^{\prime}} =\operatorname*{dp}(B_{1},B_{2})
$ where
\begin{align*}
B_{1}=(H_{0,\delta_{0}-1},H_{1,\delta_{1}-1},\ldots,H_{n,\delta_{n}%
-1}),\ \ B_{2}=(R_{\delta+e_{1}},\ldots,R_{\delta+e_{n}})
\end{align*}
Denote $\max(\deg B_{1})$, $\max(\deg B_{2})$ and the number of polynomials in
$B_{1}$ by $m_{1}$, $m_{2}$ and $\#B_{1}$, respectively. Then we have
$m_{1}=d_{0}+\delta_{0}-1$, $m_{2}=d_{0}-|\delta|-1$ and $\#B_{1}=\delta
_{0}+|\delta|$. It follows that
\[
m_{2}=m_{1}-\#B_{1}
\]
By Lemma \ref{lemma:002}-(2), we have
\begin{align}
\label{equ:017}r_{\delta}^{n}\ R_{\delta+1^{\prime}} \ =\rho R_{\delta
+1^{\prime}}=\ {\operatorname*{pcdp}}(B_{1})\cdot\operatorname*{dp}(B_{2})
\end{align}
%In order to have an explicit expression of $\pcdp(B_{1})$, we carry out the following deduction and obtain
It is easy to see that
\begin{align*}
\operatorname*{dp}(B_{1}) \ =\ \operatorname*{dp}(H_{0,\delta_{0}%
-1},H_{1,\delta_{1}-1},\ldots,H_{n,\delta_{n}-1}) \ =\ R_{\delta}%
\end{align*}
which immediately implies that ${\operatorname*{pcdp}}(B_{1})=r_{\delta}$.
Substituting it into \eqref{equ:017} yields
\begin{align*}
r_{\delta}^{n} R_{\delta+1^{\prime}} \ =\ {\operatorname*{pcdp}}(B_{1}%
)\cdot\operatorname*{dp}(B_{2}) \ =\ r_{\delta}\cdot\operatorname*{dp}%
(R_{\delta+e_{1}},\ldots,R_{\delta+e_{n}})
\end{align*}
It follows that
\begin{align*}
r_{\delta}^{n-1} R_{\delta+1^{\prime}} \ =\ \operatorname*{dp}(R_{\delta
+e_{1}},\ldots,R_{\delta+e_{n}})
\end{align*}
Eq. \eqref{k=1:conclusion1} is proved.
\end{proof}

\subsubsection{Proof of Eq. \eqref{k=1:conclusion2}}

\begin{proof}
[Proof of Eq. \eqref{k=1:conclusion2}] Without loss of generality, we only
prove the case when $i=1$, that is,
\[
R_{1^{\prime}+e_{1}}(R_{w_{0}+e_{0}},R_{w_{0}+e_{1}},\ldots,R_{w_{0}+e_{n}})
\ =\ {\operatorname*{dp}}(R_{w_{0}+e_{0}},xR_{w_{0}+e_{1}},R_{w_{0}+e_{1}%
},\ldots,R_{w_{0}+e_{n}})
\]
The other cases of $i>0$ can be proved with the same procedure.

\medskip

Let $\delta=w_{0}=(\delta_{1},\ldots,\delta_{n})$. Thus we only need to show
that
\begin{align*}
r_{\delta}^{n+1} R_{\delta+1^{\prime}+e_{1}} ={\operatorname*{dp}}%
(R_{\delta+e_{0}},xR_{\delta+e_{1}},R_{\delta+e_{1}},\ldots,R_{\delta+e_{n}})
\end{align*}
Let $G_{k,j}=x^{j}F_{k}$ and $H_{k,j}=(G_{k,j},\ldots,G_{k,0})$. Then we have
\begin{align*}
R_{\delta+1^{\prime}+e_{1}} =\left\{
\begin{array}
[c]{rl}%
{{\operatorname*{dp}}}(G_{0,\delta_{0}+1},H_{0,\delta_{0}},H_{1,\delta_{1}%
+1},H_{2,\delta_{2}},\ldots,H_{n,\delta_{n}}) & \text{if}\ \ d_{1}+\delta
_{1}=d_{0}+\delta_{0};\\
{{\operatorname*{dp}}}(\ \ \ \ \ \ \ \ \ \ \ H_{0,\delta_{0}},H_{1,\delta
_{1}+1},H_{2,\delta_{2}},\ldots,H_{n,\delta_{n}}) & \text{otherwise}%
\end{array}
\right.
\end{align*}
Recall \eqref{equ:coeff_S+ei}, that is, for $i\ge1$,
\begin{align}
\label{equ:027}R_{\delta+e_{i}}\ =\ \sum_{\substack{0\le t\le n}}^{}\sum
_{j=0}^{\delta_{t}-1}c_{tj}^{(i)}G_{t,j}+c_{i\delta_{i}}^{(i)}G_{i,\delta_{i}%
}+\left\{
\begin{array}
[c]{ll}%
c_{0\delta_{0}}^{(0)}G_{0,\delta_{0}} & \text{if}\ \ d_{i}+\delta_{i}%
=d_{0}+\delta_{0};\\
0 & \text{otherwise}%
\end{array}
\right.
\end{align}
where
\begin{align}
\label{equ:019}c_{i\delta_{i}}^{(i)}=(-1)^{\sigma_{i}+1}r_{\delta}%
\end{align}
and $\sigma_{i}=\delta_{i}+\cdots+\delta_{n}$.

By \eqref{equ:019}, we have
\begin{align*}
c_{1\delta_{1}}^{(1)}\prod_{i=1}^{n}c_{i\delta_{i}}^{(i)} =(-1)^{\sigma_{1}%
+1}r_{\delta}\cdot\prod_{i=1}^{n}(-1)^{\sigma_{i}+1}r_{\delta} =(-1)^{\sigma
_{1}+1}\cdot r_{\delta}^{n+1}\cdot\prod_{i=1}^{n}(-1)^{\sigma_{i}+1}%
\end{align*}


Again we introduce the short-hands $\psi=(-1)^{\sigma_{1}+1}\prod_{i=1}%
^{n}(-1)^{\sigma_{i}+1}$ and $\rho=r_{\delta}^{n+1}$. Then $c_{1\delta_{1}%
}^{(1)}\prod_{i=1}^{n}c_{i\delta_{i}}^{(i)}=\psi\cdot\rho$. Now we consider
the following two cases for the product of $\psi$, $\rho$ and $R_{\delta
+1^{\prime}+e_{1}}$, depending on whether $d_{1}+\delta_{1}=d_{0}+\delta_{0}$
holds or not. \medskip

\textbf{Case (1)}: $d_{1}+\delta_{1}=d_{0}+\delta_{0}$. In this case,
\begin{align*}
&  \psi\ \rho\ R_{\delta+1^{\prime}+e_{1}}\\
\ =\  &  c_{1\delta_{1}}^{(1)}\prod_{i=1}^{n}c_{i\delta_{i}}^{(i)}%
\ {\operatorname*{dp}}(H_{0,\delta_{0}+1},H_{1,\delta_{1}+1},H_{2,\delta_{2}%
},\ldots,H_{n,\delta_{n}})\\
\ =\  &  c_{1\delta_{1}}^{(1)}\prod_{i=1}^{n}c_{i\delta_{i}}^{(i)}%
\ {\operatorname*{dp}}(H_{0,\delta_{0}+1},\underset{H_{1,\delta_{1}%
+1}}{\underbrace{G_{1,\delta_{1}+1},G_{1,\delta_{1}},H_{1,\delta_{1}-1}}%
},\underset{H_{2,\delta_{2}}}{\underbrace{G_{2,\delta_{2}},H_{2,\delta_{2}-1}%
}},\ldots,\underset{H_{n,\delta_{n}}}{\underbrace{G_{n,\delta_{n}}%
,H_{n,\delta_{n}-1}}})\\
\ =\  &  \psi\ c_{1\delta_{1}}^{(1)}\prod_{i=1}^{n}c_{i\delta_{i}}%
^{(i)}\ {\operatorname*{dp}}(H_{0,\delta_{0}+1},H_{1,\delta_{1}-1}%
,H_{2,\delta_{2}-1},\ldots,H_{n,\delta_{n}-1},G_{1,\delta_{1}+1},
G_{1,\delta_{1}},G_{2,\delta_{2}},\ldots,G_{n,\delta_{n}})\\
&  \text{(by reordering the arguments of}\ {\operatorname*{dp})}\\
\ =\  &  \psi\ {\operatorname*{dp}}(H_{0,\delta_{0}+1},H_{1,\delta_{1}%
-1},H_{2,\delta_{2}-1},\ldots,H_{n,\delta_{n}-1},c_{1\delta_{1}}%
^{(1)}G_{1,\delta_{1}+1}, c_{1\delta_{1}}^{(1)}G_{1,\delta_{1}},c_{2\delta
_{2}}^{(2)}G_{2,\delta_{2}},\ldots,c_{n\delta_{n}}^{(n)}G_{n,\delta_{n}})\\
&  \text{(by\ pushing}\ c_{i\delta_{i}}^{(i)}\ \text{into}
\ {\operatorname*{dp)}}\\
\ =\  &  \psi\ {\operatorname*{dp}} (H_{0,\delta_{0}+1},H_{1,\delta_{1}%
-1},H_{2,\delta_{2}-1},\ldots,H_{n,\delta_{n}-1},xR_{\delta+e_{1}}%
,R_{\delta+e_{1}},R_{\delta+e_{2}},\ldots,R_{\delta+e_{n}})\ \ \ \ \text{by}%
\ \eqref{equ:027}\\
\ =\  &  \psi\ {\operatorname*{dp}} (\underset{H_{0,\delta_{0}+1}%
}{\underbrace{G_{0,\delta_{0}+1},G_{0,\delta_{0}},H_{0,\delta_{0}-1}}%
},H_{1,\delta_{1}-1},H_{2,\delta_{2}-1},\ldots,H_{n,\delta_{n}-1}%
,xR_{\delta+e_{1}},R_{\delta+e_{1}},R_{\delta+e_{2}},\ldots,R_{\delta+e_{n}%
})\\
\ =\  &  \psi\ a_{0d_{0}}^{2} {\operatorname*{dp}} (H_{0,\delta_{0}%
-1},H_{1,\delta_{1}-1},H_{2,\delta_{2}-1},\ldots,H_{n,\delta_{n}-1}%
,xR_{\delta+e_{1}},R_{\delta+e_{1}},R_{\delta+e_{2}},\ldots,R_{\delta+e_{n}%
})\ \ \ \ \text{by}\ \text{Lemma\ \ref{lemma:002}-(2)}\\
\ =\  &  \psi\ {\operatorname*{dp}} (H_{0,\delta_{0}-1},H_{1,\delta_{1}%
-1},H_{2,\delta_{2}-1},\ldots,H_{n,\delta_{n}-1},xR_{\delta+e_{1}}%
,R_{\delta+e_{1}},R_{\delta+e_{2}},\ldots,R_{\delta+e_{n}}%
)\ \ \ \ \text{since}\ a_{0d_{0}}=1
\end{align*}


\medskip

\textbf{Case (2)}: $d_{1}+\delta_{1}\neq d_{0}+\delta_{0}$.
\begin{align*}
&  \psi\ \rho\ R_{\delta+1^{\prime}+e_{1}}\\
\ =\  &  c_{1\delta_{1}}^{(1)}\prod_{i=1}^{n}c_{i\delta_{i}}^{(i)}%
{\operatorname*{dp}} (H_{0,\delta_{0}},H_{1,\delta_{1}+1},H_{2,\delta_{2}%
},\ldots,H_{n,\delta_{n}})\\
\ =\  &  c_{1\delta_{1}}^{(1)}\prod_{i=1}^{n}c_{i\delta_{i}}^{(i)}%
{\operatorname*{dp}} (H_{0,\delta_{0}},\underset{H_{1,\delta_{1}%
+1}}{\underbrace{G_{1,\delta_{1}+1},G_{1,\delta_{1}},H_{1,\delta_{1}-1}}%
},\underset{H_{2,\delta_{2}}}{\underbrace{G_{2,\delta_{2}},H_{2,\delta_{2}-1}%
}},\ldots,\underset{H_{n,\delta_{n}}}{\underbrace{G_{n,\delta_{n}}%
,H_{n,\delta_{n}-1}}})\\
\ =\  &  \psi\ c_{1\delta_{1}}^{(1)}\prod_{i=1}^{n}c_{i\delta_{i}}%
^{(i)}{\operatorname*{dp}}(H_{0,\delta_{0}},H_{1,\delta_{1}-1},H_{2,\delta
_{2}-1},\ldots,H_{n,\delta_{n}-1},G_{1,\delta_{1}+1},G_{1,\delta_{1}%
},G_{2,\delta_{2}},\ldots,G_{n,\delta_{n}})\\
&  \text{(by reordering the arguments of}\ {\operatorname*{dp}})\\
\ =\  &  \psi\ {\operatorname*{dp}}(H_{0,\delta_{0}},H_{1,\delta_{1}%
-1},H_{2,\delta_{2}-1},\ldots,H_{n,\delta_{n}-1},c_{1\delta_{1}}%
^{(1)}G_{1,\delta_{1}+1},c_{1\delta_{1}}^{(1)}G_{1,\delta_{1}},c_{2\delta_{2}%
}^{(2)}G_{2,\delta_{2}},\ldots,c_{n\delta_{n}}^{(n)}G_{n,\delta_{n}})\\
&  \text{(by\ pushing}\ c_{i\delta_{i}}^{(i)}\ \text{into}
\ {\operatorname*{dp}})\\
\ =\  &  \psi\ {\operatorname*{dp}}(H_{0,\delta_{0}},H_{1,\delta_{1}%
-1},H_{2,\delta_{2}-1},\ldots,H_{n,\delta_{n}-1},xR_{\delta+e_{1}}%
,R_{\delta+e_{1}},R_{\delta+e_{2}},\ldots,R_{\delta+e_{n}})\ \ \ \ \text{by}%
\ \eqref{equ:027}\\
\ =\  &  \psi\ {\operatorname*{dp}}(\underset{H_{0,\delta_{0}}%
}{\underbrace{G_{0,\delta_{0}},H_{0,\delta_{0}-1}}},H_{1,\delta_{1}%
-1},H_{2,\delta_{2}-1},\ldots,H_{n,\delta_{n}-1},xR_{\delta+e_{1}}%
,R_{\delta+e_{1}},R_{\delta+e_{2}},\ldots,R_{\delta+e_{n}})\\
\ =\  &  \psi\ a_{0d_{0}}\ {\operatorname*{dp}}(H_{0,\delta_{0}-1}%
,H_{1,\delta_{1}-1},H_{2,\delta_{2}-1},\ldots,H_{n,\delta_{n}-1}%
,xR_{\delta+e_{1}},R_{\delta+e_{1}},R_{\delta+e_{2}},\ldots,R_{\delta+e_{n}%
})\ \ \ \ \text{by}\ \text{Lemma\ \ref{lemma:002}-(2)}\\
\ =\  &  \psi\ {\operatorname*{dp}}(H_{0,\delta_{0}-1},H_{1,\delta_{1}%
-1},H_{2,\delta_{2}-1},\ldots,H_{n,\delta_{n}-1},xR_{\delta+e_{1}}%
,R_{\delta+e_{1}},R_{\delta+e_{2}},\ldots,R_{\delta+e_{n}}%
)\ \ \ \ \text{since}\ a_{0d_{0}}=1
\end{align*}
It can be seen that regardless of whether $d_{1}+\delta_{1}=d_{0}+\delta_{0}$
holds or not, the following equation is always true:
\begin{align*}
\psi\ \rho\ R_{\delta+1^{\prime}+e_{1}} \ =\ \psi\ {\operatorname*{dp}%
}(H_{0,\delta_{0}-1},H_{1,\delta_{1}-1},H_{2,\delta_{2}-1},\ldots
,H_{n,\delta_{n}-1},xR_{\delta+e_{1}},R_{\delta+e_{1}},R_{\delta+e_{2}}%
,\ldots,R_{\delta+e_{n}})
\end{align*}
The cancellation of $\psi$ in the left-hand side and right-hand side of above
expressions yields
\begin{align}
\label{equ:020}\rho\ R_{\delta+1^{\prime}+e_{1}} \ =\ {\operatorname*{dp}%
}(H_{0,\delta_{0}-1},H_{1,\delta_{1}-1},H_{2,\delta_{2}-1},\ldots
,H_{n,\delta_{n}-1},xR_{\delta+e_{1}},R_{\delta+e_{1}},R_{\delta+e_{2}}%
,\ldots,R_{\delta+e_{n}})
\end{align}
Partitioning the polynomial matrix in the right-hand side of \eqref{equ:020},
we have $\rho\ R_{\delta+1^{\prime}+e_{1}}={\operatorname*{dp}}(B_{1},B_{2}),
$ where
\begin{align*}
B_{1}\ =\ (H_{0,\delta_{0}-1},H_{1,\delta_{1}-1},H_{2,\delta_{2}-1}%
,\ldots,H_{n,\delta_{n}-1}), \ \ \ B_{2}\ =\ (xR_{\delta+e_{1}},R_{\delta
+e_{1}},R_{\delta+e_{2}},\ldots,R_{\delta+e_{n}})
\end{align*}
Denote $\max(\deg B_{1})$, $\max(\deg B_{2})$ and the number of polynomials in
$B_{1}$ by $m_{1}$, $m_{2}$ and $\#B_{1}$, respectively. Then we have
$m_{1}=d_{0}+\delta_{0}-1$, $m_{2}=d_{0}-|\delta|$ and $\#B_{1}=|\delta
|+\delta_{0}$. It follows that
\begin{align*}
m_{2}\ =\ m_{1}-\#B_{1}+1
\end{align*}
By Lemma \ref{lemma:002}-(1), we have
\begin{align}
\label{equ:021}r_{\delta}^{n+1}\ R_{\delta+1^{\prime}+e_{1}}\ =\rho
\ R_{\delta+1^{\prime}+e_{1}}=\ {\operatorname*{dp}}(\operatorname*{dp}%
(B_{1}),B_{2})
\end{align}
It easy to know
\begin{align}
\label{equ:022}\operatorname*{dp}(B_{1}) \ =\ \operatorname*{dp}%
(H_{0,\delta_{0}-1},H_{1,\delta_{1}-1},\ldots,H_{n,\delta_{n}-1})
\ =\ R_{\delta}%
\end{align}
The substitution of \eqref{equ:022} into \eqref{equ:021} yields%
\begin{align*}
r_{\delta}^{n+1}\ R_{\delta+1^{\prime}+e_{1}} \ =\  &  {\operatorname*{dp}}
(R_{\delta},xR_{\delta+e_{1}},R_{\delta+e_{1}},\ldots,R_{\delta+e_{n}})
\end{align*}
Eq. \eqref{k=1:conclusion2} is proved.
\end{proof}

\subsection{Inductive step (i.e. from $k=j$ to $k=j+1$)}

Similarly to the simplification as done in the case $k=1$ (i.e., Theorem \ref{thm:k=1}), we let $k^{\prime}=(k,\ldots,k)$. Again by using \eqref{equ:v:denpen:i} and \eqref{equ:epsilon:denpen:i}, we  provide an equivalent theorem of Main Result (Theorem \ref{thm:main}) for $k\geq2$, which facilitates the proof.

\begin{theorem}
[Main Result for $k\geq2$]\label{thm:k>=2} Assume Theorem \ref{thm:main} holds
for $v=j^{\prime}+e_{i}$ (i.e., $k=j$), that is,
\begin{align}
r_{w_{0}}^{(n+1)j-2} R_{w_{0}+j^{\prime}}  &  =R_{j^{\prime}}(R_{w_{0}+e_{0}%
},\ldots,R_{w_{0}^{\prime}+e_{n}})\label{equ:theorem:k=j_1}\\
r_{w_{0}}^{(n+1)j} R_{w_{0}+j^{\prime}+e_{i}}  &  =R_{j^{\prime}+e_{i}%
}(R_{w_{0}+e_{0}},\ldots,R_{w_{0}+e_{n}}) \ \ \text{for $i>0$}
\label{equ:theorem:k=j_2}%
\end{align}
where $n+1=\# F$. Then the theorem is true for $v=j^{\prime}+1^{\prime}+e_{i}$
(i.e., $k=j+1$), that is,
\begin{align}
r_{w_{0}}^{(n+1)(j+1)-2} R_{w_{0}+j^{\prime}+1^{\prime}}  &  =R_{j^{\prime
}+1^{\prime}}(R_{w_{0}+e_{0}},\ldots,R_{w_{0}+e_{n}}%
)\label{equ:theorem:k=j+1_1}\\
r_{w_{0}}^{(n+1)(j+1)} R_{w_{0}+j^{\prime}+1^{\prime}+e_{i}}  &
=R_{j^{\prime}+1^{\prime}+e_{i}}(R_{w_{0}+e_{0}}, \ldots,R_{w_{0}+e_{n}})
\ \ \text{for $i>0$} \label{equ:theorem:k=j+1_2}%
\end{align}

\end{theorem}

Here we give a sketch of the main idea adopted in the inductive proof. In the
inductive step, we first use the relationship proved in the induction base to
write the subresultant of the input polynomials with higher order (i.e.,
$w_{0}+j^{\prime}+1^{\prime}+e_{i}$) into a determinant polynomial of
subresultants of order $w_{0}+j^{\prime}+e_{\tau}$, where $\tau=0,\ldots,n$.
This is the most key step in the inductive proof. Then we use the same
techniques (i.e., multi-linearity of determinant polynomial and the membership
of subresultant in the ideal generated by the defining polynomials) as in the
induction base to simplify the nested subresultants in the right-hand side of
\eqref{equ:theorem:k=j+1_1} and \eqref{equ:theorem:k=j+1_2}. The only
difference from the induction base is that the defining polynomials of the
internal subresultant is, by induction, subresultants in the previous step.
Again we employ the properties of determinant polynomials in Subsection
\ref{ssec:detp_properties} to further simplify the determinant polynomial
obtained in the previous step, which will produce the result we want.

\label{subsec:inductive}

\subsubsection{Proof of Eq. \eqref{equ:theorem:k=j+1_1} from Eqs.
\eqref{equ:theorem:k=j_1}--\eqref{equ:theorem:k=j_2}}

The goal of this part is to prove
\begin{align*}
r_{w_{0}}^{(n+1)(j+1)-2} R_{w_{0}+j^{\prime}+1^{\prime}}=R_{j^{\prime
}+1^{\prime}}(R_{w_{0}+e_{0}},\ldots,R_{w_{0}+e_{n}})
\end{align*}
with \eqref{equ:theorem:k=j_1} and \eqref{equ:theorem:k=j_2} assumed to be true.

\begin{proof}
[Proof of Eq. \eqref{equ:theorem:k=j+1_1}] By Lemma \ref{thm:k=1}, we get
\begin{align*}
r_{w_{0}+j^{\prime}}^{n-1} \ R_{w_{0}+j^{\prime}+1^{\prime}}  &
\ =\ R_{1^{\prime}}(R_{w_{0}+j^{\prime}+e_{0}},\ldots,R_{w_{0}+j^{\prime
}+e_{n}})\\
&  \ =\ {\operatorname*{dp}}(R_{w_{0}+j^{\prime}+e_{1}},\ldots,R_{w_{0}%
+j^{\prime}+e_{n}})
\end{align*}
Let $\delta=w_{0}=(\delta_{1},\ldots,\delta_{n})$. Thus we only need to show
that
\begin{equation}
\label{equ:equivalent1}{\operatorname*{dp}}(R_{\delta+j^{\prime}+e_{1}}%
,\ldots,R_{\delta+j^{\prime}+e_{n}}) \ =\ r_{\delta}^{2-(n+1)(j+1)}
r_{\delta+j^{\prime}}^{n-1}\ R_{j^{\prime}+1}(R_{\delta+e_{0}},\ldots
,R_{\delta+e_{n}})
\end{equation}


By induction (i.e. \eqref{equ:theorem:k=j_2}), for $i>0$,
\begin{align}
\label{equ:uij_1}r_{\delta}^{(n+1)j}\ R_{\delta+j^{\prime}+e_{i}}%
=R_{j^{\prime}+e_{i}}(R_{\delta+e_{0}},\ldots,R_{\delta+e_{n}})
\end{align}
Let $\hat{G}_{i,s}=x^{s}R_{\delta+e_{i}}$ and $\hat{H}_{i,s}=(\hat{G}%
_{i,s},\ldots,\hat{G}_{i,0}$). Then we have
\begin{align*}
R_{j^{\prime}+e_{i}}(R_{\delta+e_{0}},\ldots,R_{\delta+e_{n}}) \ =\  &
\operatorname*{dp}(\hat{H}_{0,j-1},\ldots,\hat{H}_{i-1,j-1},\hat{H}_{i,j}%
,\hat{H}_{i+1,j-1},\ldots,\hat{H}_{n,j-1})
\end{align*}
for $i>0$. Thus
\begin{align*}
r_{\delta}^{(n+1)j}\ R_{\delta+j^{\prime}+e_{i}}  &  \ =\ \operatorname*{dp}%
(\hat{H}_{0,j-1},\ldots,\hat{H}_{i-1,j-1},\hat{H}_{i,j},\hat{H}_{i+1,j-1}%
,\ldots,\hat{H}_{n,j-1})
\end{align*}
By Corollary \ref{cor:dp}, we deduce that
\begin{align}
\label{equ:uij_2}r_{\delta}^{(n+1)j}\ R_{\delta+j^{\prime}+e_{i}}  &
\ =\ \sum_{t=0}^{n}\sum_{h=0}^{j-1}u_{th}^{(i)}\hat{G}_{t,h}+u_{ij}^{(i)}%
\hat{G}_{i,j}%
\end{align}
for $i>0$. Note that
\begin{align}
u_{ij}^{(i)}  &  =(-1)^{(n+1-i)j}\ {\operatorname*{pcdp}}%
(\ \ \ \ \ \ \ \ \ \ \hat{H}_{0,j-1}, \ldots, \hat{H}_{i-1,j-1},\hat
{H}_{i,j-1},\hat{H}_{i+1,j-1},\ldots,\hat{H}_{n,j-1})\nonumber\\
&  =(-1)^{(n+1-i)j}\ {\operatorname*{pcdp}}(\underset{\hat{H}_{0,j-1}%
}{\underbrace{\hat{G}_{0,j-1},\hat{H}_{0,j-2}}},\ldots,\hat{H}_{i-1,j-1}%
,\hat{H}_{i,j-1},\hat{H}_{i+1,j-1},\ldots,\hat{H}_{n,j-1})\nonumber\\
&  =(-1)^{(n+1-i)j}\ {\operatorname*{pcdp}}(\hat{G}_{0,j-1})\ \cdot
{\operatorname*{pcdp}}(\hat{H}_{0,j-2},\hat{H}_{1,j-1},\ldots,\hat
{H}_{i-1,j-1},\hat{H}_{i,j-1},\hat{H}_{i+1,j-1},\ldots,\hat{H}_{n,j-1}%
)\nonumber\\
&  =(-1)^{(n+1-i)j}\ r_{\delta}\cdot r_{j^{\prime}}(R_{\delta+e_{0}}%
,\ldots,R_{\delta+e_{n}}) \label{equ:010}%
\end{align}
In addition, by the assumption \eqref{equ:theorem:k=j_1}, we have
\begin{align}
r_{\delta}^{(n+1)j-2} r_{\delta+j^{\prime}}  &  =r_{j^{\prime}}(R_{\delta
+e_{0}},\ldots,R_{\delta+e_{n}}) \label{equ:009}%
\end{align}
The substitution of \eqref{equ:009} into \eqref{equ:010} yields
\begin{align}
\label{equ:uij_3}u_{ij}^{(i)} \ =\ (-1)^{(n+1-i)j}\ r_{\delta} \cdot
r_{\delta}^{(n+1)j-2}\ r_{\delta+j^{\prime}} \ =\ (-1)^{(n+1-i)j}\ r_{\delta
}^{(n+1)j-1}\ r_{\delta+j^{\prime}}%
\end{align}
By \eqref{equ:uij_3}, we have
\begin{align*}
\prod_{i=1}^{n}u_{ij}^{(i)} \ =\ \prod_{i=1}^{n}\left(  (-1)^{(n+1-i)j}
r_{\delta}^{(n+1)j-1} r_{\delta+j^{\prime}}\right)  \ =\ \left(  \prod
_{i=1}^{n}(-1)^{(n+1-i)j}\right)  \cdot(r_{\delta}^{(n+1)j-1} r_{\delta
+j^{\prime}})^{n}%
\end{align*}
Now we introduce the short-hands $\psi_{j} =\prod_{i=1}^{n}(-1)^{(n+1-i)j}$
and $\rho_{j} =r_{\delta}^{(n+1)j}$. Then
\[
\prod_{i=1}^{n}u_{ij}^{(i)}\ =\ \psi_{j}\cdot(\rho_{j}r_{\delta}^{-1}
r_{\delta+j^{\prime}})^{n}%
\]
Next we consider the product of $\psi_{j}$, $(\rho_{j}r_{\delta}^{-1}
r_{\delta+j^{\prime}})^{n}$ and $R_{j^{\prime}+1}(R_{\delta+e_{0}}%
,\ldots,R_{\delta+e_{n}})$ and carry out the following simplification:
\begin{align*}
&  \psi_{j}\ \ (\rho_{j}r_{\delta}^{-1} r_{\delta+j^{\prime}})^{n}%
\ R_{j^{\prime}+1}(R_{\delta+e_{0}},\ldots,R_{\delta+e_{n}})\\
\ =\  &  \prod_{i=1}^{n}u_{ij}^{(i)}\ \operatorname*{dp}(\hat{H}_{0,j-1}%
,\hat{H}_{1,j},\ldots,\hat{H}_{n,j})\\
\ =\  &  \prod_{i=1}^{n}u_{ij}^{(i)}\ \operatorname*{dp}(\hat{H}%
_{0,j-1},\underset{\hat{H}_{1,j}}{\underbrace{\hat{G}_{1,j},\hat{H}_{1,j-1}}%
},\ldots,\underset{\hat{H}_{n,j}}{\underbrace{\hat{G}_{n,j},\hat{H}_{n,j-1}}%
})\\
\ =\  &  \psi_{j}\ \prod_{i=1}^{n}u_{ij}^{(i)}\ \operatorname*{dp}(\hat
{H}_{0,j-1},\hat{H}_{1,j-1},\ldots,\hat{H}_{n,j-1},\hat{G}_{1,j}\ldots,\hat
{G}_{n,j})\ \ \text{by reordering the arguments of}\ {\operatorname*{dp}}\\
\ =\  &  \psi_{j}\ {\operatorname*{dp}}(\hat{H}_{0,j-1},\hat{H}_{1,j-1}%
,\ldots,\hat{H}_{n,j-1},u_{1j}^{(1)}\hat{G}_{1,j},\ldots,u_{nj}^{(n)}\hat
{G}_{n,j})\ \ \text{by\ pushing}\ u_{ij}^{(i)}\ \text{into}
\ {\operatorname*{dp}}\\
\ =\  &  \psi_{j}\ {\operatorname*{dp}}(\hat{H}_{0,j-1},\hat{H}_{1,j-1}%
,\ldots,\hat{H}_{n,j-1},\rho_{j}\ R_{\delta+j^{\prime}+e_{1}},\ldots,\rho
_{j}\ R_{\delta+j^{\prime}+e_{n}}) \ \ \text{by}\ \eqref{equ:uij_2}\\
\ =\  &  \psi_{j}\ \rho_{j}^{n}\ {\operatorname*{dp}}(\hat{H}_{0,j-1},\hat
{H}_{1,j-1},\ldots,\hat{H}_{n,j-1},R_{\delta+j^{\prime}+e_{1}},\ldots,
R_{\delta+j^{\prime}+e_{n}}) \ \ \text{by\ pulling\ out }\rho_{j}%
\ \text{out\ of }{\operatorname*{dp}}%
\end{align*}
The cancellation of $\psi_{j}\rho_{j}^{n}$ from the first and last expressions
yields
\begin{align}
r_{\delta+j^{\prime}}^{n}\ r_{\delta}^{-n}\ R_{j^{\prime}+1}(R_{\delta+e_{0}%
},\ldots,R_{\delta+e_{n}}) \ =\ {\operatorname*{dp}}(\hat{H}_{0,j-1},\hat
{H}_{1,j-1},\ldots,\hat{H}_{n,j-1},R_{\delta+j^{\prime}+e_{1}},\ldots,
R_{\delta+j^{\prime}+e_{n}}) \label{eq:partitioned_matrix}%
\end{align}
Partitioning the polynomial matrix in the right-hand side of
\eqref{eq:partitioned_matrix}, we have
\begin{align}
\label{equ:003}r_{\delta+j^{\prime}}^{n}\ r_{\delta}^{-n}\ R_{j^{\prime
}+1^{\prime}}(R_{\delta+e_{0}},\ldots,R_{\delta+e_{n}}) ={\operatorname*{dp}%
}(B_{1},B_{2})
\end{align}
where
\begin{align*}
B_{1}=(\hat{H}_{0,j-1},\hat{H}_{1,j-1},\ldots,\hat{H}_{n,j-1}),\qquad
B_{2}=(R_{\delta+j^{\prime}+e_{1}},\ldots, R_{\delta+j^{\prime}+e_{n}})
\end{align*}
Denote $\max(\deg B_{1})$, $\max(\deg B_{2})$ and the number of polynomials in
$B_{1}$ by $m_{1}$, $m_{2}$ and $\#B_{1}$, respectively. Then we have
$m_{1}=d_{0}-|\delta|+j-1$, $m_{2}=d_{0}-|\delta|-nj-1$ and $\#B_{1}=(n+1)j$.
It follows that
\begin{align*}
m_{2}=m_{1}-\#B_{1}%
\end{align*}
By Lemma \ref{lemma:002}-(2), we derive the following
\begin{align}
\label{equ:023}{\operatorname*{dp}}(B_{1},B_{2}) = {\operatorname*{pcdp}%
}(B_{1})\cdot{\operatorname*{dp}}(B_{2})
\end{align}
In order to have an explicit expression of ${\operatorname*{pcdp}}(B_{1})$, we
carry out the following deduction:
\begin{align*}
\operatorname*{dp}(B_{1})\ =\  &  \operatorname*{dp}(\ \ \ \ \ \ \ \ \ \ \hat
{H}_{0,j-1},\hat{H}_{1,j-1},\ldots,\hat{H}_{n,j-1})\\
\ =\  &  \operatorname*{dp}(\underset{\hat{H}_{0,j-1}}{\underbrace{\hat
{G}_{0,j-1},\hat{H}_{0,j-2}}},\hat{H}_{1,j-1},\ldots,\hat{H}_{n,j-1})\\
\ =\  &  { \operatorname*{pcdp}}(\hat{G}_{0,j-1})\cdot\operatorname*{dp}%
(\hat{H}_{0,j- 2},\hat{H}_{1,j-1},\ldots,\hat{H}_{n,j-1}%
)\ \ \ \ \ \text{by\ Lemma\ \ref{lemma:002}-(2)}\\
\ =\  &  {\operatorname*{pcdp}}(\hat{G}_{0,j-1})\cdot R_{j^{\prime}}%
(R_{\delta},\ldots,R_{\delta^{\prime}+e_{n}})\\
\ =\  &  r_{\delta}\cdot r_{ \delta}^{(n+1)j-2} R_{\delta+j^{\prime}}
\ \ \ \ \ \text{by\ the\ assumption}\ \eqref{equ:theorem:k=j_1}\\
\ =\  &  r_{\delta}^{(n+1)j -1} R_{\delta+j^{\prime}}%
\end{align*}
which implies ${\operatorname*{pcdp}}(B_{1})=r_{\delta}^{(n+1)j-1}
r_{\delta+j^{\prime}}$. After substituting it into \eqref{equ:023}, we have
\begin{align}
\label{equ:025}\operatorname*{dp}(B_{1},B_{2}) \ =\ r_{\delta}^{(n+1)j-1}%
\ r_{\delta+j^{\prime}}\cdot\operatorname*{dp}(R_{\delta+j^{\prime}+e_{1}%
},\ldots,R_{\delta+j^{\prime}+e_{n}})
\end{align}
Combining \eqref{equ:003} and \eqref{equ:025}, we have
\begin{align*}
r_{\delta+j^{\prime}}^{n}\ r_{\delta}^{-n}\ R_{j^{\prime}+1^{\prime}%
}(R_{\delta+e_{0}},\ldots,R_{\delta+e_{n}}) \ =\ r_{\delta}^{(n+1)j-1}%
\ r_{\delta+j^{\prime}}\ {\operatorname*{dp}}(R_{\delta+j^{\prime}+e_{1}%
},\ldots, R_{\delta+j^{\prime}+e_{n}})
\end{align*}
which can be simplified into \eqref{equ:equivalent1} after pushing the
coefficients to the left-hand side. The proof of Eq.
\eqref{equ:theorem:k=j+1_1} is completed.
\end{proof}

\subsubsection{Proof of Eq. \eqref{equ:theorem:k=j+1_2} from Eqs.
\eqref{equ:theorem:k=j_1}--\eqref{equ:theorem:k=j_2}}

The goal of this part is to prove
\begin{align}
\label{equ:3.3.2need_to_proof}r_{w_{0}}^{(n+1)(j+1)}\ R_{w_{0}+j^{\prime
}+1^{\prime}+e_{i}} \ =\ R_{j^{\prime}+1^{\prime}+e_{i}}(R_{w_{0}+e_{0}%
},\ldots,R_{w_{0}+e_{n}}), \ \ i=1,\ldots,n
\end{align}
with \eqref{equ:theorem:k=j_1} and \eqref{equ:theorem:k=j_2} assumed to be true.

\begin{proof}
[Proof of Eq. \eqref{equ:theorem:k=j+1_2} ] Without loss of generality, we
proceed to prove it is true for the case when $i=1$. The other cases can be
proved with the same procedure.

By using Theorem \ref{thm:k=1} with $w_{0}$ specified as $w_{0}+j^{\prime}$,
we have
\begin{align*}
r_{w_{0}+j^{\prime}}^{n+1} R_{w_{0}+j^{\prime}+1^{\prime}+e_{1}}  &
\ =\ R_{1^{\prime}+e_{1}}(R_{w_{0}+j^{\prime}+e_{0}},\ldots,R_{w_{0}%
+j^{\prime}+e_{n}})\\
&  \ =\ {\operatorname*{dp}}(R_{w_{0}+j^{\prime}},xR_{w_{0}+j^{\prime}+e_{1}%
},R_{w_{0}+j^{\prime}+e_{1}},\ldots,R_{w_{0}+j^{\prime}+e_{n}})
\end{align*}
Let $\delta=w_{0}=(\delta_{1},\ldots,\delta_{n})$. Thus we only need to show
the following equivalence of \eqref{equ:3.3.2need_to_proof}:
\begin{align}
\label{equ:equivalent2} &  {\operatorname*{dp}}(R_{\delta+j^{\prime}%
},xR_{\delta+j^{\prime}+e_{1}},R_{\delta+j^{\prime}+e_{1}},\ldots
,R_{\delta+j^{\prime}+e_{n}}) \ =\ r_{\delta}^{-(n+1)(j+1)} r_{\delta
+j^{\prime}}^{n+1}\ R_{j^{\prime}+1^{\prime}+e_{1}}(R_{\delta+e_{0}}%
,\ldots,R_{\delta+e_{n}})
\end{align}
Let $\hat{G}_{i,s}=x^{s}R_{\delta+e_{i}}$ and $\hat{H}_{i,s}=(\hat{G}%
_{i,s},\ldots,\hat{G}_{i,0}$). Then we have
\begin{align*}
R_{j^{\prime}+1^{\prime}+e_{1}}(R_{\delta+e_{0}},\ldots,R_{\delta+e_{n}%
})=\operatorname*{dp}(\hat{H}_{0,j},\hat{H}_{1,j+1},\hat{H}_{2,j},\ldots
,\hat{H}_{n,j})
\end{align*}
Recall \eqref{equ:uij_1}, \eqref{equ:uij_2} and \eqref{equ:uij_3}. We further
deduce that
\begin{align}
\label{equ:026}r_{\delta}^{(n+1)j} R_{\delta+j^{\prime}+e_{i}} =\sum_{t=0}%
^{n}\sum_{h=0}^{j-1}u_{th}^{(i)}\hat{G}_{t,h}+u_{ij}^{(i)}\hat{G}_{i,j},
\ \ i=1\ldots,n
\end{align}
where $u_{ij}^{(i)}=(-1)^{(n+1-i)j} r_{\delta}^{(n+1)j-1} r_{\delta+j^{\prime
}}$. It follows that
\begin{align*}
u_{1j}^{(1)}\cdot\prod_{i=1}^{n}u_{ij}^{(i)} \ =\  &  (-1)^{nj} r_{\delta
}^{(n+1)j-1} r_{\delta+j^{\prime}} \cdot\left(  \prod_{i=1}^{n}(-1)^{(n+1-i)j}
r_{\delta}^{(n+1)j-1} r_{\delta+j^{\prime}}\right) \\
\ =\  &  (-1)^{nj}\left(  \prod_{i=1}^{n}(-1)^{(n+1-i)j}\right)
\cdot(r_{\delta}^{(n+1)j-1} r_{\delta+j^{\prime}})^{n+1}%
\end{align*}
Now we introduce the short-hands $\psi_{j} =(-1)^{nj}\prod_{i=1}%
^{n}(-1)^{(n+1-i)j}$ and $\rho_{j} = r_{\delta}^{(n+1)j}$. Then
\[
u_{1j}^{(1)}\cdot\prod_{i=1}^{n}u_{ij}^{(i)} \ =\ \psi_{j} \cdot(\rho_{j}
r_{\delta}^{-1} r_{\delta+j^{\prime}})^{n+1}%
\]
Next we consider the product of $\psi_{j}$, $(\rho_{j} r_{\delta}^{-1}
r_{\delta+j^{\prime}})^{n+1}$ and $R_{j^{\prime}+1^{\prime}+e_{1}}%
(R_{\delta+e_{0}},\ldots,R_{\delta+e_{n}})$ and carry out the following
simplification:
\begin{align*}
&  \psi_{j} \cdot(\rho_{j} r_{\delta}^{-1} r_{\delta+j^{\prime}})^{n+1}
R_{j^{\prime}+1^{\prime}+e_{1}}(R_{\delta+e_{0}},\ldots,R_{\delta+e_{n}})\\
\ =\  &  u_{1j}^{(1)}\prod_{i=1}^{n}u_{ij}^{(i)}\ \ \operatorname*{dp}(\hat
{H}_{0,j},\hat{H}_{1,j+1},\hat{H}_{2,j},\ldots,\hat{H}_{n,j})\\
\ =\  &  u_{1j}^{(1)}\prod_{i=1}^{n}u_{ij}^{(i)}\ \ \operatorname*{dp}(\hat
{H}_{0,j},\underset{\hat{H}_{1,j+1}}{\underbrace{\hat{G}_{1,j+1},\hat{G}%
_{1,j},\hat{H}_{1,j-1}}},\underset{\hat{H}_{2,j}}{\underbrace{\hat{G}%
_{2,j},\hat{H}_{2,j-1}}},\ldots,\underset{\hat{H}_{n,j}}{\underbrace{\hat
{G}_{n,j},\hat{H}_{n,j-1}}})\\
\ =\  &  \psi_{j}\cdot u_{1j}^{(1)}\prod_{i=1}^{n}u_{ij}^{(i)}%
\ \ \operatorname*{dp}(\hat{H}_{0,j},\hat{H}_{1,j-1},\hat{H}_{2,j-1}%
,\ldots,\hat{H}_{n,j-1},\hat{G}_{1,j+1},\hat{G}_{1,j},\hat{G}_{2,j}%
,\ldots,\hat{G}_{n,j})\\
&  \text{(by reordering the arguments of}\ {\operatorname*{dp}})\\
\ =\  &  \psi_{j}\ \operatorname*{dp}(\hat{H}_{0,j},\hat{H}_{1,j-1},\hat
{H}_{2,j-1},\ldots,\hat{H}_{n,j-1},u_{1j}^{(1)}\hat{G}_{1,j+1},u_{1j}%
^{(1)}\hat{G}_{1,j},u_{2j}^{(2)}\hat{G}_{2,j},\ldots,u_{nj}^{(n)}\hat{G}%
_{n,j})\\
&  \text{(by\ pushing}\ u_{ij}^{(i)}\ \text{into} \ {\operatorname*{dp}})\\
\ =\  &  \psi_{j}\ {\operatorname*{dp}}(\hat{H}_{0,j},\hat{H}_{1,j-1},\hat
{H}_{2,j-1},\ldots,\hat{H}_{n,j-1},\rho_{j}\ xR_{\delta+j^{\prime}+e_{1}}%
,\rho_{j}\ R_{\delta+j^{\prime}+e_{1}},\rho_{j}\ R_{\delta+j^{\prime}+e_{2}%
},\ldots,\rho_{j}\ R_{\delta+j^{\prime}+e_{n}})\\
&  \text{(by}\ \eqref{equ:026})\\
\ =\  &  \psi_{j}\ \rho_{j}^{n+1}\ {\operatorname*{dp}}(\hat{H}_{0,j},\hat
{H}_{1,j-1},\hat{H}_{2,j-1},\ldots,\hat{H}_{n,j-1},xR_{\delta+j^{\prime}%
+e_{1}},R_{\delta+j^{\prime}+e_{1}}, R_{\delta+j^{\prime}+e_{2}},\ldots,
R_{\delta+j^{\prime}+e_{n}})\\
&  \text{(by\ pulling\ out }\rho_{j}\ \text{out\ of }{\operatorname*{dp}})
\end{align*}
The cancellation of $\psi_{j}\rho_{j}^{n+1}$ from the first and last
expressions yields
\begin{align}
&  r_{\delta}^{-n-1}r_{\delta+j^{\prime}}^{n+1}R_{j^{\prime}+1^{\prime}+e_{1}%
}(R_{\delta+e_{0}},\ldots,R_{\delta+e_{n}})\nonumber\\
\ =\  &  {\operatorname*{dp}}(\hat{H}_{0,j},\hat{H}_{1,j-1},\hat{H}%
_{2,j-1},\ldots,\hat{H}_{n,j-1},xR_{\delta+j^{\prime}+e_{1}},R_{\delta
+j^{\prime}+e_{1}}, R_{\delta+j^{\prime}+e_{2}},\ldots,R_{\delta+j^{\prime
}+e_{n}}) \label{eq:partitioned_matrix2}%
\end{align}
Partitioning the polynomial matrix in the right-hand side of
\eqref{eq:partitioned_matrix2}, we have
\begin{align}
\label{equ:007}r_{\delta}^{-n-1}r_{\delta+j^{\prime}}^{n+1}R_{j^{\prime
}+1^{\prime}+e_{1}}(R_{\delta+e_{0}},\ldots,R_{\delta+e_{n}}%
)={\operatorname*{dp}}(B_{1},B_{2})
\end{align}
where
\begin{align*}
B_{1}=(\hat{H}_{0,j},\hat{H}_{1,j-1},\hat{H}_{2,j-1},\ldots,\hat{H}%
_{n,j-1}),\ \ \ B_{2}=(xR_{\delta+j^{\prime}+e_{1}},R_{\delta+j^{\prime}%
+e_{1}}, R_{\delta+j^{\prime}+e_{2}},\ldots, R_{\delta+j^{\prime}+e_{n}})
\end{align*}
Denote $\max(\deg B_{1})$, $\max(\deg B_{2})$ and the number of polynomials in
$B_{1}$ by $m_{1}$, $m_{2}$ and $\#B_{1}$, respectively. Then we have
$m_{1}=d_{0}-|\delta|+j$, $m_{2}=d_{0}-|\delta|-nj$ and $\#B_{1}=(n+1)j+1$. It
follows that
\begin{align*}
m_{2}=m_{1}-\#B_{1}+1
\end{align*}
By Lemma \ref{lemma:002}-(1), we derive the following
\begin{align}
\label{equ:028}\operatorname*{dp}(B_{1},B_{2}) =\operatorname*{dp}%
({\operatorname*{dp}}(B_{1}),B_{2})
\end{align}
In order to have an explicit expression of $\operatorname*{dp}(B_{1})$, we
carry out the following deduction:
\begin{align}
\label{equ:029}\operatorname*{dp}(B_{1}) =  &  \operatorname*{dp}(\hat
{H}_{0,j},\hat{H}_{1,j-1},\hat{H}_{2,j-1},\ldots,\hat{H}_{n,j-1})\nonumber\\
=  &  \operatorname*{dp}(\underset{\hat{H}_{0,j}}{\underbrace{\hat{G}%
_{0,j},\hat{G}_{0,j-1},\hat{H}_{0,j-2}}},\hat{H}_{1,j-1},\hat{H}%
_{2,j-1},\ldots,\hat{H}_{n,j-1})\nonumber\\
=  &  {\operatorname*{pcdp}}(\hat{G}_{0,j},\hat{G}_{0,j-1})\cdot
\operatorname*{dp}(\hat{H}_{0,j-2},\hat{H}_{1,j-1},\hat{H}_{2,j-1},\ldots
,\hat{H}_{n,j-1})\ \ \ \ \ \text{by\ Lemma\ \ref{lemma:002}-(2)}\nonumber\\
=  &  r_{\delta}^{2}\cdot R_{j^{\prime}}(R_{\delta},\ldots,R_{\delta^{\prime
}+e_{n}})\nonumber\\
=  &  r_{\delta}^{2}\cdot r_{\delta}^{(n+1)j-2} R_{\delta+j^{\prime}%
}\ \ \ \ \ \text{by\ the\ assumption}\ \eqref{equ:theorem:k=j_1}\nonumber\\
=  &  r_{\delta}^{(n+1)j}\ R_{\delta+j^{\prime}}%
\end{align}
After substituting \eqref{equ:029} into \eqref{equ:028}, we have
\begin{align}
\operatorname*{dp}(B_{1},B_{2})  &  = \operatorname*{dp}\ ( r_{\delta
}^{(n+1)j} R_{\delta+j^{\prime}},\ \ \ xR_{\delta+j^{\prime}+e_{1}},
R_{\delta+j^{\prime}+e_{1}},R_{\delta+j^{\prime}+e_{2}},\ldots,R_{\delta
+j^{\prime}+e_{n}})\nonumber\\
&  = r_{\delta}^{(n+1)j}\ {\operatorname*{dp}}\ (\ R_{\delta+j^{\prime}%
},\ \ xR_{\delta+j^{\prime}+e_{1}}, R_{\delta+j^{\prime}+e_{1}},R_{\delta
+j^{\prime}+e_{2}},\ldots,R_{\delta+j^{\prime}+e_{n}}) \label{equ:008}%
\end{align}
Combining \eqref{equ:007} and \eqref{equ:008}, we have
\begin{align*}
&  r_{\delta}^{-n-1}r_{\delta+j^{\prime}}^{n+1}R_{j^{\prime}+1^{\prime}+e_{1}%
}(R_{\delta+e_{0}},\ldots,R_{\delta+e_{n}})\\
=  &  r_{\delta}^{(n+1)j}{\operatorname*{dp}}(R_{\delta+j^{\prime}}%
,xR_{\delta+j^{\prime}+e_{1}}, R_{\delta+j^{\prime}+e_{1}},R_{\delta
+j^{\prime}+e_{2}},\ldots,R_{\delta+j^{\prime}+e_{n}})
\end{align*}
which can be simplified into \eqref{equ:equivalent2} after pushing the
coefficients to the left-hand side. The proof of Eq.
\eqref{equ:theorem:k=j+1_2} is completed.
\end{proof}

\section{Conclusion}

\label{sec:conclusion} In this paper, we present a generalization of the well
known Habicht's theorem to several polynomials, that is, expressing a
subresultant of several polynomials with higher order to the subresultant of
other subresultants with lower orders. With the help of this discovery, we can
identify many non-trivial inherent relationships among subresultants of
several polynomials and thus can explore the nice hidden structure of
subresultants in a more efficient and systematic way.

In the classical subresultant theory, Habicht's theorem has been proved to be
a productive tool for the theory development, from which people discovered the
famous gap structure of subresultant chain for two polynomials. We hope that
the generalized Habicht's theorem can also become a powerful tool for people
to investigate similar structures for subresultants of multiple polynomials.

One may also notice that in the classical Habicht's theorem, in some special
degeneracy cases, the subresultant of two polynomials is proportional to the
pseudo-remainder of other two subresultants, which means the Habicht's theorem
can be stated in a uniform way. However, for the multi-polynomial case, it is
no longer true. That is, the result in \cite{Hong_Yang-2023} and that in the
current paper are independent. Therefore, a natural question is how to
formulate them in a uniform way, which is also worthy of further investigation
in the future.

