\appendix 

\section{On Boolean Implication and Ideal Membership}
\label{sec:polyclaim}

In this appendix, we provide a proof of the folklore result
that being implied by a set of polynomials and being in the ideal
generated by these polynomials is the same in the Boolean setting.

\begin{restatablelem}{\ref{lem:implication-ideal}}[restated]
  Let $g$ be a polynomial and $Q$ be a set of polynomials
  in~$\F[x_1, \ldots, x_n]$, and suppose that $Q$ contains all the
  Boolean axioms. Then it holds that $g$ vanishes on all common roots
  of~$Q$ if and only if $g \in \langle Q \rangle$.
\end{restatablelem}

\begin{proof}
  If $g \in \langle Q \rangle$, then we can write
  $g = \sum_{i} f_i q_i$ for $f_i \in \F[x_1, \ldots, x_n]$ and
  $q_i \in Q$. Observe that $\restrict{\sum_{i} f_i q_i}{\xi} = 0$ for
  any common root $\xi \in \set{0,1}^n$ of $Q$. Hence $g$ vanishes on
  all common roots of $Q$.

  For the other direction, let $\xi = (\xi_1, \xi_2, \ldots, \xi_n)$
  be an element of $\{0,1\}^n$ and write $\indic_\xi$ for the
  multilinear polynomial that evaluates to $1$ on $\xi$ and to $0$ on
  all other elements of $\{0,1\}^n$, that is,
  \begin{equation}
    \indic_\xi(x)
    =
    \prod_{i: \xi_i = 1}x_i
    \prod_{j: \xi_j = 0}(1-x_j)
    \eqperiod
  \end{equation} 
  Clearly, every function $f\colon \{0, 1\}^n \to \F$ can be expressed
  as a multilinear polynomial through the identity
  \begin{equation}
    f
    =
    \sum_{\xi \in \{0, 1\}^n}
    f(\xi)
    \cdot
    \indic_\xi
    \eqcomma
  \end{equation}
  and as the polynomials $\set{\indic_\xi\mid \xi \in \{0, 1\}^n}$
  form a basis of the vector space of multilinear polynomials
  over~$\F[x_1, \ldots, x_n]$, this representation is unique. Let
  $S\subseteq \{0, 1\}^n$ be the set of common roots of the
  polynomials in~$Q$. Since $g$ vanishes on $S$, we may write
  \begin{equation}
    g
    =
    \sum_{\xi \in \{0, 1\}^n\setminus S}
    g(\xi)
    \cdot
    \indic_\xi
    \eqperiod
  \end{equation}
  We now show that if $\xi\in \{0, 1\}^n \setminus S$, then it holds
  that $\indic_\xi\in \langle Q \rangle$. This suffices to prove the
  desired result, as $g$ is then a linear combination of
  polynomials in~$\langle Q \rangle$ and hence is also in
  $\langle Q \rangle$. 

  Let $\xi$ be an element in~$\{0, 1\}^n \setminus S$. Because $S$ is
  the set of common roots of the polynomials in~$Q$, there exists a
  polynomial $q \in Q$ such that $q(\xi) \neq 0$. The polynomial
  $\indic_\xi\cdot (q(\xi))^{-1}q$
  coincides with $\indic_\xi$ on all of $\{0, 1\}^n$, so $\indic_\xi\cdot (q(\xi))^{-1}q = \indic_\xi$ modulo the Boolean axioms. 
  Since~$\langle Q \rangle$ contains both~$\indic_\xi\cdot (q(\xi))^{-1}q$ and the Boolean axioms, it
  follows that $\indic_\xi \in \langle Q \rangle$.
\end{proof}

\section{Random Graphs Are Sparse}
\label{sec:sparsity}


In this appendix we prove \reflem{lem:razborov-sparse}, which is a
quantitative version of Lemma 4.15 in
\cite{Razborov17WidthSemialgebraic}. We make no claim of originality,
but present this result here to make the paper self-contained.


We start by proving the sparsity lemma for graphs sampled from the
\erdosrenyi random graph distribution~$\gndn$ in
\reflem{lem:razborov-sparse-Gnp} and then establish the analogous
result for random regular graphs sampled according to~$\gnd$ in
\reflem{lem:razborov-sparse-Gnd}.

\begin{lemma}[Sparsity lemma for \erdosrenyi random graphs]
  \label{lem:razborov-sparse-Gnp}
  Let $n,d\in \N^+$ and $\epsilon, \delta \in \R^+$ be such that
  $\epsilon \delta = \omega(1/\log n)$.  If $G$ is a graph sampled
  from~$\gndn$, then \aas it is
  $((4d)^{- (1+\delta)(1+\epsilon)/\epsilon}n, \epsilon)$-sparse.
\end{lemma}
\begin{proof}
  Let $\alpha = (4d)^{- (1+\delta)(1+\epsilon)/\epsilon}$ and denote
  by $\eventa$ the event ``$G$ is $(\alpha n, \epsilon)$-sparse''.
  For a set $U\subseteq V$ of size $s$, the random variable
  $|E(G[U])|$ is a sum of $s(s-1)/2$ random indicator variables for
  the edges that are $1$ with probability $d/n$ and $0$ otherwise. We
  apply a union bound over sets of size $s\leq \alpha n$ to conclude
  that
  \begin{subequations}
    \begin{align}
      \Pr[\lnot \eventa]  
      &\leq
        \sum_{\substack{U \subseteq V\\  \setsize{U} \leq \alpha n}}
        \Pr[\setsize{E(G[U])} \geq (1+\epsilon) \setsize{U}] \\
      &\le
        \sum_{s=1}^{\alpha n}
        \binom{n}{s}
        \binom{\frac{s(s-1)}{2}}{(1+\epsilon) s} \cdot
        \left(\frac{d}{n}\right)^{(1+\epsilon) s}   \\
      &\le
        \sum_{s=1}^{\alpha n}
        \left(\frac{en}{s}\right)^s
        \left(\frac{e(s-1)}{2(1+\epsilon) }\right)^{(1+\epsilon) s}
        \cdot
        \left(\frac{d}{n}\right)^{(1+\epsilon) s}  \\
      &\le
        \sum_{s=1}^{\alpha n}
        \exp
        \left(
        - \epsilon s \ln\left(\frac{n}{s}\right) +
        (1+\epsilon) s
        \left(
        \ln
        \left(\frac{e^2d}{2(1+\epsilon)}\right)
        \right)
        \right) \\
      &\le
        \sum_{s=1}^{\alpha n}
        \exp \left( -
        {\delta\epsilon s \ln(n/s)}
        \right) \label{eq:bound-alpha} \\
      &\leq
        o(1)
        \label{eq:bound-epsilon}
        \eqcomma
    \end{align}
  \end{subequations} 
  where for \refeq{eq:bound-alpha} we use that
  $n/s \geq 1/\alpha = (4d)^{(1+\delta)(1+\epsilon)/\epsilon}$ to
  estimate that
  \begin{align}
    (1+\epsilon)
    \left(\ln\left(\frac{e^2d}{2(1+\epsilon)}\right)\right)
    \le
    (1+\epsilon)
    \ln\left({4d}\right)
    =
    \frac{\epsilon  \ln(1/\alpha)}{1+\delta}
    \le
    \frac{\epsilon  \ln(n/s)}{1+\delta}
    \eqcomma
  \end{align}
  and for \refeq{eq:bound-epsilon} we use that
  $\epsilon \delta = \omega(1/\log n)$ and that
  $s\ln(n/s) \geq \ln n + s-1 $ (for $1 \leq s\leq n/e^2$).
\end{proof}

We next prove the sparsity lemma for random regular graphs.  In order
to sample $G$ from $\gnd$ we use the \emph{configuration model}, which
is defined as follows.  Given $n$ and $d$ such that $dn$ is even, we
have a vertex set $V$ of size $n$ and for each vertex $v\in V$ there
is a cell $C_v$ with $d$ elements.  We sample a perfect matching $M$
uniformly from the set $\mathcal{M}_{dn}$ of all possible perfect
matchings of the $dn$ elements and consider the corresponding
multi-graph $G_M = (V,E)$, possibly with parallel edges and loops,
where $(u,v)\in E$ if and only if there exists $(x,y)\in {M}$ such
that $x\in C_u$ and $y\in C_v$.  Since all simple graphs (without
parallel edges or loops) are sampled with the same probability, we can
sample $G$ from $\gnd$ by sampling according to the configuration
model repeatedly until we sample a simple graph.
\begin{theorem}[\cite{MW91AsymptoticEnumeration,Wormald99ModelsRandom}]
  For $d = o(n^{1/2})$, the probability that $G_M$ is simple when $M$
  is sampled uniformly from $\mathcal{M}_{dn}$ is equal to
  \begin{equation*}
    \exp\left(
      - \frac{{d^2 - 1}}{4}
      - \frac{d^3}{12 n}
      + O(d^2/n)
    \right) \eqperiod
  \end{equation*}
\end{theorem}

Let $S_{\ell, q}$ denote the sum of $\ell$ random variables that are
$1$ with probability $q$ and $0$ otherwise.  We argue that we can
bound the probability that a set of vertices $U\subseteq V$ witnesses
that the graph is not sparse by bounding the probability that
$S_{\ell, q}$ is too large.
\begin{claim}\label{claim:Bernoulli}
  For any $s\le n/2$ and $B\in \R^+$, if $U\subseteq V$ is of size $s$
  and $q = s/(n - s)$, it holds that
  \begin{equation*}
    \Pr_{M\sim \mathcal{M}_{dn}}
    [
    \setsize{E(G_M[U])} \geq B
    ]
    \le
    \Pr[S_{ds, q} \geq B] \eqperiod
  \end{equation*}
\end{claim}
\begin{proof}
  To see why this is true, consider the random process in the
  configuration model that matches one by one the elements in the
  cells $C_v$ for all $v\in U$. At each step, there are at most $ds$
  elements in cells $C_v$ where $v\in U$ that are not yet matched, and
  at least $d(n-s)$ elements in cells $C_v$ where $v\not\in U$ that
  are not yet matched.  This implies that at each step the probability
  that we obtain an edge between cells in $U$ is at most
  $ds/d(n-s)=q$. Since at least one element in a cell of $U$ is
  matched at every step, there are at most $ds$ steps in total. Hence
  the claim follows.
\end{proof}

\begin{lemma}[Sparsity lemma for random regular graphs]
  \label{lem:razborov-sparse-Gnd}
  Let $n,d\in \N^+$ and $\epsilon, \delta \in \R^+$ be such that
  $\epsilon \delta = \omega(1/\log n)$ and
  $d^2\le \epsilon \delta \log n$.  If $G$ is a graph sampled
  from~$\gnd$, then \aas it is
  $((8d)^{- (1+\delta)(1+\epsilon)/\epsilon}n, \epsilon)$-sparse.
\end{lemma}

\begin{proof}
  Fix $\epsilon >0$, let $\alpha=(8d)^{-2(1+1/\epsilon)}$, and denote
  by $\eventa$ the event ``$G$ is $(\alpha n, \epsilon)$-sparse''.  We
  want to prove that $G\sim \gnd$ is $(\alpha n, \epsilon)$-sparse
  with probability that goes to $1$ as $n$ goes to infinity.  To this
  end, we prove that if we sample $G$ from the configuration model,
  the probability that it is not $(\alpha n, \epsilon)$-sparse is much
  smaller than the probability that $G$ is a random regular
  graph. More formally, our goal is to prove that
  \begin{align}
    \Pr[\lnot \eventa]
    \cdot
    \exp\left(\frac{d^2 - 1}{4}\right)
    \leq o(1) \eqcomma
  \end{align}
  where we recall that the probability here and in what follows is
  taken over sampling $G$ in the configuration model.  By union bound
  and using \refclaim{claim:Bernoulli} we have that
  \begin{subequations}
    \begin{align}
      \Pr[\lnot \eventa]
      \cdot
      \exp\left(\frac{d^2 - 1}{4}\right)
      &\leq
        \sum_{\substack{U \subseteq V\\ \setsize{U} \leq \alpha n}}
        \Pr[\setsize{E(G[U])} \geq (1+\epsilon) \setsize{U}]
        \cdot
        \exp\left(\frac{d^2 }{4}\right) \\
      &\le
        \sum_{s=1}^{\alpha n}
        \binom{n}{s}
        \Pr[S_{ds, q} \geq (1+\epsilon) s]
        \cdot
        \exp\left(\frac{d^2 }{4}\right) \eqperiod
    \end{align}
  \end{subequations} 
  Our goal is to show that $Pr[S_{ds, q} \geq (1+\epsilon) s]$ is so
  small that it compensates for the other factors. More concretely, we
  wish to show that for $s\leq \alpha n$ it holds that
  \begin{align}\label{eq:smallprob}
    \binom{n}{s}
    \Pr[S_{ds, q} \geq (1+\epsilon) s]  
    &\le
      \exp
      \left(
      -
      {\epsilon \delta s \ln(n/s)}
      \right) \eqcomma
  \end{align}
  from which it follows, since
  $d^2 \le \epsilon \delta \log n \le 2\epsilon \delta \ln n $, that
  \begin{subequations}
    \begin{align}
      \Pr[\lnot \eventa]
      \cdot
      \exp\left(\frac{d^2 - 1}{4}\right)
      &\le
        \sum_{s=1}^{\alpha n}
        \exp
        \left(
        -{\epsilon\delta s \ln(n/s)}
        + \frac{d^2}{4}
        \right) \\
      &\le
        \sum_{s=1}^{\alpha n}
        \exp\left(
        -\frac{\epsilon \delta s \ln(n/s)}{2}
        \right) \\
        &= o(1) \eqcomma
    \end{align}
  \end{subequations} 
  where we use the fact that $\epsilon \delta = \omega(1/\log n)$ and
  that $s\ln(n/s) \geq \ln n + s - 1 $ (for $1 \leq s\leq n/e^2$).

  It remains to show that \refeq{eq:smallprob} holds. This follows
  from the sequence of calculations
  \begin{subequations}
    \begin{align}
      \binom{n}{s}
      \Pr[S_{ds, q} \geq (1+\epsilon) s]
      &\le
        \binom{n}{s}
        \binom{ds}{(1+\epsilon) s}
        \cdot
        \left(\frac{s}{n-s}\right)^{(1+\epsilon) s}   \\
      &\le
        \left(\frac{en}{s}\right)^s
        \left(\frac{eds}{(1+\epsilon)s}\right)^{(1+\epsilon) s}
        \cdot
        \left(\frac{s}{n-s}\right)^{(1+\epsilon) s}  \\
      &\le
        \exp
        \left(-
        \epsilon s \ln \left(\frac{n-s}{s}\right) +
        s +
        (1+\epsilon) s
        \ln\left(\frac{ed}{(1+\epsilon)}\right)
        \right)   \\
      &\le
        \exp \left(-
        \epsilon s \ln \left(\frac{n}{s}\right) +
        (1+\epsilon) s
        \ln\left(\frac{e^2d}{(1+\epsilon)}\right)
        \right) \label{eq:bound-ln}  \\
      &\le
        \exp
        \left(
        - {\epsilon \delta s \ln \left({n}/{s}\right)}
        \right) \label{eq:bound-alphaGnd}
        \eqcomma
    \end{align}
  \end{subequations} 
  where for \refeq{eq:bound-ln} we use that
  $\ln(n/s - 1) \geq \ln(n/s) -1$ (for $s \leq n/2$), and for
  \refeq{eq:bound-alphaGnd} we use that
  $n/s \geq 1/\alpha = (8d)^{-(1+\delta)(1+\epsilon)/\epsilon}$ to
  bound
  \begin{align}
    (1+\epsilon)
    \left(
    \ln\left(\frac{e^2d}{(1+\epsilon)}\right)
    \right)
    \le
    (1+\epsilon)
    \ln\left({8d}\right)
    =
    \frac{\epsilon  \ln(1/\alpha)}{1+\delta}
    \le
    \frac{\epsilon  \ln(n/s)}{1+\delta} \eqperiod
  \end{align}
  This concludes the proof of \reflem{lem:razborov-sparse}.
\end{proof}



\section{\erdosrenyi Graphs Almost Have Small Maximum Degree}
\label{sec:TDelta-small}



In this section we provide a proof of \reflem{lem:TDelta-small-v2}
stating that \erdosrenyi random graphs have small degree except for a
small set of vertices.

\begin{restatablelem}{\ref{lem:TDelta-small-v2}}[restated]
  Let~$G=(V, E)$ be a graph sampled from~$\gndn$ where
  $d=\bigoh{\log n}$.  If $\Delta\geq d$ is such that
  $(\Delta/ed)^\Delta = \littleoh{n}$, then \aas there exists a set
  $\badset_\Delta$ of size at most $(ed/\Delta)^\Delta \cdot 2en$ such
  that the maximum degree in~$G[V\setminus \badset_\Delta]$ is at
  most~$\Delta-1$.
\end{restatablelem}
\begin{proof}
  Let~$\eventa$ denote the event that there exists a
  set~$\badset_\Delta \subseteq V$ of
  size~$\ell = (ed/\Delta)^\Delta \cdot 2en$ such that the maximum
  degree in~$G[V\setminus \badset_\Delta]$ is at most~$\Delta-1$. We
  prove that~$\Pr[\lnot \eventa]= \littleoh{1}$.

  Note that if $\eventa$ does not hold, then, in particular, if we go
  over the vertices of~$G$ in any given fixed order, and remove from
  $G$ any vertex of degree at least $\Delta$ that we encounter, we
  will end up removing at least $\ell$ vertices. Observe further that
  after the removal of $i$ vertices, the probability that a vertex has
  degree at least $\Delta$ is at most
  $\binom{n -i}{\Delta} (d/n)^\Delta$ and is independent of the fact
  that the removed vertices had degree at least $\Delta$.  Therefore,
  by taking a union bound over all sets of size $\ell$, we can bound
  the probability of the event $\eventa$ not holding by
  \begin{subequations}
    \begin{align}
      \Pr[\lnot \eventa] 
      &\leq
        \binom{n}{\ell}
        \prod_{i = 1}^\ell
        \binom{n-i}{\Delta}
        \left(\frac{d}{n}\right)^\Delta \\
      &\leq
        \binom{n}{\ell}
        \left(
        \binom{n}{\Delta}
        \left(
        \frac{d}{n}
        \right)^\Delta
        \right)^\ell \\
      &\leq
        \left(
        \frac{en}{\ell}
        \right)^\ell
        \left(
        \frac{ed}{\Delta}
        \right)^{\Delta\ell}\\
      &= \littleoh{1} \eqcomma \label{eq:last}
    \end{align}
  \end{subequations}
  where for \refeq{eq:last} we use that
  $\ell = 2en \left({ed}/{\Delta}\right)^{\Delta}$ to derive that
  $\left({en}/{\ell}\right)^\ell
  \left({ed}/{\Delta}\right)^{\Delta\ell} = 2^{-\ell}$, and then use
  that $\ell = \littleomega{1}$, which holds since
  $(\Delta/ed)^\Delta = \littleoh{n}$, to conclude
  $2^{-\ell} = \littleoh{1}$. The lemma follows.
\end{proof}











