\section{Our Competitive Analysis Results on $2$ Identical Machines with $k$-Lookahead ($P_2\hspace{0.1cm}|\hspace{0.1cm}{LA}_k \hspace{0.1cm}| \hspace{0.1cm}C_{max}$)}
\subsection{Lower Bound Result}
\begin{theorem}
Let $ALG$ be a deterministic semi-online algorithm for the problem $P_2\hspace{0.1cm}|\hspace{0.1cm}{LA}_k \hspace{0.1cm}| \hspace{0.1cm}C_{max}$. Then there exists an instance $\sigma$ such that \hspace*{0.2cm}  $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{4}{3}$.\\
\end{theorem}
\begin{proof}
We construct an instance $\sigma = \langle J_1, J_2, \ldots, J_n \rangle$, where $p_i=x$ for $1\leq i\leq n-k-1$, $p_i=1$, for $n-k\leq i\leq n-1$, and $p_n=y$. \\\\
Given the instance $\sigma$, we compute $C_{OPT}(\sigma)$ and $C_{ALG}(\sigma)$. When the $(n-k)^{th}$ job arrives, the jobs $J_1, J_2, \ldots, J_{n-k-1}$ have been scheduled, and the processing time $p_{n-k}, p_{n-k+1}, \ldots, p_{n-1}, p_n$ are known. At this time, let the loads of machines $M_1$ and $M_2$ be $l_1$ and $l_2$. We consider the follwing two cases by assuming $l_1\geq l_2$.\\\\
\hspace*{0.4cm}\textbf{Case 1:} $l_1\geq 2l_2$. Consider $p_n=y=k$. We have $C_{ALG}(\sigma)\geq l_1$, while \\ \hspace*{1.6cm} $C_{OPT}(\sigma)=\frac{l_1+l_2+2k}{2}\leq \frac{l_1+(l_1/2)+k}{2}\leq \frac{3l_1+4k}{4}$. Implies,\\\\
\hspace*{1.6cm} $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{4l_1}{3l_1+4k} \rightarrow \frac{4}{3}$, for large $n$.\\\\
\hspace*{0.3cm} \textbf{Case 2:} $l_1 < 2l_2$. Consider $p_n=y=2l_1-l_2$. We have $C_{ALG}(\sigma)\geq \hspace*{1.9cm} l_2+p_n=2l_1$, while \\   
\hspace*{1.8cm} $C_{OPT}(\sigma)=\frac{l_1+l_2+k+2l_1-l_2}{2}\leq \frac{3l_1+k}{2}$. Implies,\\\\
\hspace*{1.8cm} $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{4l_1}{3l_1+k} \rightarrow \frac{4}{3}$, for large $n$. \hfill\(\Box\)\\
\end{proof}
