\textbf{Research Question:} \textit{How much lookahead is sufficient to achieve a upper bound of $\frac{4}{3}$ on the CR for $P_2\hspace{0.1cm}|\hspace{0.1cm}{LA}_k \hspace{0.1cm}| \hspace{0.1cm}C_{max}$?}\\\\
In the following section, we will address the above research question.
\subsection{An Optimal Semi-online Algorithm with $1$-lookahead : 2-${LA}_1$}
We design a deterministic semi-online algorithm named 2-${LA}_1$ for $2$ identical parallel machines setting by considering a lookahead of size $1$. We prove that algorithm 2-${LA}_1$ is optimal for the problem $P_2\hspace*{0.1cm|\hspace*{0.1cm}{LA}_1 \hspace{0.1cm}|\hspace{0.1cm}C_{max}}$ and has a upper bound of $\frac{4}{3}$ on the CR. We present algorithm 2-${LA}_1$ in \textbf{Algorithm 1}.\\
\begin{algorithm}
\caption{2-${LA}_1$}
\begin{algorithmic}
\scriptsize
\STATE Initially, $l_1=l_2=0$ \\
\STATE When a new job $J_{i}$ arrives, $p_i$ and $p_{i+1}$ are known.\\
%\STATE \hspace*{0.2cm} BEGIN\\
\STATE FOR $i=1$ to $n-1$\\
\STATE \hspace*{0.2cm} BEGIN\\
\STATE \hspace*{0.5cm} IF $(l_1+p_i)\leq \frac{2}{3}\cdot (l_1+l_2+p_i+p_{i+1})$  \\
\STATE \hspace*{0.8cm} THEN assign job $J_i$ to machine $M_1$ \\
\STATE \hspace*{0.8cm} UPDATE $l_1=l_1+p_i$\\
\STATE \hspace*{0.5cm} ELSE \\
\STATE \hspace*{0.8cm} Assign job $J_i$ to machine $M_2$ \\
\STATE \hspace*{0.8cm} UPDATE $l_2=l_2+p_i$\\
\STATE \hspace*{0.2cm} END\\
\STATE $l_{min}\leftarrow \{l_1, l_2\}$\\
\STATE Assign job $J_n$ to machine $M_j$ for which $l_j=l_{min}$, where $j=\{1, 2\}$\\
\STATE UPDATE $l_j=l_j+p_i$\\
\STATE UPDATE $l_1$, $l_2$\\
\STATE Return \hspace*{0.3cm} $C_{2-{LA}_1}=\max\{l_1, l_2\}$
\end{algorithmic}
\end{algorithm}\\
Algorithm 2-${LA}_1$ considers the EPI $p_{i+1}$ for efficient scheduling of each incoming job $J_i$. The objective is to show that $k=1$ is sufficient to achieve an improved CR over the best-known upper bound of $\frac{3}{2}$ on the CR. Algorithm 2-${LA}_1$ imbalances the current total load between machines $M_1$ and $M_2$ such that $l_1\leq 2\cdot l_2$ and the final maximum load of any machine is not more than $\frac{2}{3}\cdot \sum_{i=1}^{n}{p_i}$, or $p_{max}$.\\
In Theorem 2, we prove that algorithm 2-${LA}_1$ has a CR of at least $\frac{4}{3}$ for  $P_2\hspace*{0.1cm|\hspace*{0.1cm}{LA}_1 \hspace{0.1cm}|\hspace{0.1cm}C_{max}}$.\\
\begin{theorem}
There exists an instance $\sigma$ of the problem $P_2\hspace{0.1cm}|\hspace{0.1cm}{LA}_1 \hspace{0.1cm}| \hspace{0.1cm}C_{max}$ such that $\frac{C_{2-{LA}_1}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{4}{3}$.
\end{theorem}
\begin{proof}
Consider an instance $\sigma$ with a sequence of $n$ independent jobs, where $p_i=1$, for $1\leq i\leq n-3$, $p_{n-2}=n$, $p_{n-1}=2n+3$, and $p_n=2n$.\\\\
Initially, the load $l_1=l_2=0$. In $\sigma$, jobs are given one by one in order, and each job $J_i$ from $i=1$ to $n-1$ satisfies the condition $l_1+p_i \leq \frac{2}{3}\cdot (l_1+l_2+p_i+p_{i+1})$. Therefore, algorithm 2-${LA}_1$ schedules each incoming job $J_i$ to machine $M_1$, where $1\leq i\leq n-1$.\\
We now have $l_1=4n$ and $l_2=0$. Algorithm 2-${LA}_1$ assigns the last job $J_n$ to the current least loaded machine $M_2$. Hence, $C_{2-{LA}_1}(\sigma)\geq 4n$, while $C_{OPT}=3n$. Therefore, $\frac{{C_{2-{LA}_1}(\sigma)}}{{C_{OPT}(\sigma)}}\geq \frac{4}{3}$. \hfill\(\Box\)
\end{proof}
\subsection{Upper Bound Result}
Before proving the upper bound on the CR of algorithm 2-${LA}_1$, we consider some practically-significant problem instances. We show by following lemmas that algorithm 2-${LA}_1$ is at most $\frac{4}{3}$-competitive for the considered instances of $P_2\hspace*{0.1cm|\hspace*{0.1cm}{LA}_1 \hspace{0.1cm}|\hspace{0.1cm}C_{max}}$.\\
\begin{lemma}
Let $\sigma_1$ be an instance of $P_2\hspace{0.1cm}|\hspace{0.1cm}{LA}_1 \hspace{0.1cm}| \hspace{0.1cm}C_{OPT}$, where $p_i=x$, $\forall J_i$, and $x\geq 1$.  Algorithm 2-${LA}_1$ is such that $\frac{C_{2-{LA}_1}(\sigma_1)}{C_{max}(\sigma_1)}\leq \frac{4}{3}$.
\end{lemma}
\begin{proof}
Let us consider $n$ jobs in $\sigma_1$. Given that $\sum_{i=1}^{n}{p_i}=n\cdot x$ as $p_i=x$, $\forall J_i$. Irrespective of $n$ is even or odd, algorithm 2-${LA}_1$ assigns $\lfloor \frac{2n}{3} \rfloor$ jobs to machine $M_1$ and $\lceil \frac{n}{3} \rceil$ jobs to machine $M_2$. Therefore, $C_{2-{LA}_1}(\sigma_1)\leq \frac{2n}{3}\cdot x$. If $n$ is even, algorithm $OPT$ schedules $\frac{n}{2}$ jobs to each of the machines, and incurs $C_{OPT}(\sigma_1)=\frac{n}{2}\cdot x$. Therefore, $\frac{C_{2-{LA}_1}(\sigma_1)}{C_{OPT}(\sigma_1)}\leq \frac{4}{3}$. \\\\
If $n$ is odd, algorithm $OPT$ assigns $\lceil \frac{n}{2} \rceil$ jobs to one machine and the remaining jobs to the other, incurring $C_{OPT}(\sigma_1)=\lceil \frac{n}{2} \rceil \cdot x$, while $C_{2-{LA}_1}(\sigma_1)\leq \frac{2n}{3}\cdot x$.\\ Therefore, $\frac{C_{2-{LA}_1}(\sigma_1)}{C_{OPT}(\sigma_1)}\leq \frac{4}{3}$. \hfill\(\Box\)\\
\end{proof}
\textbf{Corollary 2.1.} \textit{Let $\sigma_1$ consists of $n$ jobs, where $n=6x$, $x\geq 1$, and $p_i=1$, $\forall i$. \hspace*{2.3cm}Then $\frac{C_{2-{LA}_1}(\sigma_1)}{C_{OPT}(\sigma_1)}\leq \frac{4}{3}$}.\\\\
\textbf{Remark 1:} No algorithm can outperform Graham's LS strategy for scheduling a sequence of equal length jobs in $2$-identical machine setting. Therefore, LS algorithm is optimal for $\sigma_1$. \\\\
\begin{theorem}
Let $\sigma$ be an instance of $P_2\hspace{0.1cm}|\hspace{0.1cm}{LA}_1 \hspace{0.1cm}| \hspace{0.1cm}C_{max}$. Algorithm 2-${LA}_1$ is such that $\frac{C_{2-{LA}_1}(\sigma)}{C_{OPT}(\sigma)}\leq \frac{4}{3}$ for all $\sigma$.
\end{theorem}
\begin{proof}
We use the method of contradiction to prove the theorem. \\
Assume that there exists an instance $\sigma$ with minimum number of jobs, which contradicts the theorem, where $\sigma=\langle J_1, J_2, \ldots , J_t\rangle$. Implies, \\\\ \hspace*{4.2cm}$\frac{C_{2-{LA}_1}(\sigma)}{C_{OPT}(\sigma)} > \frac{4}{3}$. \\\\
Suppose, in the schedule generated by algorithm 2-${LA}_1$ for $\sigma$, job $J_x$ is the last job that completes its execution and $x<t$. Therefore, the instance $\sigma_1=\langle J_1, J_2, \ldots , J_x\rangle$ makes $C_{2-{LA}_1}(\sigma_1)=C_{2-{LA}_1}(\sigma)$, while $C_{OPT}(\sigma_1) < C_{OPT}(\sigma)$.\\\\ Implies, 
\hspace*{0.2cm} $\frac{C_{2-{LA}_1}(\sigma_1)}{C_{OPT}(\sigma_1)} > \frac{C_{2-{LA}_1}(\sigma)}{C_{OPT}(\sigma)} > \frac{4}{3}$. \\\\
This conveys, $\sigma_1$ is the smallest counterexample with minimum number of jobs, which contradicts our assumption on minimality of $\sigma$ with $t$ jobs. Hence, job $J_x$ does not exist and the instance $\sigma$ is the smallest counterexample in terms of number of jobs such that $\frac{C_{2-{LA}_1}(\sigma)}{C_{OPT}(\sigma)} > \frac{4}{3}$.\\ Therefore, for all other instances $\sigma^{'}$ with $t-1$ jobs, $\frac{C_{2-{LA}_1}(\sigma^{'})}{C_{OPT}(\sigma^{'})} \leq \frac{4}{3}$.\\\\
Algorithm 2-${LA}_1$ imbalances the total load on machines $M_1$ and $M_2$ such that $l_1\geq l_2$ and $l_1\leq \frac{2}{3}\cdot \sum_{i=1}^{t-1}{p_i}$. Therefore, we have $\frac{C_{2-{LA}_1}(\sigma^{'})}{C_{OPT}(\sigma^{'})} \leq \frac{4}{3}$. Clearly, the inclusion and scheduling of job $J_t$ makes $\frac{C_{2-{LA}_1} (\sigma)}{C_{OPT}(\sigma)} > \frac{4}{3}$.\\\\
Prior to scheduling $J_t$, we have $l_{max}=\frac{2}{3}\cdot \sum_{i=1}^{t-1}{p_i}$ and $l_{min}=\frac{1}{3}\cdot \sum_{i=1}^{t-1}{p_i}$.\\\\ Algorithm 2-${LA}_1$ schedules $J_t$ on $M_j$ with $l_j=l_{min}$. Implies, \\\\
\hspace*{2.2cm} $l_{min}+p_t > \frac{2}{3}\cdot \sum_{i=1}^{t}{p_i}$\\
$\implies \hspace{0.3cm}\frac{1}{3}\cdot \sum_{i=1}^{t-1}{p_i}+p_t > \frac{2}{3}\cdot \sum_{i=1}^{t-1}{p_i}+\frac{2}{3}\cdot p_t$ \\\\
Without loss of generality, we assume that $l_2 < l_1$, implies, $l_2+p_t > l_1+\frac{2}{3}\cdot p_t$\\
$\implies \hspace{0.3cm} l_2+p_t > 2\cdot l_2+\frac{2}{3}\cdot p_t$\\
$\implies \hspace*{0.3cm} p_t > l_1+l_2$, implies, $p_t > \sum_{i=1}^{t-1}{p_i}$.\\\\ In such a case algorithm 2-${LA}_1$ schedules each incoming job $J_i$ from $i=1$ to $t-1$ on machine $M_1$ and assigns job $J_t$ to machine $M_2$ to incur $C_{2-{LA}_1}(\sigma)=p_t$, while $C_{OPT}(\sigma)=p_t$. Implies, $\frac{C_{2-{LA}_1}(\sigma)}{C_{OPT}(\sigma)}=1\leq \frac{4}{3}$, which is a contradiction on our assumption on $\sigma$.\\\\
Therefore, there does not exist a counterexample to the theorem. We can now conclude that the theorem holds for all instances. \hfill\(\Box\)
\end{proof}
\textbf{Observations}
\begin{itemize}
\item Increasing the value of lookahead from $1$ to any $k$ would not lead to a better CR than $\frac{4}{3}$.
\item The proposed $1$-lookahead model and algorithm consider the arrival and scheduling of one job at a time with knowledge of non-zero positive processing time of the current and the next job. The model can not achieve a better CR than $\frac{3}{2}$ if it considers $p_i=0$ for any $J_i$, and scheduling of $J_{i+1}$ without knowledge of $p_{i+2}$. For example, consider an instance $\sigma=\langle J_1, J_2, J_3 \rangle$ with $p_1=p_2=1$, and $p_3=y$. Let $ALG$ be a semi-online algorithm. If $ALG$ assigns $J_1$ and $J_2$ to the same machine, then consider $p_3=y=0$. Implies, $C_{ALG}(\sigma)=2$, while $C_{OPT}(\sigma)=1$.\\
If $ALG$ schedules $J_1$ and $J_2$ on different machines, then consider $p_3=y=2$. Implies, $C_{ALG}(\sigma)=3$, while $C_{OPT}(\sigma)=2$. Therefore, $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{3}{2}$.\\
Hence, our model has significance over the traditional lookahead models concerning performance improvement.
\end{itemize}
\section{Our Competitive Analysis Results on $3$ Identical Machines with $1$-Lookahead ($P_3\hspace{0.1cm}|\hspace{0.1cm}{LA}_1 \hspace{0.1cm}| \hspace{0.1cm}C_{max}$)}
Graham \cite{Graham:66} explored the following multiprocessing timing anomaly. An increase in the number of machines does not necessarily guarantee the minimization of makespan. Graham proved that the LS algorithm is the optimal one with CR of $\frac{5}{3}\approx 1.66$ for $3$-identical machine setting. In this section, we study the problem $P_3\hspace*{0.1cm}|\hspace*{0.1cm}{LA}_1 \hspace*{0.1cm}|\hspace*{0.1cm}C_{max}$ and achieve an improved CR of $\frac{16}{11}\approx 1.45$.
\subsection{Lower Bound Result}
\begin{theorem}
Let $ALG$ be a deterministic semi-online algorithm for the problem $P_3\hspace{0.1cm}|\hspace{0.1cm}{LA}_1 \hspace{0.1cm}| \hspace{0.1cm}C_{max}$. Then there exists an instance $\sigma$ such that $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{15}{11}$.
\end{theorem}
\begin{proof}
We consider the adverserial instances of the problem to prove the lower bound. Let us assume that the adversary knows the nature of $ALG$ and dynamically generates an instance $\sigma$ such that $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{15}{11}$. We examine through the following cases, various strategies of scheduling $\sigma$ that $ALG$ could employ. We use the notation $J_i/p_i$ to denote a job $J_i$ and its corresponding processing time $p_i$. Without loss of generality, let us consider an instance $\sigma=\{J_1/7, J_2/4, J_3/p_3, \ldots, J_n/p_n\}$, where $n\geq 3$. Intially, the loads $l_1=l_2=l_3=0$.\\\\
\textbf{Case 1:} If $ALG$ assigns $J_1$, $J_2$ and $J_3$ to three different machines  (say $M_1$, $M_2$ and $M_3$ respectively), or to the same machine. Consider $p_3=4$, $p_4=7$ and $p_5=11$. We have $C_{ALG}(\sigma)\geq 15$, while $C_{OPT}(\sigma)=11$. Therefore, $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{15}{11}$.\\\\
\textbf{Case 2:} If $ALG$ assigns $J_1$, $J_2$ to the same machine (say $M_1$) and $J_3$ to a different machine (say $M_2$). Consider $p_3=4$, now $l_1=11$, $l_2=4$ and $l_3=0$.\\
\hspace*{1.0cm} \textbf{Sub-case 2.1:} If $J_4$ is assigned to $M_3$. Consider $p_4=7$ and $p_5=11$.\\ 
\hspace*{1.0cm} We have $C_{ALG}(\sigma)\geq 15$, while $C_{OPT}(\sigma)=11$. Therefore, $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{15}{11}$.\\
\hspace*{1.0cm} \textbf{Sub-case 2.2:} If $J_4$ is assigned to $M_2$. Consider $p_4=11$ and $p_5=7$.\\
\hspace*{1.0cm} Implies, $C_{ALG}(\sigma)\geq 15$, while $C_{OPT}(\sigma)=11$.  Therefore, $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{15}{11}$. \\ 
\hspace*{1.0cm} \textbf{Sub-case 2.3:} If $J_4$ is assigned to $M_1$. Consider $p_4=4$ and $p_5=11$.\\
\hspace*{1.0cm} Clearly, $C_{ALG}(\sigma)\geq 15$, while $C_{OPT}(\sigma)=11$.  Therefore, $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{15}{11}$. \\\\
\textbf{Case 3:} If $ALG$ assigns $J_1$, $J_2$ to different machines (say $M_1$ and $M_2$ respectively).\\
\hspace*{1.0cm} \textbf{Sub-case 3(a):} Job $J_3$ is assigned to $M_1$. Consider $p_3=4$, now $l_1=11$,\\
\hspace*{1.0cm} $l_2=4$ and $l_3=0$.\\
\hspace*{1.3cm} \textbf{Sub-case 3(a).1:} If $J_4$ is assigned to $M_3$. Consider $p_4=7$ and $p_5=11$.\\
\hspace*{1.3cm} We have $C_{ALG}(\sigma)\geq 15$, while $C_{OPT}(\sigma)=11$. Therefore, $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{15}{11}$.\\
\hspace*{1.3cm} \textbf{Sub-case 3(a).2:} If $J_4$ is assigned to $M_1$. Consider $p_4=4$ and $p_5=11$.\\
\hspace*{1.3cm} Clearly, $C_{ALG}(\sigma)\geq 15$, while $C_{OPT}(\sigma)=11$.  Therefore, $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{15}{11}$.\\
\hspace*{1.3cm} \textbf{Sub-case 3(a).3:} If $J_4$ is assigned to $M_2$. Consider $p_4=11$ and $p_5=7$.\\
\hspace*{1.3cm} Implies, $C_{ALG}(\sigma)\geq 15$, while $C_{OPT}(\sigma)=11$. Therefore, $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{15}{11}$. \\\\
\hspace*{1.0cm} \textbf{Sub-case 3(b):} Job $J_3$ is assigned to $M_2$. Consider $p_3=4$, now $l_1=7$,\\
\hspace*{1.0cm} $l_2=8$ and $l_3=0$.\\
\hspace*{1.3cm} \textbf{Sub-case 3(b).1:} If $J_4$ is assigned to $M_2$ or $M_3$. Consider $p_4=7$ and \\
\hspace*{1.3cm} $p_5=8$. We have $C_{ALG}(\sigma)\geq 15$, while $C_{OPT}(\sigma)=11$.   \\
\hspace*{1.3cm} \textbf{Sub-case 3(b).2:} If $J_4$ is assigned to $M_1$. Consider $p_4=8$ and $p_5=7$.\\
\hspace*{1.3cm} Implies, $C_{ALG}(\sigma)\geq 15$, while $C_{OPT}(\sigma)=11$.  Therefore, $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{15}{11}$. \\\\
Therefore, we conclude that there exists an instance $\sigma$ of the problem  $P_3\hspace{0.1cm}|\hspace{0.1cm}{LA}_1 \hspace{0.1cm}| \hspace{0.1cm}C_{max}$ such that $\frac{C_{ALG}(\sigma)}{C_{OPT}(\sigma)}\geq \frac{15}{11}$. \hfill\(\Box\)
\end{proof}
\subsection{An Improved Semi-online Algorithm with $1$-lookahead : 3-${LA}_1$ }
We design a deterministic semi-online algorithm named 3-${LA}_1$ for $3$ identical parallel machines setting by considering a lookahead of size $1$. We prove that algorithm 3-${LA}_1$ has a CR of at most $\frac{16}{11}\approx 1.45$. We present algorithm 3-${LA}_1$ in \textbf{Algorithm 2}.
\begin{algorithm}
\caption{3-${LA}_1$}
\begin{algorithmic}
\scriptsize
\STATE Initially, $l_1=l_2=l_3=0$ \\
\STATE When a new job $J_{i}$ arrives, $p_i$ and $p_{i+1}$ are known.\\
%\STATE \hspace*{0.2cm} BEGIN\\
\STATE FOR $i=1$ to $n-1$\\
\STATE \hspace*{0.2cm} BEGIN\\
\STATE \hspace*{0.5cm} IF $(l_1+p_i)\leq \frac{16}{33}\cdot (l_1+l_2+l_3+p_i+p_{i+1})$  \\
\STATE \hspace*{0.8cm} THEN assign job $J_i$ to machine $M_1$ \\
\STATE \hspace*{0.8cm} UPDATE $l_1=l_1+p_i$\\
\STATE \hspace*{0.5cm} ELSE IF $(l_2+p_i)\leq \frac{15}{33}\cdot (l_1+l_2+l_3+p_i+p_{i+1})$  \\
\STATE \hspace*{0.8cm} Assign job $J_i$ to machine $M_2$ \\
\STATE \hspace*{0.8cm} UPDATE $l_2=l_2+p_i$\\
\STATE \hspace*{0.5cm} ELSE \\
\STATE \hspace*{0.8cm} Assign job $J_i$ to machine $M_3$ \\
\STATE \hspace*{0.2cm} END\\
\STATE $l_{min}\leftarrow \min \{l_1, l_2, l_3\}$\\
\STATE Assign job $J_n$ to machine $M_j$ for which $l_j=l_{min}$, where $j=\{1, 2, 3\}$\\
\STATE UPDATE $l_j=l_j+p_i$\\
\STATE UPDATE $l_1$, $l_2$, $l_3$\\
\STATE Return \hspace*{0.3cm} $C_{3-{LA}_1}=\max\{l_1, l_2, l_3\}$
\end{algorithmic}
\end{algorithm}\\
Algorithm 3-${LA}_1$ considers the EPI $p_{i+1}$ for efficient scheduling of each incoming job $J_i$. Our goal is to show that $k=1$ is sufficient to achieve an improved CR over the best-known upper bound of $\frac{5}{3}\approx 1.66$ on the CR. The objective of algorithm 3-${LA}_1$ is to keep an imbalance in the loads of machines $M_1$, $M_2$ and $M_3$ such that the final loads $l_1\leq \frac{16}{33}\cdot \sum_{i=1}^{n}{p_i}$, $l_2\leq \frac{15}{33}\cdot \sum_{i=1}^{n}{p_i}$ and $l_3\leq C_{OPT}$. Our goal is to show that $C_{3-{LA}_1}\leq \frac{16}{33}\cdot \sum_{i=1}^{n}{p_i}$, while $C_{OPT}\geq \frac{1}{3}\cdot \sum_{i=1}^{n}{p_i}$, or $C_{OPT}\geq p_{max}$ such that $\frac{C_{3-{LA}_1}}{C_{OPT}}\leq \frac{16}{11}\approx 1.45$ for all instances of $P_3\hspace*{0.1cm|\hspace*{0.1cm}{LA}_1 \hspace{0.1cm}|\hspace{0.1cm}C_{max}}$. 
\subsection{Upper Bound Result}
We prove the competitiveness of algorithm 3-${LA}_1$ by considering several critical cases as Lemmas to establish the upper bound on the CR.\\
\begin{theorem}
Let $\sigma$ be an instance of $P_3\hspace{0.1cm}|\hspace{0.1cm}{LA}_1 \hspace{0.1cm}| \hspace{0.1cm}C_{max}$. Algorithm 3-${LA}_1$ is such that $\frac{C_{3-{LA}_1}(\sigma)}{C_{OPT}(\sigma)}\leq \frac{15}{11}$ for all $\sigma$.
\end{theorem}
\textit{Proof.} We prove Theorem 5 by Lemma 3-6 as follows. 
\begin{lemma}
Let $T=\sum_{i=1}^{n}{p_i}$ for any instance $\sigma$ of the problem $P_3\hspace*{0.1cm|\hspace*{0.1cm}{LA}_1 \hspace{0.1cm}|\hspace{0.1cm}C_{max}}$. If the final load of machine $M_3$ is such that $l_3\leq \frac{2}{33}\cdot T$, then $\frac{C_{3-{LA}_1}(\sigma)}{C_{OPT}(\sigma)}\leq \frac{16}{11}$. 
\end{lemma}
\begin{proof}
This is the obvious case, no matter the order of arrival of jobs in $\sigma$ and their processing times, we have $C_{3-{LA}_1}(\sigma)=l_{max}=l_1\leq \frac{16}{33}\cdot T$, while $C_{OPT}(\sigma)\geq \frac{1}{3}\cdot T$. Therefore, $\frac{C_{3-{LA}_1}(\sigma)}{C_{OPT}(\sigma)}\leq \frac{16}{11}$. \hfill\(\Box\)
\end{proof}
The following lemma put some insights into the maximum value of $p_{max}$ and its impact on the performance of algorithm 3-${LA}_1$.\\
\begin{lemma}
If $p_{max} \geq \frac{16}{33}\cdot T$, then $C_{3-{LA}_1}=C_{OPT}=p_{max}$. 
\begin{proof}
If $p_{max} \geq \frac{16}{33}\cdot T$, then $\sum_{}^{}{p_i}\leq \frac{17}{33}\cdot T$ for the rest $n-1$ jobs. As we consider $n\geq 3$, w.o.l.g, let us normalize the processing times of the jobs such that $T=33$. Clearly, $p_{max}\leq \frac{31}{33}\cdot T$. Consider the sequence $\sigma=\langle J_1/16, J_2/16, J_3/1 \rangle$ with least number of jobs. We have, ${3-{LA}_1}(\sigma)=C_{OPT}(\sigma)=p_{max}$.\\ \hfill\(\Box\)
\end{proof}
\end{lemma}
\begin{lemma}
If $p_{max}=p_1$ or $p_n$, and $p_{max}\geq \sum_{i}^{}{p_i}$ for rest $n-1$ jobs, then $C_{3-{LA}_1}=C_{OPT}=p_{max}$. 
\end{lemma}
\begin{proof}
Following the proof of the previous lemma, let us consider the sequences $\sigma_2=\langle J_1/17, J_2/14, J_3/1, J_2/1 \rangle$ and $\sigma_3=\langle J_1/1, J_2/1, J_3/14, J_2/17 \rangle$, where $p_{max}=17$. For both sequences, we have, ${3-{LA}_1}(\sigma)=C_{OPT}(\sigma)=p_{max}$. \hfill\(\Box\) 
\end{proof}
\begin{lemma}
Let $\sigma$ be an instance with $n$ jobs, where $p_i=1$, $\forall J_i$, then $\frac{C_{3-{LA}_1}(\sigma)}{C_{OPT}(\sigma)}\leq \frac{16}{11}$.
\end{lemma}
\begin{proof}
We explore and consider a worst job sequence $\sigma$ to establish our claim. Let $n=33x$, where $x\geq 1$. Here, $T=n$. Consider an instance $\sigma$, where $x=1$, implies $T=33$. We have $C_{3-{LA}_1}\leq 16$, while $C_{OPT}(\sigma)=11$. Therefore, $\frac{C_{3-{LA}_1}(\sigma)}{C_{OPT}(\sigma)}\leq \frac{16}{11}$. \hfill\(\Box\)  
\end{proof}
