\begin{algorithm}
\caption{Sudoku Set from Colouring of $G_{n,d}$}\label{alg:simple}
\begin{algorithmic}
\Require $G_{n,d} = (V,E)$ where $V = v_0,\dots, v_{n-1}$. $C(i): [n] \to [k]$ colours $G_{n,d}$.
\Ensure $L$ is a Sudoku Set for $G_{n,d}$.
\State $L \gets [~]$
\For{$i \in [n]$}
\State $c_i \gets -1$
\EndFor
\For{$i \in [n]$}
\State $c_i \gets C(i)$
\If{$[k] \not= \bigcup_{v_j \in N[v_i]}\{C(j)\}$}
\State $L \gets L + [(i,c_i)]$
\Else
\For{$c \in [k] \setminus\bigcup_{v_j \in N[v_i]} \{c_j\}$}
\State $v \gets \text{selected uniformly at random from} \{v_l: v_l \in N(v_i), C(l) =c\}$
\State $E \gets E \setminus v_iv$
\EndFor
\EndIf
\EndFor
\end{algorithmic}
\end{algorithm}

\begin{proposition}
    Algorithm \ref{alg:simple} generates a Sudoku Set of size $$n\cdot (1-\frac{\sum_{i=k-1}^d (\frac12)^{d-i}\cdot\prob(e)^{d-i}\cdot\prob(\overline{e})^i\cdot(k-1)!\snsk{i}{k-1}}{d^{k-1}})$$ a.a.s., where $\prob(e)$ denotes the probability an edge is deleted by Algorithm \ref{alg:simple}.
\end{proposition}

