\subsection{Search for invariant subspaces: algebraic preliminaries}\label{sec:theory}

For this section, we fix a ground field $k$ of characteristic zero.
The cases we are mostly interested in are rational numbers $\mathbb{Q}$, algebraic numbers $\overline{\mathbb{Q}}$, and complex numbers $\mathbb{C}$.

\begin{definition}[Radical of an algebra]\label{def:radical}
Let $\mathcal{A} \subseteq k^{n \times n}$ be an algebra.
\begin{itemize}
    \item A subspace $\mathcal{I} \subseteq \mathcal{A}$ is called \keyw{an ideal} (resp., \keyw{left ideal}) if $AB, BA \in \mathcal{I}$ (resp., $AB \in \mathcal{I}$) for every $A \in \mathcal{A}$ and $B \in \mathcal{I}$.
    \item An ideal (resp., left ideal) $\mathcal{I} \subseteq \mathcal{A}$ is \keyw{nilpotent} if there exists $N$ such that the product of any $N$ elements of $\mathcal{I}$ is zero.

    \item The set of all elements $A \in \mathcal{A}$ such that the left ideal $\mathcal{A}\cdot A$ is nilpotent is called \keyw{the radical} of $\mathcal{A}$.
    It is a nilpotent ideal of $\mathcal{A}$ by~\cite[Theorems~3.1.6, 3.1.10]{kir_drozd}.
\end{itemize}
\end{definition}

\begin{example}\label{ex:radical}
   Let $T_n$ be the set of all upper-triangular matrices in $k^{n \times n}$.
   Consider a subset $U_n \subset T_n$ of strictly upper-triangular matrices.
   One can easily verify that $U_n$ is an ideal and the product of any $n$ elements of $U_n$ is zero.
   Since, for every $A \in U_n$, we have $T_n \cdot A \subseteq U_n$, we deduce that $U_n$ is the radical of $T_n$.
\end{example}

Dixon's theorem~\cite[Theorem~11]{constructive_survey} implies that the radical of an algebra $\mathcal{A} \subseteq k^{n \times n}$ can be computed by finding the kernel of a square matrix of order $\dim \mathcal{A} \leqslant n^2$.
The relevance of the notion of radical to our problem is demonstrated by the following lemma.

\begin{lemma}
\label{lemma:radical-kernel}
  Let $\mathcal{A} \subseteq k^{n \times n}$ be an algebra, and let $\mathcal{R} \subset \mathcal{A}$ be its radical.
  If $\mathcal{R} \neq \{0\}$, then the intersection $\bigcap\limits_{R \in \mathcal{R}} \operatorname{Ker} R$ is nonzero and is invariant w.r.t. $\mathcal{A}$.
\end{lemma}

\begin{proof}

    Since $\mathcal{R}$ is a nilpotent ideal, there exists the smallest integer $N$ such that the product of any $N$ elements of $\mathcal{R}$ is zero.
   Then, there exists $0 \neq M \in k^{n\times n}$ which is a product of $N - 1$ elements of $\mathcal{R}$.
   Hence, we have $RM = 0$ for every $R \in \mathcal{R}$, so $V := \bigcap\limits_{R \in \mathcal{R}} \operatorname{Ker} R \supseteq \operatorname{Im} M$ is nontrivial.

   Consider $v \in V$, $A \in \mathcal{A}$, and $R \in \mathcal{R}$.
   Since $RA \in \mathcal{R}$, we have $RAv = 0$, so $Av \in \operatorname{Ker} R$.
   Thus, $V$ is invariant w.r.t. $\mathcal{A}$.
\end{proof}

\begin{example}
   Consider the system from \Cref{ex:jac_decomp}.
   In~\Cref{ex:jac_algebra}, it was shown that the Jacobian algebra of this system is the set of lower triangular matrices.
   Similarly to \Cref{ex:radical} we find that the radical of this algebra is $\begin{pmatrix}
     0 & 0\\
     \lambda & 0
   \end{pmatrix}$.
   The common kernel of the radical is spanned by the second basis vector yielding the reduction $y' = -y + y^2$ (with $y = x_2$). 
\end{example}

\begin{definition}[Semisimple algebra]
  An algebra $\mathcal{A} \subseteq k^{n \times n}$ is called \keyw{semisimple} if its radical is zero.
\end{definition}

We will use the following characterization of semisimple algebras.

\begin{theorem}[Wedderburn-Artin, {{\cite[Theorems~2.4.3 and~2.6.2]{kir_drozd}}}]\label{thm:wedart}
  Let $\mathcal{A} \subseteq k^{n \times n}$ be a semisimple algebra.
  Then there exist
  \begin{enumerate}
      \item algebras $\mathcal{A}_1 \subseteq k^{n_1 \times n_1}, \ldots, \mathcal{A}_\ell \subseteq k^{n_\ell \times n_\ell}$ such that $\mathcal{A}_i$ does not have a nontrivial proper invariant subspace in $k^{n_i}$ for every $1 \leqslant i \leqslant \ell$,
      \item integers $m_1, \ldots, m_\ell$ such that $n_1m_1 + \ldots + n_\ell m_\ell = n$,
      \item a basis in $k^n$
  \end{enumerate}
  such that, in this basis, we have
  \begin{equation}\label{eq:wedart}
    \mathcal{A} = \left\{ \operatorname{Diag}(\underbrace{A_1, \ldots, A_1}_{m_1 \text{ times}}, \ldots, \underbrace{A_\ell, \ldots, A_\ell}_{m_\ell \text{ times}}) \mid A_1 \in \mathcal{A}_1,\ldots, A_\ell \in \mathcal{A}_\ell \right\},
  \end{equation}
where $\operatorname{Diag}(B_1, \ldots, B_N)$ denotes the block-diagonal matrix with blocks $B_1, \ldots, B_N$.
\end{theorem}

\begin{example}
   Consider the set of all matrices of the form
   \[
   \begin{pmatrix}
     a & b & 0 & 0\\
     -b & a & 0 & 0\\
     0 & 0 & c & 0\\
     0 & 0 & 0 & c
   \end{pmatrix}, \quad \text{where } a, b, c \in \mathbb{Q}.
   \]
   This is a semisimple algebra in the form~\eqref{eq:wedart} with $\ell = 2$, $m_1 = 1$, and $m_2 = 2$.
\end{example}

In the case $\ell = 1$ and $m_1 = 1$ in the decomposition~\eqref{eq:wedart} from~\Cref{thm:wedart}, there are no invariant subspaces in $k^n$ but there still may be invariant subspaces in $\overline{k}^n$ if $k \neq \overline{k}$, where $\overline{k}$ is the algebraic closure of field $k$.
These subspaces can be found using the center of the algebra.

\begin{definition}[Center/Centralizer]\label{def:center}
    Let $\mathcal{A} \subseteq k^{n\times n}$ be an algebra.
    \begin{itemize}
        \item The \keyw{center} of $\mathcal{A}$ is the set of all $M \in \mathcal{A}$ such that $MA = AM$ for every $A \in \mathcal{A}$.
        \item The \keyw{centralizer} of $\mathcal{A}$ is the set of all $M \in k^{n \times n}$ such that $MA = AM$ for every $A \in \mathcal{A}$.
    \end{itemize}

\end{definition}

Since, for every fixed $A$, $AM = MA$ is a system of linear equations in the entries, the center and centralizer can be computed by solving a system of linear equations.

\begin{lemma}\label{lem:center}
  Let $\mathcal{A} \subseteq k^{n\times n}$ be a subalgebra.
  Let $\mathcal{C}$ be the centralizer of $\mathcal{A}$.
  For every $C \in \mathcal{C}$, every eigenspace of $C$ is an invariant subspace of $\mathcal{A}$ in $\overline{k}^n$.
\end{lemma}

\begin{proof}
   Let $V$ be an eigenspace of $C$ corresponding to the eigenvalue $\lambda$.
   Let $A \in \mathcal{A}$.
   Then, for $v\in V$, we have $C(Av) = (CA)v = (AC) v = \lambda Av$, so $Av$ belongs to $V$ as well.
\end{proof}

\begin{lemma}\label{lem:equal_blocks_crit}
  Let $\mathcal{A} \subseteq \mathbb{Q}^{n \times n}$ be a semisimple algebra.
  Let $M \in \mathcal{A}$ be a matrix such that the characteristic polynomial of $M$ is of the form $p(t)^d$, where $p(t)$ is $\mathbb{Q}$-irreducible.
  Let $\mathcal{Z}$ and $\mathcal{C}$ be the center and centralizer of $\mathcal{A}$, respectively.
  Then the equality $\dim\mathcal{C} = d^2 \dim\mathcal{Z}$ is equivalent to the fact that, in the Wedderburn-Artin decomposition~\eqref{eq:wedart} of $\mathcal{A}$, we have $\ell = 1$ and $m_1 = d$.
\end{lemma}

\begin{proof}
   We consider the Wedderburn-Artin decomposition~\eqref{eq:wedart} of $\mathcal{A}$.
   For every $1 \leqslant i \leqslant \ell$, we denote the center of $\mathcal{A}_i$ by $\mathcal{Z}_i$.
   Then $\dim \mathcal{Z} = \dim \mathcal{Z}_1 + \ldots + \dim \mathcal{Z}_\ell$.
   The number of irreducible factors of a characteristic polynomial of any element of $\mathcal{A}$ will be at least $m_1 + \ldots + m_\ell$, so $d \geqslant m_1 + \ldots + m_\ell$.
   A direct computation using the Schur's lemma~\cite[Theorem~2.1.1]{kir_drozd} implies that the centralizer $\mathcal{C}$ of $\mathcal{A}$ is isomorphic to $\operatorname{Mat}_{m_1}(\mathcal{Z}_1) \times \ldots \times \operatorname{Mat}_{m_\ell}(\mathcal{Z}_\ell)$, where $\operatorname{Mat}_{m_i}(\mathcal{Z}_i)$ denotes the space of $m_i\times m_i$-block matrices with each block being an element of $\mathcal{Z}_i$ (cf. \cite[Theorem~2.6.4]{kir_drozd}).
   Therefore
   \[
     \dim \mathcal{C} = m_1^2 \dim \mathcal{Z}_1 + m_2^2 \dim \mathcal{Z}_2 + \ldots + m_\ell^2 \dim \mathcal{Z}_\ell.
   \]
   Bounding the right-hand side, we can write
   \[
     \dim\mathcal{C} \leqslant (m_1 + \ldots + m_\ell)^2 (\dim \mathcal{Z}_1 + \ldots + \dim\mathcal{Z}_\ell) \leqslant d^2 \dim \mathcal{Z}
   \]
   Both inequalities will be equalities if and only if $\ell = 1$ and $d = m_1$, and this proves the lemma.
\end{proof}

