\subsection{Search for invariant subspaces: how to find one}
In this subsection, we present~\Cref{alg:one_space_full} for finding an invariant subspace if there is any.
The rest of the subsection is devoted to justifying its correctness and termination, see~\Cref{prop:alg_correct}.

\begin{algorithm}
\caption{Finding a nontrivial invariant subspace of an algebra}
\label{alg:one_space_full}
\begin{description}[itemsep=0pt]
\item[Input ] a basis $B_1, \ldots, B_N \in \mathbb{Q}^{n \times n}$ of an algebra $\mathcal{A} \subseteq \mathbb{Q}^{n \times n}$;
\item[Output ] One of the following:
\begin{itemize}
    \item \texttt{NO} if there is no subspace in $\overline{\mathbb{Q}}^n$ invariant w.r.t. $\mathcal{A}$;
    \item nontrivial proper subspace in $\mathbb{Q}^n$ invariant w.r.t. $\mathcal{A}$;
    \item a maximal chain of subspaces in $\overline{\mathbb{Q}}^n$ invariant w.r.t. $\mathcal{A}$.
\end{itemize}
\end{description}

\begin{enumerate}[label = \textbf{(Step~\arabic*)}, leftmargin=*, align=left, labelsep=2pt, itemsep=4pt]
\item[]
    \hspace{-14mm}\emph{Considering corner cases:}
    \item\label{step:full_alg} If $N = n^2$, return \texttt{NO}.
    \item\label{step:full_saturation} For an arbitrary nonzero vector $v$, consider the space $V$ spanned by $B_1v,\ldots, B_Nv$.
    If $\dim V < n$, \textbf{return} $V$.

    \smallskip
    \hspace{-14mm}\emph{Examining the radical:}
    \item Find a basis of the radical $\mathcal{R}$ of $\mathcal{A}$ (\Cref{def:radical}) using Dixon's theorem~\cite[Theorem~11]{constructive_survey}.
    \item\label{step:full_radical} If $\dim \mathcal{R} > 0$ compute the common kernel of the basis elements of $\mathcal{R}$ and \textbf{return} it (see~\Cref{lemma:radical-kernel}).

    \smallskip
    \hspace{-14mm}\emph{Semisimple case:}
    \item\label{step:full_semisimple} Set $D := 1$.
    \item\label{step:full_sampling1} Compute $M := \sum_{i = 1}^N a_i B_i$, where $a_1, \ldots, a_N$ are sampled independently and uniformly at random from $\{1, 2, \ldots, D\}$.
    \item\label{step:reducible} If the characteristic polynomial of $M$ has at least two distinct $\mathbb{Q}$-irreducible factors (say, $p_1(t)$ and $p_2(t)$):
    \begin{enumerate}[ref= \theenumi (\alph*)]
        \item Check the invariance of $\operatorname{Ker}p_1(M)$ w.r.t. $B_1, \ldots, B_N$.
        \item\label{step:full_decomposable} If it is invariant, \textbf{return} $\operatorname{Ker}p_1(M)$. Otherwise, set $D := 2D$ and \textbf{go to}~\ref{step:full_sampling1}.
    \end{enumerate}
    \item Write the characteristic polynomial of $M$ as $p(t)^d$, where $p(t)$ is $\mathbb{Q}$-irreducible.
    \item\label{step:full_center} Compute the center $\mathcal{Z}$ and centralizer~$\mathcal{C}$ of $\mathcal{A}$ (\Cref{def:center}).
    \item If $\dim \mathcal{C} < d^2 \dim\mathcal{Z}$, set $D := 2D$ and \textbf{go to}~\ref{step:full_sampling1}.
    \item\label{step:sampling_center} Let $C_1, \ldots, C_s$ be a basis of $\mathcal{C}$.
    Set $C := \sum_{i = 1}^s b_i C_i$, where $b_1, \ldots, b_s$ are sampled independently and uniformly at random from $\{1, 2, \ldots, D\}$. 
    \item\label{step:full_compute_q} Compute $q(t)$, the minimal polynomial of $C$. If $q$ is $\mathbb{Q}$-reducible or $\deg q < d \dim \mathcal{Z}$, set $D := 2D$ and \textbf{go to}~\ref{step:full_sampling1}.
    \item\label{step:eigenspaces} Let $V_1, \ldots, V_\ell$\\  
    (where $\ell = d \dim \mathcal{Z}$) be the eigenspaces of $C$.
    \item\label{step:full_return_chain} \textbf{Return} $V_1 \subset V_1\oplus V_2 \subset \ldots \subset V_1 \oplus V_2 \oplus\ldots \oplus V_{\ell - 1}$.
\end{enumerate}
\end{algorithm}

\begin{proposition}\label{prop:chpoly}
    Let $\mathcal{A} \subseteq \mathbb{Q}^{n \times n}$ be a semisimple algebra such that there are no nontrivial proper $\mathcal{A}$-invariant subspaces in $\mathbb{Q}^n$.
    Let $M_1, \ldots, M_N$ be a basis of $\mathcal{A}$ as a vector space.
    Then the polynomial
    \[
      \operatorname{det} (x_1M_1 + \ldots + x_N M_N) \in \mathbb{Q}[x_1, \ldots, x_N]
    \]
    is of the form $P^d$, where $P$ is irreducible over $\mathbb{Q}$.
\end{proposition}

\begin{remark}[On the importance of being a basis]
  While the statement of \Cref{prop:chpoly} may sound quite natural, the situation is in fact quite subtle: if one replaces linear basis with a set of generators of $\mathcal{A}$ in the statement of the proposition, it will not longer be true~\cite[Theorem 1.2 and Subsection 2.1]{KlepVolvic}.
\end{remark}

\begin{proof}[Proof of~\Cref{prop:chpoly}]
    By performing a change of coordinates over $\mathbb{Q}$, we will assume that $M_1$ is the identity matrix.

    Let $\overline{\mathcal{A}}$ be the complexification of $\mathcal{A}$.
    By the Wedderburn-Artin theorem~\cite[Corollary 2.4.4]{kir_drozd}, there exist $n_1, \ldots, n_\ell$ such that $N = n_1^2 + \ldots + n_\ell^2$ and \begin{equation}\label{eq:decom_alg}
        \overline{\mathcal{A}} \cong \operatorname{Mat}_{n_1}(\mathbb{C}) \times \ldots \times \operatorname{Mat}_{n_\ell}(\mathbb{C}).
    \end{equation}

    Then the complexification $\mathbb{C}^n$ of the original representation $\mathbb{Q}^n$ of $\mathcal{A}$ can be decomposed~\cite[Theorem~2.6.2]{kir_drozd} as
    \begin{equation}\label{eq:decomp_module}
        \mathbb{C}^n = k_1V_{1} \oplus k_2V_2 \oplus \ldots \oplus k_\ell V_\ell,
    \end{equation}
    where $V_i \cong \mathbb{C}^{n_i}$ is the unique irreducible representation of $\operatorname{Mat}_{n_i}(\mathbb{C})$.
    We denote the base change corresponding to~\eqref{eq:decomp_module} by $C \in \mathbb{C}^{n\times n}$.
    Then $CMC^{-1}$, where $M := x_1M_1 + \ldots + x_NM_N$, is block diagonal with the dimensions of blocks as in~\eqref{eq:decomp_module}. Since $M_1, \ldots, M_N$ span the whole $\overline{\mathcal{A}}$, the distinct nonzero entries of $CMC^{-1}$ are $\mathbb{C}$-linearly independent linear forms in $x_1, \ldots, x_N$. 
    By denoting these forms by $y_1, \ldots, y_N$ we obtain an
     invertible matrix $B \in \mathbb{C}^{N\times N}$ such that $\mathbf{y} := B\mathbf{x}$, and, reordering $y_1, \ldots, y_N$ if necessary, one has
    \[
      CMC^{-1} = \operatorname{diag}(\underbrace{Y_1, \ldots, Y_1}_{k_1 \text{times}}, \ldots, \underbrace{Y_\ell, \ldots, Y_\ell}_{k_\ell \text{times}}),
    \]
    where $Y_i$ is a matrix with entries $y_{n_1 + \ldots + n_{i - 1}^2 + 1}, \ldots, y_{n_1^2 + \ldots + n_i^2}$ for $1 \leqslant i \leqslant \ell$.

    Then we have
    \[
      \operatorname{det}(M) = \operatorname{det}(CMC^{-1}) = \operatorname{det}(Y_1)^{k_1} \ldots \operatorname{det}(Y_\ell)^{k_\ell}.
    \]
    Furthermore, since $M_1$ is the identity, $\det(M)|_{x_1 = x_1 + t}$ as a polynomial in $t$ is the characteristic polynomial of $-M$.
    Let $Q(\mathbf{x}) := \det Y_1\ldots \det Y_\ell \in \mathbb{Q}[\mathbf{x}]$.
    Then $Q|_{x_1 = x_1 + t}$ as a polynomial in $t$ is the minimal polynomial of $-M$.

    Since $\det Y_i$ is a determinant of a matrix with independent entries, it is irreducible over $\mathbb{C}$.
    Let $p(\mathbf{x})$ be a $\mathbb{Q}$-irreducible divisor of $\det M$.
    Then $p$ divides $Q$, so, by reordering $Y_i$'s if necessary, we can assume that $p(\mathbf{x}) = \det Y_1\ldots \det Y_r$ for $r \leqslant \ell$.
    Assume that $r < \ell$.
    Set $p_0(t) := p(x_1 - t, x_2, \ldots, x_N)$ and consider $p_0(M)$.
    We will have 
    \begin{multline*}
      C p_0(M) C^{-1} = \\ \operatorname{diag}(\underbrace{0, \ldots, 0}_{k_1 + \ldots + k_r \text{ times}}, \underbrace{p_0(Y_{r + 1}), \ldots, p_0(Y_{r + 1})}_{k_{r + 1} \text{ times}}, \ldots, \underbrace{p_0(Y_{r + 1}), \ldots, p_0(Y_{r + 1})}_{k_\ell \text{ times}}).
    \end{multline*}
    Since $p_0$ is coprime with the characteristic polynomials of $Y_{r + 1}, \ldots, Y_\ell$, each of the matrices $p_0(Y_{r + 1}), \ldots, p_0(Y_\ell)$ is nonsingular.
    Therefore, the kernel of $C p_0(M) C^{-1}$ is exactly the span of the first $k_1 + \ldots + k_r$ basis vectors.
    Therefore, the kernel of $p_0(M)$ is the span of this many first columns of $C^{-1}$.
    Therefore, the kernel of $p_0(M)$ is $\overline{\mathcal{A}}$-invariant and is defined over $\mathbb{C}$.
    On the other hand, the entries of $p_0(M)$ belong to $\mathbb{Q}(\mathbf{x})$, so the kernel of $p_0(M)$ in fact is defined over $\mathbb{C} \cap \mathbb{Q}(\mathbf{x}) = \mathbb{Q}$.
    Therefore, the kernel of $p_0(M)$ yields a nontrivial $\mathcal{A}$-invariant subspace of $\mathbb{Q}^n$ contradicting with the irreducibility of this representation.
    Hence $p$ must be equal to $Q$, so $\det M$ must be a power of $p$.
\end{proof}

The proof of the proposition provides a way to find the degree of $\deg P$.

\begin{corollary}\label{cor:Pdegree}
    In the notation of the proof (see~\eqref{eq:decom_alg}) of~\Cref{prop:chpoly}, $\deg P = n_1 + n_2 + \ldots + n_\ell$.
\end{corollary}

\begin{proposition}\label{prop:alg_correct}
  \Cref{alg:one_space_full} is correct and terminates with probability one.
\end{proposition}

\begin{remark}[On the probability of termination]
    By ``terminates with probability one'' we mean that the algorithm makes a random choice in an infinite probability space, and will terminate for all the choices except for a set of probability zero. 
    Simply put, the algorithm repeatedly tosses a coin and will terminate as long as there will be at least one heads which will eventually happen with probability one.
\end{remark}

\begin{proof}[Proof of~\Cref{prop:alg_correct}]
   We will first prove the \emph{correctness}.
   If the algorithm returned on~\ref{step:full_alg}, then $\mathcal{A}$ is the full matrix algebra, and does not have any nontrivial proper invariant subspace.
   If the algorithm returned on~\ref{step:full_saturation}, then the returned subspace is invariant by construction.
   If the algorithm returned on~\ref{step:full_radical}, the returned subspace is nonzero, proper (since if $\mathcal{A}$ was a zero algebra, the algorithm would have returned at~\ref{step:full_saturation}), and invariant due to~\Cref{lemma:radical-kernel}.

   It remains to consider the case when the algorithm returns after~\ref{step:full_semisimple}.
   If the algorithm returned on~\ref{step:full_decomposable}, then the returned subspace is invariant by construction and is nonzero because $p_1(t)$ divides the charpoly of $M$, so $p_1(M)$ is a singular matrix.
   Finally, consider the case when the algorithm returned on~\ref{step:full_return_chain}.
   Consider the decomposition~\eqref{eq:wedart} from~\Cref{thm:wedart} for $\mathcal{A}$.
   If the algorithm reached~\ref{step:sampling_center}, it contains a matrix with the charpoly being $p(t)^d$ with $\mathbb{Q}$-irreducible $p(t)$ such that $\dim \mathcal{C} = d^2 \dim \mathcal{Z}$.
   \Cref{lem:equal_blocks_crit} implies that, in the decomposition~\eqref{eq:wedart}, we have $\ell = 1$ and $m_1 = d$.
   Thus, the whole space $\mathbb{Q}^n$ can be written as $U_1 \oplus U_2 \oplus \ldots \oplus U_d$ such that each of $U_i$'s is $\mathcal{A}$-invariant without proper nontrivial $\mathcal{A}$-invariant subspaces.
   \cite[Corollary~2.2.4]{kir_drozd} implies that, over $\overline{\mathbb{Q}}$, each of $U_i$'s can be decomposed as a direct sum of at most $\dim\mathcal{Z}$ $\mathcal{A}$-invariant subspaces.
   Therefore, the whole $\overline{\mathbb{Q}}^n$ can be decomposed into at most $d \dim\mathcal{Z}$ $\mathcal{A}$-invariant subspaces by~\cite[Theorem~2.6.2]{kir_drozd}.

   \Cref{lem:center} implies that each of $V_i$'s from~\ref{step:eigenspaces} is an invariant subspace w.r.t. $\mathcal{A}$.
   Since there are $d \dim\mathcal{Z}$ of them, each of $V_i$'s does not contain nontrivial proper $\mathcal{A}$-invariant subspaces.
   Therefore, the chain $V_1 \subset V_1\oplus V_2 \subset \ldots \subset V_1 \oplus V_2 \oplus\ldots \oplus V_{\ell - 1}$ returned at~\ref{step:full_return_chain} is maximal.
   This finished the proof of the \emph{correctness} of the algorithm.

   We will now prove that the algorithm \emph{terminates} with probability one.
   Consider the decomposition~\eqref{eq:wedart} of $\mathcal{A}$ from~\Cref{thm:wedart}.
   Consider variables $z_1, \ldots, z_N$ and a matrix $M_0 := \sum_{i = 1}^N z_i B_i$.
   Then $M$ at~\ref{step:full_sampling1} is a specialization of $M_0$ at $z_i = a_i$.
   Let $P(z_1, \ldots, z_N, t)$ be the charpoly of $M_0$.
   Consider the decomposition~\eqref{eq:wedart} for $\mathcal{A}$.
   For every $1 \leqslant i \leqslant \ell$, we apply~\Cref{prop:chpoly} to the block corresponding to $\mathcal{A}_i$ and obtain a $\mathbb{Q}$-irreducible $P_i$ and its power $d_i$.
   Thus, we obtain the following factorization for $M_0$
   \[
     P = P_1^{d_1 m_1} P_2^{d_2 m_2}\ldots P_\ell^{d_\ell m_\ell}.
   \]
   The characteristic polynomial of $M$ computed at~\ref{step:full_sampling1} equals $P(a_1, \ldots, a_N, t)$.
   \ul{Assume that $P_i(a_1, \ldots, a_N, t)$ is $\mathbb{Q}$-reducible for every $1 \leqslant i \leqslant s$ and these polynomials are distinct.}
   \begin{itemize}
       \item Assume that $\ell > 1$.
       Then $p_1(t)$ from~\ref{step:reducible} will be equal to $P_i(a_1, \ldots, a_N, t)$ for some $i$.
       Then $\operatorname{Ker} p_1(M)$ will be the subspace corresponding to the $i$-th block in the decomposition~\eqref{eq:wedart}.
       The subspace is invariant, so it will be returned on~\ref{step:full_decomposable}.
       \item Assume that $\ell = 1$.
       We will study matrix $C$ similarly to the way we studied $M$ above. 
       Let $y_1, \ldots, y_s$ be independent variables, and we define $C_0 := y_1 C_1 + \ldots + y_s C_s$.
       By the same argument as in the proof of~\Cref{lem:equal_blocks_crit}, we have $\mathcal{C} \cong \operatorname{Mat}_r(\mathcal{Z})$ for some integer $r$.
       By~\cite[Proposition~2.3.4]{kir_drozd}, algebra $\mathcal{C}$ is simple and every $\mathcal{C}$-module (in particular, our ambient space $\mathbb{Q}^n$) is a direct sum of isomorphic copies of the same $\mathcal{C}$-module.
       We apply~\Cref{prop:chpoly} to this module and deduce that the characteristic  polynomial of $C_0$ is of the form $Q(y_1, \ldots, y_s, t)^h$ for some integer $h$ and $\mathbb{Q}$-irreducible polynomial $Q$.
       Furthermore, $\deg Q = d \dim \mathcal{Z}$ by~\Cref{cor:Pdegree}.
       \ul{Assume that $Q(b_1, \ldots, b_s, t)$ is $\mathbb{Q}$-irreducible.}
       Then $Q(b_1, \ldots, b_s, t)$ will be the minimal polynomial of $C$, so this polynomial will not satisfy the condition of~\ref{step:full_compute_q} and, thus, the algorithm will terminate without going back to~\ref{step:full_sampling1}.
   \end{itemize}

   Combining the two underlined assumptions in the text above, we see that the algorithm will return for a fixed value of $D$ if the following conditions hold:
   \begin{enumerate}
       \item $P_i(a_1, \ldots, a_N, t)$ is $\mathbb{Q}$-reducible for every $1 \leqslant i \leqslant s$ and these polynomials are all distinct;
       \item $Q(b_1, \ldots, b_s, t)$ is $\mathbb{Q}$-irreducible.
   \end{enumerate}
   \cite[Theorem~2.1]{Cohen} implies that there exists constants $C_0, C_1$ such that the probability of any of $P_i(a_1, \ldots, a_N, t)$'s and $Q(b_1, \ldots, b_s, t)$ being $\mathbb{Q}$-reducible is less that $\frac{C_1}{\sqrt[3]{D}}$ if $D > C_0$.
   Furthermore, the Schwartz-Zippel lemma~\cite[Proposition~98]{Zippel} implies that there exists a constant $C_2$ such that the probability of any of $P_i(a_1, \ldots, a_N, t)$'s being equal does not exceed $\frac{C_2}{D}$.
   Therefore, for $D > C_0$, the probability that $D$ will be updated is at most $\frac{C_1}{\sqrt[3]{D}} + \frac{C_2}{D}$.
   This number will eventually become less than $0.99$, so the probability of non-termination will be bounded by $0.99 \cdot 0.99 \cdot \ldots = 0$.
\end{proof}
\subsection{Search for invariant subspaces: how to find a chain}\label{sec:chain}

In this section, we describe how to use~\Cref{alg:one_space_full} in a recursive manner to find a maximal chain of invariant subspaces in $\overline{\mathbb{Q}}$ w.r.t. the Jacobian algebra $\mathcal{A} \subset \mathbb{Q}^{n \times n}$ of an ODE system.
We will denote a basis of $\mathcal{A}$ by $B_1, \ldots, B_N$

In the cases when~\Cref{alg:one_space_full} applied to $B_1, \ldots, B_N$ returned \texttt{NO} or a maximal chain of invariant subspaces, we are done.
Therefore, we consider the case when~\Cref{alg:one_space_full} returns a single invariant subspace $V \subset \mathbb{Q}^n$.
In this case, we consider two subproblems:
\begin{enumerate}
    \item \emph{Restriction.} Since $V$ is invariant w.r.t. $B_1, \ldots, B_N$, there are well-defined restrictions $B_1|_V, \ldots, B_N|_V$.
    We fix a basis in $V$ and will denote the matrix representations for these restricted operators also by $B_{1}^\ast, \ldots, B_{N}^\ast$.

    \item \emph{Quotients.} Consider the quotient space $\mathbb{Q}^n / V$ and the quotient map $\pi\colon \mathbb{Q}^n \to \mathbb{Q}^n / V$ (see~\cite[3.83, 3.88]{linalg}).
    Since $V$ is invariant w.r.t. $B_1, \ldots, B_N$, we can consider the quotient operators $B_1 / V, \ldots, B_N / V$ (see~\cite[5.14]{linalg}), we denote their matrix representations by $B_1^\circ, \ldots, B_N^\circ$.
    Note that, for every their common invariant subspace $U \subset \mathbb{Q}^n / V$, the subspace $\pi^{-1}(U) \subset \mathbb{Q}^n$ is invariant w.r.t. $B_1, \ldots, B_N$. 
\end{enumerate}
Note that the aforementioned matrix representations can be computed solving linear systems in $n$ variables.
Thus, we can work recursively with algebras $\langle B_1^\ast, \ldots, B_N^\ast \rangle$ on $V$ and $\langle B_1^\circ, \ldots, B_N^\circ \rangle$ on $\mathbb{Q}^n / V$.
If the resulting maximal chains of invariant subspaces are
\[
  0 \subsetneq V_1 \subsetneq \ldots \subsetneq V_s \subsetneq V \quad\text{ and }\quad 0\subsetneq U_1 \subsetneq \ldots \subsetneq U_r \subsetneq \mathbb{Q}^n / V,
\]
then we can return the following maximal chain of invariant subspaces for $B_1, \ldots, B_N$
\[
  0 \subsetneq V_1 \subsetneq \ldots \subsetneq V_s \subsetneq V \subsetneq \pi^{-1}(U_1) \subsetneq \ldots \subsetneq \pi^{-1}(U_r) \subsetneq \mathbb{Q}^n.
\]

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Putting everything together}\label{sec:general_algo}

In this section we collect the subroutines from the preceding sections into the complete algorithm for finding a maximal chain of lumpings.

\begin{algorithm}[H]
\caption{Finding a maximal chain of lumpings}
\label{alg:main}
\begin{description}[itemsep=0pt]
\item[Input ] ODE system $\mathbf{x}' = \mathbf{f}(\mathbf{x})$ with $\mathbf{x} = (x_1, \ldots, x_n)$, $\mathbf{f} = (f_1, \ldots, f_n) \in \mathbb{Q}[\mathbf{x}]^n$;
\item[Output ] a maximal chain of lumpings (see~\Cref{def:chain} and~\Cref{ex:chain});
\end{description}

\begin{enumerate}[label = \textbf{(Step~\arabic*)}, leftmargin=*, align=left, labelsep=2pt, itemsep=4pt]
    \item Compute the Jacobian $J(\mathbf{x})$ of $\mathbf{f}$ and the matrices $J_1, \ldots, J_\ell \in \mathbb{Q}^{n \times n}$ from its decomposition as in~\eqref{eq:jacobian_decomposition}.
    \item \label{step:algmain:2} Use~\Cref{alg:algebra-basis} to compute the basis $B_1, \ldots, B_N$ of the Jacobian algebra $\mathcal{A} = \langle I_n, J_1, \ldots, J_\ell \rangle$ of the system.
    \item \label{step:algmain:3} Apply~\Cref{alg:one_space_full} in a recursive way as decribed in~\Cref{sec:chain} to compute a maximal chain $V_1 \subsetneq \ldots \subsetneq V_s$ of subspaces in $\overline{\mathbb{Q}}^n$ invariant w.r.t. $\mathcal{A}$.
    \item For each $1 \leqslant i \leqslant s$, find a matrix $L_i$ with the columns being a basis of $V_i$.
    \item \textbf{Return} $L_1, \ldots, L_s$.
\end{enumerate}
\end{algorithm}

