\subsection{Dual Hahn polynomials}
Dual Hahn polynomials (Fig. \ref{fig:hahn}) are defined on a nonuniform lattice $x(s) = s(s+1)$, where $x$ is the distance of a sample from the origin and $s$ is the order of a sample \cite{Flusser2009}. Dual Hahn polynomials of order $p$ are defined as 
\begin{equation}\label{eq:hahnpoly}
	\begin{array}{c}
		k_p^{(c)}\left( {s,a,b} \right) = \frac{{{{(a - b + 1)}_p}{{(a + c + 1)}_p}}}{{p!}} \times {}_3{F_2}( - p,a - s,a + s + 1;a - b + 1,a + c + 1;1)\\
		{\rm{for}}\;p,x = 0,1, \ldots ,N - 1,s = a,a + 1, \ldots ,b - 1
	\end{array}
\end{equation}

The polynomials are on the interval $(a,b-1)$ and calculated using the additional parameter $c$.  $a$, $b$, and $c$ are subject to the constraints
\[
- \frac{1}{2} < a < b,\quad \left| c \right| < 1 + a,\quad b = a + N
\]
where $a$ determines the origin of the lattice, and the difference between $a$ and $c$ affects the range of polynomial values. The larger the difference between $a$ and $c$, the larger the range of polynomial values will be. The weight function is given by
\begin{equation}\label{eq:hahnweight}w(s)= \frac{\Gamma{(a+s+1)}\Gamma{(c+s+1)}}{\Gamma{(s-a+1)}\Gamma{(b-s)}\Gamma{(b+s+1)}\Gamma{(s-c+1)}}\end{equation}
and the squared norm is 
\begin{equation}\label{eq:hahnnorm}\rho(p)= \frac{\Gamma{(a+c+p+1)}}{p!(b-a-p-1)!\Gamma{(b-c-p)}}\end{equation}
The normalized dual Hahn polynomial is defined as 
\begin{equation}\label{eq:hahnnormpoly}\hat{k}_p^{(c)}(s,a,b)= k_p^{(c)}(s,a,b)\sqrt{\frac{w(s)}{\rho(p)} (2s+1)}\end{equation}
Dual Hahn polynomials follow the recurrence formula
\begin{equation}\label{eq:hahnrecur}\hat{k}_{p+1}^{(c)}(s,a,b)= A(\frac{\rho(p)}{\rho(p+1)})\hat{k}_{p}^{(c)}(s,a,b)- B(\frac{\rho(p-1)}{\rho(p+1)})\hat{k}_{p-1}^{(c)}(s,a,b)\end{equation}
where 
\[
\begin{split}
	A&=\frac{1}{p+1}(s(s+1)- ab + ac-bc-(b-a-c-1)(2p+1)+2p^2 ),\\
	B&=-\frac{1}{p+1}(a+c+p)(b-a-p)(b-c-p)
\end{split}
\]
and 
\[
\begin{split}
	\hat{k}_0^{(c)}(s,a,b)&= \sqrt{\frac{w(s)}{\rho(0)}(2s+1)},\\
	\hat{k}_1^{(c)}(s,a,b)&=((s-a)(s+b)(s-c)-(a+s+1)(c+s+1)(b-s-1))\sqrt{\frac{w(s)}{\rho(1) (2s+1)}}
\end{split}
\]
