\end{figure}

\subsection{Fourier-Mellin polynomials} 
Fourier-Mellin polynomials (Fig. \ref{fig:fourier-mellin}) of order $p$ and repetition $\lambda$ are defined as \cite{Sheng1994}
\begin{equation}\label{eq:fmpoly}V_{p\lambda}(r,\theta)= R_p(r)\text{ exp}(j\lambda\theta)\end{equation} 
with the radial polynomial $R_p(r)$ expressed as
\begin{equation}\label{eq:fmradialpoly}R_p{r}= \sum_{k=0}^{p} (-1)^{n+k}\frac{(n+k+1)!}{k!(k+1)!(n-k)!}r^k\end{equation}
When the real-valued radial part of a generalized pseudo-Zernike polynomial has parameters $\alpha=0$ and $\lambda=0$, it is reduced to the Fourier-Mellin polynomial $R_p(r)$. The Fourier-Mellin polynomial is computed recursively by
\begin{equation}\label{eq:fmrecur}R_p(r)= (M_1 r+ M_2)R_{p-1}(r) + M_3 R_{p-2}(r)\end{equation}
with
\begin{eqnarray*}
	M_1 &=& \frac{2(2p+1)}{(p+1)}\\
	M_2 &=& -2p+ M_1\frac{p(p-1)}{2p-1}\\
	M_3 &=& (p-1)(2p-1)+ M_2(2p-2)-M_1\frac{(p-1)(p-2)}{2}
\end{eqnarray*}
and
\begin{eqnarray*}
	R_{0}^{\alpha}(r) &=& 1\\
	R_{1}^{\alpha}(r) &=& 3r-2
\end{eqnarray*}

