    \text{ModalityScore}(i) = \frac{\mathbb{E}_{a \in A_{\text{image}}}(z_i)}{\mathbb{E}_{a \in A_{\text{image}}}(z_i) + \mathbb{E}_{a \in A_{\text{text}}}(z_i)} 
 \label{eq:modality_score}
\end{align}

