	\section{Appendix}
	We collect some of the more technical and lengthy details of the proofs. We start with the following statement from the proof of Lemma \ref{lemma:interpretationrestriction}.
	\begin{lemma}\label{lemma:interpretationrestriction2}
		Let $\mathcal{T}$ be a TBox and $\Gamma$ be a sequent. Let $Z$ be the additive group of $1$ and the constants appearing in $\Gamma$ and $\mathcal{T}$ intersected with the unit interval, $\epsilon := \frac{1}{2}\min (Z \setminus \{0\})$ and $Z' := Z \cup \{z+\epsilon \mid z \in Z \setminus\{1\}\}$. Then $\Gamma$ is satisfiable under $\mathcal{T}$ iff there exists an interpretation $\mathcal{I}$ and individual $x \in \Delta^\mathcal{I}$ where $\Gamma$ is satisfied in $x$ and for every $A \sqsubseteq B \in \mathcal{T}$ and every individual $y \in \Delta^\mathcal{I}$ we have some constant $z \in Z'$ with $((\lnot A \oplus z) \sqcap (B \oplus (1-z)))^\mathcal{I}(y) \geq 1$.
	\end{lemma}
	\begin{proof}
		If there exists such an interpretation then clearly $\Gamma$ is
		satisfiable under $\mathcal{T}$ with this interpretation as
		witness. On the other hand let $\mathcal{I}'$ be an interpretation
		that satisfies $\Gamma$ under $\mathcal{T}$. We construct
		$\mathcal{I}$ in the following way: Put
		$\Delta^\mathcal{I} := \Delta^{\mathcal{I}'}$. For every individual
		$x \in \Delta^\mathcal{I}$ put
		$p^\mathcal{I}(x) := p^{\mathcal{I}'}(x)$ if
		$p^{\mathcal{I}'}(x) \in Z$ and otherwise put
		$p^\mathcal{I}(x) := \max\{z\oplus\epsilon \mid z \in Z, z <
		p^{\mathcal{I}'}(x)\}$. For every role $R \in \mathsf{N_R}$ and individuals
		$x,y \in \Delta^\mathcal{I}$ we put
		$R^\mathcal{I}(x,y) := R^{\mathcal{I}'}(x,y)$ if
		$R^{\mathcal{I}'}(x,y) \in Z$ and
		$R^\mathcal{I}(x,y) := \max\{z\oplus\epsilon \mid z \in Z, z <
		R^{\mathcal{I}'}(x,y)\}$ otherwise. We prove by induction on~$C$
		that for every subconcept $C$ of $\Gamma$ and $\mathcal{T}$, every individual
		$x\in \Delta^\mathcal{I}$, and every constant $z \in Z$,
		$C^{\mathcal{I}'}(x) \mathrel{\bowtie} z$ iff $C^\mathcal{I}(x) \mathrel{\bowtie} z$,
		and if $\mathrel{\bowtie} \in \{ \geq, \leq\}$, then this even holds for all
		$z \in Z'$ with $z \neq C^\mathcal{I}(x)$.
		\begin{itemize}[wide]
			\item $C=c$  a constant: Trivial.
			\item $C=p$ an atomic concept: We have by definition that either
			$p^\mathcal{I}(x) = p^{\mathcal{I}'}(x)$, in which case the claim
			is trivial, or
			$p^\mathcal{I}(x) = \max\{z+\epsilon \mid z \in Z, z <
			p^{\mathcal{I}'}(x)\}$. In the latter case we clearly have for all
			$z \in Z$ that $z < p^{\mathcal{I}'}(x)$ iff
			$z < p^\mathcal{I}(x)$. The other inequalities directly follow.
																					\item Induction step: 
			\begin{itemize}[wide]
				\item $C=\lnot D$: We then have $D^{\mathcal{I}'}(x) \mathrel{\bowtie} 1-z$ iff $D^\mathcal{I}(x) \mathrel{\bowtie} 1-z$ by the induction hypothesis and the claim immediately follows.
				\item $C=D \ominus c$: If $(0, <) \neq (z, \mathrel{\bowtie}) \neq (0, \geq)$ and $(1, >) \neq (z, \mathrel{\bowtie}) \neq (1, \leq)$ we then have $D^{\mathcal{I}'}(x) \mathrel{\bowtie} z+c$ iff $D^\mathcal{I}(x) \mathrel{\bowtie} z+c$ by the induction hypothesis and the claim immediately follows. If $(0, <) = (z, \mathrel{\bowtie})$ or $(1, >) = (z, \mathrel{\bowtie})$ then both assertions are never satisfiable and if $(z, \mathrel{\bowtie}) = (0, \geq)$ or $(1, \leq) = (z, \mathrel{\bowtie})$ then the assertions are trivially always satisfied.
				\item $C= D_1 \sqcap D_2$: Using the induction hypothesis we have $D_1^{\mathcal{I}'}(x) \mathrel{\bowtie} z$ iff $D_1^\mathcal{I}(x) \mathrel{\bowtie} z$ and $D_2^{\mathcal{I}'}(x) \mathrel{\bowtie} z$ iff $D_2^\mathcal{I}(x) \mathrel{\bowtie} z$. If $\mathrel{\bowtie} = \mathrel{\triangleright}$ then we have $C^{\mathcal{I}'}(x) \mathrel{\triangleright} z$ iff $D_1^{\mathcal{I}'}(x) \mathrel{\triangleright} z, D_2^{\mathcal{I}'}(x) \mathrel{\triangleright} z$. By the induction hypothesis we then obtain $C^{\mathcal{I}'}(x) \mathrel{\triangleright} z$ iff $D_1^{\mathcal{I}}(x) \mathrel{\triangleright} z, D_2^{\mathcal{I}}(x) \mathrel{\triangleright} z$ which gives us $C^{\mathcal{I}'}(x) \mathrel{\triangleright} z \leftrightarrow C^{\mathcal{I}}(x) \mathrel{\triangleright} z$. On the other hand if $\mathrel{\bowtie} = \mathrel{\triangleleft}$ then we have $C^{\mathcal{I}'}(x) \mathrel{\triangleleft} z$ iff $D_1^{\mathcal{I}'}(x) \mathrel{\triangleleft} z$ or $D_2^{\mathcal{I}'}(x) \mathrel{\triangleleft} z$. Using the induction hypothesis on the corresponding case then immediately proves the claim.
				\item $C = \exists R . D$: If $\mathrel{\bowtie} = \mathrel{\triangleright}$ then $(\exists R . D)^{\mathcal{I}'}(x) \mathrel{\triangleright} z$ iff there exists $y \in \Delta^{\mathcal{I}'}$ with $R^{\mathcal{I}'}(x,y) \mathrel{\triangleright} z$ and $D^{\mathcal{I}'}(y) \mathrel{\triangleright} z$. The first one is by definition true iff $R^{\mathcal{I}}(x,y) \mathrel{\triangleright} z$ and the second one is true iff $D^{\mathcal{I}}(y) \mathrel{\triangleright} z$ by the induction hypothesis. Finally if $\mathrel{\bowtie} = \mathrel{\triangleleft}$ then for all $y \in \Delta^{\mathcal{I}'}$ we have $R^{\mathcal{I}'}(x,y) \mathrel{\triangleleft} z$ or $D^{\mathcal{I}'}(y) \mathrel{\triangleleft} z$ iff $(\exists R . D)^{\mathcal{I}'}(x) \mathrel{\triangleleft} z$. The first one is by defintion equivalent to $R^{\mathcal{I}}(x,y) \mathrel{\triangleleft} z$ and the second one by the induction hypothesis to $D^{\mathcal{I}}(y) \mathrel{\triangleleft} z$ which concludes the case.
			\end{itemize}
		\end{itemize}
		Using this we immediately obtain a constant $z \in Z'$ for every individual $x \in \Delta^\mathcal{I}$ and GCI $A \sqsubseteq B \in \mathcal{T}$ with $((\lnot A \oplus z) \sqcap (B \oplus (1-z)))^\mathcal{I}(x) \geq 1$ by for example taking $z = A^\mathcal{I}(x)$. Now let $x$ be the individual such that for all $C \mathrel{\bowtie} c \in \Gamma$ we have $C^{\mathcal{I}'}(x) \mathrel{\bowtie} c$. We then also have $C^{\mathcal{I}}(x) \mathrel{\bowtie} c$ by the induction and the fact that $c \in Z$.
	\end{proof}
														\noindent We have the following lemmas for the proof of Theorem \ref{tableau:completeness}:
	\begin{lemma}\label{lem:satpath}
		Let $G_c$ be a consistent marking for a tableau $G$ and $v_0, \ldots, v_n$ be a $G_c$-saturation path of $v_0$. Then:
		\begin{enumerate}[wide]
			\item all assertions of the form $p \mathrel{\bowtie} c$, $d \mathrel{\bowtie} c$, $\exists R . C \mathrel{\bowtie} c$ 
			of the label of each $v_i$ are in the label of $v_n$, where $p \in \mathsf{N_C}$.
			\item the label of each $v_i$ does not clash.
			\item the set formed by taking the union of the labels $v_0, v_1, \ldots, v_n$ does not clash.
		\end{enumerate}
	\end{lemma}
	\begin{proof}
		\begin{enumerate}[wide]
			\item This is trivial, as no rule operates on these assertions apart from the axioms which are disqualified because of it being a consistent marking and the $(\exists R)$ rule, which cannot be in the middle of such a path, as it would be an AND-node.
			\item If we have clashing assertions in some node $v$, there would have to be an axiom applied in $G$ to all successors of the corresponding node of $G$ before any other AND-node 
						can happen. This means that the AND-node $v_n$ would be the conclusion of an axiom, i.e. it would have a $\bot$ label, which violates the consistent marking condition. Contradiction.
			\item We take the union of the labels of $v_0, \ldots, v_n$. If there are clashing assertions, we have the following possibilities: either $p \mathrel{\triangleright} c$ with $p \in \mathsf{N_C}, c \mathrel{\overline{\triangleright}} 1$ or $p \mathrel{\triangleleft} c$ with $p \in \mathsf{N_C}, c \mathrel{\overline{\triangleleft}} 0$ is in the union, but then it would have been part of some $v_i$ which contradicts statement 2. The same is true for $c \mathrel{\triangleleft} d$ with $c \mathrel{\overline{\triangleleft}^\circ} d$, as this assertion would be in $v_n$ by statement 1. and by statement 2. this cannot be the case. Finally if we have the case $p \mathrel{\triangleleft} c, p \mathrel{\triangleright} d$ with $p \in \mathsf{N_C}$, $d \blacktriangleleft_{(\mathrel{\triangleleft}, \mathrel{\triangleright})} c$, we once again use statement 1. to assert that both of these must be in $v_n$ and as such by statement 2. this is a contradiction. 		\end{enumerate}
	\end{proof}
	\begin{definition}
		Let $G$ be a tableau graph and $v \in V^G$ be a node. Let $\exists R . C \mathrel{\triangleright} c \in \mathcal{L}^G(v)$. If the exists rule has been applied to $v$ in $G$ we call the conclusion of the instance of the exists rule, where $\exists R . C \mathrel{\triangleright} c$ is the relevant existential restriction, the \emph{associated conclusion} of $\exists R . C \mathrel{\triangleright} c$ in $v$. We will also write $\operatorname{AC}(\exists R . C \mathrel{\triangleright} c, v)$ for the associated conclusion.
	\end{definition}
	\begin{definition}\label{definition:extractedInterpretation}
		Let $G_c$ be a consistent marking for a tableau $G$. Then the interpretation $\mathcal{I}$ extracted from $G_c$, which we outlined in the proof of Theorem \ref{tableau:completeness}, is defined by the following procedure:
		\begin{enumerate}[wide]
			\item Put $\Delta^\mathcal{I} := A^G \cap V^{G_c}$.
			\item For $x \in \Delta^\mathcal{I}$, take all nodes along a $G_c$-saturation paths ending with $x$ as $\operatorname{SP}(x) := \{v_i \mid 0 \leq i \leq n, (v_0, \ldots, v_n=x) \text{ is a } G_c\text{-saturation path}\}$ and define $Y(x):=\bigcup_{v \in \operatorname{SP}(x)} \mathcal{L}^G(v)$ as the union of all labels of $G_c$-saturation paths ending with $x$. For every atomic concept $p$ we can then find a value $c \in [0,1]$ such that for every $p \mathrel{\bowtie} d \in Y(x)$ we have $c \mathrel{\bowtie} d$ is true. Define $p^\mathcal{I}(x) := c$. We can do this since the concept assertions in $Y(x)$ are not clashing.
			\item Let $x \in \Delta^\mathcal{I}$, $y \in \Delta^\mathcal{I}$ and $R$ be a role name. Define $\operatorname{EX}_{R} (x,y) \coloneqq \bigcup_{w \in \operatorname{SP}(y)} \{\exists R . D \mathrel{\triangleright} d \in \mathcal{L}^G(x) \mid (x,w) \in E^{G_c}, \mathcal{L}^G(w) = \operatorname{AC}(\exists R . D \mathrel{\triangleright} d, x)\}$ as the concept assertions $\exists R . D \mathrel{\triangleright} d$ in $Y(x)$ such that $D \mathrel{\triangleright} d$ is in $Y(y)$ and the associated conclusion in $x$ is the label of a node on a $G_c$-saturation path that ends at $y$.
			Furthermore, let $\operatorname{FA}_{R}(x):=\{\exists R . D \mathrel{\triangleleft} d \in Y(x)\}$ be the set of universal restrictions for $R$ in $x$. Find $e$ big enough such that for all $(\exists R . D \mathrel{\triangleright} d) \in \operatorname{EX}_{R}(x,y)$ we have $e \mathrel{\triangleright} d$, but small enough such that for all $(\exists R . D \mathrel{\triangleleft} d) \in \operatorname{FA}_{R} (x)$ we have $e \mathrel{\triangleleft} d$ or $(D \mathrel{\triangleleft} d) \in Y(y)$. Put $R ^\mathcal{I} (x,y) := e$. 		\end{enumerate}
	\end{definition}
	\begin{remark}
		We can always do step (3) of the construction in Definition \ref{definition:extractedInterpretation}: if we have $\exists R . D \mathrel{\triangleleft} d \in Y(x)$ then we also have $\exists R . D \mathrel{\triangleleft} d \in \mathcal{L}^G(x)$ and when we apply an exists rule to some $\exists R . F \mathrel{\triangleright} f \in \mathcal{L}^G(x)$ such that the conclusion $S$ is the label of some $w$ in $\operatorname{SP}(y)$ then $S \subseteq Y(y)$. If we have $d \blacktriangleleft_{(\mathrel{\triangleleft}, \mathrel{\triangleright})} f$, then $D \mathrel{\triangleleft} d$ is part of the conclusion, so we have $D \mathrel{\triangleleft} d \in Y(y)$.
		If we have $d \mathrel{\overline{\blacktriangleleft_{(\mathrel{\triangleleft}, \mathrel{\triangleright})}}^\circ} f$ for all $(\exists R . F \mathrel{\triangleright} f) \in \operatorname{EX}_{R}(x,y)$, then we can obviously find $e$ such that $e \mathrel{\triangleleft} d$ but for all $(\exists R . F \mathrel{\triangleright} f) \in \operatorname{EX}_{R}(x,y)$ we have $e \mathrel{\triangleright} f$.
		Doing this for all (finitely many) such assertions and taking the smallest such $e$ proves this claim.
	\end{remark}
	\begin{lemma}\label{lem:rulesapp}
		Let $\mathcal{I}$ be the interpretation extracted from a consistent marking $G_c$ for a tableau $G$ and $C \mathrel{\bowtie} c \in Y(x)$ for some $x \in \Delta^\mathcal{I}$. Then:
		\begin{enumerate}[wide]
			\item If there are OR-rules of the tableau applicable to $C \mathrel{\bowtie} c$ then at least one of the conclusions of an applicable rule is also in $Y(x)$.
			\item There is at most one OR-rule applicable to $C \mathrel{\bowtie} c$.
			\item If $C$ is not a constant, an atomic concept or $C = \exists R_l . D$ and $C \mathrel{\bowtie} c$ is not $D \ominus d \mathrel{\triangleright} c$ with $c \mathrel{\triangleright^\circ} 0$ then an OR-rule is always applicable to $C \mathrel{\bowtie} c$.
			\item If there are AND-rules of the tableau applicable to $C \mathrel{\bowtie} c = \exists R . D \mathrel{\triangleright} c$ then all of its conclusions are in $Y(y)$ and $R^\mathcal{I} (x,y) \mathrel{\triangleright} c$ for some $y \in \Delta^\mathcal{I}$.
		\end{enumerate}
	\end{lemma}
	\begin{proof}
		\begin{enumerate}[wide]
			\item Because of $C \mathrel{\bowtie} c \in Y(x)$ there exists a $G_c$-saturation path $(v_0, \ldots, v_n=x)$ with $C \mathrel{\bowtie} c \in \mathcal{L}^G(v_0)$. A $G_c$-saturation path either stops at an AND-node without successors, in which case no rule is applicable at all, or an AND-node where the exists rule is being applied, in which case no OR-rule is allowed to be applicable because of the saturation condition of the exists rule. This means that if there is any OR-rule applicable to $C \mathrel{\bowtie} c$ an OR-rule must have been applied to it along the $G_c$-saturation path, so we have some $0 \leq i \leq n$ where one of the conclusions of that rule is in the label $\mathcal{L}^G(v_i) \subseteq Y(x)$.
			\item This is true by the design of the grammar and the rules: Since we are in a consistent marking, the axioms cannot be applicable to any concept assertions in $Y(x)$, and by design the non-axiom OR-rules do not overlap.
			\item This is also trivially true by design of the grammar and the tableau rules.
			\item If the exists rule is applicable to $C \mathrel{\bowtie} c = \exists R . D \mathrel{\triangleright} c$, there has to be some $w \in G_c$ where $(x, w) \in E^{G_c}$, $D \mathrel{\triangleright} c \in \mathcal{L}^G(w)$ and for all $\exists R . F \mathrel{\triangleleft} f \in \operatorname{FA}(x)$ we have $F \mathrel{\triangleleft} f \in \mathcal{L}^G(w)$ or $f \mathrel{\triangleleft} c$. Since any node is part of at least one $G_c$-saturation path, this means that by construction we have to have $y \in \Delta^\mathcal{I}$ with $D \mathrel{\triangleright} c \in Y(y)$ and $R^\mathcal{I} (x,y) \mathrel{\triangleright} c$.
		\end{enumerate}
	\end{proof}
	\begin{lemma}\label{lem:CxSatInx}
		Let $\mathcal{I}$ be the interpretation extracted from a consistent marking $G_c$ for a tableau $G$. For every $x \in \Delta^\mathcal{I}$ and every $C \mathrel{\bowtie} c \in Y(x)$ we have $C^\mathcal{I}(x) \mathrel{\bowtie} c$.
	\end{lemma}
	\begin{proof}
		We prove this by induction:
		\begin{itemize}[wide]
			\item Induction base: Let $x \in \Delta^\mathcal{I}$ and $C=d$. Then
			$d \mathrel{\bowtie} c \in Y(x)$ means $d \mathrel{\bowtie} c \in \mathcal{L}^G(v)$
			for some $v \in \operatorname{SP}(x)$. If this was not
			satisfiable, then we would have a clashing assertion in
			$v$. Contradiction by Lemma \ref{lem:satpath} (2). Now let
			$C=p$. Then $p^\mathcal{I}(x) \mathrel{\bowtie} c \in Y(x)$ is satisfied by
			construction.
									\item Induction step:
			Let $x \in \Delta^\mathcal{I}$ and $C \mathrel{\bowtie} c \in Y(x)$. We are trying to prove $C^\mathcal{I}(x) \mathrel{\bowtie} c$. We then have some $v \in \operatorname{SP}(x)$ with $C \mathrel{\bowtie} c \in \mathcal{L}^G(v)$.
			\begin{itemize}[wide]
				\item By Lemma \ref{lem:rulesapp} (1)-(3) we have that for all cases where $C$ is neither a constant, atomic concept or $C = \exists R . D$ and $C \mathrel{\bowtie} c$ is not $D \ominus d \mathrel{\triangleright} c$ with $c \mathrel{\triangleright^\circ} 0$ that either the $(\sqcap \mathrel{\triangleright}), (\sqcap \mathrel{\triangleleft}), (\lnot \mathrel{\bowtie}), (\ominus, \mathrel{\triangleleft})$ or $(\ominus, \mathrel{\triangleright})$ rules were applied to $C \mathrel{\bowtie} c$ along a $G_c$-saturation path and that at least one of its conclusions are also in $Y(x)$. This means we can immediately conclude the cases of $C = \lnot D$, $C =  D \ominus d$ and $C = D \sqcap E$ by using the induction hypothesis on the conclusion that is in $Y(x)$. The case where $C \mathrel{\bowtie} c$ is $D \ominus d \mathrel{\triangleright} c$ with $c \mathrel{\triangleright^\circ} 0$ are trivially satisfied in any interpretation and individual.
				\item We also have by Lemma \ref{lem:rulesapp} (4) that if $C \mathrel{\bowtie} c = \exists R . D \mathrel{\triangleright} c$ then we have some $y \in \Delta^\mathcal{I}$ with $D \mathrel{\triangleright} c \in Y(y)$ and $R^\mathcal{I} (x,y) \mathrel{\triangleright} c$. Using the induction hypothesis again (this time on $y$ and  $D \mathrel{\triangleright} c$) we can immediately conclude this case.
				\item Case $C \mathrel{\bowtie} c = \exists R . D \mathrel{\triangleleft} c$:
				We have to check that for all $y \in \Delta^\mathcal{I}$ we have $R^\mathcal{I} (x,y) \mathrel{\triangleleft} c$ or $D^\mathcal{I}(y) \mathrel{\triangleleft} c$.
				Now let $y \in \Delta^\mathcal{I}$. Then by construction, if we do not have any $\exists R . F \mathrel{\triangleright} f \in Y(x)$ with $c \blacktriangleleft_{(\mathrel{\triangleleft}, \mathrel{\triangleright})} f$, we would have $R^\mathcal{I} (x,y) \mathrel{\triangleleft} c$ and would be done. On the other hand if we have $R^\mathcal{I} (x,y) \mathrel{\overline{\triangleleft}^\circ} c$, that means we have $\exists R . F \mathrel{\triangleright} f \in \operatorname{EX}_{R} (x,y)$ such that $f \mathrel{\overline{\triangleleft}^\circ} c$. We then have $\exists R . F \mathrel{\triangleright} f \in \mathcal{L}^G(x)$ and $\exists R . D \mathrel{\triangleleft} c \in \mathcal{L}^G(x)$. This means that for some $w_k$ along a $G_c$-saturation path $(w_0, \ldots, w_n=y)$ of the consistent marking and thus the tableau we have $F \mathrel{\triangleright} f \in \mathcal{L}^G(w_k)$ and $\exists R . F \mathrel{\triangleright} f \in \operatorname{EX}_{R}(x, w_k)$. Looking at the $(\exists R)$ rule, we then also have to have $D \mathrel{\triangleleft} c \in \mathcal{L}^G(w_k)$ and as such $D \mathrel{\triangleleft} c \in Y(y)$. Using the induction hypothesis on $y$ and $D \mathrel{\triangleleft} c$ then gives us $D^\mathcal{I}(y) \mathrel{\triangleleft} c$.
			\end{itemize}
		\end{itemize}
	\end{proof}
				Next we have the following claim in Theorem \ref{tableau:soundness}:
	\begin{lemma}\label{lem:sound}
		Each non-axiom tableau rule creates a (or all in the case of the exists rule) $\mathcal{T}$-satisfiable conclusion from a $\mathcal{T}$-satisfiable premiss.
	\end{lemma}
	\begin{proof}
		\begin{itemize}[wide]
			\item Case $(\sqcap \mathrel{\triangleright})$: If we have that $S, D \sqcap E \mathrel{\triangleright} d$ is $\mathcal{T}$-satisfiable, then that means there must be an interpretation $\mathcal{I}$ and an individual $x \in \Delta^\mathcal{I}$, where all concept assertions of $S$ and $D \sqcap E \mathrel{\triangleright} d$ are satisfied by $x$ under the TBox $\mathcal{T}$. However if $(D \sqcap E)^\mathcal{I}(x) \mathrel{\triangleright} d$ then by the very definition of $\sqcap$ both $D^\mathcal{I}(x) \mathrel{\triangleright} d$ and $E^\mathcal{I}(x) \mathrel{\triangleright} d$. Thus the conclusion of the rule is $\mathcal{T}$-satisfiable in the same interpretation and for the same individual.
			\item Case $(\sqcap \mathrel{\triangleleft})$: If we have that $S, D \sqcap E \mathrel{\triangleleft} d$ is $\mathcal{T}$-satisfiable, then that means there must be an interpretation $\mathcal{I}$ and an individual $x \in \Delta^\mathcal{I}$, where all concept assertions of $S$ and $D \sqcap E \mathrel{\triangleleft} d$ are satisfied by $x$ under the TBox $\mathcal{T}$. However if $(D \sqcap E)^\mathcal{I}(x) \mathrel{\triangleleft} d$ then by the very definition of $\sqcap$ we have $D^\mathcal{I}(x) \mathrel{\triangleleft} d$ or $E^\mathcal{I}(x) \mathrel{\triangleleft} d$ or both. Thus at least one of the conclusions of the rule is also $\mathcal{T}$-satisfiable in the same interpretation and for the same individual.
			\item Case $(\lnot \mathrel{\bowtie})$: If we have that $S, \lnot D \mathrel{\bowtie} d$ is $\mathcal{T}$-satisfiable, then that means there must be an interpretation $\mathcal{I}$ and an individual $x \in \Delta^\mathcal{I}$, where all concept assertions of $S$ and $\lnot D \mathrel{\bowtie} d$ are satisfied by $x$ under the TBox $\mathcal{T}$. However if $(\lnot D)^\mathcal{I}(x) \mathrel{\bowtie} d$ then by the very definition of $\lnot$ we have $D^\mathcal{I}(x) \mathrel{\bowtie^\circ} 1-d$. Thus the conclusion of the rule is $\mathcal{T}$-satisfiable in the same interpretation and for the same individual.
			\item Case $(\ominus \mathrel{\bowtie})$: If we have that $S, D \ominus d \mathrel{\bowtie} e$ is $\mathcal{T}$-satisfiable, then that means there must be an interpretation $\mathcal{I}$ and an individual $x \in \Delta^\mathcal{I}$, where all concept assertions of $S$ and $D \ominus d \mathrel{\bowtie} e$ are satisfied by $x$ under the TBox $\mathcal{T}$.
			We then have by the definition of $\ominus$ that $(D \ominus d)^\mathcal{I}(x) \mathrel{\bowtie} e \leftrightarrow \max(D^\mathcal{I}(x)-d,0) \mathrel{\bowtie} e$.
			\begin{itemize}[wide]
				\item Case $\mathrel{\bowtie} = \mathrel{\triangleleft}$: Then $e \mathrel{\triangleleft^\circ} 0$ otherwise the concept assertion would never be $\mathcal{T}$-satisfiable. We also trivially have $(D \ominus d)^\mathcal{I}(x) \geq D^\mathcal{I}(x) - d$ and as such $D^\mathcal{I}(x) \mathrel{\triangleleft} e + d$.
				\item Case $\mathrel{\bowtie} = \mathrel{\triangleright}$: Because of the condition $e \mathrel{\overline{\triangleright}} 0$ we have to have $D^\mathcal{I}(x) > d$ in order for the assertion to be $\mathcal{T}$-satisfiable and the $(\ominus \mathrel{\triangleright})$ rule to be applicable. Then we have $(D \ominus d)^\mathcal{I}(x) = D^\mathcal{I}(x) - d$ and as such $D^\mathcal{I}(x) \mathrel{\triangleright} e + d$.
			\end{itemize}
			Thus the conclusions of the rules are $\mathcal{T}$-satisfiable in the same interpretation and for the same individual.
			\item Case axioms: If any axiom rule is applicable, then the premiss was also not $\mathcal{T}$-satisfiable. Contradiction.
			\item Case $(\exists R . \mathrel{\triangleright})$: If we have that $S, \{ \exists R . E_j \mathrel{\triangleleft}_j  e_j \mid 1 \leq j \leq n\}, \exists R . D \mathrel{\triangleright} d$ is $\mathcal{T}$-satisfiable and $d \mathrel{\overline{\triangleright}} 0$, that means there must be an interpretation $\mathcal{I}$ and an individual $x \in \Delta^\mathcal{I}$, where all concept assertions of $S$ and $\{ \exists R . E_j \mathrel{\triangleleft}_j  e_j \mid 1 \leq j \leq n\}, \exists R . D \mathrel{\triangleright} d$ are satisfied by $x$ under the TBox $\mathcal{T}$. If we have for all $1 \leq j \leq n$ that $(\exists R . E_j)^\mathcal{I}(x) \mathrel{\triangleleft}_j e_j$ and $(\exists R . D)^\mathcal{I}(x) \mathrel{\triangleright} d$, that means there must be an individual $y \in \Delta^\mathcal{I}$ with $R^\mathcal{I} (x,y) \mathrel{\triangleright} d$, $D^\mathcal{I}(y) \mathrel{\triangleright} d$ and $E_j^\mathcal{I}(y) \mathrel{\triangleleft}_j e_j$ for at least all $j \in \{1, \ldots, n\}$ with $e_j \blacktriangleleft_{(\mathrel{\triangleleft}_j, \mathrel{\triangleright})} d$ under the TBox $\mathcal{T}$. The other universal restrictions can be trivially satisfied by the value of $R^\mathcal{I} (x,y)$. This is exactly the conclusion of the rule, so the conclusions also have to be $\mathcal{T}$-satisfiable.
		\end{itemize}
	\end{proof}
				We also had the following claim in the proof of Theorem \ref{theorem:exptime}:
	\begin{lemma}\label{lemma:labelsEstimate}
		Let $\Gamma$ be a sequent, $\mathcal{T}$ a TBox and $T \geq 1$ the associated concept assertion to $\mathcal{T}$ and $\Gamma$.
		Then there are at most $2^{O(n^3)}$ possible labels for a tableau of $\Gamma$ and $T \geq 1$, where $n$ is the syntactic size of $\Gamma$ and a TBox $\mathcal{T}$.
	\end{lemma}
	\begin{proof}
		When constructing $G$, we have that for any subconcept of a concept assertion in the current node there can only be one possible comparison operator and constant on the right hand side associated with this subconcept (not counting instances of the same subconcept in another place), as the propositional rules always simplify a concept when changing the comparison operator or constant and for each concept assertion there is at most one propositional rule applicable at all times. 
		The exists rules even keep their comparison operator and constants, so they do not give rise to any other possible comparison operators and constants associated with the subconcept. 
		The only possible way to have some subconcept associated with multiple pairs of comparators and constants is if the subconcept shows up multiple times in the concept. 
		However this still leaves us with at most $2^{O(m)}$ possible labels made up of just subconcept assertions from $\Gamma$, where $m$ is the syntactic size of $\Gamma$. We next have to deal with the possible labels of subconcept assertions of the TBox: 
		Let $n$ be the syntactic size of $\Gamma$ and $\mathcal{T}$. Then there are $O(n)$ constants, each having a numerator and denominator of binary length $O(n)$. The least common multiple of their denominators then has binary length $O(n^2)$ which gives us that the size of the additive group $Z$ of $1$ and constants in $\Gamma$ and $\mathcal{T}$ is of size $2^{O(n^2)}$. Let $\epsilon := \frac{1}{2} \min Z \setminus \{0\}$ then $Z' := Z \cup \{z+\epsilon \mid z \in Z \setminus \{1\}\}$ is also of size $2^{O(n^2)}$. Looking at the rules of the tableau, for each GCI $C \sqsubseteq D$ a label either has some subconcepts of $(\lnot C \oplus z) \sqcap (D \oplus (1-z)) \geq 1$ for one $z \in Z'$ or for a subset $U \subseteq Z'$ the concept assertion $\sqcup_{z \in U}(\lnot C \oplus z) \sqcap (D \oplus (1-z)) \geq 1$. We can however further restrict the possible choices of $U$ by investigating the $(\sqcap \mathrel{\triangleleft})$ rule and noticing that we only have subsets $U_z=\{z\}$ for $z \in Z'$ and $U^c=\{z \mid z \in Z', z \geq c\}$ for constants $c \in Z'$, where we supposed without loss of generality that the disjunction in the concept assertion $\sqcup_{z \in Z'}(\lnot C \oplus z) \sqcap (D \oplus (1-z)) \geq 1$ was ordered based on the ordering of $Z'$. Both of these cases yield $2^{O(n^2)}$ possible labels resulting from the GCI $C \sqsubseteq D$. This then leaves us with $2^{O(n^3)}$ possible labels for all GCIs of $\mathcal{T}$ and multiplying with the $2^{O(m)} \leq 2^{O(n)}$ possible labels resulting from $\Gamma$ we have that there are at most $2^{O(n^3)}$ possible labels in a tableau.
	\end{proof}
	Finally, we had the following claim in the proof of Theorem \ref{theorem:hardness}:
	\begin{lemma}
		Let $\mathcal{I}$ and $\mathcal{I}'$ be the interpretations from the proof of Theorem \ref{theorem:hardness}. Then we have $C^{\mathcal{I}'}(x) > 0.5 \leftrightarrow x \in C^\mathcal{I}$ for all concepts $C$ of regular $\ALC$.
	\end{lemma}
	\begin{proof}
		We prove this by induction:
		\begin{itemize}[wide]
			\item Induction base: The case for atoms is clear by the definition. The case for constants is trivial.
			\item Case $C = D \sqcap E$: We have $C^{\mathcal{I}'}(x) > 0.5 \leftrightarrow D^{\mathcal{I}'}(x) > 0.5, E^{\mathcal{I}'}(x) > 0.5$. Using the induction hypothesis we have $C^{\mathcal{I}'}(x) > 0.5 \leftrightarrow x \in D^\mathcal{I}, x \in E^\mathcal{I}$ and as such $C^{\mathcal{I}'}(x) > 0.5 \leftrightarrow x \in C^\mathcal{I}$.
			\item Case $C = \lnot D$: We have $C^{\mathcal{I}'}(x) > 0.5 \leftrightarrow D^{\mathcal{I}'}(x) \leq 0.5$. Using the induction hypothesis then gives us $C^{\mathcal{I}'}(x) > 0.5 \leftrightarrow x \notin D^\mathcal{I}$ and as such $C^{\mathcal{I}'}(x) > 0.5 \leftrightarrow x \in C^\mathcal{I}$.
			\item Case $C = \exists R . D$: We have $C^{\mathcal{I}'}(x) > 0.5 \leftrightarrow \exists y \in \Delta^{\mathcal{I}'}: R^{\mathcal{I}'}(x,y)>0.5, D^{\mathcal{I}'}(y)>0.5$. Using the definition of $\mathcal{I}$ and the induction hypothesis gives us $C^{\mathcal{I}'}(x) > 0.5 \leftrightarrow \exists y \in \Delta^\mathcal{I}: (x,y) \in R^\mathcal{I}, y \in D^\mathcal{I}$ and as such $C^{\mathcal{I}'}(x) > 0.5 \leftrightarrow x \in C^\mathcal{I}$.
		\end{itemize}
	\end{proof}
