 \item $Q=\{q_0,q_1,q_2,q_3,q_4,q_5,q_6,q_7\}$ and $I=\{q_0\}$,
 \item $\Sigma = \{a,b,c\}$,
 \item $\arraycolsep2pt
  \begin{array}[t]{lcllcllcllcl}
  \tau(q_0) & = & \{a,b\}, & \tau(q_1) & = & \emptyset, & \tau(q_2) & = & \{a\}, & \tau(q_3) & = & \{b\},\\
  \tau(q_4) & = & \emptyset, & \tau(q_5) & = & \{a\},& \tau(q_6) & = & \{a\},& \tau(q_7) & = & \{b\},
  \end{array}$
  %and $\tau(q_8) = \{a\}$,
 \item $\arraycolsep=2pt
       \begin{array}[t]{lcllcllcllcl}
        \delta(q_0,c) & = & q_1, & \delta(q_0,\lhd) & = & q_4,\\
        \delta(q_1,a) & = & q_2, & \delta(q_1,b)    & = & q_3, & \delta(q_1,\lhd) & = & \multicolumn{4}{l}{\Accept,}\\
        \delta(q_2,b) & = & q_1, & \delta(q_3,a)    & = & q_1,\\
        \delta(q_4,a) & = & q_5, & \delta(q_4,b)    & = & q_7, & \delta(q_4,\lhd) & = & \multicolumn{4}{l}{\Accept,}\\
        \delta(q_5,b) & = & q_6, & \delta(q_6,b)    & = & q_4, & \delta(q_7,a) & = & q_6. %& \delta(q_8,b) & = & q_4.
       \end{array}$
       \newline
       \vspace{+1mm}

while $\delta$ yields the empty set for all other pairs from $Q\times(\Sigma\cup\{\lhd\})$.
\end{itemize}
