                   & \vdash_{A_{\vee,c}} & q_2bba\cdot\lhd & \vdash_{A_{\vee,c}} & q_1ba\cdot\lhd & \vdash_{A_{\vee,c}} & q_3a\cdot\lhd\\
                   & \vdash_{A_{\vee,c}} & q_1\cdot\lhd & \vdash_{A_{\vee,c}} & \Accept,
