\begin{lemma}
\label{lem:1-right}
    Let $A=(1,0)$, $B=(0,0)$, and $X=(x_0,0)$ be a point on the line 
segment $AB$.
For any convex quadrilateral with $\overline{AB}$ as diagonal, there is 
a cubic \Bezier{} curve with $A$ and $B$ as endpoints and $C_1$ and $D_1$ as control points that intersects the 
line segment $\overline{AB}$ at $X$ at a right angle at the parameter
value $t=t_0=\frac{C_{1,x}-2D_{1,x}}{-1+3C_{1,x}-3D_{1,x}}$, and is contained within this quadrilateral and also within any pair of opposite quadrants around the point of intersection.
\end{lemma}
\begin{proof}
Assume $x_0<8/9$. Otherwise mirror the plane.
    Let $D_1=(D_{1,x},-r)$ and $C_1=(\frac{1}{2}(D_{1,x}-\sqrt{4D_{1,x}-3D_{1,x}^2}),\frac{1-2C_{1,x}+D_{1,x}}{2D_{1,x}-C_{1,x}}r)$ where $r\in \mathbb{R}$. We will define $D_{1,x}$ later. Let $f_1(t)=At^3+3C_1t^2(1-t)+3D_1t(1-t)^2+B(1-t)^3$ be the \Bezier{} curve
we are constructing. Then the $y$-coordinate function for $f_1$ is
    \begin{equation*}
        f_{1,y}(t)=-3\frac{1-2C_{1,x}+D_{1,x}}{2D_{1,x}-C_{1,x}}rt^2(1-t)+3rt(1-t)^2.
    \end{equation*}
    At $t=t_0$, $f_{1,y}(t)=0$. Note that there are three roots for the 
cubic polynomial $f_{1,y}$ and the other two are at $t=0$ and $t=1$.
The $x$-coordinate function for $f_1$ is
    \begin{equation*}
        f_{1,x}(t)=t^3+3\frac{1}{2}(D_{1,x}-\sqrt{4D_{1,x}-3D_{1,x}^2})t^2(1-t)+3D_{1,x}t(1-t)^2 .
    \end{equation*}
    At $t=t_0$, $f_{1,x}(t)=\frac{D_{1,x} \left(3 D_{1,x}+\sqrt{-D_{1,x} (3 D_{1,x}-4)}\right)}{3 D_{1,x}+3
   \sqrt{-D_{1,x} (3 D_{1,x}-4)}+2}$ and we choose $D_{1,x}$ to be $x_0+\sqrt[3]{x_0^2-x_0^3}$ which is a root of $f_{1,x}(t_0)=x_0$ when treated as an equation in $D_{1,x}$. This root is valid whenever $C_{1,x}$ is real, which happens when $4D_{1,x}-3D_{1,x}^2\geq 0$, which is true when $0\leq D_{1,x}\leq4/3$. This happens when $0\leq x_0\leq8/9$. Moreover,
\begin{eqnarray*}
        \diff{f_{1,y}}{t}=-\frac{3 r \left(C_{1,x} \left(9 t^2-8 t+1\right)+D_{1,x}
   \left(-9 t^2+10 t-2\right)+(2-3 t) t\right)}{C_{1,x}-2
   D_{1,x}} \mbox{~~~and}
\\
        \diff{f_{1,x}}{t}=3 \left(t (C_{1,x} (2-3 t)+t)+D_{1,x} \left(3 t^2-4
   t+1\right)\right).
\end{eqnarray*}
    At $t=t_0$, 
\[
\diff{f_{1,x}}{f_{1,y}}=\frac{\diff{f_{1,x}}{t}}{\diff{f_{1,y}}{t}}=0, 
\]
which means that the angle at the point of intersection is $\pi/2$. Also, the value of $C_{1,x}$ is such that 
$\diff{f_{1,x}}{t} = 3 t^2 (-3 C_{1,x}+3 D_{1,x}+1)+3 t (2 C_{1,x}-4 D_{1,x})+3 D_{1,x}$ is a quadratic polynomial in terms of $t$ with discriminant $0$. 
This means that $t_0$ is a repeated root and, hence, $f_{1,x}$ is monotonic. 
Thus, the curve remains in a pair of opposite quadrants, 
determined by the sign of $r$.
    Next, we show that this curve is bounded by the quadrilateral $(0,0),(x_0,\frac{-rx_0}{D_{1,x}}),(1,0),(x_0,\frac{r(1-2C_{1,x}+D_{1,x})(x_0-1)}{(C_{1,x}-1)(2D_{1,x}-C_{1,x})})$. This is obtained by the convex hull property of \Bezier{} curves in conjunction with the fact that $f_{1,x}$ is monotonic. For any value of $x_0$, these values are bounded.
    The value of $r$ can be adjusted such that this quadrilateral is contained within any quadrilateral with the diagonal $\overline{AB}$.
\end{proof}

We next address the case for the point of intersection $X$ 
having $x$-coordinate in $(0,8/9)$ and forming an angle of $0$.

% \subsubsection{Simple straight line curve that is at $(x_0,0)$ at $t=1/2$ for $x_0\in[1/8,7/8]$}\label{first curve flat}

\begin{lemma}
\label{lem:1-zero}
    Let $A=(1,0)$, $B=(0,0)$, and $X=(x_0,0)$ a point on the line segment $\overline{AB}$. There is a cubic \Bezier{} curve with $A$ and $B$ as endpoints that is at $X$ when $t=t_0$ as obtained from \cref{lem:1-right} for the same $X$ and monotonically traces the straight line segment $\overline{AB}$.
\end{lemma}
\begin{proof}
Assume $x_0<8/9$. Otherwise, mirror the plane.
    Let $C_2=D_2=(\frac{x_0-t_0^3}{3(1-t_0)t_0},0)$ and 
$f_2(t)=At^3+3C_2t^2(1-t)+3D_2t(1-t)^2+B(1-t)^3$ be the \Bezier{} curve
we are constructing.
    It is easy to see that for $f_2$'s $y$-coordinate function, $f_{2,y}=0$ 
throughout.
The $x$-coordinate function is
    \begin{equation*}
        f_{2,x}(t)=t^3+\frac{(1-t)t(x_0-t_0^3)}{(1-t_0)t_0}.
    \end{equation*}
    At $t=t_0$, $f_{2,x}(t)=x_0$. Also, $C_2$ and $D_2$, the repeated control points are between $A$ and $B$.

This means that the curve is always moving from 
$B$ to $A$ when $t$ goes from $0$ to $1$, 
without turning back or overshooting $A$.
\end{proof}

Given the previous two lemmas, we now can use them in convex combination.

% \subsection{A \Bezier{} curve intersecting at slope $m$ at $(x_0,0)$ at $t=1/2$ for $x_0\in[1/8,7/8]$}\label{first curve interpolated}

\begin{lemma}\label{lem:1-conv}
    Let $A=(1,0)$, $B=(0,0)$, $X=(x_0,0)$ a point on the line segment $\overline{AB}$ and $m$ a real number. 
For any convex quadrilateral with $\overline{AB}$ as a horizontal diagonal, 
there is a simple cubic \Bezier{} curve with $A$ and $B$ as endpoints that intersects the line segment $\overline{AB}$ at $X$ with slope $m$ 
for the parameter value $t=t_0$ as obtained from \cref{lem:1-right} for the same $X$ and is contained within this quadrilateral and also within any pair of opposite quadrants around the point of intersection.
\end{lemma}
\begin{proof}
    Let $C_3=kC_1+(1-k)C_2$ and $D_3=kD_1+(1-k)D_2$ for $k\in[0,1]$ where $C_1,D_1$ are control points of a curve $f_1(t)$ obtained from 
the proof of
\cref{lem:1-right} 
and $C_2,D_2$ are control points of a curve $f_2(t)$ obtained 
from the proof of
\cref{lem:1-zero}. 
Let 
\[
f_3(t)=At^3+3C_3t^2(1-t)+3D_3t(1-t)^2+B(1-t)^3=kf_1(t)+(1-k)f_2(t)
\]
be the more-general \Bezier{} curve we are now constructing as 
a convex combination of $f_1$ and $f_2$. 
Clearly, $f_3(t)$ is at $X$ when $t=t_0$.
In addition, we can write the slope of $f_3$ at $t_0$ as follows:
    \begin{equation*}
        \diff{f_{3,y}}{f_{3,x}} ~~=~~
       \frac{\diff{f_{3,y}}{t}}{\diff{f_{3,x}}{t}}
     ~~=~~ \frac{k\diff{f_{1,y}}{t}}{k\diff{f_{1,x}}{t}+(1-k)\diff{f_{2,x}}{t}}. 
    \end{equation*}
    To get a positive slope, we use a positive value of $r$. 
    To get a negative slope, we use a negative value of $r$. 
Values of $k$ in $[0,1]$ will span the full range of slopes
(either positive or negative) for every value of $r$.
    To get a specific slope $m$ at $t=t_0$, we set
    \begin{equation*}
        k=\frac{m\diff{f_{2,x}}{t}}{m(\diff{f_{1,x}}{t}-\diff{f_{2,x}}{t})+\diff{f_{1,y}}{t}} .
    \end{equation*}

    Now, we need to show that this curve does not self-intersect. $f_{3,x}$ is monotonic as it is a convex combination of monotonic functions. This means that no $x$-coordinate is repeated and the curve does not self intersect
The curve, $f_3$, is also bounded by the quadrilateral,
$(0,0),(x_0,\frac{-rx_0}{D_{1,x}}),(1,0),(x_0,\frac{r(1-2C_{1,x}+D_{1,x})(x_0-1)}{(C_{1,x}-1)(2D_{1,x}-C_{1,x})})$,
as it is a convex combination of the curves 
from \cref{lem:1-right} and \cref{lem:1-zero},
which are bounded by the same. 
The value of $r$ can be adjusted such that this quadrilateral 
is contained within any arbitrary quadrilateral. Again this curve also remains in a pair of opposite quadrants around $X$ since $f_{3,x}$ is monotonic.
\end{proof}

\section{RAC Drawings of 1-Planar Graphs with \Bezier{} Curves}\label{proof1planar}

We are now ready to prove 
\cref{thm:planarmain}, which is the following.

\planarmain*

% \begin{theorem}\label{planarmain}
% Any $n$-vertex $1$-planar graph has a $1$-planar RAC drawing using a single
% cubic \Bezier{} curve per edge. 
% Further, if a $1$-planar embedding of the graph has been provided, 
% a $1$-planar RAC drawing using such cubic \Bezier{} curves 
% can be computed in $O(n)$ time.
% \end{theorem}

The proof goes through three stages,
adapting a proof of
Bekos, Didimo, Liotta, Mehrabi, and Montecchiani~\cite{BEKOS201748} for
RAC drawings of 1-planar graphs with 1-bend polygonal edges.

\subsection{Augmentation}
We start with a $1$-plane combinatorial drawing $G$ of the graph. We call every connected region of the plane bounded by edges and parts of edges a face. The number of such edges or parts is called the length of the face. The induction will be using triangulated $1$-plane multigraphs, that is, $1$-plane multigraphs in which every face is of length $3$.
For every pair of crossing edges $ab,cd$, add edges $ac,cb,bd,ad$ such that the only edges contained within the cycle $acbd$ are $ab$ and $cd$. We call the subgraph consisting of these edges an empty kite. If there are $2$-length faces in this drawing, remove one of the edges recursively until there are no more. Also remove any parallel edge that was crossed. Now all faces in this drawing are either of length three with $2$ vertices and a crossing point or bounded only by vertices and no crossing points. In every face longer than $3$ add a new vertex and connect it to all the vertices on the face. We call this $1$-plane multigraph $G^+$. 
\subsection{Contraction}
A separation pair is a pair of vertices $\{u,v\}$ whose removal disconnects the graph. Lemma 5 in~\cite{BEKOS201748} states that between any separation pair $\{u,v\}$, there exist two parallel edges $e,e'$ such that $\{u,v\}$ is not a separation pair for the graph obtained by removing everything inside the cycle $\left<e,u,e',v\right>$. We call this removed subgraph along with the cycle $G_{uv}$. Replace $G_{uv}$ with a thick edge and iterate until there are no separation pairs. We call this graph $G^*$. $G^*$ is a simple triangulated $1$-plane graph.
\subsection{Drawing}
Obtain graph $H^*$ by removing all crossing pairs in $G^*$. All the faces of $H^*$ have either three or four vertices.
%\begin{lemma}
 %   $H^*$ is $3$-connected
%\end{lemma}
%\begin{proof}
