\noindent \textbf{Outline of the article.} The rest of this article is organized as follows. In Section~\ref{sec:main-results}, we introduce the numerical scheme and present the main theoretical results, along with the methodology used to prove them.
In Section~\ref{sec:rescaling}, we rescale the original problem and the numerical scheme into $\lambda$-periodic forms. Additionally, we introduce the methodology for constructing the continuation of numerical solutions, which are initially defined only at discrete time nodes. 
Section~\ref{sec:bourgain} provides the necessary definitions related to Bourgain spaces and presents key preliminary results essential for the analysis.
In Section~\ref{sec:stability}, we establish the uniform boundedness of the numerical method by formulating and analyzing an appropriate fixed point problem within the Bourgain space framework.
Section~\ref{sec:proof_of_main_theorem} focuses on deriving estimates for the consistency error and provides the detailed proof of the main theorem, Theorem~\ref{thm:main}.
Finally, in Section~\ref{sec:numerical_experiments}, we present numerical experiments that validate the theoretical findings and demonstrate the practical performance of the proposed numerical method.

\section{Main results and methodology}\label{sec:main-results}
In this section, we present the main results and methodology of this article, with a focus on the development and analysis of a filtered low-regularity integrator. We state the main theorem, which provides error estimates under suitable choices of the filter parameter, and derive a fully discrete scheme using Fourier spectral methods. Furthermore, we outline the proof of the main results, demonstrating how Bourgain spaces and a  continuous  reformulation are combined to establish the theoretical findings.

\subsection{Numerical scheme and main  results}
We consider the filtered low regularity integrator that was first introduced in \cite{Hofmanova-Schratz-2017}:
\begin{align}\label{eq:filtered_LRI}
	u^{n+1}&=e^{-\tau \partial_x^3}u^n+\frac{1}{2}\int_{\sigma_n}^{\sigma_{n+1}}e^{(t-\sigma_{n+1})\partial_x^3}\Pi_{N}\partial_{x}\left(e^{(\sigma_n-t)\partial_x^3}\Pi_{N}u^n\right)^2\d t,\notag\\
	&=e^{-\tau \partial_x^3}u^n+\frac{1}{6}\Pi_{N}\left(e^{-\tau\partial_x^3}\partial_x^{-1}\Pi_{N}u^n\right)^2-\frac{1}{6}\Pi_{N}e^{-\tau \partial_x^3}\left(\partial_x^{-1}\Pi_{N}u^n\right)^2,
\end{align}
with $u^0=\phi$ and $\sigma_n=n\tau$ for $n=0,1,\cdots,L=T/\tau$ being a partition of the time interval. Here $\Pi_N$ denotes the projection operator for the positive integer $N$, defined by 
\begin{align}
	(\widehat{\Pi_N f})_{k}=\left\{
	\begin{array}{l}
		\hat{f}_{k}\quad \text{if}\;\; |k|\leq N,\\[2mm]
		0\quad \;\, \text{if}\;\; |k|> N,
	\end{array}
	\right.\quad \text{where} \quad \hat{f}_k=\int_0^1 e^{-2\pi ikx}f(x)\d x, \quad \text{for}\quad k\in \mathbb{Z}.
\end{align}
We present the following main theorem of this paper:
%We note that for the problem considered in this article, it is crucial to choose an appropriate value of $N$ to balance the stability and convergence of the algorithm. Therefore, we present the following main theorem of this paper:
\begin{theorem}\label{thm:main}
	For given $T>0$ and initial value $\phi\in H^s(\T)$ with $s\in(-\frac{1}{2},0]$  and $\int_{\T}\phi\,\d x=0$, we denote by $u\in L^{\infty}(0,T;H^{s})$ the unique solution of \eqref{eq:KdV_equation}, and denote by $u^n$, the numerical solution given by \eqref{eq:filtered_LRI}. Then, by choosing $N=O(\tau^{-\frac{1}{2-2s}+})$, there exist constants $\tau_0\in (0,1)$, and $C>0$ such that, for time step size $\tau\in(0,\tau_0)$,
	\begin{align}\label{eq:main_thm}
		\max_{0\leq n\leq T/\tau}\|u(\sigma_n)-u^n\|_{H^{-\frac{1}{2}}}\leq C \tau^{\frac{1+2s}{4-4s}-}.
	\end{align}
\end{theorem}

\begin{remark}
	\upshape 
	Without loss of generality, we can assume that $u(0,x)=\phi(x)$ has zero mean in the spatial variable, i.e., $\int_\T \phi \, \d x = 0$. Otherwise, we can redefine the solution using the transformation
	$$
	\tilde{u}(t,x) := u(t,x - t \, \Pi_0{\phi}) - \Pi_0{\phi},
	$$
	which satisfies \eqref{eq:KdV_equation} with the initial value 
	$$
	\tilde{\phi} = \phi - \Pi_0{\phi},
	$$
	where $\tilde{\phi}$ has zero mean, i.e., $\int_\T \tilde{\phi} \, \d x = 0$.
\end{remark}

By applying Fourier spectral discretization in space, we derive the following fully discrete numerical scheme:
\begin{align}\label{eq:fully_discrete}
	u_N^{n+1} = &\, e^{-\tau \partial_x^3}\Pi_{N_c}u_N^n 
	+\frac{1}{6}\Pi_{N}\left(e^{-\tau\partial_x^3}\partial_x^{-1}\Pi_{N}u_N^n\right)^2
	-\frac{1}{6}\Pi_{N}e^{-\tau \partial_x^3}\left(\partial_x^{-1}\Pi_{N}u_N^n\right)^2,
\end{align}
with initial condition $u_N^0=\Pi_{N_c}\phi$. Here, we set $N_c=C_L N$ with a constant $C_L\geq 1$, which can be suitably chosen to balance the errors arising from the linear and nonlinear discretizations. Note that under the condition $N=O(\tau^{-\frac{1}{2-2s}+})$, we have $N^{-\frac{1}{2}-s}=O(\tau^{\frac{1+2s}{4-4s}-})$. Thus, as a direct consequence of Theorem~\ref{thm:main}, we obtain the following error estimate:

\begin{corollary}\label{rem:fully_discrete}
	Under the conditions of Theorem~\ref{thm:main}, let $u_N^n$ denote the numerical solution of the fully discrete scheme \eqref{eq:fully_discrete} with $N_c=C_L N$, $C_L\geq 1$. Then, under the CFL-type condition $\tau=O(N^{-2+2s-})$, there exist constants $N_0\geq 1$ and $C>0$ such that for all $N\geq N_0$,
	\begin{align}
		\max_{0\leq n\leq T/\tau}\|u(\sigma_n)-u_N^n\|_{H^{-\frac{1}{2}}}\leq C N^{-\frac{1}{2}-s}.
	\end{align}
\end{corollary}

\subsection{Sketch of the proof}
For the readers' convenience, we outline the proof of Theorem~\ref{thm:main} as follows, based on the Bourgain-space estimates at the continuous level, and present the details of the proof in the following sections. 

First, we introduce an appropriate rescaling for both the exact solution $u$ of the original KdV equation \eqref{eq:KdV_equation} and the numerical solution $u^n$ obtained from the filtered low-regularity integrator \eqref{eq:filtered_LRI}:
\begin{align*}
	u_{\lambda}(t,x) = \lambda^{-2}u\left(\frac{t}{\lambda^3}, \frac{x}{\lambda}\right), 
	\quad\text{and}\quad 
	u^n_{\lambda}(x) = \lambda^{-2}u^n\left(\frac{x}{\lambda}\right),
\end{align*}
where $\lambda$ is a constant independent of $N$ and $\tau$. By applying the variation-of-constants formula to the rescaled KdV equation and introducing a suitable temporal localization function $\eta$, we define the nonlinear mapping $\widetilde{\Gamma}$ as follows:
\begin{align}\label{eq:fix_point_2}
	\widetilde{\Gamma}(w)(t) = \eta(t)e^{-t \partial_x^3}u_{\lambda}(0)
	+ \frac{1}{2}\eta(t)\int_{0}^{t} e^{(s - t)\partial_x^3}\eta(s)\partial_x\left(w(s)^2\right)\,\mathrm{d}s,
\end{align}
where $\eta$ is a smooth bump function satisfying $\eta(t)\equiv 1$ for $t\in[0,1]$. It follows from \cite[Proposition 6]{Colliander} that, for sufficiently large $\lambda$, the mapping $\widetilde{\Gamma}$ admits a unique fixed point $u_\lambda^*(t)$ in a suitable Bourgain space, and this fixed point coincides with the rescaled solution:
\begin{align*}
	u_\lambda^*(t)\equiv u_{\lambda}(t),\quad \text{for}\quad t\in[0,1].
\end{align*}

Next, to rigorously analyze the numerical scheme, we construct a continuous-in-time function $\mathcal{U}(t)$ interpolating the discrete numerical solutions $u^n_\lambda$ over the interval $[0,\lambda^3 T]$, i.e.,
\begin{align*}
	\mathcal{U}(t_n) = u^n_{\lambda},\quad \text{for each}\quad n\in\{0,1,\dots,T/\tau\},\quad\text{with}\quad t_n=\lambda^3\sigma_n=n\lambda^3\tau.
\end{align*}
This interpolated function satisfies an integral equation defined in continuous time (see equation~\eqref{eq:continuation_problem} in the next section for the explicit expression). The corresponding nonlinear mapping, incorporating the discretization perturbation, is defined as
\begin{align}\label{eq:fix_point_1}
	\Gamma(w)(t) = \eta(t)e^{-t \partial_x^3}u_{\lambda}^0
	+ \frac{1}{2}\eta(t)\int_{0}^{t} e^{(s - t)\partial_x^3}\eta(s)\partial_x\left(w(s)^2\right)\,\mathrm{d}s
	+ \mathcal{A}(w)(t),
\end{align}
where $\mathcal{A}(w)$ represents the perturbation term resulting from the discretization (see equation~\eqref{eq:def_Gamma} for its explicit form). Clearly, equation \eqref{eq:fix_point_1} can be viewed as a perturbed version of the continuous fixed-point problem \eqref{eq:fix_point_2}. By employing Picard iteration combined with Bourgain-space estimates, we shall prove that, for suitably chosen $\lambda$ and an appropriate relation between the temporal step size $\tau$ and filter constant $N$, the perturbed nonlinear mapping $\Gamma$ admits a unique fixed point $\mathcal{U}^*(t)$ in an appropriate Bourgain space, satisfying
\begin{align*}
	\mathcal{U}^*(t)\equiv \mathcal{U}(t),\quad \text{for}\quad t\in[0,1],
\end{align*}
with Bourgain-space bounds independent of the discretization parameters $\tau$, $N$, and the scaling factor $\lambda$.

By comparing the fixed-point equations \eqref{eq:fix_point_1} and \eqref{eq:fix_point_2}, we transform the estimation of the numerical error $u(\sigma_n)-u^n$ (for $\sigma_n\leq \lambda^{-3}$) into the analysis of the difference between their corresponding fixed points:
\begin{align*}
	\max_{\sigma_n\leq \lambda^{-3}}\|u(\sigma_n)-u^n\|_{H^{-\frac{1}{2}}}
	&\leq \lambda^{\frac{3}{2}}\max_{\lambda^3\sigma_n\leq 1}\|u_{\lambda}(\lambda^3\sigma_n)-u_{\lambda}^n\|_{H^{-\frac{1}{2}}(0,\lambda)}\\
	&\leq \lambda^{\frac{3}{2}}\|u_\lambda^*-\mathcal{U}^*\|_{L^{\infty}(0,1;H^{-\frac{1}{2}}(0,\lambda))}.
\end{align*}
By further applying the embedding theorem for Bourgain spaces (see Lemma~\ref{lem:embedding_Ys}), we can control the $H^{-\frac{1}{2}}$ norm of the difference between $u^{*}_{\lambda}(t)$ and $\mathcal{U}^{*}(t)$ using Bourgain space estimates. In particular, this difference can be bounded by carefully estimating the perturbation term $\mathcal{A}(w)$ appearing in \eqref{eq:fix_point_1}, which captures the error between the two fixed-point formulations in \eqref{eq:fix_point_1} and \eqref{eq:fix_point_2}.

Finally, by iteratively applying the above local-in-time estimates from the initial interval (starting at $n=0$) and sequentially advancing through subsequent intervals, we extend these local error estimates globally in time. Thus, we ultimately establish the rigorous global error bound for all time steps $0\leq n\leq T/\tau$ as stated in Theorem~\ref{thm:main}.

