The notation $a+$ represents $a + \varepsilon$ for an arbitrarily small $\varepsilon > 0$, and $a-$ represents $a - \varepsilon$ for an arbitrarily small $\varepsilon > 0$. 
We also define the following rescaled quantities:
\begin{align}\label{eq:notation_tau_lambda}
	\tau_\lambda = \lambda^3 \tau, \quad N_\lambda = \lambda^{-1} N, \quad \text{and} \quad t_n = n\tau_\lambda = \lambda^3 \sigma_n,
\end{align}
where $\tau$, $N$, and $\sigma_n$ are the original time step size, degrees of the freedom, and time node, respectively.







\section{Rescaling argument and continuation of the numerical solution}\label{sec:rescaling}

\subsection{The $\lambda$-periodic KdV equation and numerical scheme}

By utilizing the rescaling argument $u_{\lambda}(t,x)=\lambda^{-2}u(\frac{t}{\lambda^3},\frac{x}{\lambda})$ as in \cite{Colliander}, 
we derive that $u_{\lambda}$ is the solution of the following $\lambda$-periodic problem:
\begin{equation}\label{eq:lambda_KdV_equation}
	\left\{\begin{array}{l}
		{\displaystyle \partial_t u_{\lambda}(t,x)+\partial^{3}_{x}u_{\lambda}(t,x)=\frac{1}{2}\partial_x (u_{\lambda}(t,x)^2),\quad x\in[0,\lambda] \;\; \text{and}\;\; t\in(0,\lambda^3 T],}\\[2mm]
		{\displaystyle u_{\lambda}(0)=\phi_{\lambda},}
	\end{array}\right.
\end{equation}
where $\phi_{\lambda}(x)=\lambda^{-2}\phi(\frac{x}{\lambda})$, and $\lambda\geq 1$ is a constant to be determined later, which is independent of $\tau$ and $N$, but may depend on $\|u\|_{L^{\infty}(0,T;H^s)}$.

We define the normalized counting measure $(\d k)_{\lambda}$ on the discrete set $\mathbb{Z}/\lambda:=\{\frac{l}{\lambda} : l\in \mathbb{Z}\}$ as follows:
\begin{align}\label{eq:def_dk_lambda}
	\int a(k)(\d k)_{\lambda}=\frac{1}{\lambda}\sum_{k\in \mathbb{Z}/\lambda}a(k).
\end{align}
The Fourier transform on $[0,\lambda]$ and its inverse are defined by
\begin{align}
	\hat{f}(k)=\int_0^\lambda e^{-2\pi ikx}f(x)\d x,\quad \text{and} \quad f(x)=\int e^{2\pi ikx}\hat{f}(k)(\d k)_{\lambda}.
\end{align}
Additionally, the Fourier transform satisfies the usual properties:
\begin{align}
	\|f\|_{L^2([0,\lambda])}&=\|\hat{f}\|_{L^2((\d k)_{\lambda})}&& (\text{Plancherel's identity})\\
	\int_0^{\lambda}f(x)\overline{g(x)}\d x&=\int\hat{f}(k)\bar{\hat{g}}(k)(\d k)_{\lambda}&& (\text{Parseval's identity})\\
	\widehat{fg}(k)=\hat{f}*_{\lambda}\hat{g}(k)&=\int\hat{f}(k-k_1)\hat{g}(k_1)(\d k_1)_{\lambda}&& (\text{Convolution relation}).
\end{align}
The operator $\partial_x^\alpha$, $\alpha\in \mathbb{N}$, and the Sobolev space $H^s(0,\lambda)$ are defined analogously to the 1-periodic case:
\begin{align}
	\partial_x^\alpha f(x)&=\int e^{2\pi ikx}(2\pi ik)^{\alpha}\hat{f}(k)(\d k)_{\lambda},\quad 
	\|f\|_{H^{s}(0,\lambda)}=\|\hat{f}(k)\langle k\rangle^s\|_{L^2((\d k)_{\lambda})},
\end{align}
where we denote $\langle k\rangle=(1+k^2)^{\frac{1}{2}}$. Thus, we have
\begin{align*}
	\|\phi_{\lambda}\|_{H^s(0,\lambda)}= \lambda^{-\frac12}\Big(\sum_{k\in\mathbb{Z}/\lambda}|\hat{\phi}_{\lambda}(k)|^2\langle k\rangle^{2s}\Big)^{\frac{1}{2}}.
\end{align*}
By direct computation, we find
\begin{align*}
	\hat{\phi}_{\lambda}(k)=\lambda^{-1}\hat{\phi}(\lambda k),
\end{align*}
which implies
\begin{align*}
	\|\phi_{\lambda}\|_{H^s(0,\lambda)}= \lambda^{-\frac12}\Big(\sum_{\xi\in\mathbb{Z}}\big|\lambda^{-1}\hat{\phi}(\xi)\big|^2\Big\langle \frac{\xi}{\lambda}\Big\rangle^{2s}\Big)^{\frac{1}{2}}.
\end{align*}
Noting that $(1+\xi^2)^{\frac{s}{2}} \leq \big(1+\big(\xi/\lambda\big)^2\big)^{\frac{s}{2}} \leq \lambda^{-s}(1+\xi^2)^{\frac{s}{2}}$ for $s\leq 0$ and $\lambda\geq 1$, we conclude that
\begin{align}\label{eq:relation_Hs}
	\lambda^{-\frac{3}{2}}\|\phi\|_{H^s(0,1)}\leq \|\phi_{\lambda}\|_{H^s(0,\lambda)}\leq\lambda^{-\frac{3}{2}-s}\|\phi\|_{H^s(0,1)}.
\end{align}
Thus, for any $\phi\in H^s(0,1)$, we can choose an appropriate $\lambda\geq 1$ to transform the original problem into one with a small initial value. This allows for a closed estimate of the nonlinear terms within a small neighborhood at the initial time.

Using the Fourier transform, the solution operator $e^{-t\partial_{x}^3}$ of the linear homogeneous $\lambda$-periodic problem
\begin{equation}\label{eq:linear_lambda_KdV_equation}
	\left\{
	\begin{array}{l}
		{\displaystyle \partial_t w(t,x)+\partial^{3}_{x}w(t,x)=0, \quad x\in[0,\lambda],}\\[2mm]
		{\displaystyle w(0)=\phi_{\lambda},}
	\end{array}
	\right.
\end{equation}
is expressed as
\begin{align}
	w(t,x)=e^{-t\partial_{x}^3}\phi_{\lambda}=\int e^{2\pi ikx}e^{-(2\pi ik)^3 t}\hat{\phi}_{\lambda}(k)(\d k)_{\lambda}.
\end{align}


For the numerical solution $u^n$ given by \eqref{eq:filtered_LRI}, the corresponding rescaled time discrete scheme is
\begin{align}\label{eq:lambda_filtered_LRI}
	u_{\lambda}^{n+1}=&e^{-\tau_{\lambda} \partial_x^3}u_{\lambda}^n+\frac{1}{2}\int_{t_{n}}^{t_{n+1}}e^{(t-t_{n+1})\partial_x^3}\Pi_{N_{\lambda}}\partial_{x}\left(e^{(t_{n}-t)\partial_x^3}\Pi_{N_{\lambda}}u_{\lambda}^n\right)^2\d t,
\end{align}
with $u^{n}_{\lambda}(x)=\lambda^{-2}u^{n}(\frac{x}{\lambda})$, and
\begin{align}\label{eq:def_Pi_lambda}
	(\widehat{\Pi_{N_{\lambda}} f})_{k}=\left\{
	\begin{array}{l}
		\hat{f}_{k}\quad \text{if}\;\; |k|\leq N_{\lambda},\\[2mm]
		0\quad \;\, \text{if}\;\; |k|> N_{\lambda},
	\end{array}
	\right.\quad\text{for}\quad k\in \mathbb{Z}/\lambda,
\end{align}
where $t_n$, $\tau_{\lambda}$, $N_{\lambda}$ are rescaled quantities of $\sigma_{n}$, $\tau$ and $N$ respectively, as denoted in \eqref{eq:notation_tau_lambda}.


\subsection{Continuation of the numerical solution}


In order to make use of the Bourgain-space estimates at the continuous level, we introduce the time-continuous function $\U(t)$, $t \in [0, \lambda^3 T]$, defined as follows:  
\begin{align}\label{eq:continuation_solution}
	\U(t) &= e^{(t_n-t) \partial_x^3}u_{\lambda}^n + \frac{1}{2} \int_{t_{n}}^{t} e^{(s-t)\partial_x^3} \Pi_{N_{\lambda}} \partial_{x} \left( e^{(t_{n}-s)\partial_x^3} \Pi_{N_{\lambda}} u_{\lambda}^n \right)^2 \, \mathrm{d}s
	\quad\mbox{for\,\, $t \in [t_n, t_{n+1}]$. }
\end{align}  
For the simplicity of notation, we define  
\begin{align}\label{eq:def_F0}
	F^n(t, w) = \frac{1}{2} \int_{t_{n}}^{t} e^{(s-t)\partial_x^3} \Pi_{N_{\lambda}} \partial_{x} \left( e^{(t_{n}-s)\partial_x^3} \Pi_{N_{\lambda}} w \right)^2 \, \mathrm{d}s,
\end{align}  
for each $n \in \{0, 1, \cdots, T/\tau\}$ and $t \in [t_n, t_{n+1}]$. Using this notation, we define the piecewise time-dependent function $\mathcal{F}(t, \U)$ as  
\begin{align}\label{eq:def_F}
	\mathcal{F}(t, \U) = F^n(t, \U(t_n)), \quad \text{for} \quad t \in [t_n, t_{n+1}].
\end{align}  
It follows directly from \eqref{eq:lambda_filtered_LRI} and \eqref{eq:continuation_solution} that  
$\U(t_n) = u^{n}_{\lambda}$,  
and  
\begin{align*}
	\U(t) &= e^{(t_n-t) \partial_x^3} \U(t_n) + \F(t, \U).
\end{align*}  
By substituting $e^{(t_n-s) \partial_x^3} u^n_{\lambda}(t_n) = e^{(t_n-s) \partial_x^3} \U(t_n) = \U(s) - \F(s, \U)$ into the right-hand side of \eqref{eq:continuation_solution}, we obtain  
\begin{align}
	\U(t) &= e^{(t_n-t) \partial_x^3} \U(t_n) + \frac{1}{2} \int_{t_{n}}^{t} e^{(s-t)\partial_x^3} \Pi_{N_{\lambda}} \partial_{x} \left( \Pi_{N_{\lambda}} \U(s) \right)^2 \, \mathrm{d}s \notag \\
	& \quad - \int_{t_{n}}^{t} e^{(s-t)\partial_x^3} \Pi_{N_{\lambda}} \partial_{x} \Big( \Pi_{N_{\lambda}} \F(s, \U) \Pi_{N_{\lambda}} \U(s) \Big) \, \mathrm{d}s \notag \\
	& \quad + \frac{1}{2} \int_{t_{n}}^{t} e^{(s-t)\partial_x^3} \Pi_{N_{\lambda}} \partial_{x} \left( \Pi_{N_{\lambda}} \F(s, \U) \right)^2 \, \mathrm{d}s.
\end{align}  
By iterating this expression, we obtain
\begin{align}\label{eq:continuation_problem}
	\U(t) &= e^{-t \partial_x^3} \U(0) + \frac{1}{2} \int_{0}^{t} e^{(s-t)\partial_x^3} \Pi_{N_{\lambda}} \partial_{x} \left( \Pi_{N_{\lambda}} \U(s) \right)^2 \, \mathrm{d}s \notag \\
	& \quad - \int_{0}^{t} e^{(s-t)\partial_x^3} \Pi_{N_{\lambda}} \partial_{x} \Big( \Pi_{N_{\lambda}} \F(s, \U) \Pi_{N_{\lambda}} \U(s) \Big) \, \mathrm{d}s \notag \\
	& \quad + \frac{1}{2} \int_{0}^{t} e^{(s-t)\partial_x^3} \Pi_{N_{\lambda}} \partial_{x} \left( \Pi_{N_{\lambda}} \F(s, \U) \right)^2 \, \mathrm{d}s\notag\\
	&=e^{-t \partial_x^3} \U(0) + \frac{1}{2} \int_{0}^{t} e^{(s-t)\partial_x^3} \partial_{x} \left(  \U(s) \right)^2 \, \mathrm{d}s+\mathcal{R}(\U)(t),
\end{align}  
where
\begin{align*}
	\mathcal{R}(\U)(t)=&- \int_{0}^{t} e^{(s-t)\partial_x^3} \Pi_{N_{\lambda}} \partial_{x} \Big( \Pi_{N_{\lambda}} \F(s, \U) \Pi_{N_{\lambda}} \U(s) \Big) \, \mathrm{d}s\\
	& + \frac{1}{2} \int_{0}^{t} e^{(s-t)\partial_x^3} \Pi_{N_{\lambda}} \partial_{x} \left( \Pi_{N_{\lambda}} \F(s, \U) \right)^2 \, \mathrm{d}s\\
	&+\frac{1}{2} \int_{0}^{t} e^{(s-t)\partial_x^3}  \partial_{x} \left[\Pi_{N_{\lambda}}\left( \Pi_{N_{\lambda}} \U(s) \right)^2-\left(  \U(s) \right)^2\right] \, \mathrm{d}s. 
\end{align*}
Since the $\lambda$-periodic KdV equation \eqref{eq:lambda_KdV_equation} is equivalent to the integral equation  
\begin{align}\label{eq:mild_lambda_KdV}
	u_{\lambda}(t) = e^{-t \partial_x^3} u_\lambda(0) + \frac{1}{2} \int_{0}^{t} e^{(s-t)\partial_x^3} \partial_{x} \left( u_{\lambda}(s) \right)^2 \, \mathrm{d}s,
\end{align}  
the continuation problem \eqref{eq:continuation_problem} can be viewed as a perturbation of \eqref{eq:mild_lambda_KdV}. By comparing the differences between \eqref{eq:continuation_problem} and \eqref{eq:mild_lambda_KdV}, we can estimate the error $u_{\lambda}(t_n) - u^n_{\lambda}$. Using the rescaling relationship, we have  
\begin{align}\label{eq:relation_scaling}
	\| u(\sigma_n) - u^n \|_{H^{-\frac{1}{2}}(0,1)} \leq \lambda^{\frac{3}{2}} \| u_{\lambda}(t_n) - u^n_{\lambda} \|_{H^{-\frac{1}{2}}(0,\lambda)} = \lambda^{\frac{3}{2}} \| u_{\lambda}(t_n) - \U(t_n) \|_{H^{-\frac{1}{2}}(0,\lambda)}.
\end{align}  
Thus, the proof of Theorem~\ref{thm:main} is reduced to estimating $\| u_{\lambda}(t_n) - \U(t_n) \|_{H^{-\frac{1}{2}}(0,\lambda)}$.  





\section{Bourgain spaces and preliminary results}\label{sec:bourgain}
As in the literature \cite{Colliander, Tao}, we define the Bourgain space $X_{s,b}$ for $\lambda$-periodic problems using the following norm:  
\begin{align}
	\|w\|_{X_{s,b}(\mathbb{R} \times ([0,\lambda]))} = 
	\big\|\langle k \rangle^s \langle \sigma - 4\pi^2k^3 \rangle^b \tilde{w}(\sigma,k) \big\|_{L^2(\mathrm{d}\sigma (\mathrm{d}k)_{\lambda})},
\end{align}  
where $\tilde{w}$ is the space-time Fourier transform of $w$, given by  
\begin{align*}
	\tilde{w}(\sigma,k) = \int_{\mathbb{R} \times [0,\lambda]} e^{-2\pi i \sigma t - 2\pi i k x} w(t,x) \, \mathrm{d}t \, \mathrm{d}x.
\end{align*}  
We also introduce a slightly smaller space $Y^s$, compared to $X_{s,\frac{1}{2}}$, as described in \cite{Colliander}. This ensures that any solution in $Y^s$ is also contained in $L^{\infty}_{t}H^{s}_x$:  
\begin{align}
	\|w\|_{Y^s} = \|w\|_{X_{s,\frac{1}{2}}} + \|\langle k \rangle^s \tilde{w}(\sigma,k)\|_{L^2((\mathrm{d}k)_{\lambda}) L^1(\mathrm{d}\sigma)}.
\end{align}  
Additionally, we define the functional space $Z^s$ via the norm  
\begin{align}
	\|w\|_{Z^s} = \|w\|_{X_{s,-\frac{1}{2}}} + \left\|\frac{\langle k \rangle^s \tilde{w}(\sigma,k)}{\langle \sigma - 4\pi^2k^3 \rangle}\right\|_{L^2((\mathrm{d}k)_{\lambda}) L^1(\mathrm{d}\sigma)}.
\end{align}  
Let $\eta \in C^{\infty}_0(\mathbb{R})$ be a smooth bump function such that  
\begin{align}\label{eq:bump_function}
	\text{supp}(\eta) \subset [-2,2], \quad \text{with} \quad \eta \equiv 1 \quad \text{on} \quad [-1,1].
\end{align}  



Next, we present some preliminary results (i.e., Lemmas~\ref{lem:free_solution}–\ref{lem:embedding_theorem}), established in \cite{Colliander, Tao}, which will be frequently used throughout this article. These focus on estimates in the Bourgain space for $\lambda$-periodic problems, where the constants are independent of $\lambda$. 
%For completeness, we postpone the proofs of some lemmas to Appendix~\ref{Appendix:A} in the supplementary material.

\begin{lemma}[{Free solutions lie in $Y^s$ \cite[Lemma~7.1]{Colliander}}]\label{lem:free_solution}
	Let $\phi_{\lambda}\in H^s([0,\lambda])$ for $s\in\R$, and $\eta$ be the bump function given by \eqref{eq:bump_function}. Then
	\begin{align}\label{eq:free_solution}
		\|\eta(t)e^{-t\partial_x^3}\phi_{\lambda}\|_{Y^s}\leq C\|\phi_{\lambda}\|_{H^s},
	\end{align}
	where $C$ is a positive constant independent of $\lambda$.
\end{lemma}

\begin{lemma}[Embedding result for $Y^s$ \cite{Colliander}]\label{lem:embedding_Ys}
	If $w\in Y^s$ for $s\in \R$, then
	\begin{align}\label{eq:embedding_Ys}
		\|w\|_{L_{t}^{\infty}H_{x}^s}\leq C\|w\|_{Y^s},
	\end{align}
	where $C$ is a positive constant independent of $\lambda$.
\end{lemma}
For the convenience of readers, the proof of this lemma is presented in the supplementary material.



\begin{lemma}[Boundedness of the time localization \cite{Colliander,Tao}]\label{lem:time_localization}
	Let $\eta$ be the bump function given by \eqref{eq:bump_function}. Then
	\begin{align}\label{eq:time_localization}
		\|\eta(t)w\|_{X_{s,b}}\leq C\|w\|_{X_{s,b}}, \quad \|\eta(t)w\|_{Y^s}\leq C\|w\|_{Y^s},\quad \text{and}\quad\|\eta(t)w\|_{Z^s}\leq C\|w\|_{Z^s},
	\end{align}
	where $C$ is a positive constant independent of $\lambda$.
\end{lemma}
For the convenience of readers, the proof of this lemma is presented in the supplementary material.



\begin{lemma}[{Energy estimate \cite[Lemma~7.2]{Colliander}}] \label{lem:energy_estimate}
	Let $\eta$ be the bump function given by \eqref{eq:bump_function}, and $F\in Z^s$ for $s\in\R$. Then
	\begin{align}\label{eq:energy_estimate}
		\left\|\eta(t)\int_0^t e^{(s-t)\partial_x^3}F(s)\d s\right\|_{Y^s}\leq C \|F\|_{Z^s},
	\end{align}
	where $C$ is a positive constant independent of $\lambda$.
\end{lemma}

\begin{lemma}[{Bilinear estimate \cite[Proposition 5]{Colliander}}]\label{lem:bilinear_estimate}
	If $u$ and $v$ are $\lambda$-periodic functions of $x$,
	and have zero $x$-mean for all $t$, then
	\begin{align}
		\|\eta(t)\partial_x (uv)\|_{Z^{-\frac{1}{2}}}\leq C \lambda^{0+}\|u\|_{X_{-\frac{1}{2},\frac{1}{2}}}\|v\|_{X_{-\frac{1}{2},\frac{1}{2}}},
	\end{align}
	where $C$ is a positive constant independent of $\lambda$.
\end{lemma}


\begin{remark}\label{rem:bilinear_estimate}
	It follows from the inequality:
	\begin{align*}
		\langle k_1+k_2\rangle^a\lesssim \langle k_1\rangle^a \langle k_2\rangle^a,
	\end{align*}
	for any $k_1,k_2\in\R$ and $a\geq 0$, that Lemma~\ref{lem:bilinear_estimate} implies, for all $s \geq -\frac{1}{2}$:
	\begin{align}
		\|\eta(t)\partial_x (uv)\|_{Z^{s}}\leq C\lambda^{0+}\|u\|_{X_{s,\frac{1}{2}}}\|v\|_{X_{s,\frac{1}{2}}},
	\end{align}
	where $C$ is a positive constant independent of $\lambda$.
\end{remark}

\begin{lemma}[{Embedding theorem for $X_{0,\frac{1}{3}}$ \cite[Lemma~7.3]{Colliander}}]\label{lem:embedding_theorem}
	Let $w\in X_{0,\frac{1}{3}}$ be a $\lambda$-periodic function and let $\eta$ be the bump function given by \eqref{eq:bump_function}. Then
	\begin{align}\label{eq:embedding_theorem}
		\|\eta(t)w\|_{L^4_t L^4_x}\leq C\|w\|_{X_{0,\frac{1}{3}}},
	\end{align}
	where $C$ is a positive constant independent of $\lambda$.
\end{lemma}






\begin{corollary}\label{corollary:Z0}
	If $w\in Z^0$ is a $\lambda$-periodic function, then
	\begin{align}
		\|w\|_{Z^0}\leq C\|w\|_{L^{\frac{4}{3}}_t L^{\frac{4}{3}}_x},
	\end{align}
	where $C$ is a positive constant independent of $\lambda$.
\end{corollary}
For the convenience of readers, the proof of this corollary is presented in the supplementary material.





\begin{lemma}[Bernstein's type inequality]\label{lem:Bernstein}
	Let $ \Pi_{N_{\lambda}} $ be the projection operator defined by \eqref{eq:def_Pi_lambda}, and let $ \Pi_{>N_{\lambda}} = I - \Pi_{N_{\lambda}} $. Then, the following inequalities hold:
	\begin{equation}\label{eq:Bernstein_1}
		\begin{array}{l}
			\|\Pi_{N_{\lambda}} u\|_{H^{\gamma}} \leq C N_{\lambda}^{\gamma-s} \|u\|_{H^s}, \quad \|\Pi_{N_{\lambda}} u\|_{X_{\gamma,b}} \leq C N_{\lambda}^{\gamma-s} \|u\|_{X_{s,b}}, \\[2mm]
			\|\Pi_{N_{\lambda}} u\|_{Y^{\gamma}} \leq C N_{\lambda}^{\gamma-s} \|u\|_{Y^s}, \quad \|\Pi_{N_{\lambda}} u\|_{Z^{\gamma}} \leq C N_{\lambda}^{\gamma-s} \|u\|_{Z^s},
		\end{array}
	\end{equation}
	for all $ s \leq \gamma $, $ b \in \mathbb{R} $, and
	\begin{align}\label{eq:Bernstein_3}
		\begin{array}{l}
			\|\Pi_{>N_{\lambda}} u\|_{H^{\gamma}} \leq C N_{\lambda}^{\gamma-s} \|u\|_{H^s}, \quad \|\Pi_{>N_{\lambda}} u\|_{X_{\gamma,b}} \leq C N_{\lambda}^{\gamma-s} \|u\|_{X_{s,b}}, \\[2mm]
			\|\Pi_{>N_{\lambda}} u\|_{Y^{\gamma}} \leq C N_{\lambda}^{\gamma-s} \|u\|_{Y^s}, \quad \|\Pi_{>N_{\lambda}} u\|_{Z^{\gamma}} \leq C N_{\lambda}^{\gamma-s} \|u\|_{Z^s},
		\end{array}
	\end{align}
	for all $ \gamma \leq s $, $ b \in \mathbb{R} $, and
	\begin{align}\label{eq:Bernstein_2}
		\|\Pi_{N_{\lambda}} u\|_{L^{4}} \leq C N_{\lambda}^{\frac{1}{4}} \|u\|_{L^2},
	\end{align}
	with a positive constant $ C $ independent of $ \lambda $.
\end{lemma}
For the convenience of readers, the proof of this lemma is presented in the supplementary material.










