\begin{lemma}\label{lem:boundedness_um}
	Let $\Gamma$ be the nonlinear operator defined in \eqref{eq:def_Gamma}, with $\phi_{\lambda} \in H^{s}(0, \lambda)$, and $N_{\lambda}, \tau_{\lambda} > 0$ being the rescaled quantities of $\phi \in H^s(0, 1)$ and $N, \tau > 0$ defined in \eqref{eq:lambda_KdV_equation} and \eqref{eq:lambda_filtered_LRI}. Then, for fixed $N$ and $\tau$ satisfying $N \lesssim \tau^{-\frac{1}{2 - 2s}}$ for $s \in \left(-\frac{1}{2}, 0\right]$, there exists a positive constant $\lambda_0$ independent of $N$ and $\tau$, but possibly dependent on $\|\phi\|_{H^s}$, such that for any $\lambda \geq \lambda_0$, the following bound holds:
	\begin{align}\label{eq:boundedness_um}
		\|\U^\ell\|_{Y^s} \leq C^{\#} \|\phi_{\lambda}\|_{H^s},
	\end{align}
	for all $\ell \geq 0$, where $C^{\#}$ is a positive constant independent of $\tau$, $N$, and $\lambda$.
\end{lemma}


\begin{proof}
For better readability, we provide the detailed proof of this lemma to Appendix~\ref{Appendix:B} in the supplementary material.
\end{proof}


We are now ready to demonstrate  the existence of the fixed point of $\Gamma$ in the Bourgain space $Y^s$:
\begin{theorem}\label{thm:existence}
	Under the conditions of Lemma~\ref{lem:boundedness_um}, there exists a positive constant $\lambda_0$ independent of $N$ and $\tau$ but possibly dependent on $\|\phi\|_{H^s}$ such that for any $\lambda\geq \lambda_0$ the equation $\Gamma(\U^*)=\U^*$ admits a solution $\U^*\in Y^s$ satisfying 
	\begin{align}\label{eq:boundedness_u*}
		\|\U^*\|_{Y^s}\leq C^{\#}\|\phi_{\lambda}\|_{H^s},
	\end{align}
	where $C^{\#}$ is a positive constant independent of $\tau$, $N$ and $\lambda$.
\end{theorem}

\begin{proof}
	Let $\{\U^\ell\}_{\ell \geq 0}$ be the iterative sequence given by \eqref{eq:iterative_sequence}. 
	Then, for $\ell\geq 2$, we have
	\begin{align}
		\U^{\ell+1}-\U^{\ell}=&\frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\Pi_{N_{\lambda}}\partial_{x}\Big(\Pi_{N_{\lambda}}\left(\U^\ell-\U^{\ell-1}\right)(s)\cdot\Pi_{N_{\lambda}}\left(\U^\ell+\U^{\ell-1}\right)(s)\Big)\d s\notag\\
		&+\mathcal{A}_1(\U^\ell)-\mathcal{A}_1(\U^{\ell-1})+\mathcal{A}_2(\U^\ell)-\mathcal{A}_2(\U^{\ell-1}),
	\end{align} 
	where we have used the equivalent reformulation of \eqref{eq:def_Gamma}, namely \eqref{eq:def_Gamma_equivalent}, as introduced in the supplementary material.

	From Lemma~\ref{lem:boundedness_um}, we know that the sequence is uniformly bounded in the $Y^s$ space, i.e., $\|\U^\ell\|_{Y^s}\leq C^{\#}\|\phi_{\lambda}\|_{H^s}$ for all $\ell\geq 0$.
	Combining the boundedness with Lemma~\ref{lem:energy_estimate},  Lemma~\ref{lem:bilinear_estimate}, and Remark~\ref{rem:bilinear_estimate}, we deduce that
	\begin{align}
		&\left\|\frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\Pi_{N_{\lambda}}\partial_{x}\Big(\Pi_{N_{\lambda}}\left(\U^\ell-\U^{\ell-1}\right)(s)\cdot\Pi_{N_{\lambda}}\left(\U^\ell+\U^{\ell-1}\right)(s)\Big)\d s\right\|_{Y^s}\notag\\
		&\quad \leq C\lambda^{0+}\left\|\U^\ell-\U^{\ell-1}\right\|_{Y^s}\left(\left\|\U^\ell\right\|_{Y^s}+\left\|\U^{\ell-1}\right\|_{Y^s}\right)\notag\\
		&\quad\leq 2C\cdot C^{\#}\lambda^{-\frac{3}{2}-s+}\|\phi\|_{H^s}\left\|\U^\ell-\U^{\ell-1}\right\|_{Y^s}.
	\end{align}
	Since $\mathcal{A}_1(w)$ and $\mathcal{A}_2(w)$ are multi-linear functions of $w$, we can estimate $\|\mathcal{A}_1(\U^\ell)-\mathcal{A}_1(\U^{\ell-1})\|_{Y^s}$ and $\|\mathcal{A}_2(\U^\ell)-\mathcal{A}_2(\U^{\ell-1})\|_{Y^s}$ in a same manner as in the proof of Lemma~\ref{lem:boundedness_um}:
	\begin{align}
		&\|\mathcal{A}_1(\U^\ell)-\mathcal{A}_1(\U^{\ell-1})\|_{Y^s}\notag\\
		&\leq C\tau_{\lambda}N_{\lambda}^{2-2s}(C^{\#})^2\|\phi_{\lambda}\|^2_{H^s}\left\|\U^\ell-\U^{\ell-1}\right\|_{Y^s}\notag\\
		&\quad+C\tau_{\lambda}^\frac{4}{3} N_{\lambda}^{\frac{5}{2}-2s}C^{\#}\|\phi_{\lambda}\|^2_{H^s}\Big(\|\U^{\ell-1}-\U^{\ell-2}\|_{Y^s}+\left\|\U^{\ell}-\U^{\ell-1}\right\|_{Y^s}\Big)\notag\\
		&\quad+C\tau_{\lambda}^\frac{5}{3} N_{\lambda}^{\frac{5}{2}-2s}\|\phi_{\lambda}\|_{H^s}^2\left\|\U^{\ell}-\U^{\ell-1}\right\|_{Y^s}\notag\\
		&\quad+C\sum_{j=2}^{7}\tau_{\lambda}^{j}N_{\lambda}^{[1+\frac{3j}{2}-(j+1)s]}(C^{\#})^{j+1}\|\phi_{\lambda}\|_{H^s}^{j+1}\Big(\|\U^{\ell-1}-\U^{\ell-2}\|_{Y^s}+\left\|\U^{\ell}-\U^{\ell-1}\right\|_{Y^s}\Big)\notag\\
		&=:\tilde{\mathcal{C}}\left(s,\tau_{\lambda},N_{\lambda},\left\|\U^{\ell}\right\|_{Y^s},\|\U^{\ell-1}\|_{Y^s}, \|\U^{\ell-2}\|_{Y^s}\right),
	\end{align}
	and
	\begin{align*}
		&\|\mathcal{A}_2(\U^\ell)-\mathcal{A}_2(\U^{\ell-1})\|_{Y^s}\\
		&\quad\leq C\tau_{\lambda}N_{\lambda}^{\frac{7}{4}-s}C^{\#}\left\|\phi_{\lambda}\right\|_{H^s}\tilde{\mathcal{C}}\left(s,\tau_{\lambda},N_{\lambda},\left\|\U^{\ell}\right\|_{Y^s},\|\U^{\ell-1}\|_{Y^s}, \|\U^{\ell-2}\|_{Y^s}\right).
	\end{align*}
	Under condition $N\lesssim \tau^{-\frac{1}{2-2s}}$, it  follows from the same discussions as in \eqref{eq:bound_constant_1}--\eqref{eq:bound_constant_3} that there exists $\lambda_0>1$ independent of $\tau$ and $N$, such that for $\lambda>\lambda_0$, the following inequality holds
	\begin{align*}
		\|\U^{\ell+1}-\U^{\ell}\|_{Y^s}\leq \frac{1}{4}\|\U^{\ell}-\U^{\ell-1}\|_{Y^s}+\frac{1}{4}\|\U^{\ell-1}-\U^{\ell-2}\|_{Y^s}.
	\end{align*}
	Therefore, the sequence $\{\U^\ell\}_{\ell \geq 0}$ is a Cauchy sequence in $Y^s$, and it converges to a fixed point $\U^*$ of the operator $\Gamma$.
\end{proof}

\section{Error estimate of the filtered low-regularity integrator \eqref{eq:filtered_LRI}}\label{sec:proof_of_main_theorem}
From \cite[Proposition~6]{Colliander}, we know that there exists a constant $\lambda_0>1$ such that when $\lambda\geq \lambda_0$, the  equation 
\begin{align}\label{eq:local_well_posedness}
	u_{\lambda}^*(t)=&\eta(t)e^{-t \partial_x^3}\phi_{\lambda}+\frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\partial_{x}\left(u_{\lambda}^{*}(s)\right)^2\d s,
\end{align}
has a unique solution in the $Y^s$ space and satisfies 
$$\|u_{\lambda}^*\|_{Y^s}\leq C^{\#}\|\phi_{\lambda}\|_{H^s}.$$
Since the bump function $\eta\equiv 1$ for $t \in [0, 1]$, we obtain the relation
\begin{align}\label{eq:relation_u*_u}
	u_{\lambda}^*(t)=u_{\lambda}(t),\quad \text{for}\quad t \in [0, 1].
\end{align}
Therefore, by combining Remark~\ref{lem:relation_Gamma} with Lemma~\ref{lem:embedding_Ys}, we have
\begin{align}\label{eq:u-u*}
	\|u_{\lambda}-\U\|_{L^{\infty}(0,1; H^{-\frac{1}{2}})}\lesssim \|u_{\lambda}^{*}-\U^*\|_{Y^{-\frac{1}{2}}},
\end{align}
where $\U^*$ is the solution to
\begin{align}\label{eq:Gamma_U*}
	\Gamma(\U^*)=\U^*,
\end{align}
constructed in the Theorem~\ref{thm:existence}.
Thus, we can transform the error estimate between $u(t_n)$ and $u^{n}$ into an estimate of the Bourgain norm of the error
\begin{align}\label{eq:def_error}
	e(t,x):=u_{\lambda}^{*}(t,x)-\U^*(t,x).
\end{align}

Subtracting \eqref{eq:Gamma_U*} from \eqref{eq:local_well_posedness}, we derive the error equation
\begin{align}\label{eq:error_function}
	u_{\lambda}^*(t)-\U^*(t)=&\eta(t)e^{-t \partial_x^3}\big(u_{\lambda}^*(0)-\U^*(0)\big)\notag\\
	&+\frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\partial_{x}\left[\left(u_{\lambda}^{*}(s)\right)^2-\left(\U^{*}(s)\right)^2\right]\d s-\mathcal{A}(\U^*)(t),
\end{align}
where $\mathcal{A}(\U^*)(t)$ is defined in \eqref{eq:def_Gamma}.

Taking the $Y^{-\frac{1}{2}}$ norm of the both sides of \eqref{eq:error_function}, we deduce that
\begin{align}\label{eq:Y_norm_inequality}\notag
	\|e\|_{Y^{-\frac{1}{2}}}&\leq \left\|\frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\partial_{x}\Big(e(s)\cdot\left(u_{\lambda}^{*}+\U^*\right)(s)\Big)\d s\right\|_{Y^{-\frac{1}{2}}}\\
	&\quad + \left\|\eta(t)e^{-t \partial_x^3}e(0)\right\|_{Y^{-\frac{1}{2}}}
	+\|\mathcal{A}(\U^*)\|_{Y^{-\frac{1}{2}}}.
\end{align}


From Lemmas~\ref{lem:free_solution}, \ref{lem:energy_estimate} and \ref{lem:bilinear_estimate}, we know that
\begin{align}\label{eq:e_0_Y12}
	\left\|\eta(t)e^{-t \partial_x^3}e(0)\right\|_{Y^{-\frac{1}{2}}}\lesssim \|e(0)\|_{H^{-\frac{1}{2}}},
\end{align} 
and
\begin{align}\label{eq:e_times_u_Y12}
	&\left\|\frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\partial_{x}\Big(e(s)\cdot\left(u_{\lambda}^{*}+\U^*\right)(s)\Big)\d s\right\|_{Y^{-\frac{1}{2}}}\notag\\
	&\quad\lesssim \left\|\eta(t)\partial_{x}\Big(e(t)\cdot\left(u_{\lambda}^{*}+\U^*\right)(t)\Big)\right\|_{Z^{-\frac{1}{2}}} \lesssim \lambda^{0+}\left(\left\|u^{*}_{\lambda}\right\|_{Y^{-\frac{1}{2}}}+\left\|\U^{*}\right\|_{Y^{-\frac{1}{2}}}\right)\cdot\|e\|_{Y^{-\frac{1}{2}}}.
\end{align}
We shall estimate the remaining term on the right-hand side of \eqref{eq:Y_norm_inequality}, i.e. $\|\mathcal{A}(\U^*)\|_{Y^{-\frac{1}{2}}}$.

\subsection{Consistency error}
%In a certain sense, the remaining three terms in \eqref{eq:Y_norm_inequality}, i.e. $\|\mathcal{R}_1(u^*_{\lambda})\|_{Y^{-\frac{1}{2}}}$, $\|\mathcal{A}_1(\U^*)\|_{Y^{-\frac{1}{2}}}$, and $\|\mathcal{A}_2(\U^*)\|_{Y^{-\frac{1}{2}}}$, correspond to the consistency errors of the numerical scheme \eqref{eq:lambda_filtered_LRI} when solving the rescaled KdV equation after applying the rescaling transformation. For the estimation of these three consistency error terms, we have the following two lemmas.

The remaining term in \eqref{eq:Y_norm_inequality}, namely $\|\mathcal{A}(\U^*)\|_{Y^{-\frac{1}{2}}}$, can be viewed as the consistency errors of the numerical scheme \eqref{eq:lambda_filtered_LRI} when solving the rescaled KdV equation after applying the rescaling transformation. Recalling the definition of $\mathcal{A}(\U^*)$ in \eqref{eq:def_Gamma}, we note that $\mathcal{A}(\U^*)$ consists of three components: $\mathcal{A}_1(\U^*)$, $\mathcal{A}_2(\U^*)$, and $\mathcal{A}_3(\U^*)$. To estimate these three consistency error terms, we provide the following two lemmas.




\begin{lemma}\label{lem:estimate_A1A2}
	Under the assumptions of Theorem~\ref{thm:existence}, the following estimate holds:
	\begin{align}\label{eq:estimate_A1A2}
		\|\mathcal{A}_1(\U^*)\|_{Y^{-\frac{1}{2}}} + \|\mathcal{A}_2(\U^*)\|_{Y^{-\frac{1}{2}}} \leq C \lambda^{-\frac{3}{2}} \tau N^{3\left( \frac{1}{2} - s \right)},
	\end{align}
	where $C$ is a positive constant independent of $N$, $\tau$, and $\lambda$, but possibly dependent on $\|\phi\|_{H^s}$.
\end{lemma} 
\begin{proof}
	Recalling the definitions of $\mathcal{A}1$ and $\mathcal{A}2$ in \eqref{eq:def_Gamma}, and applying Lemma~\ref{lem:energy_estimate}, Lemma~\ref{lem:embedding_theorem}, and Corollary~\ref{corollary:Z0}, we derive the following estimates:
	\begin{align}
		\|\mathcal{A}_1(\U^*)\|_{Y^{-\frac{1}{2}}}&\lesssim \left\|\eta(t)\Pi_{N_{\lambda}}\partial_{x}\Big(\Pi_{N_{\lambda}}\F(t,\U^*)\Pi_{N_{\lambda}}\U^*(t)\Big)\right\|_{Z^{-\frac{1}{2}}}\notag\\
		&\lesssim N_{\lambda}^{\frac{1}{2}}\left\|\eta(t)\Big(\Pi_{N_{\lambda}}\F(t,\U^*)\Pi_{N_{\lambda}}\U^*(t)\Big)\right\|_{Z^0}\notag\\
		&\lesssim N_{\lambda}^{\frac{1}{2}}\left\|\eta(t)\Big(\Pi_{N_{\lambda}}\F(t,\U^*)\Pi_{N_{\lambda}}\U^*(t)\Big)\right\|_{L^{\frac{4}{3}}_tL^{\frac{4}{3}}_x}\notag\\
		&\lesssim N_{\lambda}^{\frac{1}{2}}\left\|\eta(t)\Pi_{N_{\lambda}}\F(t,\U^*)\right\|_{L^2_t L^2_x}\|\Pi_{N_{\lambda}}\U^*(t)\|_{L^4_t L^4_x},
	\end{align}
	and
	\begin{align}
		\|\mathcal{A}_2(\U^*)\|_{Y^{-\frac{1}{2}}}&\lesssim N_{\lambda}^{\frac{1}{2}}\left\|\eta(t)\Pi_{N_{\lambda}}\F(t,\U^*)\right\|_{L^2_t L^2_x}\|\eta(t)\Pi_{N_{\lambda}}\F(t,\U^*)\|_{L^4_t L^4_x}.
	\end{align}
	Next, we estimate $\|\eta(t)\Pi_{N_{\lambda}}\F(t,\U^*)\|_{L^2_t L^2_x}$, $\|\eta(t)\Pi_{N_{\lambda}}\F(t,\U^*)\|_{L^4_t L^4_x}$, and $\|\Pi_{N_{\lambda}} \U^*(t)\|_{L^4_t L^4_x}$ in the same way as in the proof of Lemma~\ref{lem:boundedness_um}. This leads to 
	\begin{align}\label{eq:A_1_Y12}
		\|\mathcal{A}_1(\U^*)\|_{Y^{-\frac{1}{2}}}
		&\lesssim \tau_{\lambda}N_{\lambda}^{\frac{3}{2}-3s}\left\|\U^{*}\right\|^3_{Y^s}+\tau_{\lambda}^\frac{4}{3} N_{\lambda}^{2-3s}\|\phi_{\lambda}\|_{H^s}\|\U^{*}\|^2_{Y^s}\notag\\
		&\quad+\tau_{\lambda}^\frac{5}{3} N_{\lambda}^{2-3s}\|\phi_{\lambda}\|_{H^s}^2\left\|\U^{*}\right\|_{Y^s}+\sum_{j=2}^{7}\tau_{\lambda}^{j}N_{\lambda}^{[\frac{1}{2}+\frac{3j}{2}-(j+2)s]}\|\U^{*}\|^{j+2}_{Y^s}\notag\\
		&=:\mathcal{C}^*\left(s,\tau_{\lambda},N_{\lambda},\left\|\U^{*}\right\|_{Y^s}\right).\\
		\label{eq:A_2_Y12}
		\|\mathcal{A}_2(\U^*)\|_{Y^{-\frac{1}{2}}}&\lesssim\tau_{\lambda}N_{\lambda}^{\frac{7}{4}-s}\left\|\U^{*}\right\|_{Y^s}\cdot\mathcal{C}^*\left(s,\tau_{\lambda},N_{\lambda},\left\|\U^{*}\right\|_{Y^s}\right).
	\end{align}
	Substituting $\|\U^{*}\|_{Y^s}\leq C^{\#}\|\phi_{\lambda}\|_{H^s}$, $\|\phi_{\lambda}\|_{H^s}\leq\lambda^{-\frac{3}{2}-s}\|\phi\|_{H^s}$, $\tau_{\lambda}=\lambda^3\tau$ and $N_{\lambda}=\lambda^{-1}N$, we get the following estimates:
	\begin{align}\label{eq:estimate_constant}
		\tau_{\lambda}N_{\lambda}^{\frac{7}{4}-s}\left\|\U^{*}\right\|_{Y^s}&\leq \left[C^{\#}\lambda^{-\frac{1}{4}}\tau N^{\frac{7}{4}-s}\right]\cdot\|\phi\|_{H^s}\lesssim 1,
	\end{align}
	and
	\begin{align}\label{eq:estimate_C*}
		&\mathcal{C}^*\left(s,\tau_{\lambda},N_{\lambda},\left\|\U^{*}\right\|_{Y^s}\right)\notag\\		
		&\leq\lambda^{-\frac{3}{2}}\tau N^{3(\frac{1}{2}-s)}\cdot\Big((C^{\#})^3\lambda^{-\frac{3}{2}}\|\phi\|_{H^s}^3+(C^{\#})^2\lambda^{-1}\tau^{\frac{1}{3}}N^{\frac{1}{2}}\|\phi\|_{H^s}^3\notag\\
		&\qquad+C^{\#}\tau^{\frac{2}{3}}N^{\frac{1}{2}}\|\phi\|_{H^s}^3+\sum_{j=2}^{7}(C^{\#})^{j+2}\lambda^{-2}\tau^{j-1}N^{[\frac{1}{2}+\frac{3(j-1)}{2}-(j-1)s]}\|\phi\|_{H^s}^{j+2}\Big)\notag\\
		&\lesssim \lambda^{-\frac{3}{2}}\tau N^{3(\frac{1}{2}-s)},
	\end{align}
	which holds for $\lambda\geq 1$ and $N\lesssim\tau^{-\frac{1}{2-2s}}$ with $s\in(-\frac{1}{2},0]$.
	In above, we have used the inequality
	\begin{align*}
		j-1\geq \frac{1}{2-2s}\cdot\left[\frac{1}{2}+\frac{3(j-1)}{2}-(j-1)s\right],
	\end{align*}
	which  is equivalent to $(\frac{1}{2}-s)(j-1)\geq \frac{1}{2}$ that holds  for $j\geq 2$ and $s\leq 0$. Combining \eqref{eq:A_1_Y12}--\eqref{eq:estimate_C*}, we complete the proof. 
\end{proof}

\begin{lemma}\label{lem:estimate_R1}
	Let $u^{*}_{\lambda}$ be the unique solution of \eqref{eq:local_well_posedness} in $Y^s$ for $s\in(-\frac{1}{2},0]$, and let $\U^*$ be the fixed point of the operator $\Gamma$ under the same assumptions as in Theorem~\ref{thm:existence}. Then, the following result holds:
	\begin{align}\label{eq:estimate_R1}
		\|\mathcal{A}_3(\U^*)\|_{Y^{-\frac{1}{2}}}\leq  C\left[\lambda^{-\frac{5}{2}-s+}N^{-\frac{1}{2}-s}+\lambda^{0+}\left(\left\|u^{*}_{\lambda}\right\|_{Y^{-\frac{1}{2}}}+\left\|\U^{*}\right\|_{Y^{-\frac{1}{2}}}\right)\cdot\|e\|_{Y^{-\frac{1}{2}}}\right],
	\end{align}
	where $C$ is a positive constant independent of $N$, $\tau$ and $\lambda$, but possibly dependent on $\|\phi\|_{H^s}$.
\end{lemma}

\begin{proof}
	We decompose $\mathcal{A}_3(\U^*)$ as follows
	\begin{align}\label{eq:A_3}
		\mathcal{A}_3(\U^*)=&\frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\partial_{x}\left[\Pi_{N_{\lambda}}\left(\Pi_{N_{\lambda}}\U^*(s)\right)^2-\Pi_{N_{\lambda}}\left(\Pi_{N_{\lambda}}u^*_{\lambda}(s)\right)^2\right]\d s\notag\\
		&+\frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\partial_{x}\left[\Pi_{N_{\lambda}}\left(\Pi_{N_{\lambda}}u^*_{\lambda}(s)\right)^2-\left(u^*_{\lambda}(s)\right)^2\right]\d s\notag\\
		&+\frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\partial_{x}\left[\left(u^*_{\lambda}(s)\right)^2-\left(\U^*(s)\right)^2\right]\d s\notag\\
		=&:\mathcal{B}_1(\U^*,u^*_{\lambda})+\mathcal{B}_2(u^*_{\lambda})+\mathcal{B}_3(\U^*,u^*_{\lambda}).
	\end{align}
	Using the same arguments as in \eqref{eq:e_times_u_Y12}, and noting the boundedness of the projection operator, we obtain:
	\begin{align}\label{eq:estimate_B1B3}
		\left\|\mathcal{B}_1(\U^*,u^*_{\lambda})\right\|_{Y^{-\frac{1}{2}}}+\left\|\mathcal{B}_3(\U^*,u^*_{\lambda})\right\|_{Y^{-\frac{1}{2}}}\lesssim \lambda^{0+}\left(\left\|u^{*}_{\lambda}\right\|_{Y^{-\frac{1}{2}}}+\left\|\U^{*}\right\|_{Y^{-\frac{1}{2}}}\right)\cdot\|e\|_{Y^{-\frac{1}{2}}}.
	\end{align}
	Next, we further split $\mathcal{B}_2(u^*_{\lambda})$ as follows
	\begin{align}\label{eq:R_1}
		\mathcal{B}_2(u^*_{\lambda})=&-\frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\Pi_{>N_{\lambda}}\partial_{x}\left(u_{\lambda}^{*}(s)\right)^2\d s\notag\\
		&-\frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\Pi_{N_{\lambda}}\partial_{x}\Big[\Pi_{>N_{\lambda}}u^*_{\lambda}(s)\cdot\left(u^*_{\lambda}(s)+\Pi_{N_{\lambda}}u^*_{\lambda}(s)\right)\Big]\d s \notag\\
		=&:\mathcal{B}_{21}(u^*_{\lambda})+\mathcal{B}_{22}(u^*_{\lambda}),
	\end{align}
	where we denote $\Pi_{>N_{\lambda}}=I-\Pi_{N_{\lambda}}$. By using Lemmas~\ref{lem:energy_estimate}, \ref{lem:bilinear_estimate}, \ref{lem:Bernstein} and Remark~\ref{rem:bilinear_estimate}, we get
	\begin{align}\label{eq:R_11}
		\left\|\mathcal{B}_{21}(u^*_{\lambda})\right\|_{Y^{-\frac{1}{2}}}&\lesssim 	\left\|\eta(t)\Pi_{>N_{\lambda}}\partial_{x}\left(u_{\lambda}^{*}(t)\right)^2\right\|_{Z^{-\frac{1}{2}}}\notag\\
		&\lesssim N_{\lambda}^{-\frac{1}{2}-s}\left\|\eta(t)\partial_{x}\left(u_{\lambda}^{*}(t)\right)^2\right\|_{Z^{s}}\lesssim \lambda^{0+}N_{\lambda}^{-\frac{1}{2}-s}\|{u^*_{\lambda}}\|_{Y^s}^2,
	\end{align}
	and
	\begin{align}\label{eq:R_12}
		\left\|\mathcal{B}_{22}(u^*_{\lambda})\right\|_{Y^{-\frac{1}{2}}}&\lesssim 	\left\|\eta(t)\Pi_{N_{\lambda}}\partial_{x}\Big[\Pi_{>N_{\lambda}}u^*_{\lambda}(t)\cdot\left(u^*_{\lambda}(t)+\Pi_{N_{\lambda}}u^*_{\lambda}(t)\right)\Big]\right\|_{Z^{-\frac{1}{2}}}\notag\\
		&\lesssim \lambda^{0+}\left\|\Pi_{>N_{\lambda}}u^*_{\lambda}(t)\right\|_{Y^{-\frac{1}{2}}}\cdot \left(\|{u^*_{\lambda}}\|_{Y^{-\frac{1}{2}}}+\left\|\Pi_{N_{\lambda}}{u^*_{\lambda}}\right\|_{Y^{-\frac{1}{2}}}\right)\notag\\
		&\lesssim \lambda^{0+}N_{\lambda}^{-\frac{1}{2}-s}\|{u^*_{\lambda}}\|_{Y^s}^2.
	\end{align}
	Finally,  substituting \eqref{eq:estimate_B1B3}, \eqref{eq:R_11} and \eqref{eq:R_12} into \eqref{eq:A_3} and noting that $\|{u^*_{\lambda}}\|_{Y^s}\leq C^{\#}\|\phi_{\lambda}\|_{H^s}\leq C^{\#}\lambda^{-\frac{3}{2}-s}\|\phi\|_{H^s}$, we obtain the desired estimate \eqref{eq:estimate_R1}.
\end{proof}


\subsection{The proof of Theorem~\ref{thm:main} for short time}\label{subsec:proof_small_T}
From the discussions in Remark~\ref{lem:relation_Gamma}, equation \eqref{eq:u-u*} and the rescaling relationship \eqref{eq:relation_scaling}, we deduce that
\begin{align}\label{eq:final_ineq_1}
	\max_{\sigma_n \leq \lambda^{-3}} \|u(\sigma_n) - u^n\|_{H^{-\frac{1}{2}}}
	&\leq \lambda^{\frac{3}{2}} \max_{t_n \leq 1} \|u_{\lambda}(t_n) - u_{\lambda}^n\|_{H^{-\frac{1}{2}}}\notag\\
	&\leq \lambda^{\frac{3}{2}}\|u_{\lambda}-\U\|_{L^{\infty}(0,1;H^{-\frac{1}{2}})}\lesssim \lambda^{\frac{3}{2}}\|e\|_{Y^{-\frac{1}{2}}},
\end{align}
where the error function $e=u^*_\lambda-\U^*$ is defined in \eqref{eq:def_error}. The scaling parameter $\lambda\geq1$ satisfies the conditions in Theorem~\ref{thm:existence} and \eqref{eq:condition_lambda} below. Importantly, $\lambda$ is independent of $N$ and $\tau$ but possibly depends on $\|\phi\|_{H^s}$. Consequently, if $T< \lambda^{-3}$ the proof of the error estimate in \eqref{eq:main_thm}  reduces to estimating $\|e\|_{Y^{-\frac{1}{2}}}$.

By combining \eqref{eq:Y_norm_inequality}, \eqref{eq:e_0_Y12}, \eqref{eq:e_times_u_Y12}, and the estimates from Lemmas~\ref{lem:estimate_R1} and \ref{lem:estimate_A1A2}, we obtain the following inequality:
\begin{align}\label{eq:e_estimate}
	\|e\|_{Y^{-\frac{1}{2}}}\leq& C\lambda^{0+}\left(\left\|u^{*}_{\lambda}\right\|_{Y^{-\frac{1}{2}}}+\left\|\U^{*}\right\|_{Y^{-\frac{1}{2}}}\right)\cdot\|e\|_{Y^{-\frac{1}{2}}}+C \lambda^{-\frac{5}{2}-s+} N^{-\frac{1}{2}-s}+C\lambda^{-\frac{3}{2}}\tau N^{3(\frac{1}{2}-s)},
\end{align}
where $C$ is a positive constant independent of $N$, $\tau$ and $\lambda$ but possibly dependent on $\|\phi\|_{H^s}$. Since $$\left\|u^{*}_{\lambda}\right\|_{Y^{-\frac{1}{2}}}+\left\|\U^{*}\right\|_{Y^{-\frac{1}{2}}}\leq2C^{\#}\|\phi_{\lambda}\|_{H^s}\leq 2C^{\#}\lambda^{-\frac{3}{2}-s}\|\phi\|_{H^s},$$
we can choose a sufficient large $\lambda$ such that 
\begin{align}\label{eq:condition_lambda}
	C\lambda^{0+}\left(\left\|u^{*}_{\lambda}\right\|_{Y^{-\frac{1}{2}}}+\left\|\U^{*}\right\|_{Y^{-\frac{1}{2}}}\right)\leq 2CC^{\#}\lambda^{-\frac{3}{2}-s+}\|\phi\|_{H^s}\leq \frac{1}{2}.
\end{align}
Thus, we obtain the estimate
\begin{align}\label{estimate_e}
	\|e\|_{Y^{-\frac{1}{2}}}\lesssim& \lambda^{-\frac{5}{2}-s+} N^{-\frac{1}{2}-s}+\lambda^{-\frac{3}{2}}\tau N^{3(\frac{1}{2}-s)}.
\end{align} 
%Assuming that $\lambda^3\tau\ll 1$, for $0\leq n\leq M_0:=\lfloor\frac{\lambda^{-3}}{\tau}\rfloor$, we have
%\begin{align}\label{eq:final_ineq_2}
%	\sup_{0\leq n\leq M_0}\|u(\sigma_n)-u^n\|_{H^{-\frac{1}{2}}}\leq \lambda^{\frac{3}{2}}\sup_{0\leq n\leq M_0}\|u_{\lambda}(t_{n})-u_{\lambda}^n\|_{H^{-\frac{1}{2}}}\leq \lambda^{\frac{3}{2}}\|u_{\lambda}-\U\|_{L^{\infty}(0,1;H^{-\frac{1}{2}})}.
%\end{align}
By combining  \eqref{eq:final_ineq_1} and \eqref{estimate_e},  taking $N=O(\tau^{-\frac{1}{2-2s}+})$, and noting that $\lambda^{-1-s+}\leq 1$ for $\lambda\geq1$ and $s\in(-\frac{1}{2},0]$,
we obtain
\begin{align}\label{eq:iterate_ineq}
	&\sup_{0\leq n\leq T/\tau}\|u(\sigma_n)-u^n\|_{H^{-\frac{1}{2}}}\lesssim  \lambda^{-1-s+}N^{-\frac{1}{2}-s}+\tau N^{3(\frac{1}{2}-s)}\lesssim 
	\tau^{\frac{1+2s}{4-4s}-}.
\end{align}
This completes the proof of Theorem~\ref{thm:main} for the problem \eqref{eq:KdV_equation} within short time interval, i.e. $T<\lambda^{-3}$ for $\lambda$ satisfying the conditions in Theorem~\ref{thm:existence} and \eqref{eq:condition_lambda}.

\subsection{The proof of Theorem~\ref{thm:main} for large time}

For the case $T \ge \lambda^{-3}$, since it has already been established in Subsection~\ref{subsec:proof_small_T} that the conclusion of Theorem~\ref{thm:main} holds for $0\leq n \leq M_0$ where $M_0:=\lfloor\frac{\lambda^{-3}}{\tau}\rfloor$, we can proceed from $u(\sigma_{M_0})$ and $u^{M_0}$ as initial data and then repeatedly apply similar arguments to prove the error estimates for $n > M_0$. Specifically, we first consider the following nonlinear operators:
\begin{align}\label{eq:def_Gamma_1}
	\Gamma_1(w)(t) = & \, \eta(t)e^{-t \partial_x^3}u^{M_0}_{\lambda} + \frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\partial_{x}\left(w(s)\right)^2 \, \mathrm{d}s + \mathcal{A}(w)(t),
\end{align}
and
\begin{align}\label{eq:def_tilde_Gamma_1}
	\widetilde{\Gamma}_1(w)(t)=\eta(t)e^{-t \partial_x^3}u_{\lambda}(t_{M_0})+\frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\partial_{x}\left(w(s)\right)^2\d s,
\end{align}
where $\mathcal{A}$ in \eqref{eq:def_Gamma_1} is defined as in \eqref{eq:def_Gamma}.  And then convert the estimate $\|u(\sigma_n)-u^n\|_{H^{-\frac{1}{2}}}$ for $M_0\leq n\leq 2M_0$ into the Bourgain norm estimate between the two fix points of \eqref{eq:def_Gamma_1} and \eqref{eq:def_tilde_Gamma_1}, as the discussions in \eqref{eq:final_ineq_1}.

It is important to observe from Theorem~\ref{thm:existence} and \eqref{eq:condition_lambda} that the choice of the scaling parameter $\lambda$ depends on the $H^s$ norm of the initial data, specifically $\|u^{M_0}_{\lambda}\|_{H^s}$. This implies that for large $T$, ensuring the stability of the numerical solution in the $H^s$ space becomes crucial. However, directly applying the results from Theorem~\ref{thm:existence} is quite challenging. The difficulty arises because Theorem~\ref{thm:existence} only provides the following boundedness estimate:  
\begin{align}\label{eq:boundedness_estimate}  
	\|u^{M_0}_{\lambda}\|_{H^s} \leq C^{\#}\|\phi_{\lambda}\|_{H^s},  
\end{align}  
for some constant $C^{\#} > 1$. When $T$ becomes significantly larger compared to $\lambda^{-3}$, it is necessary to partition the entire time interval into smaller segments and iteratively apply short-time error estimates within each segment.  
Relying only on the boundedness estimate \eqref{eq:boundedness_estimate} leads to exponential growth in the $H^s$-norm estimate of the numerical solution. Consequently, $\lambda$ must be chosen sufficiently large, which in turn causes the length of the time segments, $\lambda^{-3}$, to become extremely small. This makes it challenging to extend the convergence results in Subsection~\ref{subsec:proof_small_T} to longer time intervals.

One approach to addressing this difficulty is to incorporate the error estimate and Bernstein's inequality by choosing  
$N \sim \tau^{-\frac{1}{2-2s}+\varepsilon}$  
for some small $\varepsilon > 0$ with $\varepsilon \ll 1$. This choice introduces an additional small term in the error estimate, allowing us to establish a uniform bound on the numerical solution in $H^{\gamma}$ for a fixed $\gamma \in (-1/2, s)$ as $\tau$ tends to zero (see, for example, \eqref{eq:error_H_gamma_2} below). %This bound remains consistent across different time segments and depends only on $\|u\|_{L^\infty(0,T; H^s)}$.  

From Theorem~\ref{thm:existence}, we observe that the nonlinear operator \eqref{eq:def_Gamma_1} admits a unique fixed point in the Bourgain space $Y^{\gamma}$ under the choice of the scaling parameter $\lambda$, which depends only on the $H^{\gamma}$ norm of the numerical solution. Consequently, for the entire time interval $[0,T]$, we can select a uniform time segment length,  
$\lambda^{-3}$,  
which depends solely on $\|u\|_{L^\infty(0,T; H^s)}$. By iteratively applying the short-time error estimate from Subsection~\ref{subsec:proof_small_T}, we obtain a convergence result for the long-time interval.  

Meanwhile, from Lemma~\ref{lem:estimate_A1A2}, we note that part of the consistency error estimate of our numerical method depends on the regularity of the initial value for the nonlinear operator \eqref{eq:def_Gamma_1}, i.e., the regularity of the numerical solution. Therefore, to ensure the validity of the error estimate, we choose $\gamma < s$ such that  
$|s - \gamma|$  
is sufficiently small and satisfies:


%\begin{align}\label{eq:gamma_condition_1}
%	-\frac{3}{2}-3\gamma<-\frac{1}{2}-s,\quad\; \text{for}\quad N=O(\tau^{-\frac{1}{3}})\quad\;\; s\in(-\frac{1}{2},0],
%\end{align}
%or
\begin{align}\label{eq:gamma_condition_2}
	\frac{3}{2-2s}(\gamma-s)+(2-2\gamma)\varepsilon>0,\quad \text{for}\quad N=O(\tau^{-\frac{1}{2-2s}+\varepsilon}), \quad \text{and}\quad s\in(-\frac{1}{2},0],
\end{align}
where $\varepsilon$ is fixed for all time-steps. And we will prove that there exist a $\tau_0$ sufficiently small such that if $\tau<\tau_0$ there holds
\begin{subequations}\label{reformulated_problem}
	\begin{align}
		\|u(\sigma_n)-u^n\|_{H^{-\frac{1}{2}}}&\leq C \tau^{\frac{1+2s}{4-4s}-\frac{1+2s}{2}\varepsilon},\label{reformulate_1}\\
		\|u^n\|_{H^{\gamma}}&\leq \|u\|_{L^{\infty}(0,T;H^{s})}+1,\label{reformulate_2}
	\end{align}
\end{subequations}
for all $0\leq n\leq T/\tau$, where $C$ is a positive constant independent of $\tau$ and $N$ but possibly depends on $T$ and $\|u\|_{L^{\infty}(0,T;H^{s})}$.

Firstly, we infer from \eqref{eq:iterate_ineq} that
\begin{align}\label{eq:reformulated_estimate}
	\sup_{0\leq n\leq M_0}\|u(\sigma_n)-u^n\|_{H^{-\frac{1}{2}}}&\lesssim  \lambda^{-1-s+}N^{-\frac{1}{2}-s}+\tau N^{3(\frac{1}{2}-s)}\notag\\
	&\lesssim \lambda^{-1-s+}\tau^{\frac{1+2s}{4-4s}-\frac{1+2s}{2}\varepsilon}+\tau ^{1+3(\frac{1}{2}-s)(-\frac{1}{2-2s}+\varepsilon)}\notag\\
	&=\tau^{\frac{1+2s}{4-4s}-\frac{1+2s}{2}\varepsilon}\left(\lambda^{-1-s+}+\tau^{(2-2s)\varepsilon}\right)\lesssim \tau^{\frac{1+2s}{4-4s}-\frac{1+2s}{2}\varepsilon}.
\end{align}
Thus, we have proved  \eqref{reformulate_1} for $0\leq n\leq M_0$.

Next, from the definition of the filtered low-regularity integrator \eqref{eq:filtered_LRI}, we have
\begin{align*}
	\Pi_{>N}u^{n}=\Pi_{>N}\left(e^{-n \tau\partial_x^3}\phi\right),
\end{align*}
for all  $0\leq n\leq T/\tau$.
Thus, using \eqref{eq:reformulated_estimate} and the Bernstein's inequality, we obtain
\begin{align}\label{eq:H_gamma_estimate}
	\|u^{n}-u(\sigma_{n})\|_{H^\gamma}&\leq 	\left\|\Pi_{N}\left(u^{n}-u(\sigma_{n})\right)\right\|_{H^\gamma}+\|\Pi_{>N}u^{n}\|_{H^\gamma}+\|\Pi_{>N}u(\sigma_{n})\|_{H^{\gamma}}\notag\\
	&\lesssim \tau^{\frac{1+2s}{4-4s}-\frac{1+2s}{2}\varepsilon}N^{\gamma+\frac{1}{2}}
	+N^{\gamma-s}\left(\|\phi\|_{H^s}+\|u\|_{L^\infty(0,T; H^s)}\right),
\end{align}
for all $0\leq n\leq M_0$.
Through direct calculation, we deduce the following result
\begin{align}\label{eq:error_H_gamma_2}
	\|u^{n}-u(\sigma_{n})\|_{H^\gamma}\lesssim\tau^{(s-\gamma)(\frac{1}{2-2s}-\varepsilon)}.
\end{align}
Since $\gamma<s$,
the exponent of $\tau$ in \eqref{eq:error_H_gamma_2} is strictly positive.
There exists a constant $\tau_0>0$ such that, if $\tau<\tau_0$, then
\begin{align*}
	\|u^{n}-u(\sigma_{n})\|_{H^\gamma}\leq 1.
\end{align*}
Therefore, we have
\begin{align}\label{eq:un_H_gamma}
	\|u^{n}\|_{H^\gamma}\leq \|u(\sigma_{n})\|_{H^{\gamma}}+1\leq \|u\|_{L^{\infty}(0,T;H^{s})}+1,
\end{align}
which is the uniform estimate of the numerical solution in $H^{\gamma}$, i.e. \eqref{reformulate_2} for all $0\leq n\leq M_0$.
%and
%\begin{align}
%	\|u^{M_0}_{\lambda}\|_{H^\gamma}\leq\lambda^{-\frac{3}{2}-\gamma}\|u^{M_0}\|_{H^{\gamma}}\leq \lambda^{-\frac{3}{2}-\gamma}\left(\|u\|_{L^{\infty}(0,T;H^{s})}+1\right).
%\end{align}

Now, we starting from $u(\sigma_{M_0})$ and $u^{M_0}$ as initial data, from Theorem~\ref{thm:existence}, we have, there exists a positive constant $\lambda_0$, which is independent of $N$ and $\tau$ but may dependent on $\|u^{M_0}\|_{H^\gamma}$, such that for any $\lambda>\lambda_0$ the equation $\Gamma_1(\U^{*,1})=\U^{*,1}$ admits a solution $\U^{*,1}\in Y^{\gamma}$ satisfying
\begin{align}
	\|\U^{*,1}\|_{Y^{\gamma}}\leq C^{\#}\|u^{M_0}_{\lambda}\|_{H^\gamma}\leq C^{\#} \lambda^{-\frac{3}{2}-\gamma}\|u^{M_0}\|_{H^\gamma}.
\end{align}
Moreover, we note from the definition of $\Gamma_1$ in \eqref{eq:def_Gamma_1} that for $t\in[0,1]$ there holds
\begin{align}
	\U^{*,1}(t)\equiv \U(t_{M_0}+t).
\end{align}


\begin{remark}
	\upshape
	Since $\lambda_0$ depends only on $\|u^{M_0}\|_{H^\gamma}$ which is bounded by the fixed constant $\|u\|_{L^{\infty}(0,T;H^{s})}+1$ and is independent of $\tau$ and the numerical solution $u^n$,  we can, without loss of generality, assume that $\lambda_0$ here is the same as previously defined. 
	This ensures consistent use of the same scaling constant $\lambda$ throughout the analysis.
	Meanwhile, we note that, the conditions $\gamma<s$ and \eqref{eq:gamma_condition_2} are sufficient to guarantee the condition
	$N\lesssim \tau^{-\frac{1}{2-2\gamma}}$, which is necessary for maintaining the stability of the numerical scheme with $H^{\gamma}$ initial data (see Theorem~\ref{thm:existence}).
	To see this, note that for $N=O(\tau^{-\frac{1}{2-2s}+\varepsilon})$, the condition above is equivalent to
	\begin{align*}
		-\frac{1}{2-2\gamma}\leq -\frac{1}{2-2s}+\varepsilon,
	\end{align*}
	which simplifies to $	\frac{1}{2}(s-\gamma)+\frac{3}{2-2s}(\gamma-s)+(2-2\gamma)\varepsilon\geq 0.$
	%	\begin{align*}
		%		\frac{1}{2}(s-\gamma)+\frac{3}{2-2s}(\gamma-s)+(2-2\gamma)\varepsilon\geq 0.
		%	\end{align*}
	This inequality follows directly from the conditions $\gamma<s$ and \eqref{eq:gamma_condition_2}.
\end{remark}


We note from \cite[Proposition~6]{Colliander} that, since $u_{\lambda}(t_{M_0})\in H^s$, the equation 
\begin{align}
	\widetilde{\Gamma}(u^{*,1}_{\lambda})=u^{*,1}_{\lambda},
\end{align}
admits a unique solution in the $Y^s$ space, satisfying
$$\|u_{\lambda}^{*,1}\|_{Y^s}\leq C^{\#}\|u_{\lambda}(t_{M_0})\|_{H^s},$$
and
\begin{align}\label{eq:gamma_1_relation_u*_u}
	u_{\lambda}^*(t)=u_{\lambda}(t_{M_0}+t),\quad \text{for}\quad t \in [0, 1].
\end{align}
Thus,  the error between $\U(t)$ and $u_{\lambda}(t)$ for $t\in [M_0\tau_{\lambda},M_0\tau_{\lambda}+1]$ can be estimated by analyzing $u^{*,1}_{\lambda}-\U^{*,1}$ in the Bourgain space $Y^{-\frac{1}{2}}$. Denoting
\begin{align*}
	e_1(t,x):=u^{*,1}_{\lambda}-\U^{*,1},
\end{align*}
and following the same arguments as in \eqref{eq:Y_norm_inequality}--\eqref{eq:e_times_u_Y12}, we deduce
\begin{align}\label{eq:gamma_Y_norm_inequality}
	\|e_1\|_{Y^{-\frac{1}{2}}}\lesssim&\left\|e_1(0)\right\|_{H^{-\frac{1}{2}}}+\lambda^{0+}\left(\left\|u^{*,1}_{\lambda}\right\|_{Y^{-\frac{1}{2}}}+\left\|\U^{*,1}\right\|_{Y^{-\frac{1}{2}}}\right)\cdot\|e_1\|_{Y^{-\frac{1}{2}}}\notag\\
	&\quad +\|\mathcal{A}_1(\U^{*,1})\|_{Y^{-\frac{1}{2}}}+\|\mathcal{A}_2(\U^{*,1})\|_{Y^{-\frac{1}{2}}}+\|\mathcal{A}_3(\U^{*,1})\|_{Y^{-\frac{1}{2}}}.
\end{align}
Since 	$\|u^{M_0}\|_{H^\gamma}\leq \|u\|_{L^{\infty}(0,T;H^{s})}+1$, it follows from Lemma~\ref{lem:estimate_A1A2} that
\begin{align}\label{eq:gamma_estimate_A1A2}
	\|\mathcal{A}_1(\U^{*,1})\|_{Y^{-\frac{1}{2}}}+\|\mathcal{A}_2(\U^{*,1})\|_{Y^{-\frac{1}{2}}}\leq C\lambda^{-\frac{3}{2}}\tau N^{3(\frac{1}{2}-\gamma)},
\end{align}
where $C$ is a positive constant independent of $N$, $\tau$ and $\lambda$ but possibly dependent on $	\|u^{M_0}_{\lambda}\|_{H^\gamma}$.

From Lemma~\ref{lem:estimate_R1}, the estimate of $\mathcal{A}_3(\U^{*,1})$ can be decomposed into two parts: the projection error for the nonlinear term of $u^{*,1}_{\lambda}$ and the difference between the nonlinear terms of $u^{*,1}_{\lambda}$ and $\U^{*,1}$. Since $u^{*,1}_{\lambda} \in Y^s$, we obtain the following estimate:
\begin{align}\label{eq:gamma_estimate_R1}
	\|\mathcal{A}_3(\U^{*,1})\|_{Y^{-\frac{1}{2}}}\leq C\left[\lambda^{-\frac{5}{2}-s+}N^{-\frac{1}{2}-s}+\lambda^{0+}\left(\left\|u^{*,1}_{\lambda}\right\|_{Y^{-\frac{1}{2}}}+\left\|\U^{*,1}\right\|_{Y^{-\frac{1}{2}}}\right)\cdot\|e_1\|_{Y^{-\frac{1}{2}}}\right].
\end{align}

Combining \eqref{eq:gamma_estimate_A1A2}, \eqref{eq:gamma_Y_norm_inequality}, \eqref{eq:gamma_estimate_R1}, and  applying the same reasoning as in \eqref{eq:e_estimate}--\eqref{eq:iterate_ineq}, we obtain
\begin{align}\label{eq:iterate_ineq_new}
	&\sup_{M_0\leq n\leq 2M_0}\|u(\sigma_n)-u^n\|_{H^{-\frac{1}{2}}}\notag\\
	&\quad\leq C_0 \|u(\sigma_{M_0})-u^{M_0}\|_{H^{-\frac{1}{2}}}+C_0\lambda^{-1-s+} N^{-\frac{1}{2}-s}+C_0\tau N^{3(\frac{1}{2}-\gamma)}\notag\\
	&\quad\leq C_0\left(\left\|u(\sigma_{M_0})-u^{M_0}\right\|_{H^{-\frac{1}{2}}}+\tau^{\frac{1+2s}{4-4s}-\frac{1+2s}{2}\varepsilon}\right),
\end{align}
with constant $C_0$ independent of $\tau$, $N$ and $\lambda$. Here we have used the relation $N=O(\tau^{-\frac{1}{2-2s}+\varepsilon})$, and 
\begin{align*}
	\tau N^{3(\frac{1}{2}-\gamma)}\sim\tau ^{1+3(\frac{1}{2}-\gamma)(-\frac{1}{2-2s}+\varepsilon)}=\tau^{\frac{1+2s}{4-4s}-\frac{1+2s}{2}\varepsilon}\cdot \tau^{\frac{3}{2-2s}(\gamma-s)+(2-2\gamma)\varepsilon+(s-\gamma)\varepsilon}
\end{align*}
where
\begin{align*}
	\frac{3}{2-2s}(\gamma-s)+(2-2\gamma)\varepsilon+(s-\gamma)\varepsilon>0
\end{align*}
by utilizing $s>\gamma$ and the condition \eqref{eq:gamma_condition_2}. 
By further combining \eqref{eq:reformulated_estimate} and \eqref{eq:iterate_ineq_new}, we establish the error estimate \eqref{reformulate_1} for all $M_0 \leq n \leq 2M_0$. Then, following the same steps as in \eqref{eq:H_gamma_estimate}--\eqref{eq:un_H_gamma}, we obtain the uniform $H^{\gamma}$ stability of the numerical method for all $M_0 \leq n \leq 2M_0$:
\begin{align}\label{eq:un_H_gamma_new}
	\sup_{M_0\leq n\leq 2M_0}\|u(\sigma_n)-u^n\|_{H^{\gamma}}\leq \|u\|_{L^{\infty}(0,T;H^{s})}+1,
\end{align}
for $\tau$ sufficiently small.

Since the time interval $[0,T]$ can be divided into at most $L:=\lfloor \frac{T}{M_0\tau}\rfloor+1$ slices, and
\begin{align*}
	\left\lfloor \frac{T}{M_0\tau}\right\rfloor+1\lesssim T\lambda^3,
\end{align*}
which is independent of $\tau$ and $N$, but may depends only on $T$ and $\|u\|_{L^{\infty}(0,T;H^{s})}$. 
We can iterate \eqref{eq:iterate_ineq_new} and \eqref{eq:un_H_gamma_new} in the classical manner to derive 
\begin{align}
	\sup_{0\leq n\leq T/\tau}\|u(\sigma_n)-u^n\|_{H^{-\frac{1}{2}}}\leq (1+C_0)^{L}\cdot\tau^{\frac{1+2s}{4-4s}-\frac{1+2s}{2}\varepsilon},
\end{align}
and
\begin{align}
	\sup_{0\leq n\leq T/\tau}\|u^n\|_{H^{\gamma}}\leq \|u\|_{L^{\infty}(0,T;H^{s})}+1
\end{align}
for $\tau$ sufficiently small. From this, it is clear that the conclusion \eqref{eq:main_thm} has been established, thereby completing the proof of Theorem~\ref{thm:main}.




\section{Numerical experiments}\label{sec:numerical_experiments}
In this section, we conduct numerical experiments to substantiate the theoretical analysis presented earlier. We demonstrate the convergence properties of the numerical solutions obtained using the proposed filtered low-regularity integrator, specifically for computing nonsmooth solutions of the Korteweg-de Vries (KdV) equation in spaces below $L^2$. We consider the KdV equation on the torus $[-\pi, \pi]$ with the following initial condition:
\begin{equation}
	u^{0}(x) = \frac{1}{10} \sum_{0 \neq k \in \mathbb{Z}} q_k|k|^{-0.501-s} e^{ikx},
\end{equation}
where $q_k\in\mathbb{C}$ is a phase factor satisfying $|q_k|=O(1)$, which ensures that the initial function $u^0$ belongs to $H^{s}$ but not to $H^{s+0.001}$. For $s=0$ and $s=-\frac{1}{4}$, we present the graph of the function $u^0$ in Figures~\ref{fig:6-0}(a) and (b), highlighting the significant singularities at $x=0$.

To address the KdV equation with nonsmooth initial data, specifically when $u_0 \in L^2$ and $u_0 \in H^{-\frac{1}{4}}$, we utilize the filtered low-regularity integrator, given by:
\begin{itemize}
	\item $\tau = 2^{-16} T$ and $N = O(\tau^{-\frac{1}{2}}) = 2^{-8}$ for $s = 0$,
	\item $\tau = 2^{-20} T$ and $N = O(\tau^{-\frac{2}{5}}) = 2^{-8}$ for $s = -\frac{1}{4}$.
\end{itemize}
The spatial discretization is performed using a Fourier pseudo-spectral method with $2^{14}$ modes.
