\section{Proofs of some results in Section~\ref{sec:bourgain}}\label{Appendix:A}
\begin{proof}[Proof of Lemma~\ref{lem:embedding_Ys}]
	The proof follows directly from the inequality $$\|w\|_{L_{t}^{\infty}H_{x}^s}\leq \|\langle k \rangle^s \tilde{w}(\sigma,k)\|_{L^2((\mathrm{d}k)_{\lambda}) L^1(\mathrm{d}\sigma)}.$$

\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:time_localization}]
	If we use Fourier expansion $\eta(t)=\int_{\mathbb{R}}\hat{\eta}(\sigma_0)e^{it\sigma_0}\d \sigma_0$, then following the same reasoning as in Lemma~2.11 of \cite{Tao}, we obtain
	\begin{align*}
		\|\eta(t)w\|_{X_{s,b}}\leq C_0 \left(\int_{\mathbb{R}}|\hat{\eta}(\sigma_0)|\langle\sigma_0\rangle^{|b|}\d\sigma_0\right)\|w\|_{X_{s,b}},
	\end{align*}
	where $C_0$ is a positive constant depending only on $b$. Since $\eta$ is Schwartz, $\hat{\eta}$ is also rapidly decreasing, and thus the desired estimate $\|\eta(t)w\|_{X_{s,b}}\leq C\|w\|_{X_{s,b}}$ holds with a positive constant $C$ independent of $\lambda$. The other two inequalities in \eqref{eq:time_localization} can be proved in exactly the same manner.
\end{proof}

\begin{proof}[Proof of Corollary~\ref{corollary:Z0}]
	From the definition of the Bourgain space $X_{s,b}$ and the embedding result in Lemma~\ref{lem:embedding_theorem},
	we know that $X_{0,\frac{1}{2}}\hookrightarrow X_{0,\frac{1}{3}}\hookrightarrow L^{4}_t L^{4}_x$. 
	By applying the duality argument, we obtain $(L^{4}_t L^{4}_x)^{\prime}\hookrightarrow (X_{0,\frac{1}{2}})^{\prime}.$

	Since $(L^{4}_t L^{4}_x)^{\prime}=L^{\frac{4}{3}}_t L^{\frac{4}{3}}_x$ and $(X_{0,\frac{1}{2}})^{\prime}=X_{0,-\frac{1}{2}}$, it follows that $\|w\|_{X_{0,-\frac{1}{2}}}\lesssim \|w\|_{L^{\frac{4}{3}}_t L^{\frac{4}{3}}_x}$.

	Thus, it remains to show that
	\begin{align}
		\left\|\frac{\tilde{w}(\sigma,k)}{\langle\sigma-4\pi^2k^3\rangle}\right\|_{L^2((\d k)_{\lambda})L^1(\d \sigma)}\lesssim \|w\|_{L^{\frac{4}{3}}_t L^{\frac{4}{3}}_x}.
	\end{align}
	By the duality argument, it suffices to prove
	\begin{align}\label{eq:dulaity_L43}
		\sup_{\|\tilde{f}\|_{L^2_k L^\infty_\sigma}=1}\int\int \langle\sigma-4\pi^2k^3\rangle^{-1}\tilde{w}(\sigma,k)\tilde{f}(\sigma,k)\d \sigma(\d k)_{\lambda}\lesssim \|w\|_{L^{\frac{4}{3}}_t L^{\frac{4}{3}}_x}.
	\end{align}
	By using the Parseval equality, we have
	\begin{align*}
		&\int\int \langle\sigma-4\pi^2k^3\rangle^{-1}\tilde{w}(\sigma,k)\tilde{f}(\sigma,k)\d \sigma(\d k)_{\lambda}\\
		&\quad=\int_0^{\infty}\int_0^{\lambda}w(t,x)\mathscr{F}^{-1}\left(\langle\sigma-4\pi^2k^3\rangle^{-1}\tilde{f}(\sigma,k) \right)(t,x)\d t\d x\\
		&\quad \leq  \|w\|_{L^{\frac{4}{3}}_t L^{\frac{4}{3}}_x}\cdot
		\Big\|\mathscr{F}^{-1}\left(\langle\sigma-4\pi^2k^3\rangle^{-1}\tilde{f}(\sigma,k) \right)(t,x)\Big\|_{L^4_t L^4_x},
	\end{align*}
	where $\mathscr{F}^{-1}$ denotes the inverse Fourier transform.  Then, according to the embedding result \eqref{eq:embedding_theorem}, we obtain
	\begin{align*}
		&\left\|\mathscr{F}^{-1}\left(\langle\sigma-4\pi^2k^3\rangle^{-1}\tilde{f}(\sigma,k) \right)(t,x)\right\|_{L^4_t L^4_x}\\
		&\quad\lesssim \left\|\mathscr{F}^{-1}\left(\langle\sigma-4\pi^2k^3\rangle^{-1}\tilde{f}(\sigma,k) \right)(t,x)\right\|_{X_{0,\frac{1}{3}}} =\left\|\langle\sigma-4\pi^2k^3\rangle^{-\frac{2}{3}}\tilde{f}(\sigma,k)\right\|_{L^2_\sigma L^2_k}\\
		&\quad=\left(\int\int \langle\sigma-4\pi^2k^3\rangle^{-\frac{4}{3}}|\tilde{f}(\sigma,k)|^2\d \sigma (\d k)_{\lambda}\right)^{\frac{1}{2}}\\
		&\quad \leq \left(\int \|\tilde{f}(\sigma,k)\|_{L^{\infty}_{\sigma}}^2\cdot\left(\int \langle\sigma-4\pi^2k^3\rangle^{-\frac{4}{3}}\d \sigma\right) (\d k)_{\lambda}\right)^{\frac{1}{2}}\lesssim \|\tilde{f}\|_{L^2((\d k)_{\lambda})L^{\infty}(\d \sigma)}.
	\end{align*}
	Combining these estimates yields \eqref{eq:dulaity_L43}, which completes the proof.
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:Bernstein}]
	Inequalities \eqref{eq:Bernstein_1} and \eqref{eq:Bernstein_3} can be directly proven using the definition of the projection operator. Moreover, from the scaling invariance of the Sobolev inequality, we have:
	\begin{align}
		\|\Pi_{N_{\lambda}} u\|_{L^{4}} \lesssim \|\Pi_{N_{\lambda}} u\|_{H^{\frac{1}{4}}}.
	\end{align}
	Finally, by applying \eqref{eq:Bernstein_1}, we deduce \eqref{eq:Bernstein_2}.
\end{proof}

\section{Proof of Lemma~\ref{lem:boundedness_um}}\label{Appendix:B}

\begin{proof}
	Since $\U^0=0$, the estimate in \eqref{eq:boundedness_um} naturally holds for $\ell=0$. Moreover, from the definition of $\Gamma$ in \eqref{eq:def_Gamma}, we have $\U^1=\eta(t)e^{-t \partial_x^3}\phi_{\lambda}$. By Lemma~\ref{lem:free_solution}, we obtain
	\begin{align*}
		\|\U^1\|_{Y^s}=\|\eta(t)e^{-t \partial_x^3}\phi_{\lambda}\|_{Y^s}\leq C_0\|\phi_{\lambda}\|_{H^s},
	\end{align*}
	where the constant $C_0$ independent of $\tau$, $N$ and $\lambda$. 

	Next, we assume that \eqref{eq:boundedness_um} holds with $C^{\#} = 2C_0$ for all $\U^j$ with $j \in \{0, \dots, \ell\}$ and $\ell \geq 1$. 
	%	Next, we assume \eqref{eq:boundedness_um} is satisfied  with $C^{\#}=2C_0$ for all $\U^j$, $j\in\{0,\cdots, m\}$ where $m\geq1$.
	By taking the $Y^s$ norm on both sides of $\U^{\ell+1} = \Gamma(\U^\ell)$, with $\Gamma$ given by the following equivalent reformulation of \eqref{eq:def_Gamma}:
	\begin{align}\label{eq:def_Gamma_equivalent}
		\Gamma(w)(t)=&\eta(t)e^{-t \partial_x^3}\phi_{\lambda}\notag\\
		&+\frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\Pi_{N_{\lambda}}\partial_{x}\left(\Pi_{N_{\lambda}}w(s)\right)^2\d s+\mathcal{A}_1(w)(t)+\mathcal{A}_2(w)(t),
	\end{align}
	we obtain:
	\begin{align}\label{eq:u_mp1}
		\|\U^{\ell+1}\|_{Y^s}&\leq  \|\eta(t)e^{-t \partial_x^3}\phi_{\lambda}\|_{Y^s}+\left\|\frac{1}{2}\eta(t)\int_{0}^{t}e^{(s-t)\partial_x^3}\eta(s)\Pi_{N_{\lambda}}\partial_{x}\left(\Pi_{N_{\lambda}}\U^\ell(s)\right)^2\d s\right\|_{Y^s}\notag\\
		&\quad+\|\mathcal{A}_1(\U^\ell)\|_{Y^s}+\|\mathcal{A}_2(\U^\ell)\|_{Y^s}\notag\\
		&\leq C_0\|\phi_{\lambda}\|_{H^s}+C\left\|\eta(t)\Pi_{N_{\lambda}}\partial_{x}\left(\Pi_{N_{\lambda}}\U^\ell(t)\right)^2\right\|_{Z^s}+\|\mathcal{A}_1(\U^\ell)\|_{Y^s}+\|\mathcal{A}_2(\U^\ell)\|_{Y^s}\notag\\
		&\leq C_0\|\phi_{\lambda}\|_{H^s}+C\lambda^{0+}\left\|\U^\ell\right\|^2_{X_{s,\frac{1}{2}}}+\|\mathcal{A}_1(\U^\ell)\|_{Y^s}+\|\mathcal{A}_2(\U^\ell)\|_{Y^s},
	\end{align}
	where we have used Lemmas~\ref{lem:free_solution}, \ref{lem:energy_estimate}, \ref{lem:bilinear_estimate} and Remark~\ref{rem:bilinear_estimate} in the above inequalities. We shall estimate each term on the right-hand side of \eqref{eq:u_mp1}, i.e. $\|\mathcal{A}_1(\U^\ell)\|_{Y^s}$ and $\|\mathcal{A}_2(\U^\ell)\|_{Y^s}$.

	{\sc Estimate of $\|\mathcal{A}_1(\U^\ell)\|_{Y^s}$:} Recalling the definition of $\mathcal{A}_1$ in \eqref{eq:def_Gamma} and using the results in Lemma~\ref{lem:energy_estimate}, Lemma~\ref{lem:embedding_theorem} and Corollary \ref{corollary:Z0}, we get
	\begin{align}\label{eq:estimate_A_1}
		\|\mathcal{A}_1(\U^\ell)\|_{Y^s}&\lesssim \left\|\eta(t)\Pi_{N_{\lambda}}\partial_{x}\Big(\Pi_{N_{\lambda}}\F(t,\U^\ell)\Pi_{N_{\lambda}}\U^\ell(t)\Big)\right\|_{Z^s}\notag\\
		&\lesssim N_{\lambda}^{1+s}\left\|\eta(t)\Big(\Pi_{N_{\lambda}}\F(t,\U^\ell)\Pi_{N_{\lambda}}\U^\ell(t)\Big)\right\|_{Z^0}\notag\\
		&\lesssim N_{\lambda}^{1+s}\left\|\eta(t)\Big(\Pi_{N_{\lambda}}\F(t,\U^\ell)\Pi_{N_{\lambda}}\U^\ell(t)\Big)\right\|_{L^{\frac{4}{3}}_t L^{\frac{4}{3}}_x}\notag\\
		&\lesssim N_{\lambda}^{1+s}\left\|\eta(t)\Pi_{N_{\lambda}}\F(t,\U^\ell)\right\|_{L^2_t L^2_x}\|\Pi_{N_{\lambda}}\U^\ell(t)\|_{L^4_t L^4_x}\notag\\
		&\lesssim N_{\lambda}^{1+s}\left\|\eta(t)\Pi_{N_{\lambda}}\F(t,\U^\ell)\right\|_{L^2_t L^2_x}\|\Pi_{N_{\lambda}}\U^\ell(t)\|_{X_{0,\frac{1}{3}}}.
	\end{align}
	Since $\|\Pi_{N_{\lambda}}\U^\ell(t)\|_{X_{0,\frac{1}{3}}}\leq \|\Pi_{N_{\lambda}}\U^\ell(t)\|_{X_{0,\frac{1}{2}}}\lesssim N_{\lambda}^{-s}\|\U^\ell\|_{X_{s,\frac{1}{2}}}$, we get
	\begin{align}\label{eq:A_1}
		\|\mathcal{A}_1(\U^\ell)\|_{Y^s}\lesssim N_{\lambda}\left\|\eta(t)\Pi_{N_{\lambda}}\F(t,\U^\ell)\right\|_{L^2_t L^2_x}\|\U^\ell\|_{X_{s,\frac{1}{2}}}.
	\end{align}
	%	Next, we provide a careful estimate of $\left\|\eta(t)\Pi_{N_{\lambda}}\F(t,\U^m)\right\|_{L^2_t L^2_x}$. Notably, $\F$ is defined in terms of time slices. If we directly use the boundedness of the $L_t^\infty H_x^{s}$ norm of $\U^m$ to estimate the $L^2_x$ norm of $\F$ at each time step, the resulting estimate proves too coarse to ensure satisfactory stability results.
	%	 Therefore, we use the Bourgain norm of $\U^m$ directly to estimate $\left\|\eta(t)\Pi_{N_{\lambda}}\F(t,\U^m)\right\|_{L^2_t L^2_x}$. 
	%To proceed, recalling \eqref{eq:def_F0}-\eqref{eq:def_F} and introducing the following notation, 


	Next, we provide a detailed estimate of $\left\|\eta(t)\Pi_{N_{\lambda}}\F(t, \U^\ell)\right\|_{L^2_t L^2_x}$. Recall that $\F$ is defined in terms of time slices. If we were to directly use the boundedness of the $L_t^\infty H_x^{s}$ norm of $\U^\ell$ to estimate the $L^2_x$ norm of $\F$ at each time step, the resulting estimate would be too coarse to guarantee satisfactory stability results.
	Therefore, we instead use the Bourgain norm of $\U^\ell$ to estimate $\left\|\eta(t)\Pi_{N_{\lambda}}\F(t,\U^\ell)\right\|_{L^2_t L^2_x}$ directly.
	To proceed, we recall \eqref{eq:def_F0}–\eqref{eq:def_F} and introduce the following notation:
	\begin{align}\label{defNmn}
		\mathcal{N}_n^\ell(s) := \Pi_{N_{\lambda}}\U^{\ell}(s) - e^{(t_{n}-s)\partial_x^3}\Pi_{N_{\lambda}}\U^{\ell}(t_n).
	\end{align}
	Then, we have the following estimate:
	\begin{align}\label{eq:F_L2L2}
		&\left\|\eta(t)\Pi_{N_{\lambda}}\F(t,\U^\ell)\right\|_{L^2_t L^2_x}^2\notag\\
		&=\frac{1}{4}\sum_{n}\int_{t_n}^{t_{n+1}}
		\int_0^{\lambda}
		\Big|\eta(t)\int_{t_{n}}^t  e^{(s-t)\partial_x^3}\Pi_{N_{\lambda}}
		\partial_{x}\left(e^{(t_{n}-s)\partial_x^3}\Pi_{N_{\lambda}}\U^{\ell}(t_n)\right)^2\d s
		\Big|^2\d x\d t\notag\\
		& \leq \frac{1}{4}\sum_{n}\int_{t_n}^{t_{n+1}} 
		\int_0^{\lambda}
		\Big|\eta(t)\int_{t_{n}}^t e^{(s-t)\partial_x^3}\Pi_{N_{\lambda}}\partial_{x}
		\big(\Pi_{N_{\lambda}}\U^{\ell}(s)\big)^2\d s
		\Big|^2\d x\d t\notag\\
		&\quad+\frac{1}{2}\sum_{n}\int_{t_n}^{t_{n+1}}\int_0^{\lambda}
		\Big|
		\eta(t)\int_{t_{n}}^t e^{(s-t)\partial_x^3}\Pi_{N_{\lambda}}\partial_{x} 
		\big(\mathcal{N}_n^\ell(s) \Pi_{N_{\lambda}}\U^{\ell}(s)\big)\d s
		\Big|^2\d x\d t\notag\\
		&\quad+\frac{1}{4}\sum_{n}\int_{t_n}^{t_{n+1}}\int_0^{\lambda}
		\Big|\eta(t)\int_{t_{n}}^t e^{(s-t)\partial_x^3}\Pi_{N_{\lambda}}\partial_{x} \big(\mathcal{N}_n^\ell(s)\big)^2\d s
		\Big|^2\d x\d t\notag\\
		&=:I_1+I_2+I_3.
	\end{align}
	We begin by estimating $I_1$ using Bernstein's inequality and Hölder's inequality, yielding the following result:
	\begin{align}\label{eq:I_1}
		I_1&\lesssim N_{\lambda}^2\cdot \sum_{n}\int_{t_n}^{t_{n+1}}\int_0^{\lambda}\Big|\eta(t)\int_{t_{n}}^t e^{(s-t)\partial_x^3}\left(\Pi_{N_{\lambda}}\U^{\ell}(s)\right)^2\d s\Big|^2\d x\d t\notag\\
		&\leq N_{\lambda}^2\cdot\sum_{n}\int_{t_n}^{t_{n+1}}(t-t_n)\int_0^{\lambda}\int_{t_{n}}^t \Big|e^{(s-t)\partial_x^3}\left(\Pi_{N_{\lambda}}\U^{\ell}(s)\right)^2\Big|^2\d s\d x\d t\notag\\
		&=N_{\lambda}^2\cdot\sum_{n}\int_{t_n}^{t_{n+1}}(t-t_n)\left\|e^{(s-t)\partial_x^3}\left(\Pi_{N_{\lambda}}\U^{\ell}(s)\right)^2\right\|^2_{L^2(t_n,t;L^2(0,\lambda))}\d t.
	\end{align}
	Since the operator $e^{(s-t)\partial_x^3}$ preserves the $L^2_x$ norm of function, we have 
	\begin{align*}
		&\Big\|e^{(s-t)\partial_x^3}\left(\Pi_{N_{\lambda}}\U^{\ell}(s)\right)^2\Big\|^2_{L^2(t_n,t;L^2(0,\lambda))}=\Big\|\left(\Pi_{N_{\lambda}}\U^{\ell}(s)\right)^2\Big\|^2_{L^2(t_n,t;L^2(0,\lambda))}\\[2mm]
		&\quad=\left\|\Pi_{N_{\lambda}}\U^{\ell}(s)\right\|^4_{L^4(t_n,t;L^4(0,\lambda))}
		\leq \left\|\Pi_{N_{\lambda}}\U^{\ell}(s)\right\|^4_{L^4(t_n,t_{n+1};L^4(0,\lambda))},
	\end{align*}
	for all $t\in[t_n,t_{n+1}]$ and $n=0,1,2,\cdots$.
	This together with \eqref{eq:I_1} and Lemma~\ref{lem:embedding_theorem} yields
	\begin{align}
		I_1&\lesssim N_{\lambda}^2\cdot\sum_{n}\int_{t_n}^{t_{n+1}}(t-t_n)\d t\cdot \left\|\Pi_{N_{\lambda}}\U^{\ell}(s)\right\|^4_{L^4(t_n,t_{n+1};L^4(0,\lambda))}\notag\\
		&\leq N_{\lambda}^2\tau_{\lambda}^2\sum_{n}\left\|\Pi_{N_{\lambda}}\U^{\ell}(s)\right\|^4_{L^4(t_n,t_{n+1};L^4(0,\lambda))}=N_{\lambda}^2\tau_{\lambda}^2\left\|\Pi_{N_{\lambda}}\U^{\ell}(s)\right\|^4_{L^4(\R;L^4(0,\lambda))}\notag\\
		&\lesssim N_{\lambda}^2\tau_{\lambda}^2\left\|\Pi_{N_{\lambda}}\U^{\ell}\right\|^4_{X_{0,\frac{1}{3}}}\lesssim N_{\lambda}^{2-4s}\tau_{\lambda}^2\left\|\U^{\ell}\right\|^4_{X_{s,\frac{1}{2}}}.
	\end{align}
	The estimate for $I_2$ relies on the following rough estimates for any $t^\prime\geq t$ and functions $v, w$,
	\begin{align}\label{eq:rough_estimate}
		&\Big\|\int_{t}^{t^\prime}e^{(s-t)\partial_x^3}\Pi_{N_{\lambda}}\partial_{x}\Big(\Pi_{N_{\lambda}}v(s)\cdot\Pi_{N_{\lambda}}w(s)\Big)\d s\Big\|_{L^2_x}\notag\\
		&\quad \lesssim (t^\prime-t)N_{\lambda}\|\Pi_{N_{\lambda}}v(s)\|_{L^{\infty}(t,t^\prime;L^{4}(0,\lambda))}\|\Pi_{N_{\lambda}}w(s)\|_{L^{\infty}(t,t^\prime;L^4(0,\lambda))}\notag\\
		&\quad\lesssim(t^\prime-t)N_{\lambda}^{\frac{3}{2}}\|\Pi_{N_{\lambda}}v(s)\|_{L^{\infty}(t,t^\prime;L^2(0,\lambda))}\|\Pi_{N_{\lambda}}w(s)\|_{L^{\infty}(t,t^\prime;L^2(0,\lambda))},
	\end{align}
	where we have applied Lemma~\ref{lem:Bernstein} in the above estimates. 
	By using \eqref{eq:rough_estimate}, we obtain
	\begin{align}\label{eq:estimate_I2}
		I_2&\lesssim \sum_{n}\int_{t_n}^{t_{n+1}}\tau_{\lambda}^2 N_{\lambda}^{3}
		\left\| \mathcal{N}_n^\ell(t) \right\|^2_{L^{\infty}(t_n,t_{n+1};L^2(0,\lambda))}
		\cdot \|\Pi_{N_{\lambda}}\U^\ell(t)\|^2_{L^{\infty}(t_n,t_{n+1};L^2(0,\lambda))}\d t\notag\\
		&\lesssim \tau_{\lambda}^2 N_{\lambda}^{3}\sup_{n}
		\left\|\mathcal{N}_n^\ell(t) \right\|^2_{L^{\infty}_t(t_n,t_{n+1};L^2(0,\lambda))}
		\|\Pi_{N_{\lambda}}\U^\ell(t)\|^2_{L^{\infty}_t L^2_x}.
	\end{align}
	To estimate $\mathcal{N}_n^\ell(t)$, we recall the expression $\U^\ell(t_n)=\Gamma(\U^{\ell-1})(t_n)$. 
	Thus, it follows that
	\begin{align*}
		e^{(t_{n}-t)\partial_x^3}\U^\ell(t_n)=\ &\eta(t_n)e^{-t \partial_x^3}\phi_{\lambda}+\frac{1}{2}\eta(t_n)\int_{0}^{t_n}e^{(s-t)\partial_x^3}\eta(s)\Pi_{N_{\lambda}}\partial_{x}\left(\Pi_{N_{\lambda}}\U^{\ell-1}(s)\right)^2\d s\notag\\
		&-\eta(t_n)\int_{0}^{t_n}e^{(s-t)\partial_x^3}\eta(s)\Pi_{N_{\lambda}}\partial_{x}\Big(\Pi_{N_{\lambda}}\F(s,\U^{\ell-1})\Pi_{N_{\lambda}}\U^{\ell-1}(s)\Big)\d s\\
		&+\frac{1}{2}\eta(t_n)\int_{0}^{t_n}e^{(s-t)\partial_x^3}\eta(s)\Pi_{N_{\lambda}}\partial_{x}\left(\Pi_{N_{\lambda}}\F(s,\U^{\ell-1})\right)^2\d s.
	\end{align*}
	By subtracting the above equation from $\U^{\ell}(t)=\Gamma(\U^{\ell-1})(t)$ for $t\in[t_n,t_{n+1}]$, we derive
	\begin{align}\label{eq:estimate_um}
		\mathcal{N}_n^\ell(t)
		& =\left[\eta(t)-\eta(t_n)\right]e^{-t \partial_x^3}\Pi_{N_{\lambda}}\phi_{\lambda}\notag\\
		&\quad+\frac{1}{2}\left[\eta(t)-\eta(t_n)\right]\int_{0}^{t_n}e^{(s-t)\partial_x^3}\eta(s)\Pi_{N_{\lambda}}\partial_{x}\left(\Pi_{N_{\lambda}}\U^{\ell-1}(s)\right)^2\d s\notag\\
		&\quad-\left[\eta(t)-\eta(t_n)\right]\int_{0}^{t_n}e^{(s-t)\partial_x^3}\eta(s)\Pi_{N_{\lambda}}\partial_{x}\Big(\Pi_{N_{\lambda}}\F(s,\U^{\ell-1})\Pi_{N_{\lambda}}\U^{\ell-1}(s)\Big)\d s\notag\\
		&\quad+\frac{1}{2}\left[\eta(t)-\eta(t_n)\right]\int_{0}^{t_n}e^{(s-t)\partial_x^3}\eta(s)\Pi_{N_{\lambda}}\partial_{x}\left(\Pi_{N_{\lambda}}\F(s,\U^{\ell-1})\right)^2\d s\notag\\
		&\quad+\frac{1}{2}\eta(t)\int_{t_n}^{t}e^{(s-t)\partial_x^3}\eta(s)\Pi_{N_{\lambda}}\partial_{x}\left(\Pi_{N_{\lambda}}\U^{\ell-1}(s)\right)^2\d s\notag\\
		&\quad-\eta(t)\int_{t_n}^{t}e^{(s-t)\partial_x^3}\eta(s)\Pi_{N_{\lambda}}\partial_{x}\Big(\Pi_{N_{\lambda}}\F(s,\U^{\ell-1})\Pi_{N_{\lambda}}\U^{\ell-1}(s)\Big)\d s\notag\\
		&\quad+\frac{1}{2}\eta(t)\int_{t_n}^{t}e^{(s-t)\partial_x^3}\eta(s)\Pi_{N_{\lambda}}\partial_{x}\left(\Pi_{N_{\lambda}}\F(s,\U^{\ell-1})\right)^2\d s.
	\end{align}
	Noting that $|\eta(t)-\eta(t_n)|\lesssim (|\eta(t)|+|\eta(t_n)|)^{\frac{2}{3}}|\eta(t)-\eta(t_n)|^{\frac{1}{3}}\lesssim \tau^{\frac{1}{3}}_{\lambda}$, we obtain the estimate
	\begin{align*}
		\big\|\left[\eta(t)-\eta(t_n)\right]e^{-t \partial_x^3}\Pi_{N_{\lambda}}\phi_{\lambda}\big\|_{L^2_x}\lesssim \tau^{\frac{1}{3}}_{\lambda}N_{\lambda}^{-s}\|\phi_{\lambda}\|_{H^s}.
	\end{align*}
	For the remaining terms on the right-hand side of \eqref{eq:estimate_um}, since $t,t_n\lesssim 1$, whenever $\eta(t),\eta(t_n)\neq 0$, we use the estimate $|\eta(t)-\eta(t_n)|\lesssim\tau_{\lambda}$ and  apply the inequality \eqref{eq:rough_estimate} repeatedly. This gives
	\begin{align}\label{eq:u-eu}
		\left\|\mathcal{N}_n^{\ell}(t)\right\|_{L^2_x}
		&\lesssim \tau^{\frac{1}{3}}_{\lambda}N_{\lambda}^{-s}\|\phi_{\lambda}\|_{H^s}+\tau_{\lambda}N_{\lambda}^{\frac{3}{2}}\|\Pi_{N_{\lambda}}\U^{\ell-1}\|^2_{L^\infty_t L^2_x}+\tau_{\lambda}N_{\lambda}^{\frac{3}{2}}\|\Pi_{N_{\lambda}}\F(t,\U^{\ell-1})\|^2_{L^\infty_t L^2_x}\notag\\
		&\lesssim \tau^{\frac{1}{3}}_{\lambda}N_{\lambda}^{-s}\|\phi_{\lambda}\|_{H^s}+\tau_{\lambda}N_{\lambda}^{\frac{3}{2}}\|\Pi_{N_{\lambda}}\U^{\ell-1}\|^2_{L^\infty_t L^2_x}+\Big(\tau_{\lambda}N_{\lambda}^{\frac{3}{2}}\Big)^3\|\Pi_{N_{\lambda}}\U^{\ell-1}\|^4_{L^\infty_t L^2_x},
	\end{align}
	for all $t\in[t_n,t_{n+1}]$, where we have used \eqref{eq:rough_estimate} for $\|\Pi_{N_{\lambda}}\F(t,\U^{\ell-1})\|_{L^\infty_t L^2_x}$ in the last inequality. Substituting \eqref{eq:u-eu} into \eqref{eq:estimate_I2} and applying Lemma~\ref{lem:embedding_Ys} and Lemma~\ref{lem:Bernstein}, 
	we derive
	\begin{align}\label{eq:I_2}
		I_2&\lesssim  \tau_{\lambda}^{\frac{8}{3}} N_{\lambda}^{3-2s}\|\phi_{\lambda}\|_{H^s}^2\|\Pi_{N_{\lambda}}\U^{\ell-1}\|^2_{L^\infty_t L^2_x}+\left(\tau_{\lambda}^2 N_{\lambda}^{3}\right)^2 \|\Pi_{N_{\lambda}}\U^{\ell-1}\|^6_{L^\infty_t L^2_x}\notag\\
		&\quad+\left(\tau_{\lambda}^2 N_{\lambda}^{3}\right)^4 \|\Pi_{N_{\lambda}}\U^{\ell-1}\|^{10}_{L^\infty_t L^2_x}\notag\\
		&\lesssim \tau_{\lambda}^{\frac{8}{3}} N_{\lambda}^{3-4s}\|\phi_{\lambda}\|_{H^s}^2\|\U^{\ell-1}\|^2_{Y^s}+\left(\tau_{\lambda}^2 N_{\lambda}^{3}\right)^2 N_{\lambda}^{-6s}\|\U^{\ell-1}\|^6_{Y^s}+\left(\tau_{\lambda}^2 N_{\lambda}^{3}\right)^4 N_{\lambda}^{-10s} \|\U^{\ell-1}\|^{10}_{Y^s}.
	\end{align}
	%	where we have used Lemma~\ref{lem:embedding_Ys} and Lemma~\ref{lem:Bernstein} in the last inequality.
	Similarly, for $I_3$, we  use the inequalities \eqref{eq:rough_estimate} and \eqref{eq:u-eu} to obtain
	\begin{align}\label{eq:I_3}
		I_3&\lesssim \tau_{\lambda}^2 N_{\lambda}^{3}
		\big(\sup_{n}
		\left\|\mathcal{N}_n^\ell(t)\right\|^2_{L^{\infty}_t(t_n,t_{n+1};L^2(0,\lambda))}\big)^2\notag\\
		&\lesssim \tau_{\lambda}^{\frac{10}{3}} N_{\lambda}^{3-4s}\|\phi_{\lambda}\|_{H^s}^4+\left(\tau_{\lambda}^2 N_{\lambda}^{3}\right)^3 N_{\lambda}^{-8s}\|\U^{\ell-1}\|^8_{Y^s}+\left(\tau_{\lambda}^2 N_{\lambda}^{3}\right)^7 N_{\lambda}^{-16s}\|\U^{\ell-1}\|^{16}_{Y^s}.
	\end{align}
	Now, substituting \eqref{eq:I_1}, \eqref{eq:I_2} and \eqref{eq:I_3} into \eqref{eq:F_L2L2}, 
	we derive the following estimate:
	\begin{align}\label{eq:F_L2L2_new}
		\left\|\eta(t)\Pi_{N_{\lambda}}\F(t,\U^\ell)\right\|_{L^2_t L^2_x}
		%\lesssim I_1^{\frac{1}{2}}+I_2^{\frac{1}{2}}+I_3^{\frac{1}{2}}\notag\\
		& \lesssim \tau_{\lambda}N_{\lambda}^{1-2s}\left\|\U^{\ell}\right\|^2_{X_{s,\frac{1}{2}}}+\tau_{\lambda}^\frac{4}{3} N_{\lambda}^{\frac{3}{2}-2s}\|\phi_{\lambda}\|_{H^s}\|\U^{\ell-1}\|_{Y^s}\notag\\
		&\quad+\tau_{\lambda}^{\frac{5}{3}} N_{\lambda}^{\frac{3}{2}-2s}\|\phi_{\lambda}\|_{H^s}^2+\sum_{j=2}^{7}\tau_{\lambda}^{j}N_{\lambda}^{[\frac{3j}{2}-(j+1)s]}\|\U^{\ell-1}\|^{j+1}_{Y^s}.
	\end{align}
	Combining \eqref{eq:A_1} with the inequality $\|\U^{\ell}\|_{X_{s,\frac{1}{2}}}\leq \|\U^\ell\|_{Y^s}$ leads to the estimate for $ \mathcal{A}_1(\U^\ell)$:
	\begin{align}\label{eq:A_1_Ys}
		\|\mathcal{A}_1(\U^\ell)\|_{Y^s}
		&\lesssim \tau_{\lambda}N_{\lambda}^{2-2s}\left\|\U^{\ell}\right\|^3_{Y^s}+\tau_{\lambda}^\frac{4}{3} N_{\lambda}^{\frac{5}{2}-2s}\|\phi_{\lambda}\|_{H^s}\|\U^{\ell-1}\|_{Y^s}\left\|\U^{\ell}\right\|_{Y^s}\notag\\
		&\quad+\tau_{\lambda}^\frac{5}{3} N_{\lambda}^{\frac{5}{2}-2s}\|\phi_{\lambda}\|_{H^s}^2\left\|\U^{\ell}\right\|_{Y^s}+\sum_{j=2}^{7}\tau_{\lambda}^{j}N_{\lambda}^{[1+\frac{3j}{2}-(j+1)s]}\|\U^{\ell-1}\|^{j+1}_{Y^s}\left\|\U^{\ell}\right\|_{Y^s}\notag\\
		& =:\mathcal{C}\left(s,\tau_{\lambda},N_{\lambda},\left\|\U^{\ell}\right\|_{Y^s},\|\U^{\ell-1}\|_{Y^s}\right).
	\end{align}

	{\sc Estimate of $\|\mathcal{A}_2(\U^\ell)\|_{Y^s}$:} We estimate $\|\mathcal{A}_2(\U^\ell)\|_{Y^s}$ using the same approach as in \eqref{eq:estimate_A_1}. Specifically, we have
	\begin{align}\label{eq:A_2}
		\|\mathcal{A}_2(\U^\ell)\|_{Y^s}
		&\lesssim N_{\lambda}^{1+s}
		\big\|\eta^{\frac{1}{2}}(t)\Pi_{N_{\lambda}}\F(t,\U^\ell)\big\|_{L^2_t L^2_x}
		\big\|\eta^{\frac{1}{2}}(t)\Pi_{N_{\lambda}}\F(t,\U^\ell)\big\|_{L^4_t L^4_x}.
	\end{align}
	Using the scaling invariance of the Sobolev inequality and the fact that the support of $\eta$ is contained within the interval $[-2,2]$, we obtain the following estimate:
	\begin{align*}
		\left\|\eta^{\frac{1}{2}}(t)\Pi_{N_{\lambda}}\F(t,\U^\ell)\right\|_{L^4_t L^4_x}\lesssim \left\|\Pi_{N_{\lambda}}\F(t,\U^\ell)\right\|_{L^\infty_t L^4_x}\lesssim \left\|\Pi_{N_{\lambda}}\F(t,\U^\ell)\right\|_{L^\infty_t H^{\frac{1}{4}}_x}.
	\end{align*}
	Thus, applying Bernstein's inequality and using the estimate \eqref{eq:rough_estimate}, we obtain
	\begin{align}\label{eq:F_L4L4}
		\left\|\eta^{\frac{1}{2}}(t)\Pi_{N_{\lambda}}\F(t,\U^\ell)\right\|_{L^4_t L^4_x}\lesssim N_{\lambda}^{\frac{1}{4}}\tau_{\lambda}N_{\lambda}^{\frac{3}{2}}\left\|\Pi_{N_{\lambda}} \U^{\ell}\right\|^2_{L_{t}^{\infty}L_{x}^2}\lesssim \tau_{\lambda}N_{\lambda}^{\frac{7}{4}-2s}\left\| \U^{\ell}\right\|^2_{Y^s}.
	\end{align}
	Combining this result with \eqref{eq:F_L2L2_new} and \eqref{eq:A_2} yields the following estimate
	\begin{align}\label{eq:A_2_Ys}
		&\|\mathcal{A}_2(\U^\ell)\|_{Y^s}\lesssim \tau_{\lambda}N_{\lambda}^{\frac{7}{4}-s}\left\|\U^{\ell}\right\|_{Y^s}\cdot \mathcal{C}\left(s,\tau_{\lambda},N_{\lambda},\left\|\U^{\ell}\right\|_{Y^s},\|\U^{\ell-1}\|_{Y^s}\right),
	\end{align}
	where $\mathcal{C}\left(s,\tau_{\lambda},N_{\lambda},\left\|\U^{\ell}\right\|_{Y^s},\|\U^{\ell-1}\|_{Y^s}\right)$ is a function defined by \eqref{eq:A_1_Ys}.

	By substituting \eqref{eq:A_1_Ys} and \eqref{eq:A_2_Ys} into \eqref{eq:u_mp1}, we get the estimate for $\|\U^{\ell+1}\|_{Y^s}$ as follows
	\begin{align}\label{eq:u_mp1_Ys}
		\|\U^{\ell+1}\|_{Y^s}\leq& C_0\|\phi_{\lambda}\|_{H^s}+C\lambda^{0+}\left\|\U^\ell\right\|^2_{X_{s,\frac{1}{2}}}\notag\\
		&+C\Big(1+\tau_{\lambda}N_{\lambda}^{\frac{7}{4}-s}\left\|\U^{\ell}\right\|_{Y^s}\Big)\mathcal{C}\left(s,\tau_{\lambda},N_{\lambda},\left\|\U^{\ell}\right\|_{Y^s},\|\U^{\ell-1}\|_{Y^s}\right).
	\end{align}
	Next, we apply the inductive hypothesis $\|\U^\ell\|_{Y^s},\|\U^{\ell-1}\|_{Y^s}\leq C^{\#}\|\phi_{\lambda}\|_{H^s}$ along with relations $\|\phi_{\lambda}\|_{H^s}\leq\lambda^{-\frac{3}{2}-s}\|\phi\|_{H^s}$, $\tau_{\lambda}=\lambda^3\tau$ and $N_{\lambda}=\lambda^{-1}N$ to obtain the following estimates:
	\begin{align}
		\lambda^{0+}\left\|\U^\ell\right\|^2_{X_{s,\frac{1}{2}}}&\leq \left[(C^{\#})^2\lambda^{-\frac{3}{2}-s+}\|\phi\|_{H^s}\right]\cdot\|\phi_{\lambda}\|_{H^s},\label{eq:bound_constant_1}\\
		\tau_{\lambda}N_{\lambda}^{\frac{7}{4}-s}\left\|\U^{\ell}\right\|_{Y^s}&\leq \left[C^{\#}\lambda^{-\frac{1}{4}}\tau N^{\frac{7}{4}-s}\right]\cdot\|\phi\|_{H^s},\label{eq:bound_constant_2}
	\end{align}
	and
	\begin{align}\label{eq:bound_constant_3}
		&\mathcal{C}\left(s,\tau_{\lambda},N_{\lambda},\left\|\U^{\ell}\right\|_{Y^s},\|\U^{\ell-1}\|_{Y^s}\right)\notag\\
		&\leq (C^{\#})^3 \|\phi_{\lambda}\|_{H^s} 
		\Big[\lambda^{-2}\tau N^{2-2s}\|\phi\|_{H^s}^2 
		+ \lambda^{-\frac{3}{2}}\tau^{\frac{4}{3}} N^{\frac{5}{2}-2s}\|\phi\|^2_{H^s}\notag\\
		&\quad+\lambda^{-\frac{1}{2}}\tau^{\frac{5}{3}} N^{\frac{5}{2}-2s}\|\phi\|^2_{H^s}
		+\sum_{j=2}^{7} \lambda^{-\frac{5}{2}}\tau^{j}N^{[1+\frac{3j}{2}-(j+1)s]}\|\phi\|^{j+1}_{H^s}\Big].
	\end{align} 
	It is easy to observe that the coefficients of term $\|\phi_{\lambda}\|_{H^s}$ in the inequalities \eqref{eq:bound_constant_1}--\eqref{eq:bound_constant_3} all contain negative powers of the scaling constant $\lambda$. Moreover, under condition $N\lesssim \tau^{-\frac{1}{2-2s}}$ for $s\in(-\frac{1}{2},0]$, the following boundedness property holds:
	\begin{align*}
		\max \left\{\tau N^{\frac{7}{4}-s},\; \tau N^{2-2s},\; \tau^{\frac{4}{3}} N^{\frac{5}{2}-2s}, \;\tau^{\frac{5}{3}} N^{\frac{5}{2}-2s}\|\phi\|^2_{H^s},\; \max_{j\in\{2,\cdots,7\}}\tau^{j}N^{[1+\frac{3j}{2}-(j+1)s]}\right\}\lesssim 1.
	\end{align*}
	Thus, by combining \eqref{eq:u_mp1_Ys},  there exists a constant 
	$\lambda_0>1$ independent of $\tau$ and $N$ but possibly dependent on $\|\phi\|_{H^s}$ such that for $\lambda\geq \lambda_0$,   the following estimate holds:
	\begin{align}
		\|\U^{\ell+1}\|_{Y^s}\leq2C_0 \|\phi_{\lambda}\|_{H^s}=C^{\#}\|\phi_{\lambda}\|_{H^s}.
	\end{align}
	Thus, by induction, we have proven the conclusion of Lemma~\ref{lem:boundedness_um}.
\end{proof}

