\section{Proofs of the main theoretical results}


\subsection{Notation}


It will be convenient to switch from indexing rows by sets $S\subset 2^{[d]}\setminus \{[d],\emptyset\}$ and instead index by integers $i\in [2^d-2]$.
Given $d \in \mathbb{N}$, we fix an ordering of the subsets of $[d]$ according to the size of the subset. 
Subsets of the same size are ordered in any fixed way (since the sampling probabilities of all distributions we consider only depends on the subset size).
We then identify $i \in [2^d - 2]$ to integers $(h, l)$ satisfying $h \in [d - 1]$, $l \in [\binom{d}{h}]$ by
\begin{equation}
    i = \sum_{j = 1}^{h - 1} \binom{d}{j} + l.
\end{equation}
Unless mentioned otherwise, $\bm{e}_1, \dotsc, \bm{e}_q$ are the standard basis vectors for $\mathbb{R}^q$.
$\bm{0}$ and $\bm{1}$ are the vectors of all zeros and ones, respectively, while $\bm{I}$ is the identity matrix.
$\norm{\cdot}$ denotes the Euclidean norm for vectors, while the spectral norm for matrices.
$\norm{\cdot}_\F$ denotes the Frobenius norm.
Given a matrix $\bm{A}$, $\bm{A}^+$ denotes its Moore-Penrose pseudoinverse.
Finally, given a matrix $\bm{U}$ with orthonormal columns, we write $\bm{P}_{\bm{U}} = \bm{I} - \bm{U} \bm{U}^\T$.

\subsection{Proofs from Randomized Numerical Linear Algebra}
\label{sec:RNLA_proofs}

In this section, we provide bounds for approximate matrix-multiplication and sketched regression. 
Our proofs follow standard techniques in randomized numerical linear algebra \cite{woodruff2014sketching,Martinsson2020,Tropp2015}, and are included to illustrate core concepts which may provide a useful starting point for proving theoretical guarantees for more complicated sketching distributions for Shapley value estimation.
For simplicity, we analyze the simpler case that $\bm{S}$ has independent rows; i.e. that 
\begin{equation}\label{eqn:S_theory_def}
    \bm{S} = \frac{1}{\sqrt{m}} \sum_{j=1}^{m} \frac{1}{\sqrt{p_{I_j}}} \bm{e}_j (\bm{e}_{I_j})^\T,
\end{equation}
where $I_1, \ldots, I_m$ are iid copies of a random variable $I$ for which $\mathbb{P}[I=k] = p_k$, $k \in [r]$ for some fixed $r \in \mathbb{N}$.

Proofs for sampling without replacement, which follow a similar strategy, are described in \cref{app:samp_noreplace}.

\subsubsection{Approximate Matrix Multiplication}
We begin with a simple bound on approximate matrix multiplication.
This bound immediately gives provable guarantees for the Shapley estimator $\bm{\phi}^{\textup{M}}$ defined in \cref{sec:estimator_def}.

\begin{theorem}[Matrix multiplication]
    \label{thm:matvec_samp_replace}
    Let $\bm{U}\in\mathbb{R}^{r\times q}$ and $\bm{z}\in\mathbb{R}^r$. 
    Let $\bm{S}$ be a $m\times r$ sketching matrix with iid rows drawn according to probability $\mathcal{P}$.
    Then, if
    \begin{equation*}
        m\geq \paren*{ \gamma(\bm{z}) - \norm*{\bm{U}^\T \bm{z}}^2} \frac{1}{\delta \varepsilon^2}
    \end{equation*}
    it holds that
    \begin{equation*}
        \mathbb{P}\brak*{\norm*{ \bm{U}^\T\bm{S}^\T\bm{S}\bm{z} - \bm{U}^\T\bm{z} }
        \leq \varepsilon }
        \geq 1- \delta.
    \end{equation*}
\end{theorem}
\begin{proof}
    Let $I_1, \dotsc, I_m$ denote $m$ iid random variables that sample indices from $[r]$ according to probability $\mathcal{P}$.
    Let $\bm{u}_1, \dotsc, \bm{u}_r$ be the columns of $\bm{U}^\T$, and define $\bm{X}_j = \bm{u}_{I_j} z_{I_j}/p_{I_j}$ for $j \in [m]$.
    Then, $\bm{X}_j$ are iid $d$-dimensional random vectors.
    It can be verified that $\mathbb{E}[\bm{X}_j] = \bm{U}^\T \bm{z}$ for all $j \in [m]$.
    Next, we calculate the variance of the random vector $\bm{X}_j$ for $j \in [m]$.
    Using \cref{eqn:gamma_eta_def}, observe that
    \begin{equation}
        \mathbb{E}\brak*{\norm*{\bm{X}_j}^2} = \sum_{i = 1}^r p_i \frac{\norm*{\bm{u}_i}^2}{p_i^2} z_i^2
        = \gamma(\bm{z}),
    \end{equation}
    so that $\operatorname{var}(\bm{X}_j) = \mathbb{E}[\norm*{\bm{X}_j - \mathbb{E}[\bm{X}_j]}^2] = \gamma(\bm{z}) - \norm*{\bm{U}^\T \bm{z}}^2$ for all $j \in [m]$.
    Since $\bm{X}_1, \dotsc, \bm{X}_m$ are independent and $(1/m) \sum_{i = 1}^m \bm{X}_i = \bm{U}^\T \bm{S}^\T \bm{S} \bm{z}$, we have
    \begin{equation}
    \mathbb{E}\brak*{ \norm{\bm{U}^\T\bm{S}^\T\bm{S}\bm{z}- \bm{U}^\T\bm{z} }^2 }
    =
    \mathbb{E}\brak*{\norm*{\frac{1}{m} \sum_{j = 1}^m \bm{X}_j - \mathbb{E}[\bm{X}_j]}^2}
        = \frac{1}{m} \operatorname{var}(\bm{X}_1). \label{eqn:matmult_replace_var}
    \end{equation}
    Then, using the bound on $m$, the result follows by Markov's inequality.
\end{proof}

\subsubsection{Subspace Embedding}

Before we prove a bound for the sketched regression $\bm{\phi}^{\textup{R}}$ from \cref{sec:estimator_def}, we prove a subspace embedding guarantee.

We begin by recalling the following well-known matrix concentration inequality; see e.g., \cite[Theorem 6.6.1]{Tropp2015}.
\begin{imptheorem}[Matrix Bernstein's inequality]
    \label{thm:matrix_Bernstein}
    Let $\bm{X}_1, \dotsc, \bm{X}_m$ be zero-mean, independent, $q\times q$ Hermitian random matrices.
    Then, if $\norm*{\bm{X}_i}\leq L$ for all $i \in [m]$, we have
    \begin{equation}
        \mathbb{P}\brak*{\norm*{\sum_{i = 1}^m \bm{X}_i} \geq \varepsilon} \leq q \exp\paren*{-\frac{\varepsilon^2}{2 \norm*{\sum_{i = 1}^m \mathbb{E}[\bm{X}_i^2]} + (2 L / 3) \varepsilon}}.
    \end{equation}
    In particular, denoting $\bm{X} = m^{-1}\sum_{i = 1}^m \bm{X}_i$ and $\norm*{\sum_{i = 1}^m \mathbb{E}[\bm{X}_i^2]} = m \sigma^2$, if
    \begin{equation*}
        m \geq \paren*{\frac{2 \sigma^2}{\varepsilon^2} + \frac{2 L}{3 \varepsilon}} \log\paren*{\frac{q}{\delta}},
    \end{equation*}
    it holds that $\mathbb{P}[\norm*{\bm{X}} \leq \varepsilon] \geq 1 - \delta$.
\end{imptheorem}

By subsampling sufficiently many rows/columns of a matrix, we can obtain an appropriate subspace embedding guarantee.
\begin{theorem}[Subspace embedding]
\label{thm:subspace_embedding}
Given an $r \times d$ matrix $\bm{U}$, let $\bm{u}_1, \dotsc, \bm{u}_r \in \mathbb{R}^d$ denote the columns of $\bm{U}^\T$.
Let $\bm{S}$ be a $m\times r$ sketching matrix with iid rows drawn according to probability $\mathcal{P}$.
Then, if
\begin{equation*}
    m \geq \frac{2}{\varepsilon^2} \norm*{\sum_{i = 1}^r  \frac{\norm*{\bm{u}_i}^2}{p_i}\bm{u}_i \bm{u}_i^\T - (\bm{U}^\T \bm{U})^2} \log\paren*{\frac{d}{\delta}}
            + \frac{4}{3 \varepsilon} \max_{i \in [r]} \frac{\norm*{\bm{u}_i}^2}{p_i} \log\paren*{\frac{d}{\delta}}
\end{equation*}
it holds that
\begin{equation*}
    \mathbb{P}\brak*{ \norm*{\bm{U}^\T \bm{S}^\T \bm{S} \bm{U} - \bm{U}^\T \bm{U}} \leq \varepsilon } \geq 1-\delta.
\end{equation*}
\end{theorem}

\begin{proof}
    First, we write $\bm{U}^\T = (\bm{u}_1 \dotsm \bm{u}_r)$, where $\bm{u}_i \in \mathbb{R}^d$ is the $i$th column of $\bm{U}^\T$ for $i \in [r]$.
    Then, $\bm{U}^\T \bm{U} = \sum_{i = 1}^r \bm{u}_i \bm{u}_i^\T$.
    Similarly, it can be verified that $\bm{U}^\T \bm{S}^\T \bm{S} \bm{U} = \sum_{i = 1}^m \bm{u}_{I_i} \bm{u}_{I_i}^\T / (m p_{I_i})$, where $I_1, \dotsc, I_m$ are the random variables defining the sketching matrix.
    It follows that $\mathbb{E}[\bm{U}^\T \bm{S}^\T \bm{S} \bm{U}] = \bm{U}^\T \bm{U}$.
    For convenience, define $\bm{X}_i = \bm{u}_{I_i} \bm{u}_{I_i}^\T / p_{I_i} - \bm{U}^\T \bm{U}$ for $i \in [m]$ and $\bm{X} = \sum_{i = 1}^m \bm{X}_i / m$.
    Then, for all $i \in [m]$, we have
    \begin{equation}
        \norm*{\bm{u}_{I_i} \bm{u}_{I_i}^\T / p_{I_i}} \leq \max_{k \in [r]} \frac{\norm*{\bm{u}_k}^2}{p_k} =: L.
    \end{equation}
    It follows from triangle inequality and Jensen's inequality that $\norm*{\bm{X}_i} \leq 2 L$ for all $i \in [m]$.
    Furthermore, using the fact that $\bm{X}_1, \dotsc, \bm{X}_m$ are iid with zero mean, and symmetric, we have
    \begin{equation}
        \sum_{i = 1}^m \mathbb{E}\brak*{\bm{X}_i^2} 
        = m \mathbb{E}[\bm{X}_1^2] \\
        = m \paren*{\sum_{i = 1}^r \norm*{\bm{u}_i}^2 \frac{\bm{u}_i \bm{u}_i^\T}{p_i} - (\bm{U}^\T \bm{U})^2}.
    \end{equation}
    Writing $\sum_{i = 1}^m \mathbb{E}\brak*{\bm{X}_i^2} = m \sigma^2$, we have
    \begin{equation}
        \sigma^2 = \norm*{\sum_{i = 1}^r \norm*{\bm{u}_i}^2 \frac{\bm{u}_i \bm{u}_i^\T}{p_i} - (\bm{U}^\T \bm{U})^2}. \label{eqn:subspace_embed_replace_var}
    \end{equation}
    The result then follows from \cref{thm:matrix_Bernstein}.
\end{proof}

\subsubsection{Sketched Regression}
Together, \cref{thm:matvec_samp_replace,thm:subspace_embedding} give a bound on sketched regression. 
\begin{theorem}[Sketched Regression]\label{thm:sketched_regression}
Suppose $\bm{U}$ has orthonormal columns and let $\bm{y}^* = \argmin_{\bm{y}}\norm*{\bm{U}\bm{y} - \bm{b}}^2$.
Let $\bm{S}$ be a $m\times q$ sketching matrix with iid rows drawn according to probability $\mathcal{P}$.
Define
\begin{equation}
    \widehat{\bm{y}} = \argmin_{\bm{y}}\norm{\bm{S}\bm{U}\bm{y} - \bm{S}\bm{b}}^2.
\end{equation}
Then, if 
\begin{equation*}
\begin{aligned}
    m = O\paren*{ \frac{\gamma((\bm{I} - \bm{U}\bm{U}^\T)\bm{b})}{\delta\varepsilon^2} + \eta \log\paren*{\frac{d}{\delta}} },
\end{aligned}
\end{equation*}
it holds that
\begin{equation}
    \mathbb{P}\brak*{ \norm*{\bm{y}^* -  \widehat{\bm{y}}}
    \leq \varepsilon  }
    \geq 1-\delta.
\end{equation}
\end{theorem}

\begin{proof}
    Since $\bm{y}^*$ is the solution of $\min_{\bm{y}} \norm*{\bm{U} \bm{y} - \bm{b}}$, $\bm{U} \bm{y}^* - \bm{b}$ lies in the orthogonal complement of the range of $\bm{U}$, and therefore, $\bm{U}^\T (\bm{U} \bm{y}^* - \bm{b}) = 0$.
    Then, taking $\bm{z} = \bm{U} \bm{y}^* - \bm{b} = (\bm{I} - \bm{U} \bm{U}^\T )\bm{b}$ in \cref{thm:matvec_samp_replace}, we can infer that using
    \begin{equation}
         m
         = O \paren*{ \frac{\gamma(\bm{z})}{\delta\varepsilon^2} }
         \geq \paren*{\sum_{i = 1}^r \frac{\norm*{\bm{u}_i}^2}{p_i} (\bm{e}_i^\T( \bm{I} - \bm{U}\bm{U}^\T)\bm{b})^2 } \frac{8}{\delta \varepsilon^2},
    \end{equation}
    we have with probability exceeding $1-\delta/2$,
    \begin{equation}\label{eqn:MM}
        \norm*{\bm{U}^\T\bm{S}^\T\bm{S} (\bm{U} \bm{y}^* - \bm{b})}  \leq \frac{\varepsilon}{2}.
    \end{equation}

    Next, note that $\eta = \max_i \norm*{u_i}^2/p_i$ so
    \begin{equation}
        \sum_{i = 1}^r \frac{\norm*{\bm{u}_i}^2}{p_i}\bm{u}_i \bm{u}_i^\T
        \preceq
        \eta \sum_{i = 1}^r \bm{u}_i \bm{u}_i^\T
        = \eta \bm{U}^\T \bm{U},
    \end{equation}
    where $\bm{X}\preceq\bm{Y}$ indicates $\bm{Y}-\bm{X}$ is positive semi-definite.
    If $p_i > \norm*{\bm{u}_i}^2$ for all $i \in [r]$, then $1 > \sum_{i = 1}^r \norm*{\bm{u}_i}^2 = \norm*{\bm{U}}_\F^2 = d$ (since $\bm{U}^\T \bm{U} = \bm{I}$), which is a contradiction. Thus, we must have $p_i \leq \norm*{\bm{u}_i}^2$ for some $i \in [r]$, or equivalently, $\eta \geq 1$.
    Then, because $\bm{U}$ has orthonormal columns, we have
    \begin{equation}
        \norm*{\sum_{i = 1}^r \frac{\norm*{\bm{u}_i}^2}{p_i} \bm{u}_i \bm{u}_i^\T - (\bm{U}^\T \bm{U})^2}
        \leq (\eta-1)\norm*{\bm{U}^\T\bm{U}}
        \leq \eta. \label{eqn:subspace_embed_replace_var_bd}
    \end{equation}    
    Therefore, by \cref{thm:subspace_embedding}, if 
    \begin{align}
        m 
        &= O\paren*{ \eta \log\paren*{\frac{d}{\delta}}}
        \\&\geq 8 \norm*{\sum_{i = 1}^r \frac{\norm*{\bm{u}_i}^2}{p_i} \bm{u}_i \bm{u}_i^\T - (\bm{U}^\T \bm{U})^2} \log\paren*{\frac{d}{\delta}}
        + \frac{8}{3} \max_{i \in [r]} \frac{\norm*{\bm{u}_i}^2}{p_i} \log\paren*{\frac{d}{\delta}},
    \end{align}
    then, with probability exceeding $1-\delta/2$,
    \begin{equation}\label{eqn:SE}
        \norm*{ \bm{U}^\T\bm{S}^\T\bm{S}\bm{U} - \bm{I}} \leq 1/2.
    \end{equation}

    For the remainder of the proof, we condition on \cref{eqn:MM,eqn:SE}, which, by a union bound, simultaneously occur with probability exceeding $1-\delta$.

    Using the triangle inequality, submultiplicitivty, and \cref{eqn:SE}, 
    \begin{align}
         \norm*{ \bm{y}^* - \widehat{\bm{y}} }
         & = \norm*{ (\bm{U}^\T\bm{S}^\T\bm{S}\bm{U}) (\bm{y}^* - \widehat{\bm{y}}) + (\bm{I} - (\bm{U}^\T\bm{S}^\T\bm{S}\bm{U})) (\bm{y}^* - \widehat{\bm{y}}) }
         \\& \leq \norm*{ (\bm{U}^\T\bm{S}^\T\bm{S}\bm{U}) (\bm{y}^* - \widehat{\bm{y}}) } + \norm*{ (\bm{I} - (\bm{U}^\T\bm{S}^\T\bm{S}\bm{U}) )(\bm{y}^* - \widehat{\bm{y}}) }
         \\& \leq \norm*{ (\bm{U}^\T\bm{S}^\T\bm{S}\bm{U}) (\bm{y}^* - \widehat{\bm{y}}) } + \norm*{ \bm{I} - (\bm{U}^\T\bm{S}^\T\bm{S}\bm{U}) } \norm*{\bm{y}^* - \widehat{\bm{y}} }
         \\& \leq \norm*{ (\bm{U}^\T\bm{S}^\T\bm{S}\bm{U}) (\bm{y}^* - \widehat{\bm{y}}) } + \frac{1}{2} \norm*{\bm{y}^* - \widehat{\bm{y}} },
    \end{align}
    and hence,
    \begin{equation}
        \norm*{\bm{y}^* - \widehat{\bm{y}} }
        \leq 2 \norm*{ (\bm{U}^\T\bm{S}^\T\bm{S}\bm{U}) (\bm{y}^* - \widehat{\bm{y}}) }.
    \end{equation}

    Next, by the optimality of $\widehat{\bm{y}}$ we have that $(\bm{S}\bm{U})^\T(\bm{S}\bm{U}\bm{\widehat{y}} - \bm{S}\bm{b}) = \bm{0}$ and hence that $(\bm{U}^\T\bm{S}^\T\bm{S}\bm{U}) \widehat{\bm{y}} =\bm{U}^\T\bm{S}^\T\bm{S}\bm{b}$.
    Therefore, by \cref{eqn:MM},
    \begin{equation}
        \norm*{ (\bm{U}^\T\bm{S}^\T\bm{S}\bm{U}) (\bm{y}^* - \widehat{\bm{y}}) } 
        = \norm*{ \bm{U}^\T\bm{S}^\T\bm{S} (\bm{U}\bm{y}^* - \bm{b}) }
        \leq \frac{\varepsilon}{2}. \label{eqn:regression_matvec_term}
    \end{equation}
    Combining the above equations gives the result.
\end{proof}


\subsection{Proofs for Shapley Value Estimators}
\label{sec:our_proofs}

As noted in \cite[Lemma 3.3]{musco2025provably}, the matrix $\bm{Z}'$ nearly has orthonormal columns.
\begin{lemma}
Let  $c_d = {((d-1)H_{d-2} - (d-2))}/{d}$, where $H_{d}$ is the $d^{th}$ harmonic number.
Then,
\begin{equation}
(\bm{Z}')^\T\bm{Z}' = \frac{d-1}{d}\bm{I} + c_d \bm{1}\bm{1}^\T.
\end{equation}
\end{lemma}

\begin{proof}
First, we note that $(\bm{Z}')^\T\bm{Z}' = \bm{Z}^{\T} \bm{W} \bm{Z}$ is a matrix of size $d \times d$. Let $i, j \in \{1, \dots, d\}$. Then it follows from definition that,
\begin{align}
     [\bm{Z}^{\T} \bm{W} \bm{Z}]_{ij} &= \sum_{S: i, j \in S} k(S)
\end{align}
We separately consider the case where $i = j$. From the above,
\begin{align}
    [\bm{Z}^{\T} \bm{W} \bm{Z}]_{ii} 
    &= \sum_{S : i \in S} k(S) \\
    &= \sum_{|S| = 1}^{d-1} \frac{(d - 1)\binom{d-1}{|S|-1}}{\binom{d}{|S|}|S|(d-|S|)} \\
    &= \frac{d-1}{d} \sum_{|S| = 1}^{d-1} \frac{1}{d - |S|} =  \frac{(d-1) H_{d-1}}{d},
\end{align}
Similarly for $i \neq j$, 
\begin{align}
     [\bm{Z}^{\T} \bm{W} \bm{Z}]_{ij} 
     &= \sum_{S : i, j \in S} k(S) \\
    &= \sum_{|S| = 2}^{d-1} \frac{(d - 1)\binom{d-2}{|S|-2}}{\binom{d}{|S|}|S|(d-|S|)} \\
    &= \frac{1}{d}\sum_{|S| = 2}^{d} \frac{|S| - 1 }{d - |S|} = \frac{1}{d}\sum_{|S| = 2}^{d} \frac{d - 1 }{d - |S|} - 1\\
    &= \frac{(d-1)H_{d-2} - (d-2)}{d}.
\end{align}

Define $\bm{1}$ as the all ones vector in $\mathbb{R}^d$ and $\bm{I}$ as the identity matrix of size $d \times d$. The matrix $\bm{Z}^{\T} \bm{W} \bm{Z}$ can then be written as
\begin{align}
    \bm{Z}^{\T} \bm{W} \bm{Z} = \frac{d-1}{d}\bm{I} + \frac{(d-1)H_{d-2} - (d-2)}{d} \bm{1}\bm{1}^{\T},
    \label{eq:z-transpose-w-z}
\end{align}
which is the desired result.
\end{proof}

Next, we describe the conversion from the constrained problem \cref{eqn:shapley_constrained} to an unconstrained problem.
Our approach is closely related to \cite[Lemma 3.1]{musco2025provably}.
However, as noted in \cref{sec:unified}, our approach allows arbitrary $\lambda$ (where as \cite{musco2025provably} only allows $\lambda=\alpha$).
In addition, on a more technical note, we state our results in terms of the argmin of a regression problem involving a full-rank matrix $\bm{U}$.
The result of \cite{musco2025provably} is stated in terms of the argmin of a regression problem involving rank-deficient matrix, which is not uniquely defined.
As such, their result implicitly assumes that the argmin returns one particular solution (the minimum norm solution); see \cref{sec:LeverageSHAP_full}.


\begin{proof}[\textbf{Proof of \cref{thm:shapley_regression}}]
Next, using that $\bm{Q}^\T\bm{1} = \bm{0}$ and that $\bm{Q}^\T\bm{Q} = \bm{I}$,
\begin{equation}
    \bm{U}^\T\bm{U} 
    = \frac{d}{d-1} \bm{Q}^\T (\bm{Z}')^\T\bm{Z}' \bm{Q}
    = \frac{d}{d-1} \bm{Q}^\T \paren*{\frac{d-1}{d}\bm{I} + c_d \bm{1}\bm{1}^\T} \bm{Q}
    = \bm{I}.
\end{equation}   
Therefore $(\bm{U}^\T\bm{U})^{-1}\bm{U}^\T = \bm{U}^\T$ and so $\bm{Q}\argmin_{\bm{x}\in\mathbb{R}^{d-1}} \norm*{\bm{U} \bm{x} - \bm{b}_{\lambda}}^2 +  \alpha\bm{1} 
= \bm{Q} \bm{U}^\T \bm{b}_{\lambda} + \alpha\bm{1}$.

It remains to show these formulations are equivalent to \cref{eqn:shapley_constrained}.
Since $\bm{Q}^\T\bm{1}=\bm{0}$ and $\bm{1}^\T\bm{1} = d$, observe that
\begin{equation}
    \{ \bm{\phi}  : \bm{\phi}\in\mathbb{R}^d, \bm{1}^\T\bm{\phi} = v([d]) - v(\emptyset) \}
    = \{ \bm{Q}\bm{x} + \alpha \bm{1} : \bm{x}\in\mathbb{R}^{d-1} \},
\end{equation}
with the natural bijection $\bm{\phi} \leftrightarrow \bm{Q}\bm{x} + \alpha \bm{1}$ between $\bm{\phi}$ and $\bm{x}$.
Thus, using the definitions of $\bm{U}$ and $\bm{b}_\alpha$,
\begin{align}
    \bm{\phi}^*
    &= \argmin_{\substack{\bm{\phi}\in\mathbb{R}^d\\\bm{1}^\T \bm{\phi} = v([d]) - v(\emptyset)}} \norm*{ \bm{Z}' \bm{\phi} - \bm{b} }
    \\&= \bm{Q}\argmin_{\bm{x}\in\mathbb{R}^{d-1}} \norm{ \bm{Z}' (\bm{Q}\bm{x} + \alpha\bm{1}) - \bm{b} }^2 +  \alpha\bm{1} 
    \\&= \bm{Q}\argmin_{\bm{x}\in\mathbb{R}^{d-1}} \norm{ \bm{U} \bm{x} - \bm{b}_\alpha }^2 +  \alpha\bm{1}.
\end{align}
Now, since $\bm{Q}^\T \bm{1} = \bm{0}$,
\begin{equation}
\bm{U}^\T\bm{Z}'\bm{1}
= \bm{Q}^\T (\bm{Z}')^\T \bm{Z}'\bm{1}
= \bm{Q}^\T \paren*{\frac{d-1}{d}\bm{I} + c_d \bm{1}\bm{1}^\T} \bm{1} = \bm{0}.
\end{equation}
Therefore, for any $\lambda$,
\begin{equation}
\label{eqn:UTbp_UTb}
\argmin_{\bm{x}\in\mathbb{R}^{d-1}} \norm{ \bm{U} \bm{x} - \bm{b}_\lambda }
=\argmin_{\bm{x}\in\mathbb{R}^{d-1}} \norm{ \bm{U} \bm{x} - (\bm{b} - \lambda \bm{Z}'\bm{1}) }
=\argmin_{\bm{x}\in\mathbb{R}^{d-1}} \norm{ \bm{U} \bm{x} - \bm{b} }.
\end{equation}
This gives the desired result.
\end{proof}

Finally, we use \cref{thm:shapley_regression} and the bounds from \cref{sec:RNLA_proofs} to prove our main approximation guarantee.

\begin{proof}[Proof of \cref{thm:main}]
We analyze the estimators individually.
Recall from \cref{thm:shapley_regression} that
\begin{equation}
    \bm{\phi}^*
    = \bm{Q}\argmin_{\bm{x}\in\mathbb{R}^{d-1}} \norm{ \bm{U} \bm{x} - \bm{b}_{\lambda} }^2 +  \alpha\bm{1} 
    = \bm{Q} \bm{U}^\T \bm{b}_{\lambda} + \alpha\bm{1}.
\end{equation}
We will use both of these formulations.

\textbf{Regression:}
Observe,
\begin{align*}
    \bm{\phi}_\lambda^{\textup{R}} 
    = \bm{Q}\argmin_{\bm{x}\in\mathbb{R}^{d-1}} \norm*{  \bm{S}(\bm{U}\bm{x}- \bm{b}_\lambda) } + \alpha \bm{1}
    =\bm{Q}(\bm{S}\bm{U})^{+}\bm{S}\bm{b}_\lambda + \alpha\bm{1}.
\end{align*}
Now, since $\bm{Q}^\T\bm{Q} = \bm{I}$,
\begin{equation}
\norm{\bm{\phi}^* - \bm{\phi}_\lambda^{\textup{R}}}
= \norm{ \bm{Q} \bm{U}^\T\bm{b}_\lambda  -  \bm{Q}(\bm{S}\bm{U})^{+} \bm{S}\bm{b}_\lambda }
= \norm{ \bm{U}^\T\bm{b}_\lambda  - (\bm{S}\bm{U})^{+} \bm{S}\bm{b}_\lambda }. \label{eqn:Shapley_regression_replace_error}
\end{equation}
By \cref{thm:sketched_regression}, if
\begin{equation}
    m = O\paren*{ \frac{\gamma(\bm{P}_{\bm{U}}\bm{b}_\lambda)}{\delta\varepsilon^2} + \eta \log\paren*{\frac{d}{\delta}} },
\end{equation}
then
\[
\mathbb{P}\brak*{ \norm{ \bm{U}^\T\bm{b}_\lambda  - (\bm{S}\bm{U})^+\bm{S}\bm{b}_\lambda }^2
\leq \varepsilon } \geq 1-\delta.
\]

\textbf{Matrix Multiplication:}
By definition,
\begin{equation}
    \bm{\phi}_\lambda^{\textup{M}} = \bm{Q}\bm{U}^\T \bm{S}^\T\bm{S}\bm{b}_\lambda + \alpha\bm{1}.
\end{equation}
Then, since $\bm{Q}^\T\bm{Q} = \bm{I}$,
\begin{equation}
    \norm*{\bm{\phi}^* - \bm{\phi}_\lambda^{\textup{M}}}
    = \norm*{\bm{Q}\bm{U}^\T\bm{b}_\lambda - \bm{Q}\bm{U}^\T \bm{S}^\T\bm{S}\bm{b}_\lambda}
    = \norm*{\bm{U}^\T\bm{b}_\lambda - \bm{U}^\T \bm{S}^\T\bm{S}\bm{b}_\lambda}. \label{eqn:Shapley_matmult_replace_error}
\end{equation}
By \cref{thm:matvec_samp_replace}, if 
\begin{equation}
    m = O\paren*{ \frac{\gamma(\bm{b}_\lambda)}{\delta\varepsilon^2} }
    \geq \paren*{\sum_{i = 1}^r \frac{\norm*{\bm{u}_i}^2}{p_i} ((\bm{b}_\lambda)_i)^2 - \norm*{\bm{U}^\T \bm{b}_\lambda}^2} \frac{1}{\delta \varepsilon^2}
\end{equation}
then 
\begin{equation}
    \mathbb{P}\brak*{ \norm*{\bm{U}^\T\bm{b}_\lambda - \bm{U}^\T \bm{S}^\T\bm{S}\bm{b}_\lambda} < \varepsilon } > 1-\delta.
\end{equation}

This establishes the result.
\end{proof}


\subsection{Fine-grained bounds for specific probability distributions}
\label{sec:fine_grained_bounds}

\begin{theorem}
\label{thm:gamma_eta_sampling_schemes}
Map the index $i \in [2^d - 2]$ to integers $(h, l)$ satisfying $h \in [d - 1]$, $l \in [\binom{d}{h}]$, as $i = \sum_{j = 1}^{h - 1} \binom{d}{j} + l$.
Then, we have
\begin{equation}
    \norm*{\bm{u}_i}^2 = \norm*{\bm{u}_{h, l}}^2 = \frac{1}{\binom{d}{h}} \label{eqn:ui_norm}
\end{equation}
for all $l \in [\binom{d}{h}]$ and all $h \in [d - 1]$.
Moreover,
\begin{enumerate}[leftmargin=1em]
    \item ($\bm{\ell_2}$-\textbf{squared}) For $h \in [d - 1]$ and $l \in [\binom{d}{h}]$, we have
    \begin{equation*}
        p_{h, l} = \frac{\norm*{\bm{u}_{h, l}}^2}{\norm*{\bm{U}}_\F^2} = \frac{1}{(d - 1) \binom{d}{h}}, \label{eqn:l2sq_prob}
    \end{equation*}
    \begin{equation*}
        \gamma(\bm{z}) = (d - 1) \norm*{\bm{z}}^2 \qquad \textnormal{ and } \qquad \eta = d - 1. \label{eqn:gamma_eta_l2sq}
    \end{equation*}
    \item (\textbf{Kernel}) For $h \in [d - 1]$ and $l \in [\binom{d}{h}]$, denoting $k(h) = (d - 1) / (\binom{d}{h} (h (d - h)))$ we have
    \begin{equation*}
        p_{h, l} = \frac{k(h)}{\sum_{j = 1}^{d - 1} k(j) \binom{d}{j}}
                 = \frac{1}{\binom{d}{h}} \frac{\frac{1}{h (d - h)}}{\sum_{j = 1}^{d - 1} \frac{1}{j (d - j)}}, \label{eqn:kernel_prob}
    \end{equation*}
    \begin{equation*}
        \gamma(\bm{z}) = \frac{2}{d} \paren*{\sum_{h = 1}^{d - 1} \frac{1}{h}} \sum_{h = 1}^{d - 1} \sum_{l = 1}^{\binom{d}{h}} h (d - h) z_{h, l}^2 \quad \textnormal{ and } \quad \eta \leq \frac{d}{2} \sum_{h = 1}^{d - 1} \frac{1}{h}. \label{eqn:gamma_eta_kernel}
    \end{equation*}
    \item (\textbf{Modified $\ell_2$}) For $h \in [d - 1]$ and $l \in [\binom{d}{h}]$, we have
    \begin{equation*}
        p_{h, l} = \frac{\sqrt{k(h)} \norm*{\bm{u}_{h, l}}}{\sum_{j = 1}^{d - 1} \sum_{l = 1}^{\binom{d}{j}} \sqrt{k(j)} \norm*{\bm{u}_{j, l}}}
                 = \frac{1}{\binom{d}{h}} \frac{\frac{1}{\sqrt{h (d - h)}}}{\sum_{j = 1}^{d - 1} \frac{1}{\sqrt{j (d - j)}}}, \label{eqn:modl2_prob}
    \end{equation*}
    \begin{equation*}
        \gamma(\bm{z}) = \paren*{\sum_{h = 1}^{d - 1} \frac{1}{\sqrt{h (d - h)}}} \sum_{h = 1}^{d - 1} \sum_{l = 1}^{\binom{d}{h}} \sqrt{h (d - h)} z_{h, l}^2 \quad \textnormal{ and } \quad \eta \leq \frac{d}{2} \sum_{h = 1}^{d - 1} \frac{1}{\sqrt{h (d - h)}}. \label{eqn:gamma_eta_modl2}
    \end{equation*}
\end{enumerate}    
\end{theorem}
\begin{proof}
    Denote $r = 2^d - 2$, and let $\bm{e}_1, \dotsc, \bm{e}_r \in \mathbb{R}^d$ be the standard basis vectors. Since $\bm{u}_1, \dotsc, \bm{u}_r$ are the columns of $\bm{U}^\T$, we can write $\bm{u}_i = \bm{U}^\T \bm{e}_i$ for all $i \in [r]$. It follows that
    \begin{equation}
        \norm*{\bm{u}_i}^2 = \bm{e}_i^\T \bm{U} \bm{U}^\T \bm{e}_i = \frac{d}{d - 1} \bm{e}_i^\T \sqrt{\bm{W}} \bm{Z} \bm{P} \bm{Z}^\T \sqrt{\bm{W}} \bm{e}_i. \label{eqn:ui_norm_intermediate}
    \end{equation}
    Now, we map $i$ to $(h, l)$ for appropriate integers $h \in [d - 1]$ and $l \in [\binom{d}{h}]$, so that the subset $S_i \subset [d]$ is of size $h$ (according to the chosen ordering of subsets).
    Then, writing $k(h) = k(S_i)$, we have $\bm{Z}^\T \sqrt{\bm{W}} \bm{e}_{h, l} = \sqrt{k(h)} \bm{Z}^\T \bm{e}_{h, l} = \sqrt{k(h)} \bm{z}_{h, l}$, where $\bm{z}_{h, l}$ is a $d$-dimensional vector with $1$ at entry $j$ if $j \in S_{h, l}$ and $0$ otherwise.
    Substituting this in \cref{eqn:ui_norm_intermediate}, using $\bm{P} = \bm{I} - (1/d) \bm{1} \bm{1}^\T$ and $|S_{h,l}| = \norm*{\bm{z}_{h, l}}_1 = \norm*{\bm{z}_{h, l}}^2 = h$,
    we obtain
    \begin{equation}
    \begin{aligned}
        \norm*{\bm{u}_i}^2 &= \frac{d}{d - 1} k(h) \paren*{\norm*{\bm{z}_{h, l}}^2 - \frac{1}{d} \norm*{\bm{z}_{h, l}}_1^2} \\
                            &= \frac{d}{d - 1} \frac{d - 1}{\binom{d}{h} h (h - d)} \paren*{h - \frac{h^2}{d}} \\
                            &= \frac{1}{\binom{d}{h}}.
    \end{aligned}
    \end{equation}

    1. It can be verified that $\sum_{i = 1}^{2^d - 1} \norm*{\bm{u}_i}^2 = \norm*{\bm{U}_\F}^2 = d - 1$. The result follow from the definition of $p_{h, l}$, and $\gamma$, $\eta$ in \cref{eqn:gamma_eta_def}.

    2. Noting that $k(S)$ depends only on the size of the subset $S \subseteq [d]$, $p_{h, l}$ in \cref{eqn:kernel_prob} is obtained by direct calculation.
    Observe that
    \begin{equation}
        \sum_{h = 1}^{d - 1} \frac{1}{h (d - h)} = \frac{1}{d} \sum_{h = 1}^{d - 1} \paren*{\frac{1}{h} + \frac{1}{d - h}} = \frac{2}{d} \sum_{h = 1}^{d - 1} \frac{1}{h},
    \end{equation}
    and therefore,
    \begin{equation}
    \begin{aligned}
        \frac{\norm*{\bm{u}_{h, l}}^2}{p_{h, l}} &= \paren*{\frac{2}{d} \sum_{h = 1}^{d - 1} \frac{1}{h}} h (d - h),
    \end{aligned}
    \end{equation}
    for $h \in [d - 1]$ and $l \in [\binom{d}{h}]$.
    Since $h (d - h) \leq d^2/4$ for $h \in [d - 1]$, \cref{eqn:gamma_eta_kernel} follows from \cref{eqn:gamma_eta_def} by direct substitution.

    3. We obtain $p_{h, l}$ in \cref{eqn:modl2_prob} by direct substitution.
    Since
    \begin{equation}
        \frac{\norm*{\bm{u}_{h, l}}^2}{p_{h, l}} = \paren*{\sum_{h = 1}^{d - 1} \frac{1}{\sqrt{h (d - h)}}} \sqrt{h (d - h)}
    \end{equation}
    for $h \in [d - 1]$ and $l \in [\binom{d}{h}]$, we obtain \cref{eqn:gamma_eta_modl2}.
\end{proof}

\begin{remark}
    \label{rem:log_factors}
    The sum over $1/h$ in \cref{eqn:gamma_eta_kernel} and over $1/\sqrt{h (d - h)}$ in \cref{eqn:gamma_eta_modl2} only mildly depend on $d$. Indeed,
    \begin{equation}
        \sum_{h = 1}^{d - 1} \frac{1}{h} = \Theta(\log(d)) \qquad \textnormal{ and } \qquad \sum_{h = 1}^{d - 1} \frac{1}{\sqrt{h (d - h)}} = \Theta(1).
    \end{equation}

    This can be seen from the (well-known) bound
    \begin{equation}
        \log(d) = \int_1^d \frac{1}{x} dx \leq \sum_{h = 1}^{d - 1} \frac{1}{h} = 1 + \sum_{h = 2}^{d - 1} \frac{1}{h} \leq 1 + \int_1^{d - 1} \frac{1}{x} dx = 1 + \log(d - 1),
    \end{equation}
    where the approximation with the integral uses the fact that $h \mapsto 1/h$ is a decreasing function.
    Similarly, since $\lceil (d - 1) / 2 \rceil \leq d/2$, we have
    \begin{equation}
    \begin{aligned}
        \sum_{h = 1}^{d - 1} \frac{1}{\sqrt{h (d - h)}} &\leq 2 \sum_{h = 1}^{\lceil (d - 1) / 2 \rceil} \frac{1}{\sqrt{h (d - h)}} \\
        &\leq 2 \paren*{\frac{1}{\sqrt{d - 1}} + \int_1^{d/2} \frac{1}{\sqrt{x (d - x)}} dx} \\
        &= 2 \paren*{\frac{1}{\sqrt{d - 1}} + 2 \arctan(\sqrt{d - 1}) - \frac{\pi}{2}}
        \xrightarrow[d \to \infty]{} \pi,
    \end{aligned}
    \end{equation}
    and since $\lfloor (d - 1) / 2 \rfloor \geq d/2 - 1$, we have
    \begin{equation}
    \begin{aligned}
        \sum_{h = 1}^{d - 1} \frac{1}{\sqrt{h (d - h)}} &\geq 2 \sum_{h = 1}^{\lfloor (d - 1) / 2 \rfloor} \frac{1}{h (d - h)} \\
        &\geq 2 \paren*{\int_1^{d/2} \frac{1}{\sqrt{x (d - x)}} dx} \\
        &= 2 \paren*{2 \arctan(\sqrt{d - 1}) - \frac{\pi}{2}}
        \xrightarrow[d \to \infty]{} \pi.
    \end{aligned}
    \end{equation}
\end{remark}

\cref{thm:gamma_eta_sampling_schemes} allows us to directly compare the values of $\gamma$ for the different sampling strategies we consider.
\begin{corollary}
    \label{cor:gamma_comparison}
    Denote $\gamma_{\ell_2^2}$, $\gamma_{\textnormal{ker}}$, $\gamma_{\textnormal{m-}\ell_2}$ to be the expressions for $\gamma$ for $\ell_2$-squared \cref{eqn:gamma_eta_l2sq}, kernel \cref{eqn:gamma_eta_kernel}, and modified $\ell_2$ \cref{eqn:gamma_eta_modl2} sampling schemes respectively.
    Then, for all $\bm{z} \in \mathbb{R}^{2^d - 2}$, we have
    \begin{align}
        \Theta\paren*{\frac{\log(d)}{d}} &\leq \frac{\gamma_{\textnormal{ker}}(\bm{z})}{\gamma_{\ell_2^2}(\bm{z})} \leq \Theta(\log(d)), \label{eqn:gamma_ker_l2sq} \\
        \Theta\paren*{\frac{1}{\sqrt{d}}} &\leq \frac{\gamma_{\textnormal{m-}\ell_2}(\bm{z})}{\gamma_{\ell_2^2}(\bm{z})} \leq \Theta(1), \label{eqn:gamma_wl2_l2sq}
        \intertext{and}
        \Theta\paren*{\frac{\log(d)}{\sqrt{d}}} &\leq \frac{\gamma_{\textnormal{ker}}(\bm{z})}{\gamma_{\textnormal{m-}\ell_2}(\bm{z})} \leq \Theta(\log(d)). \label{eqn:gamma_ker_wl2}
    \end{align}
\end{corollary}
\begin{proof}
    Since $d - 1 \leq h (d - h) \leq d^2/4$ for all $h \in [d - 1]$, we have
    \begin{align}
        (d - 1) \norm*{\bm{z}_{h, l}}^2 \leq \sum_{h = 1}^{d - 1} \sum_{l = 1}^{\binom{d}{h}} h (d - h) z_{h, l}^2 \leq (d^2/4) \norm*{\bm{z}_{h, l}}^2
        \intertext{and}
        \sqrt{d - 1} \norm*{\bm{z}_{h, l}}^2 \leq \sum_{h = 1}^{d - 1} \sum_{l = 1}^{\binom{d}{h}} \sqrt{h (d - h)} z_{h, l}^2 \leq (d/2) \norm*{\bm{z}_{h, l}}^2.
    \end{align}
    Similarly, since $(\sqrt{d - 1}/d) \sqrt{h (d - h)} \leq h (d - h) / d \leq (1/2) \sqrt{h (d - h)}$ for $h \in [d - 1]$, we have
    \begin{equation}
        \sqrt{d - 1} \sum_{h = 1}^{d - 1} \sum_{l = 1}^{\binom{d}{h}} \sqrt{h (d - h)} z_{h, l}^2 \leq \sum_{h = 1}^{d - 1} \sum_{l = 1}^{\binom{d}{h}} h (d - h) z_{h, l}^2 \leq \frac{d}{2} \sum_{h = 1}^{d - 1} \sum_{l = 1}^{\binom{d}{h}} \sqrt{h (d - h)} z_{h, l}^2.
    \end{equation}
    Then, \cref{eqn:gamma_ker_l2sq}, \cref{eqn:gamma_wl2_l2sq}, and \cref{eqn:gamma_ker_wl2} follow from \cref{thm:gamma_eta_sampling_schemes} and \cref{rem:log_factors}.
\end{proof}
These bounds suggest that kernel weights perform at most a log factor worse than leverage scores, while it can perform nearly $d$ better than leverage scores.
On the other hand, the performance of modified $\ell_2$ weights is never worse than leverage scores (up to constant factors), but can nearly do $\sqrt{d}$ better than leverage scores.
In \cref{app:adversarial_example}, we explicitly construct a toy model that demonstrates such an advantage.
While these results are only upper bounds on the sample complexities, we also observe similar results in experiments.
Using \cref{thm:gamma_eta_sampling_schemes}, we can derive the values of $\gamma$ and $\eta$ listed in \cref{tab:sample_complexity_sampling_schemes} for the different sampling strategies as follows.
\begin{corollary}
    \label{cor:gamma_eta_sampling_schemes_simplified}
    Define $\bm{H}$ to be a $(2^d - 2) \times (2^d - 2)$ dimensional diagonal matrix with diagonal entries
    \begin{equation*}
        \bm{H}_{(h, l), (h, l)} = \frac{\sqrt{h (d - h)}}{d}
    \end{equation*}
    for $h \in [d - 1]$ and $l \in [\binom{d}{h}]$, so that
    \begin{equation*}
        \lambda_{\textup{min}}(\bm{H}) = \Theta\paren*{\frac{1}{\sqrt{d}}} \quad \textnormal{ and } \quad \lambda_{\textup{max}}(\bm{H}) = \Theta(1).
    \end{equation*}
    Then, we have the following expressions for $\gamma(\bm{z})$ and $\eta$ for all $\bm{z} \in \mathbb{R}^{2^d - 2}$.
    \begin{enumerate}
        \item ($\bm{\ell_2}$\textbf{-squared})
        \begin{equation*}
            \gamma(\bm{z}) = \Theta\big(d \norm*{\bm{z}}^2\big) \quad \textnormal{ and } \quad \eta = \Theta(d).
        \end{equation*}
        \item (\textbf{Kernel})
        \begin{equation*}
            \gamma(\bm{z}) = \Theta\big(d \log(d) \norm*{\bm{H} \bm{z}}^2\big) \quad \textnormal{ and } \quad \eta = \Theta(d \log(d)).
        \end{equation*}
        \item (\textbf{Modified} $\bm{\ell_2}$)
        \begin{equation*}
            \gamma(\bm{z}) = \Theta\big(d \norm{\sqrt{\bm{H}} \bm{z}}_2^2\big) \quad \textnormal{ and } \quad \eta = \Theta(d).
        \end{equation*}
    \end{enumerate}
\end{corollary}
\begin{proof}
    This follows from \cref{thm:gamma_eta_sampling_schemes}, \cref{rem:log_factors} and the definition of $\bm{H}$.
\end{proof}

\begin{remark}
    \label{rem:weighted_geo_mean_dist_guarantees}
    The distributions considered in \cref{thm:gamma_eta_sampling_schemes} are actually a special case of a family of distributions, obtained by interpolating between kernel weights and leverage scores.
    Specifically, given $\tau \in [0, 1]$, we can consider the weighted geometric mean $(k(h))^\tau (\norm{\bm{u}_{h, l}}^2)^{(1 - \tau)}$ of $k(h)$ and $\norm{\bm{u}_{h, l}}^2$ for $h \in [d - 1]$ and $l \in [\binom{d}{h}]$.
    This gives rise to the distribution
    \begin{equation}
    p^\tau_{h,l} = \frac{1}{\binom{d}{h}} \frac{\left(\frac{1}{h (d - h)}\right)^\tau}{\sum_{j = 1}^{d - 1}\left(\frac{1}{j (d - j)}\right)^\tau}. \label{eqn:weighted_geo_mean_dist_full}
    \end{equation}
    For $\tau = 0$, we get the leverage scores (or $\ell_2$ squared distribution), $\tau = 1$ gives the kernel weight distribution, and $\tau = 1/2$ gives the modified $\ell_2$ distribution.

    Denoting
    \begin{equation}
        \mathcal{N}_\tau = \sum_{j = 1}^{d - 1}\left(\frac{1}{j (d - j)}\right)^\tau
    \end{equation}
    to be the normalization factor, we have
    \begin{equation}
        \frac{\|\bm{u}_{h,l}\|^2}{p_{h,l}^\tau} = \left(h (d - h)\right)^\tau \mathcal{N}_\tau
    \end{equation}
    for $h \in [d - 1]$ and $l \in [\binom{d}{h}]$.
    It follows that
    \begin{equation}
        \eta_\tau = \begin{cases}
                        \left(\frac{d^2}{4}\right)^\tau \mathcal{N}_\tau & \textnormal{ if $d$ is even}  \\
                        \left(\frac{d^2 - 1}{4}\right)^\tau \mathcal{N}_\tau & \textnormal{ if $d$ is odd},
                    \end{cases}
    \end{equation}
    and
    \begin{equation}
        \gamma_\tau(\bm{z}) = \mathcal{N}_\tau \sum_{h,l} \left(h (d - h)\right)^\tau z_{h,l}^2
    \end{equation}
    for $\bm{z} \in \mathbb{R}^{2^d - 2}$.

    Using similar arguments as in \cref{rem:log_factors}, we can show that
    \begin{equation}
        \mathcal{N}_\tau = \begin{cases}
                               \Theta(d^{1 - 2\tau}) & \textnormal{ if } 0 \leq \tau < 1 \\
                               \Theta\paren*{\frac{\log(d)}{d}} & \textnormal{if } \tau = 1.
                           \end{cases}
    \end{equation}
    Here, we used the fact that
    \begin{align}
        \int_1^{d/2} \frac{1}{(x (d - x))^\tau} \mathrm{d}x
        = d^{1 - 2\tau} (\operatorname{B}_{1/2}(1 - \tau, 1 - \tau) - \operatorname{B}_{1/d}(1 - \tau, 1 - \tau))
        = \Theta(d^{1 - 2\tau})
    \end{align}
    for $0 \leq \tau < 1$, where $\operatorname{B}_z(a,b) = \int_0^z t^{a - 1} (1 - t)^{b - 1} \mathrm{d}t$ is the incomplete beta function.

    Therefore, we have
    \begin{equation}
        \gamma_\tau(\bm{z}) = \Theta(d \norm{\bm{H}^\tau \bm{z}}^2) \textnormal{ and } \eta_\tau = \Theta(d)
    \end{equation}
    for $0 \leq \tau < 1$, and
    \begin{equation}
        \gamma_\tau(\bm{z}) = \Theta(d \log(d) \norm{\bm{H}^\tau \bm{z}}^2) \textnormal{ and } \eta_\tau = \Theta(d \log(d))
    \end{equation}
    for $\tau = 1$.
    For $0 \leq \tau < 1$, we do no worse than leverage score sampling.
    We remark that because the $\Theta$ notation hides constants, for a given dimension, one can choose an appropriate $\tau$ that minimizes these constants.
    It remains to see how such a strategy performs in practice.
\end{remark}

\subsection{Theoretical guarantees for sampling without replacement}
\label{app:samp_noreplace}
In this section, we prove guarantees for matrix vector multiplication estimator and the regression estimator when the rows/columns are sampled without replacement.\footnote{We note that the term ``sampling without replacement'' is perhaps a bit of a misnomer for this type of sampling scheme. Nevertheless, we use it in order to maintain consistency with \cite{musco2025provably}.}
We follow the strategy of~\cite{musco2025provably} for sampling indices without replacement.

Let $\bm{U}$ be an $r \times q$ dimensional matrix, with rows $\bm{u}_1, \dotsc, \bm{u}_r \in \mathbb{R}^q$.
To sample the rows of $\bm{U}$ without replacement, we suppose that we have $r$ independent Bernoulli random variables $Y_1, \dotsc, Y_r$, where $Y_i$ has mean $q_i > 0$ for $i \in [r]$.
We interpret $Y_i = 1$ as having picked the $i$th row, and $Y_i = 0$ as not having picked the $i$th row.
The expected number of samples (or rows) is $m_0 = \sum_{i = 1}^r q_i$.
Thus, on an average, we will sample $m_0$ rows, none of which are the same.
Observe that while we can control the expected number of samples by choosing the probabilities $q_1, \dotsc, q_r$, the actual number of samples $m$ we draw is random.
If $i_1, \dotsc, i_m$ are the (distinct) indices we pick, then the sketching matrix $\bm{S}$ is $m \times r$ dimensional, with $j$th row having the element $1/\sqrt{q_{i_j}}$ at location $i_j$ and zero elsewhere for $j \in [m]$.
Note that an important feature of such a sampling without replacement scheme is that the probabilities $q_1, \dotsc, q_r$ need \textit{not} sum to $1$ because they independently determine whether or not a given row is picked.

\subsubsection{Approximate Matrix Multiplication}
We derive the following guarantee for the matrix multiplication estimator for sampling without replacement.
Since the number of samples are not fixed, we instead calculate the estimation error for a fixed expected number of samples (which is determined by the probabilities $q_1, \dotsc, q_r$).
\begin{theorem}[Matrix multiplication, sampling without replacement]
    \label{thm:matvec_samp_noreplace}
    Given a matrix $\bm{U} \in \mathbb{R}^{r \times q}$ and a vector $\bm{z} \in \mathbb{R}^r$, let $\bm{S}$ be an $m \times r$ dimensional sketching matrix constructed by sampling rows of $\bm{U}$ without replacement according to probabilities $q_1, \dotsc, q_r$.
    Then, using an expected number of samples $\sum_{i = 1}^r q_i$, we have
    \begin{equation*}
        \mathbb{P}\brak*{\norm*{\bm{U}^\T \bm{S}^\T \bm{S} \bm{z} - \bm{U}^\T \bm{z}} \leq \varepsilon} \geq 1 - \delta
    \end{equation*}
    for
    \begin{equation}
        \varepsilon = \sqrt{\frac{1}{\delta} \sum_{i = 1}^r \paren*{\frac{1}{q_i} - 1} \norm*{\bm{u}_i}^2 z_i^2}.
            \label{eqn:matvec_samp_noreplace_error}
    \end{equation}
\end{theorem}
\begin{proof}
    Let $Y_1, \dotsc, Y_r$ be independent Bernoulli random variables with means $q_1, \dotsc, q_r$ respectively.
    Then, the random variable
    \begin{equation}
        \widehat{\bm{X}} = \bm{U}^T \bm{S}^T \bm{S} \bm{z} = \sum_{i = 1}^r Y_i \frac{\bm{u}_i z_i}{q_i}
    \end{equation}
    is an unbiased estimator of $\bm{U}^\T \bm{z}$.
    Denote $\textnormal{var}(\widehat{\bm{X}}) = \mathbb{E}[\|\widehat{\bm{X}} - \mathbb{E}[\widehat{\bm{X}}]\|^2]$ to be variance of $\widehat{\bm{X}}$.
    Then, since all $Y_1, \dotsc, Y_r$ are independent, we have
    \begin{align}
        \textnormal{var}(\widehat{\bm{X}})
            &= \sum_{i = 1}^r \textnormal{var}\paren*{Y_i \frac{\bm{u}_i z_i}{q_i}} \\
            &= \sum_{i = 1}^r \paren*{\frac{1}{q_i} - 1} \norm*{\bm{u}_i}^2 z_i^2.
    \end{align}
    Since $\textnormal{var}(\widehat{\bm{X}}) = \mathbb{E}[\norm{\widehat{\bm{X}} - \mathbb{E}[\widehat{\bm{X}}]}_2^2]$, by Markov's inequality, we have
    \begin{equation}
        \mathbb{P}\brak*{\norm{\widehat{\bm{X}} - \mathbb{E}[\widehat{\bm{X}}]} \geq \varepsilon}
            \leq \frac{\textnormal{var}(\widehat{\bm{X}})^2}{\varepsilon^2}
            = \frac{1}{\varepsilon^2} \sum_{i = 1}^r \paren*{\frac{1}{q_i} - 1} \norm*{\bm{u}_i}^2 z_i^2.
    \end{equation}
    Setting the right-hand-side of the above inequality equal to $\delta$ and solving for $\varepsilon$ gives us \cref{eqn:matvec_samp_noreplace_error}.
\end{proof}

We can use the above result to derive the error bounds in terms of the function $\gamma(\bm{z})$ defined in \cref{eqn:gamma_eta_def}.
\begin{corollary}
    \label{cor:matvec_samp_noreplace_complexity}
    Let $\mathcal{P} = (p_1, \dotsc, p_r)$ be a probability distribution on $[r]$ with $p_i > 0$ for all $i \in [r]$.
    Given a number $m_0 \in (0, r]$, let $c > 0$ be a constant for which $q_i = \min\{1, c p_i\}$ for $i \in [r]$ and $\sum_{i = 1}^r q_i = m_0$.
    Then, given error $\varepsilon > 0$ and confidence level $1 - \delta \in (0, 1)$, if
    \begin{equation*}
        m_0 \geq \frac{\gamma(\bm{z})}{\delta \varepsilon^2},
    \end{equation*}
    by sampling the rows of $\bm{U}$ without replacement according to probabilities $q_1, \dotsc, q_r$, we have
    \begin{equation*}
        \mathbb{P}\brak*{\norm*{\bm{U}^\T \bm{S}^\T \bm{S} \bm{z} - \bm{U}^\T \bm{z}} \leq \varepsilon} \geq 1 - \delta.
    \end{equation*}
\end{corollary}
\begin{proof}
    First, note that by the continuity of $c \mapsto \min\{1, c p_i\}$ for all $i \in [r]$, given a real number $m_0 \in (0, r]$, there is always some $c > 0$ for which $\sum_{i = 1}^r \min\{1, c p_i\} = m_0$ by the intermediate value theorem.
    Furthermore, $m_0 = \sum_{i = 1}^r \min\{1, c p_i\} \leq c$, since $\sum_{i = 1}^r p_i = 1$.
    Therefore, we have
    \begin{equation}
    \begin{aligned}
        \frac{1}{\delta} \sum_{i = 1}^r \paren*{\frac{1}{q_i} - 1} \norm*{\bm{u}_i}^2 z_i^2
            &\leq \frac{1}{\delta} \sum_{\substack{i = 1\\ q_i < 1}}^r \frac{\norm*{\bm{u}_i}^2 z_i^2}{q_i} \\
            &= \frac{1}{c \delta} \sum_{\substack{i = 1\\ q_i < 1}}^r \frac{\norm*{\bm{u}_i}^2 z_i^2}{p_i} \\
            &\leq \frac{1}{c \delta} \sum_{i = 1}^r \frac{\norm*{\bm{u}_i}^2 z_i^2}{p_i} \\
            &\leq \frac{\gamma(\bm{z})}{m_0 \delta}
            \leq \varepsilon^2,
    \end{aligned}
    \end{equation}
    where we use the fact that $q_i = c p_i$ when $q_i < 1$ in the second line, the fact that the terms are non-negative in the third line, and the definition of $\gamma$ (see \cref{eqn:gamma_eta_def}) and $c \geq m_0$ in the third line.
    The result then follows from \cref{thm:matvec_samp_noreplace}.
\end{proof}

\begin{remark}
    \label{rem:var_samp_noreplace}
    We can derive a tighter bound on the expected sample complexity for sampling without replacement as
    \begin{equation*}
        m_0 \geq \frac{1}{\delta \varepsilon^2} \sum_{\substack{i = 1\\ q_i < 1}}^r \frac{\norm*{\bm{u}_i}^2 z_i^2}{p_i}.
    \end{equation*}
    Intuitively, when $q_i = 1$, we (deterministically) choose the $i$th row of $\bm{U}$, and therefore, it should not add to the estimation error, which is then reflected in the average sample complexity.
    Thus, in practice, we may observe a somewhat smaller error for sampling without replacement on an average, compared to sampling with replacement.
\end{remark}

\subsubsection{Subspace Embedding}
In this section, we derive a subspace embedding guarantee for sampling without replacement.
\begin{theorem}[Subspace embedding]
\label{thm:subspace_embedding_noreplace}
Let $\bm{U}$ be an $r \times d$ matrix with rows $\bm{u}_1, \dotsc, \bm{u}_r$, and let $\mathcal{P} = (p_1, \dotsc, p_r)$ be a probability distribution on $[r]$ with $p_i > 0$ for all $i \in [r]$.
Given a number $m_0 \in (0, r]$, let $c > 0$ be a constant for which $q_i = \min\{1, c p_i\}$ for $i \in [r]$ and $\sum_{i = 1}^r q_i = m_0$.
Then, if
\begin{equation*}
    m_0 \geq \frac{2}{\varepsilon^2} \norm*{\sum_{i = 1}^r  \frac{\norm*{\bm{u}_i}^2}{p_i}\bm{u}_i \bm{u}_i^\T} \log\paren*{\frac{d}{\delta}}
            + \frac{2}{3 \varepsilon} \max_{i \in [r]} \frac{\norm*{\bm{u}_i}^2}{p_i} \log\paren*{\frac{d}{\delta}},
\end{equation*}
by sampling the rows of $\bm{U}$ without replacement according to probabilities $q_1, \dotsc, q_r$,
it holds that
\begin{equation*}
    \mathbb{P}\brak*{ \norm*{\bm{U}^\T \bm{S}^\T \bm{S} \bm{U} - \bm{U}^\T \bm{U}} \leq \varepsilon } \geq 1-\delta.
\end{equation*}
\end{theorem}
\begin{proof}
    Let $Y_1, \dotsc, Y_r$ be independent Bernoulli random variables with means $q_1, \dotsc, q_r$ respectively.
    For $i \in [r]$, define the random variable
    \begin{equation}
        \bm{X}_i = \frac{Y_i}{q_i} \bm{u}_i \bm{u}_i^\T - \bm{u}_i \bm{u}_i^\T.
    \end{equation}
    If $q_i = 1$, then $Y_i = 1$, so that $\bm{X}_i = 0$.
    Therefore, we have
    \begin{align}
        \norm*{\bm{X}_i} &\leq \max_{\substack{i \in [r]\\ q_i < 1}} \left|\frac{Y_i}{q_i} - 1\right| \norm*{\bm{u}_i}^2 \\
            &\leq \max_{\substack{i \in [r]\\ q_i < 1}} \frac{\norm*{\bm{u}_i}^2}{q_i} \\
            &= \frac{1}{c} \max_{\substack{i \in [r]\\ q_i < 1}} \frac{\norm*{\bm{u}_i}^2}{p_i} \\
            &\leq \frac{1}{c} \max_{i \in [r]} \frac{\norm*{\bm{u}_i}^2}{p_i} \\
            &\leq \frac{1}{m_0} \max_{i \in [r]} \frac{\norm*{\bm{u}_i}^2}{p_i} =: \frac{L}{m_0}
    \end{align}
    for all $i \in [r]$.
    Here, the third line follows from the fact that $q_i = c p_i$ when $q_i < 1$, while the last line follows from the fact that $m_0 = \sum_{i = 1}^r \min\{1, c p_i\} \leq c$ since $\sum_{i = 1}^r p_i = 1$.

    Next, note that $\mathbb{E}[\bm{X}_i] = 0$ and $\sum_{i = 1}^r \bm{X}_i = \bm{U}^\T \bm{S}^\T \bm{S} \bm{U} - \bm{U}^\T \bm{U}$.
    Furthermore, we have
    \begin{equation}
        \mathbb{E}[\bm{X}_i^2] = \paren*{q_i \paren*{1 - \frac{1}{q_i}}^2 + (1 - q_i)} \norm*{\bm{u}_i}^2 \bm{u_i} \bm{u_i}^\T
                               = \frac{(1 - q_i)}{q_i} \norm*{\bm{u}_i}^2 \bm{u_i} \bm{u_i}^\T
    \end{equation}
    for all $i \in [r]$.
    Therefore, we have
    \begin{align}
        \sum_{i = 1}^r \mathbb{E}[\bm{X}_i^2] &\preceq \sum_{\substack{i = 1\\ q_i < 1}}^r \frac{\norm*{\bm{u}_i}^2}{q_i} \bm{u_i} \bm{u_i}^\T \\
      &= \frac{1}{c} \sum_{\substack{i = 1\\ q_i < 1}}^r \frac{\norm*{\bm{u}_i}^2}{p_i} \bm{u_i} \bm{u_i}^\T \\
      &\preceq \frac{1}{c} \sum_{i = 1}^r \frac{\norm*{\bm{u}_i}^2}{p_i} \bm{u_i} \bm{u_i}^\T \\
      &\preceq \frac{1}{m_0} \sum_{i = 1}^r \frac{\norm*{\bm{u}_i}^2}{p_i} \bm{u_i} \bm{u_i}^\T.
    \end{align}
    It follows that
    \begin{equation}
        \norm*{\sum_{i = 1}^r \mathbb{E}[\bm{X}_i^2]} \leq \frac{1}{m_0} \norm*{\sum_{i = 1}^r \frac{\norm*{\bm{u}_i}^2}{p_i} \bm{u_i} \bm{u_i}^\T} =: \frac{\sigma^2}{m_0}.
    \end{equation}
    The result then follows from \cref{thm:matrix_Bernstein}.
\end{proof}

\subsubsection{Sketched Regression}
We now combine approximate matrix multiplication guarantee (\cref{cor:matvec_samp_noreplace_complexity}) and subspace embedding guarantee (\cref{thm:subspace_embedding_noreplace}) to obtain guarantee for the sketched regression estimator constructed by sampling without replacement.

\begin{theorem}[Sketched Regression]
\label{thm:sketched_regression_noreplace}
Suppose $\bm{U}$ has orthonormal columns and let $\bm{y}^* = \argmin_{\bm{y}}\norm*{\bm{U}\bm{y} - \bm{b}}^2$.
Let $\mathcal{P} = (p_1, \dotsc, p_r)$ be a probability distribution on $[r]$ with $p_i > 0$ for all $i \in [r]$.
Given a number $m_0 \in (0, r]$, let $c > 0$ be a constant for which $q_i = \min\{1, c p_i\}$ for $i \in [r]$ and $\sum_{i = 1}^r q_i = m_0$.
Let $\bm{S}$ be a $m\times q$ sketching matrix obtained by sampling rows of $\bm{U}$ without replacement according to probabilities $q_1, \dotsc, q_r$.
Define
\begin{equation*}
    \widehat{\bm{y}} = \argmin_{\bm{y}}\norm{\bm{S}\bm{U}\bm{y} - \bm{S}\bm{b}}^2.
\end{equation*}
Then, if 
\begin{equation*}
\begin{aligned}
    m_0 = O\paren*{ \frac{\gamma(\bm{P}_{\bm{U}}\bm{b})}{\delta\varepsilon^2} + \eta \log\paren*{\frac{d}{\delta}} },
\end{aligned}
\end{equation*}
it holds that
\begin{equation*}
    \mathbb{P}\brak*{ \norm*{\bm{y}^* -  \widehat{\bm{y}}}
    \leq \varepsilon  }
    \geq 1-\delta.
\end{equation*}
\end{theorem}
\begin{proof}
    We closely follow the proof of \cref{thm:sketched_regression}.
    Since $\bm{y}^*$ is the solution of $\min_{\bm{y}} \norm*{\bm{U} \bm{y} - \bm{b}}$, $\bm{U} \bm{y}^* - \bm{b}$ lies in the orthogonal complement of the range of $\bm{U}$, and therefore, $\bm{U}^\T (\bm{U} \bm{y}^* - \bm{b}) = 0$.
    Then, taking $\bm{z} = \bm{U} \bm{y}^* - \bm{b} = (\bm{I} - \bm{U} \bm{U}^\T )\bm{b}$ in \cref{cor:matvec_samp_noreplace_complexity}, we can infer that using
    \begin{equation}
         m_0
         = O \paren*{ \frac{\gamma(\bm{z})}{\delta\varepsilon^2} },
    \end{equation}
    we have with probability exceeding $1-\delta/2$,
    \begin{equation}\label{eqn:MM_noreplace}
        \norm*{\bm{U}^\T\bm{S}^\T\bm{S} (\bm{U} \bm{y}^* - \bm{b})}  \leq \frac{\varepsilon}{2}.
    \end{equation}

    Next, note that $\eta = \max_i \norm*{u_i}^2/p_i$, so that
    \begin{equation}
        \sum_{i = 1}^r \frac{\norm*{\bm{u}_i}^2}{p_i}\bm{u}_i \bm{u}_i^\T
        \preceq
        \eta \sum_{i = 1}^r \bm{u}_i \bm{u}_i^\T
        = \eta \bm{U}^\T \bm{U}.
    \end{equation}
    Then, because $\bm{U}$ has orthonormal columns, we have
    \begin{equation}
        \norm*{\sum_{i = 1}^r \frac{\norm*{\bm{u}_i}^2}{p_i} \bm{u}_i \bm{u}_i^\T}
        \leq \eta \norm*{\bm{U}^\T \bm{U}}
        = \eta.
    \end{equation}    
    Therefore, by \cref{thm:subspace_embedding_noreplace}, if
    \begin{align}
        m_0
        &= O\paren*{ \eta \log\paren*{\frac{d}{\delta}}}
        \\&\geq 8 \norm*{\sum_{i = 1}^r \frac{\norm*{\bm{u}_i}^2}{p_i} \bm{u}_i \bm{u}_i^\T} \log\paren*{\frac{d}{\delta}}
        + \frac{4}{3} \max_{i \in [r]} \frac{\norm*{\bm{u}_i}^2}{p_i} \log\paren*{\frac{d}{\delta}},
    \end{align}
    then, with probability exceeding $1-\delta/2$,
    \begin{equation}\label{eqn:SE_noreplace}
        \norm*{ \bm{U}^\T\bm{S}^\T\bm{S}\bm{U} - \bm{I}} \leq 1/2.
    \end{equation}
    The remainder of the proof is the same as that of \cref{thm:sketched_regression}.
\end{proof}

\section{Description of past estimators}
\label{sec:past_full_description}

In this section we provide more details on how several existing estimators fit into the unified framework described in \cref{sec:unified}.

\subsection{KernelSHAP}
\label{sec:past_kernel} 

KernelSHAP makes use of a subsampled and reweighted version of the constrained regression formulation \cref{eqn:shapley_constrained} of the Shapley values.
Specifically, denoting $\bm{Z}_S$ to be the $S$-th row of $\bm{Z}$, observe that
\begin{equation}
\begin{aligned}
    \norm*{\bm{Z}'\bm{\phi} - \bm{b}}^2
    &= \sum_{S\in 2^{[d]}\setminus\{[d],\emptyset\}} k(S) (\bm{Z}_{S} \bm{\phi} - \bm{v}_S)^2 \\
    &= \bigg[\sum_{S\in 2^{[d]}\setminus\{[d],\emptyset\}} k(S)\bigg]\ \mathbb{E}[(\bm{Z}_{S'} \bm{\phi} - \bm{v}_{S'})^2],
\end{aligned}
\end{equation}
where in the last equation $S'$ is a random variable for which $\mathbb{P}[S'=S] \propto k(S)$ for $S \subseteq [d]$, $S \neq \emptyset, [d]$.
Note that
\begin{equation*}
    \argmin_{\substack{\bm{\phi}\in\mathbb{R}^d\\\bm{1}^\T\bm{\phi}= v([d])-v(\emptyset)}} \norm*{\bm{Z}'\bm{\phi} - \bm{b}}^2
    = \argmin_{\substack{\bm{\phi}\in\mathbb{R}^d\\\bm{1}^\T\bm{\phi}= v([d])-v(\emptyset)}} \mathbb{E}[(\bm{Z}_{S'} \bm{\phi} - \bm{v}_{S'})^2],
\end{equation*}
because the minima of a function $f$ coincide with the minima of $\zeta f$ for $\zeta > 0$.

The KernelSHAP estimator \cite{lundberg2017unified} is then defined as
\begin{equation}
    \bm{\phi}^{\textup{KS}} = \argmin_{\substack{\bm{\phi}\in\mathbb{R}^d\\\bm{1}^\T\bm{\phi}= v([d])-v(\emptyset)}} \frac{1}{m} \sum_{i=1}^{m} (\bm{Z}_{S_i} \bm{\phi} - \bm{v}_{S_i})^2,
\end{equation}
where $S_i$ are iid copies of $S'$.

As noted by \cite{musco2025provably}, this can be viewed as a constrained sketched regression problem
\begin{equation}
    \bm{\phi}^{\textup{KS}}
= \argmin_{\substack{\bm{\phi}\in\mathbb{R}^d\\\bm{1}^\T\bm{\phi}= v([d])-v(\emptyset)}} \norm*{ \bm{S}(\bm{Z}' \bm{\phi} - \bm{b})}
\end{equation}
Performing the same change of variables as in the proof of \cref{thm:shapley_regression} we find that
\begin{align}
\bm{\phi}^{\textup{KS}}&= \bm{Q}\argmin_{\bm{x}\in\mathbb{R}^{d-1}} \norm*{ \bm{S}(\bm{Z}'(\bm{Q} \bm{x} +\alpha \bm{1}) -  \bm{b})} +  \alpha\bm{1}
\\&= \bm{Q}\argmin_{\bm{x}\in\mathbb{R}^{d-1}} \norm*{ \bm{S}(\bm{Z}'\bm{Q} \bm{x} -  (\bm{b} - \alpha \bm{Z}' \bm{1})) } +  \alpha\bm{1}
\\&= \bm{Q}\argmin_{\bm{x}\in\mathbb{R}^{d-1}} \norm*{ \bm{S}(\bm{U} \bm{x} - \bm{b}_{\alpha}) } +  \alpha\bm{1}.
\end{align}

\subsection{Unbiased KernelSHAP}

In \cite{covert2020improving}, the authors observe that the Shapley values can be expressed as
\begin{equation}
    \bm{\phi}^* 
= \bm{A}^{-1}\paren*{\bm{f}  - \bm{1} \frac{\bm{1}^\T \bm{A}^{-1}\bm{f} - v([d]) + v(\emptyset)}{\bm{1}^\T \bm{A}^{-1} \bm{1}}  }
\end{equation}
where
\begin{equation}
    \bm{A} = \bm{Z}^\T \bm{W} \bm{Z}
    ,\qquad
    \bm{f} = \bm{Z}^\T \bm{W} \bm{b}.
\end{equation}
They then introduce the \emph{unbiased KernelSHAP} estimator
\begin{equation}
    \bm{\phi}^{\textup{uKS}} = \bm{A}^{-1}\paren*{\widehat{\bm{f}}  - \bm{1} \frac{\bm{1}^\T \bm{A}^{-1}\widehat{\bm{f}} - v([d]) + v(\emptyset)}{\bm{1}^\T \bm{A}^{-1} \bm{1}}  }
    ,\qquad 
    \widehat{\bm{f}} = \bm{Z}^\T \sqrt{\bm{W}} \bm{S}^\T\bm{S}\sqrt{\bm{W}}\bm{b}.
\end{equation}
Expanding, we see that
\begin{align}
    \bm{\phi}^{\textup{uKS}}
    = \bm{A}^{-1}\widehat{\bm{f}} - \frac{\bm{A}^{-1}\bm{1}\bm{1}^\T\bm{A}^{-1}}{\bm{1}^\T \bm{A}^{-1} \bm{1}}  \widehat{\bm{f}}  + \bm{A}^{-1}\bm{1} \frac{v([d]) + v(\emptyset)}{\bm{1}^\T \bm{A}^{-1} \bm{1}}
\end{align}
Since $[\bm{Q},d^{-1/2}\bm{1}]$ form an orthonormal basis for $\mathbb{R}^d$,
\begin{align}
    \bm{A}^{-1}
    = \paren*{\frac{d-1}{d} \bm{Q}\bm{Q}^\T + \paren*{d-1 + d c_d}\frac{\bm{1}\bm{1}^\T}{d} }^{-1}
    = \frac{d}{d-1} \bm{Q}\bm{Q}^\T + \paren*{d-1 + d c_d}^{-1}\frac{\bm{1}\bm{1}^\T}{d}.
\end{align}
Using this, we see that
\begin{equation}
   \bm{A}^{-1} \bm{1} = (d-1+dc_d)^{-1} \bm{1}
   ,\qquad
    \bm{1}^\T\bm{A}^{-1} \bm{1} = d(d-1+dc_d)^{-1}.
\end{equation}
We now compute
\begin{equation}
    \bm{A}^{-1} \widehat{\bm{f}}
    = \frac{d}{d-1} \bm{Q}\bm{Q}^\T \widehat{\bm{f}} + (d-1+dc_d)^{-1}  \frac{\bm{1}\bm{1}^\T}{d} \bm{\widehat{f}},
\end{equation}
\begin{equation}
    \frac{\bm{A}^{-1}\bm{1}\bm{1}^\T\bm{A}^{-1}}{\bm{1}^\T \bm{A}^{-1} \bm{1}}
    = \frac{(d-1+dc_d)^{-2} \bm{1}\bm{1}^\T}{d(d-1+dc_d)^{-1} }
    = \frac{(d-1+dc_d)^{-1} \bm{1}\bm{1}^\T}{d},
\end{equation}
and 
\begin{equation}
    \bm{A}^{-1}\bm{1} \frac{v([d]) + v(\emptyset)}{\bm{1}^\T \bm{A}^{-1} \bm{1}}
    = \frac{(d-1+dc_d)^{-1} \bm{1}}{d(d-1+dc_d)^{-1} }
    = \frac{\bm{1}}{d}.
\end{equation}
Combining these equations we have
\begin{equation}
    \bm{\phi}^{\textup{uKS}} 
    = \frac{d}{d-1} \bm{Q}\bm{Q}^\T \bm{Z}^\T \sqrt{\bm{W}} \bm{S}^\T \bm{S} \sqrt{\bm{W}}\bm{b}
    + \frac{v([d]) - v(\emptyset)}{d} \bm{1}.
\end{equation}

\subsection{LeverageSHAP}
\label{sec:LeverageSHAP_full}

In \cite{musco2025provably}, the authors show the typical formulation of the Shapley values \cref{eqn:shapley_constrained} can be rewritten as an unconstrained problem
\begin{equation}
    \bm{\phi}^* 
    = \argmin_{\bm{\phi}\in\mathbb{R}^d} \norm{ \bm{A}\bm{\phi} - \bm{b}_\alpha }^2 + \alpha \bm{1},
\end{equation}
where
\begin{equation}
    \bm{A} = \bm{Z}'\bm{P}, \qquad \bm{P} := \bm{I} - d^{-1} \bm{1}\bm{1}^\T = \bm{Q}\bm{Q}^\T.\footnote{Since $\bm{1}$ is in the null-space of $\bm{A}$, all of $\{\bm{\phi} + c \bm{1}:c\in\mathbb{R}\}$ produce the same objective value (and hence the argmin is an infinite set), it should be understood as the minimum norm solution; i.e. for which $\bm{\phi}+c\bm{1}$ is orthogonal to $\bm{1}$.}
\end{equation}
They then describe a randomized estimator \emph{LeverageSHAP} of the form
\begin{equation}
    \bm{\phi}^{\textup{LS}} 
    = \argmin_{\bm{\phi}\in\mathbb{R}^d} \norm{ \bm{S} (\bm{A}\bm{\phi} - \bm{b}_\alpha) }^2 + \alpha \bm{1}.
\end{equation}
Theoretical guarantees are given for the case where $\bm{S}$ is drawn according to the leverage scores of $\bm{A}$. 

\section{Equivalence between Lagrangian and Change of Variable Framework} 
\label{app:equivalence}

We consider,
\begin{equation}
    \bm{\phi}^{\textup{R}} = \argmin_{\substack{\bm{\phi}\in\mathbb{R}^d\\\bm{1}^\T\bm{\phi} = \alpha}} \norm*{\bm{C} \bm{\phi} - \bm{y}} .
    \label{eq:cons-eq}
\end{equation}
where $\alpha = (v([d])-v(\emptyset))/d$, and $\bm{C} = \bm{Z'}$ and $\bm{y} = \bm{b}$ for solving the constrained least squares exactly, while $\bm{C} = \bm{SZ'}$ and $\bm{y} = \bm{Sb}$ for approximately methods such that $E[\bm{S}^{\T}\bm{S}] = \bm{I}$.
Define $\bm{M} = \bm{C}^{\T}\bm{C}$ and $\bm{g} = \bm{C}^{\T}\bm{y}$. Next, we write the unconstrained solution of the above least squares as,
\begin{equation}
    \bm{\phi}^{u} = \argmin_{\substack{\bm{\phi}\in\mathbb{R}^d}} \norm*{\bm{C} \bm{\phi} - \bm{y}} = \bm{M}^+\bm{g} 
\end{equation}

\paragraph{Lagrangian method: } In order to solve \cref{eq:cons-eq}, the Lagrangian method writes,
\begin{equation}
    \mathcal{L}(\bm{\phi}, \lambda) = \frac{1}{2}\bm{\phi}^{\T}\bm{M}\bm{\phi} - \bm{g}^{\T}\bm{\phi} + \lambda (\bm{1}^{\T}\bm{\phi} - \alpha) 
\end{equation}
with the following KKT conditions,
\begin{enumerate}
    \item $\bm{M\phi} =\bm{g} + \lambda \bm{1} = 0 \rightarrow \bm{\phi} = \bm{M}^+(\bm{g} - \lambda\bm{1})$
    \item $\bm{1}^{\T}\phi = \alpha \rightarrow \lambda = \frac{\bm{1}^{\T}\bm{M}^+\bm{g} - \alpha d}{\bm{1}^{\T}\bm{M}^+\bm{1}}$
\end{enumerate}
This results in the final solution to be,
\begin{equation}
    \bm{\phi}^{\textup{R}} =  \bm{\phi}^{u} - \bm{M}^+\bm{1}\frac{\bm{1}^{\T} \bm{\phi}^{u} - \alpha d}{\bm{1}^{\T}\bm{M}^+\bm{1}}
    \label{eq:lagrangian-solution}
\end{equation}

\paragraph{Change of Variable Method:} As discussed in \cref{sec:our_proofs}, an alternative method to solve the constrained least squares is using the change of variable to explicitly enforce the constraint. Specifically, we re-parameterize $\bm{\phi}$ as,
\begin{equation}
    \bm{\phi} = \alpha\bm{1} + \bm{Q}\bm{x}
\end{equation}
where $\bm{Q} \in \mathbb{R}^{d \times (d-1)}$ is a matrix with columns forming an orthonormal basis for the null space of $\bm{1}^{\T}$, i.e., $\bm{1}^{\T}\bm{Q} = 0$ and $\bm{Q}^{\T}\bm{Q} = \bm{I}$.

Plugging $\bm{\phi}$ into the objective results in,
\begin{equation}
    \argmin_{\substack{\bm{x}}} \norm*{\bm{C} (\alpha\bm{1} + \bm{Q}\bm{x}) - \bm{y}} =  \argmin_{\substack{\bm{x}}} \norm*{\bm{C}\bm{Q}\bm{x} - (\bm{y} - \alpha\bm{C1})} 
\end{equation}
Solving this results in,
\begin{equation}
    \bm{x}^{*} = (\bm{Q}^{\T}\bm{M}^{\T}\bm{Q})^+\bm{Q}^T\bm{M}(\bm{\phi}^u - \alpha\bm{1})
\end{equation}
This the final solution is,
\begin{equation}
    \bm{\phi}^{\textup{R}}  = \bm{u} + \bm{Q}(\bm{Q}\bm{M}^{\T}\bm{Q})^+\bm{Q}^T\bm{M}(\bm{\phi}^u - \alpha\bm{1})
    \label{eq:cov-solution}
\end{equation}

\paragraph{Equivalence of the methods:} The second term in \cref{eq:cov-solution} can be seen as a projection of the vector $\bm{\phi}^u - \alpha\bm{1}$ into the span of $\bm{Q}$ (or alternatively on the null space of $\bm{1}^{\T}$) with the projection matrix,
\begin{equation}
    \bm{P} = \bm{Q}(\bm{Q}\bm{M}^{\T}\bm{Q})^+\bm{Q}^T\bm{M}
\end{equation}

Next, we can rewrite \cref{eq:cov-solution} as,
\begin{equation}
    \bm{\phi}^{\textup{R}}  = \alpha\bm{1} + \bm{P}(\bm{\phi}^u - \alpha\bm{1}) = \bm{\phi}^u - (\bm{I} - \bm{P})(\bm{\phi}^u - \alpha\bm{1})
\end{equation}

From the geometric intuition, $\bm{I} - \bm{P}$ can be seen as a metric-projection in the $\bm{M}$-norm\footnote{where $\bm{M}$-norm is defined as $\norm*{\bm{v}}_{\bm{M}} = \bm{v}^{\T}\bm{M}\bm{v}$ for all $\bm{v}\in \mathbb{R}^d$} into the orthogonal complement $\bm{Q}$, or alternatively in the span of $\bm{M}^+\bm{1}$. Such a projection in the $\bm{M}$-norm for any vector $\bm{z}$ is
\begin{equation}
    (\bm{I} - \bm{P})(\bm{z}) = \bm{M}^+\bm{1}\frac{\bm{1}^{\T}\bm{z}}{\bm{1}^{\T}\bm{M}^+\bm{1}}.
    \label{eq:equiv}
\end{equation}

Thus, plugging in this \cref{eq:equiv} results in
\begin{equation}
 \bm{\phi}^{\textup{R}} =   \bm{\phi}^u - \bm{M}^+\bm{1}\frac{\bm{1}^{\T}(\bm{\phi}^u - \alpha\bm{1})}{\bm{1}^{\T}\bm{M}^+\bm{1}},  
\end{equation}
thus recovering \cref{eq:lagrangian-solution} by noting that $\bm{1}^\T \bm{1} = d$.


\section{Variance Analysis}

\subsection{Variance reduction}
\label{app:variance_reduction}
If we have a good guess what the value function $v(s)$ looks like ahead of time, then we might hope to be able to incorporate this information into our estimators.

Observe that, for any fixed vector $\bm{f}$,
\begin{equation}
    \bm{\phi}^*
    = \bm{Q}\argmin_{\bm{x}\in\mathbb{R}^{d-1}} \norm*{\bm{U} \bm{x} - \bm{b}_{0}} +  \alpha\bm{1} 
    = \bm{Q}\argmin_{\bm{x}\in\mathbb{R}^{d-1}} \norm*{\bm{U} \bm{x} - (\bm{b}_{0} - \bm{f})} +  \alpha\bm{1} + \bm{Q}\bm{U}^\T\bm{f}
\end{equation}
and
\begin{equation}
    \bm{\phi}^* = \bm{Q}\bm{U}^\T \bm{b}  + \alpha\bm{1} 
    = \bm{Q}\bm{U}^\T (\bm{b}_0 - \bm{f}) + \alpha\bm{1} + \bm{Q}\bm{U}^\T\bm{f}.
\end{equation}
We can then define estimators\footnote{For the special choice $\bm{f} = \sqrt{d/(d-1)}\lambda \bm{Z}' \bm{1}$ we have that $\bm{\phi}_{\bm{f}}^{\textup{R-vr}} = \bm{\phi}_{\lambda}^{\textup{R}}$ and  $\bm{\phi}_{\bm{f}}^{\textup{M-vr}} = \bm{\phi}_{\lambda}^{\textup{M}}$, and hence these estimators generalize those described in \cref{sec:estimator_def}.}
\begin{equation}
    \bm{\phi}_{\bm{f}}^{\textup{R-vr}} = 
    \bm{Q}\argmin_{\bm{x}\in\mathbb{R}^{d-1}} \norm*{\bm{S}(\bm{U} \bm{x} - (\bm{b}_{0}-\bm{f}))} +  \alpha\bm{1} + \bm{Q}\bm{U}^\T\bm{f}
\end{equation}
and
\begin{equation}
    \bm{\phi}_{\bm{f}}^{\textup{M-vr}} = 
\bm{Q}\bm{U}^\T \bm{S}^\T\bm{S}(\bm{b}_0 - \bm{f}) + \alpha\bm{1} + \bm{Q}\bm{U}^\T\bm{f}.
\end{equation}

They key observation is that, if $\bm{f} \approx \bm{b}_0$, then we expect the variance of $\bm{\phi}_{\bm{f}}^{\textup{R-vr}}$ and $\bm{\phi}_{\bm{f}}^{\textup{M-vr}}$ to be reduced.

We can derive theoretical guarantees.
Following the same approach as \cref{thm:main}, we see that
\begin{equation}
    m = O\paren*{ \frac{\gamma(\bm{P}_{\bm{U}}(\bm{b}_0-\bm{f}))}{\delta\varepsilon^2} + \eta \log\paren*{\frac{d}{\delta}} }
\quad\Longrightarrow\quad
\mathbb{P}\brak*{ \norm*{\bm{\phi}^* - \bm{\phi}_{\bm{f}}^{\textup{R-vr}}} < \varepsilon } > 1-\delta,
\end{equation}
and 
\begin{equation}
    m = O\paren*{ \frac{\gamma (\bm{b}_0-\bm{f})}{\delta\varepsilon^2} }
\quad\Longrightarrow\quad
    \mathbb{P}\brak*{ \norm*{\bm{\phi}^* - \bm{\phi}_{\bm{f}}^{\textup{M-vr}}} < \varepsilon } > 1-\delta.
\end{equation}

\subsection{Ratio of mean squared errors}
\label{app:finite_asymp_mse}
In \cref{sec:RNLA_proofs}, we saw that $\gamma(\bm{z})$ and $\eta$ (see \cref{eqn:gamma_eta_def}) give \textit{upper} bounds on the sample complexity of matrix multiplication and regression estimators for sampling with replacement.
In this section, we study the ratio of mean squared errors for different sampling strategies these estimators in the finite-sample/asymptotic regime.
We find that this ratio is determined by $\gamma$ for both these estimators, as summarized below.

\begin{theorem}[Ratio of mean squared errors]
    \label{thm:mse_ratio_replace}
    Given an $r \times q$ matrix $\bm{U}$ with orthonormal columns, and an $r$-dimensional vector $\bm{b}$, suppose that we want to estimate $\bm{U}^\T \bm{b}$ using matrix multiplication estimator (see \cref{thm:matvec_samp_replace}) and $\argmin_{\bm{y}} \norm*{\bm{U} \bm{y} - \bm{b}}$ using a regression estimator (see \cref{thm:sketched_regression}).
    Given a sampling distribution $\mathcal{P}$ over $[r]$ and a fixed number of samples $m$, denote $\bm{X}_m^{\textup{M}}(\mathcal{P})$, $\bm{X}_m^{\textup{R}}(\mathcal{P})$ to be the matrix multiplication estimator and regression estimator for $\bm{U}^\T \bm{b}$, respectively.

    Given two sampling distributions $\mathcal{P}_1$ and $\mathcal{P}_2$, denote $\gamma_1$ and $\gamma_2$ to be the values of $\gamma$ as defined in \cref{eqn:gamma_eta_def} with respect to distributions $\mathcal{P}_1$ and $\mathcal{P}_2$, respectively.
    Fix the number of samples $m \in \mathbb{N}$.
    Then, we have the following results.
    \begin{enumerate}
        \item (\textbf{Matrix multiplication})
        \begin{equation}
            \frac{\mathbb{E}[\|\bm{X}_m^{\textup{M}}(\mathcal{P}_1) - \bm{U}^\T \bm{b}\|^2]}{\mathbb{E}[\|\bm{X}_m^{\textup{M}}(\mathcal{P}_2) - \bm{U}^\T \bm{b}\|^2]} = \frac{\gamma_1(\bm{b}) - \norm{\bm{U}^\T \bm{b}}^2}{\gamma_2(\bm{b}) - \norm{\bm{U}^\T \bm{b}}^2}. \label{eqn:matmult_mse_ratio_replace}
        \end{equation}
        \item (\textbf{Regression}) If for $i = 1, 2$, $\mathbb{E}[\|\bm{X}_m^{\textup{R}}(\mathcal{P}_i) - \bm{U}^\T \bm{b}\|^2] \neq 0$ and
        \begin{equation}
            \frac{\sqrt{\mathbb{E}[\|\bm{X}_m^{\textup{R}}(\mathcal{P}_i) - \bm{U}^\T \bm{b}\|^4]}}{\mathbb{E}[\|\bm{X}_m^{\textup{R}}(\mathcal{P}_i) - \bm{U}^\T \bm{b}\|^2]} = O(1), \label{eqn:reg_mse_assumption}
        \end{equation}
        we have
        \begin{equation}
             \frac{\mathbb{E}[\|\bm{X}_m^{\textup{R}}(\mathcal{P}_1) - \bm{U}^\T \bm{b}\|^2]}{\mathbb{E}[\|\bm{X}_m^{\textup{R}}(\mathcal{P}_2) - \bm{U}^\T \bm{b}\|^2]} = \left(1 \pm O\left(\frac{1}{\sqrt{m}}\right)\right) \frac{\gamma_1(\bm{P}_{\bm{U}} \bm{b})}{\gamma_2(\bm{P}_{\bm{U}} \bm{b})}, \label{eqn:regression_mse_ratio_replace}
        \end{equation}
        where $x = (a \pm b)$ means $x \in [a - b, a + b]$.
    \end{enumerate}
\end{theorem}
\begin{proof}
    Let $\bm{S}$ be an $m \times r$ sketch matrix (for sampling with replacement) as defined in \cref{eqn:S_theory_def} with respect to the distribution $\mathcal{P}$.
    Then, the matrix multiplication estimator is $\bm{X}_m^{\textup{M}}(\mathcal{P}) = \bm{U}^\T \bm{S}^\T \bm{S} \bm{b}$, while the regression estimator is $\bm{X}_m^{\textup{R}}(\mathcal{P}) = \argmin_{\bm{y}} \norm{\bm{S} \bm{U} \bm{y} - \bm{S} \bm{b}}$.

    1. \textbf{Matrix multiplication:}
    Since $\mathbb{E}[\|\bm{X}_m^{\textup{M}}(\mathcal{P}) - \bm{U}^\T \bm{b}\|^2]$ is the variance of $\bm{X}_m^{\textup{M}}$ using $m$ samples, from \cref{eqn:matmult_replace_var}, we have
    \begin{equation}
        \mathbb{E}[\|\bm{X}_m^{\textup{M}}(\mathcal{P}_i) - \bm{U}^\T \bm{b}\|^2] = \frac{1}{m} (\gamma_i(\bm{b}) - \|\bm{U}^\T \bm{b}\|^2)
    \end{equation}
    for $i = 1, 2$, from which we obtain \cref{eqn:matmult_mse_ratio_replace}.

    2. \textbf{Regression:}
    Observe that $\argmin_{\bm{y}} \norm{\bm{U} \bm{y} - \bm{b}} = \bm{U}^\T \bm{b}$.
    Furthermore, since
    \begin{equation}
        \norm{\bm{X}_m^{\textup{R}}(\mathcal{P}_i) - \bm{U}^\T \bm{b}}
            = \norm{\bm{U}^\T \bm{S}^\T \bm{S} \bm{U} (\bm{X}_m^{\textup{R}}(\mathcal{P}_i) - \bm{U}^\T \bm{b}) + (\bm{I} - \bm{U}^\T \bm{S}^\T \bm{S} \bm{U}) (\bm{X}_m^{\textup{R}}(\mathcal{P}_i) - \bm{U}^\T \bm{b})},
    \end{equation}
    we have from triangle and reverse-triangle inequalities,
    \begin{align}
        |\norm{\bm{X}_m^{\textup{R}}(\mathcal{P}_i) - \bm{U}^\T \bm{b}} - \norm{\bm{U}^\T \bm{S}^\T \bm{S} \bm{U} (\bm{X}_m^{\textup{R}}(\mathcal{P}_i) - \bm{U}^\T \bm{b})}|
            \leq \norm{(\bm{I} - \bm{U}^\T \bm{S}^\T \bm{S} \bm{U}) (\bm{X}_m^{\textup{R}}(\mathcal{P}_i) - \bm{U}^\T \bm{b})}.
    \end{align}
    For simplicity, denote $A_i = \norm{\bm{X}_m^{\textup{R}}(\mathcal{P}_i) - \bm{U}^\T \bm{b}}$, $B_i = \norm{\bm{U}^\T \bm{S}^\T \bm{S} \bm{U} (\bm{X}_m^{\textup{R}}(\mathcal{P}_i) - \bm{U}^\T \bm{b})}$, and $C_i = \norm{(\bm{I} - \bm{U}^\T \bm{S}^\T \bm{S} \bm{U}) (\bm{X}_m^{\textup{R}}(\mathcal{P}_i) - \bm{U}^\T \bm{b})}$.
    Then, we have $|A_i^2 - B_i^2| \leq (A_i + B_i) C_i$, from which it follows that
    \begin{equation}
        |\mathbb{E}[A_i^2] - \mathbb{E}[B_i^2]| \leq \mathbb{E}[(A_i + B_i) C_i].
    \end{equation}
    Now, observe that $B_i \leq \norm{\bm{U}^\T \bm{S}^\T \bm{S} \bm{U}} A_i$ and $C_i \leq \norm{\bm{I} - \bm{U}^\T \bm{S}^\T \bm{S} \bm{U}} A_i$.
    Moreover, we have $\norm{\bm{U}^\T \bm{S}^\T \bm{S} \bm{U}} \leq \eta_i$, where $\eta_i$ is defined in~\cref{eqn:gamma_eta_def} (and depends on the distribution $\mathcal{P}_i$).
    Therefore,
    \begin{align}
        |\mathbb{E}[A_i^2] - \mathbb{E}[B_i^2]| \leq (1 + \eta_i) \mathbb{E}[\norm{\bm{I} - \bm{U}^\T \bm{S}^\T \bm{S} \bm{U}} A_i^2]
                                                \leq (1 + \eta_i) \sqrt{\mathbb{E}[\norm{\bm{I} - \bm{U}^\T \bm{S}^\T \bm{S} \bm{U}}^2]} \sqrt{\mathbb{E}[A_i^4]},
    \end{align}
    where we used Cauchy-Schwarz inequality in the last step.
    Now, note that $\sqrt{\mathbb{E}[A_i^4]} \geq \mathbb{E}[A_i^2]$ by Jensen's inequality, and thus, $\sqrt{\mathbb{E}[A_i^4]}/\mathbb{E}[A_i^2] = O(1)$ implies $\sqrt{\mathbb{E}[A_i^4]}/\mathbb{E}[A_i^2] = \Theta(1)$.
    It follows from \cref{eqn:subspace_embed_replace_var} and \cref{eqn:subspace_embed_replace_var_bd} that
    \begin{align}
        \left|\frac{\mathbb{E}[B_i^2]}{\mathbb{E}[A_i^2]} - 1\right| \leq (1 + \eta_i) \sqrt{\frac{\eta_i}{m}} \frac{\sqrt{\mathbb{E}[A_i^4]}}{\mathbb{E}[A_i^2]}
                                                                      = \Theta\left(\frac{1}{\sqrt{m}}\right).
    \end{align}
    Thus, for large enough $m$ (using $(1 - x)^{-1} = 1 + O(x)$ for $x \ll 1$), we have
    \begin{align}
        \frac{\mathbb{E}[A_1^2]}{\mathbb{E}[B_1^2]} &= 1 \pm O\left(\frac{1}{\sqrt{m}}\right)
        \intertext{and}
        \frac{\mathbb{E}[B_2^2]}{\mathbb{E}[A_2^2]} &= 1 \pm O\left(\frac{1}{\sqrt{m}}\right),
    \end{align}
    which implies
    \begin{equation}
        \frac{\mathbb{E}[A_1^2]}{\mathbb{E}[A_2^2]} = \left(1 \pm O\left(\frac{1}{\sqrt{m}}\right)\right) \frac{\mathbb{E}[B_1^2]}{\mathbb{E}[B_2^2]}.
    \end{equation}
    Then, denoting $\bm{y}^* = \argmin_{\bm{y}} \norm{\bm{U} \bm{y} - \bm{b}}$, from \cref{eqn:regression_matvec_term} and \cref{eqn:matmult_replace_var}, we obtain
    \begin{align}
        \frac{\mathbb{E}[B_1^2]}{\mathbb{E}[B_2^2]}
            &= \frac{\mathbb{E}[\norm{\bm{U}^\T\bm{S}^\T\bm{S} (\bm{U}\bm{y}^* - \bm{b})}^2]}{\mathbb{E}[\norm{\bm{U}^\T\bm{S}^\T\bm{S} (\bm{U}\bm{y}^* - \bm{b})}^2]} \\
            &= \frac{\gamma_1(\bm{U}\bm{y}^* - \bm{b}) - \norm{\bm{U}^\T (\bm{U}\bm{y}^* - \bm{b})}^2}{\gamma_2(\bm{U}\bm{y}^* - \bm{b}) - \norm{\bm{U}^\T (\bm{U}\bm{y}^* - \bm{b})}^2} \\
            &= \frac{\gamma_1(\bm{P}_{\bm{U}} \bm{b})}{\gamma_2(\bm{P}_{\bm{U}} \bm{b})},
    \end{align}
    where in the last step, we use the fact that $\bm{U} \bm{y}^* - \bm{b} = \bm{P}_{\bm{U}} \bm{b}$ and $\bm{U}^\T \bm{P}_{\bm{U}} \bm{b} = 0$.
\end{proof}

Informally, \cref{eqn:reg_mse_assumption} says that (the square-root of) the fourth ``central moment" is comparable to the mean squared error of the estimator.
This requirement actually holds for the simple statistical task of estimating the mean of a scalar random variable.
Indeed, if $X_1, \dotsc, X_m$ are iid copies of a random variable $X$ with $\mathbb{E}[X^4] < \infty$,
then $\widehat{X} = \sum_{i = 1}^m X_i / m$ is an unbiased estimator of $\mathbb{E}[X]$ satisfying
\begin{equation}
    \frac{\sqrt{\mathbb{E}[(\widehat{X} - \mathbb{E}[X])^4]}}{\mathbb{E}[(\widehat{X} - \mathbb{E}[X])^2]} = \Theta(1)
\end{equation}
for all $m$.
Motivated by this observation, we expect \cref{eqn:reg_mse_assumption} to hold in practice, though this may be difficult to verify rigorously.
Also note that while \cref{eqn:regression_mse_ratio_replace} gives an expression for ratio of mean squared errors for the regression estimator in the finite-sample regime,
the number of samples needs to be large enough so that we can ignore the correction term.

Now, we specialize \cref{thm:mse_ratio_replace} to Shapley value estimation.
\begin{corollary}
    \label{cor:Shapley_mse_ratio_replace}
    Let $\bm{\phi}^*$ denote the true Shapley value vector and $\alpha$ as in \cref{thm:shapley_regression}.
    Given $\lambda \in \mathbb{R}$, define $\bm{b}_\lambda$ as in \cref{thm:main}.
    For $i = 1, 2$, given $m \in \mathbb{N}$ samples from the sampling distribution $\mathcal{P}_i$, denote $\bm{\phi}^{\textup{M}}_\lambda(\mathcal{P}_i)$ and $\bm{\phi}^{\textup{R}}_\lambda(\mathcal{P}_i)$ to be the matrix multiplication estimator and regression estimator, respectively.
    Then, for all $\lambda \in \mathbb{R}$, we have the following results.
    \begin{enumerate}
        \item (\textbf{Matrix multiplication})
        \begin{equation}
            \frac{\mathbb{E}[\|\bm{\phi}^{\textup{M}}_\lambda(\mathcal{P}_1) - \bm{\phi}^*\|^2]}{\mathbb{E}[\|\bm{\phi}^{\textup{M}}_\lambda(\mathcal{P}_2) - \bm{\phi}^*\|^2]} = \frac{\gamma_1(\bm{b}_\lambda) - \norm{\bm{\phi}^* - \alpha \bm{1}}^2}{\gamma_2(\bm{b}_\lambda) - \norm{\bm{\phi}^* - \alpha \bm{1}}^2}. \label{eqn:Shapley_matmult_mse_ratio_replace}
        \end{equation}
        \item (\textbf{Regression}) If for $i = 1, 2$, $\mathbb{E}[\|\bm{\phi}^{\textup{R}}_\lambda(\mathcal{P}_i) - \bm{\phi}^*\|^2] \neq 0$ and
        \begin{equation}
            \frac{\sqrt{\mathbb{E}[\|\bm{\phi}^{\textup{R}}_\lambda(\mathcal{P}_i) - \bm{\phi}^*\|^4]}}{\mathbb{E}[\|\bm{\phi}^{\textup{R}}_\lambda(\mathcal{P}_i) - \bm{\phi}^*\|^2]} = O(1), \label{eqn:Shapley_reg_mse_assumption}
        \end{equation}
        we have
        \begin{equation}
             \frac{\mathbb{E}[\|\bm{\phi}^{\textup{R}}_\lambda(\mathcal{P}_1) - \bm{\phi}^*\|^2]}{\mathbb{E}[\|\bm{\phi}^{\textup{R}}_\lambda(\mathcal{P}_2) - \bm{\phi}^*\|^2]} = \left(1 \pm O\left(\frac{1}{\sqrt{m}}\right)\right) \frac{\gamma_1(\bm{P}_{\bm{U}} \bm{b}_\lambda)}{\gamma_2(\bm{P}_{\bm{U}} \bm{b}_\lambda)}. \label{eqn:Shapley_regression_mse_ratio_replace}
        \end{equation}
    \end{enumerate}
\end{corollary}
\begin{proof}
    Denote $\bm{S}$ to be $m \times 2^d - 2$ sketching matrix obtained by sampling with replacement according to appropriate sampling probability.
    Let $\bm{U}$ and $\bm{Q}$ be defined as in \cref{thm:shapley_regression}.

    1. From \cref{eqn:Shapley_matmult_replace_error}, we know that $\norm{\bm{\phi}^{\textup{M}}_\lambda - \bm{\phi}^*} = \norm{\bm{U}^\T \bm{S}^\T \bm{S} \bm{b}_\lambda - \bm{U}^\T \bm{b}_\lambda}$.
    Furthermore, from \cref{thm:shapley_regression}, we have $\norm{\bm{U}^\T \bm{b}_\lambda} = \norm{\bm{Q} \bm{U}^\T \bm{b}_\lambda} = \norm{\bm{\phi}^* - \alpha \bm{1}}$.
    Then, the result follows from \cref{thm:mse_ratio_replace}.

    2. From \cref{eqn:Shapley_regression_replace_error}, we have $\norm{\bm{\phi}^{\textup{R}}_\lambda - \bm{\phi}^*} = \norm{(\bm{S} \bm{U})^+ \bm{S} \bm{b}_\lambda - \bm{U}^\T \bm{b}_\lambda} = \min_{\bm{y}} \norm{\bm{S} \bm{U} \bm{y} - \bm{S} \bm{b}_\lambda}$.
    Then, the result follows from \cref{thm:mse_ratio_replace}.
\end{proof}

The results of this section shows that while the theoretical guarantees derived in \cref{thm:main} only give upper bounds on the sample complexity,
the quantity $\gamma$ appearing in this theorem in fact determines the finite-sample/asymptotic behavior of the mean squared errors, as shown in \cref{cor:Shapley_mse_ratio_replace}.
Therefore, as long as our metric of performance is the mean squared error, we can directly compare the performance of different sampling schemes by comparing the corresponding values of $\gamma$.

\section{Adversarial example}
\label{app:adversarial_example}
In this section, we develop an adversarial example that help us separate the performance (in terms of the mean squared error) of $\ell_2$-squared sampling, kernel weight sampling, and modified $\ell_2$ sampling.
The main intuition for construction such adversarial examples comes from \cref{cor:gamma_comparison} and \cref{cor:Shapley_mse_ratio_replace}, where we compare the value of $\gamma(\bm{z})$ (see \cref{eqn:gamma_eta_def}) for different sampling strategies.
The vector $\bm{z}$ is either equal to $\bm{b}_\lambda$ or $(\bm{I} - \bm{U} \bm{U}^T) \bm{b}_\lambda$ as in \cref{thm:main}.
For ease of comparison, in our adversarial example, we will construct a model for which $\bm{b}_\lambda = (\bm{I} - \bm{U} \bm{U}^T) \bm{b}_\lambda$, and the lower bounds in \cref{cor:gamma_comparison} are saturated up to constant factors.
For simplicity, we fix $\lambda = (v([d]) - v(\emptyset)) / d = \alpha$, as done in previous studies~\cite{lundberg2017unified, musco2025provably}.

We now construct an example for which we can provably show better theoretical guarantees for modified $\ell_2$ sampling and kernel weight sampling compared to $\ell_2$-squared sampling.
To that end, define the function $f\colon \mathbb{R}^d \to \mathbb{R}$, which is our model acting on $d$-dimensional input data, as $f(x) = g(\sum_{i = 1}^d h(x_i))$, where $g$ and $h$ are real-valued functions to be chosen below.
While there is a reasonable freedom in defining the functions $h$ and $g$,
we choose these judiciously to allows us to theoretically compute the Shapley values.
Given a parameter $\epsilon_0 \in (0, 1)$, we define
\begin{equation}
    h(x) = \begin{cases}
               1            & \textnormal{ if } x > \epsilon_0 \\
               0            & \textnormal{ otherwise}.
           \end{cases} \label{eqn:adversary_h}
\end{equation}
On the other hand, given parameters $n \in \mathbb{N}$ (independent of $d$) and $\xi, \chi \in \mathbb{R}$, we define $g\colon \mathbb{R} \to \mathbb{R}$ as
\begin{equation}
    g(x) = \begin{cases}
               \xi \left(\frac{x}{d}\right)^2 + \chi x  & \textnormal{ if } 1 \leq x \leq n \textnormal{ or } d - n \leq x \leq d - 1 \\
               \chi x                        & \textnormal{ otherwise}.
           \end{cases} \label{eqn:adversary_g}
\end{equation}

Then, we have the following result.
\begin{proposition}
    \label{prop:adversarial_model}
    For the model $f(\bm{x}) = g(\sum_{i = 1}^d h(x_i))$, where $h$ is given in \cref{eqn:adversary_h} and $g$ is given in \cref{eqn:adversary_g}, baseline $\bm{y} = \bm{0}$, and explicand $\bm{x} = \bm{1}$, we have
    $\bm{\phi}^* = \chi \bm{1}$ and
    \begin{equation}
    \begin{aligned}
        \gamma_{\ell_2^2}((\bm{I} - \bm{U} \bm{U}^\T) \bm{b}_\lambda) &= \gamma_{\ell_2^2}(\bm{b}_\lambda) = \Theta(d) \\
        \gamma_{\textnormal{ker}}((\bm{I} - \bm{U} \bm{U}^\T) \bm{b}_\lambda) &= \gamma_{\textnormal{ker}}(\bm{b}_\lambda) = \Theta(\log(d)) \\
        \gamma_{\textnormal{m-}\ell_2}((\bm{I} - \bm{U} \bm{U}^\T) \bm{b}_\lambda) &= \gamma_{\textnormal{m-}\ell_2}(\bm{b}_\lambda) = \Theta(\sqrt{d}).
    \end{aligned}
    \end{equation}
\end{proposition}
\begin{proof}
    First, we compute $\bm{b}_\lambda$ and show that $(\bm{I} - \bm{U} \bm{U}^\T) \bm{b}_\lambda = \bm{b}_\lambda$.
    For a given subset $S$ of $[d]$, define $\bm{x}^S \in \mathbb{R}^d$ as $x^S_i = x_i$ if $i \in S$ and $x^S_i = y_i$ if $y \notin S$.
    Then, from the definition of $f$, it follows that for all $S \subseteq [d]$, we have $v(S) = f(\bm{x}^S) = g(|S|)$.
    By construction, we have $v([d]) = \chi d$ and $v(\emptyset) = 0$.
    Since $v(S)$ depends only on the size of the subset $S$, by \cref{Eq:shapley-value}, we have that $\bm{\phi}^* = \phi_0 \bm{1}$ for some constant $\phi_0^* \in \mathbb{R}$.
    Then, the constraint $\bm{1}^T \bm{\phi}^* = v([d]) - v(\emptyset)$ gives $\phi_0^* = (v[d] - v(\emptyset)) / d = \chi$.
    Thus, for this example, we have $\lambda = \alpha = \chi$.
    Since $\bm{\phi}^* = \chi \bm{1} = \alpha \bm{1}$, from \cref{thm:shapley_regression}, we have $\bm{Q} \bm{U}^\T \bm{b}_\lambda = \bm{0}$, and therefore, $\bm{U} \bm{U}^\T \bm{b}_\lambda = (\bm{U} \bm{Q}^\T) (\bm{Q} \bm{U}^\T) \bm{b}_\lambda = \bm{0}$.
    It follows that $(\bm{I} - \bm{U} \bm{U}^T) \bm{b}_\lambda = \bm{b}_\lambda$.

    Next, we compute $\norm*{\bm{b}_\lambda}^2$, $\norm{\bm{H} \bm{b}_\lambda}^2$, and $\norm{\sqrt{\bm{H}} \bm{b}_\lambda}^2$ (see \cref{cor:gamma_eta_sampling_schemes_simplified}).
    Since $v$ depends only on the size of the subset and $\lambda = \chi$, we obtain
    \begin{equation}
        \norm{\bm{b}_\lambda}^2 = \frac{d}{d - 1} \sum_{h = 1}^{d - 1} \frac{d - 1}{h (d - h)} (g(h) - \lambda h)^2 = \frac{\xi^2}{d^3} \paren*{\sum_{h = 1}^n \frac{h^3}{d - h} + \sum_{h = d - n}^{d - 1} \frac{h^3}{d - h}} = \Theta(1)
    \end{equation}
    since $n$ is a constant independent of $d$.
    Similarly, we have
    \begin{equation}
        \norm{\bm{H} \bm{b}_\lambda}^2 = \frac{d}{d - 1} \sum_{h = 1}^{d - 1} \frac{d - 1}{h (d - h)} \frac{h (d - h)}{d^2} (g(h) - \lambda h)^2 = \frac{\xi^2}{d^5} \paren*{\sum_{h = 1}^n h^4 + \sum_{h = d - n}^{d - 1} h^4} = \Theta\paren*{\frac{1}{d}}.
    \end{equation}
    We also have
    \begin{equation}
    \begin{aligned}
        \norm{\sqrt{\bm{H}} \bm{b}_\lambda}^2 &= \frac{d}{d - 1} \sum_{h = 1}^{d - 1} \frac{d - 1}{h (d - h)} \frac{\sqrt{h (d - h)}}{d} (g(h) - \lambda h)^2 \\
                                             &= \frac{\xi^2}{d^4} \paren*{\sum_{h = 1}^n \frac{h^{3.5}}{\sqrt{d - h}} + \sum_{h = d - n}^{d - 1} \frac{h^{3.5}}{\sqrt{d - h}}} = \Theta\paren*{\frac{1}{\sqrt{d}}}.
    \end{aligned}
    \end{equation}

    Therefore, by \cref{cor:gamma_eta_sampling_schemes_simplified}, we have
    \begin{equation}
    \begin{aligned}
       \gamma_{\ell_2^2}(\bm{b}_\lambda) &= \Theta(d \norm*{\bm{b}_\lambda}^2) = \Theta(d), \\
       \gamma_{\textnormal{ker}}(\bm{b}_\lambda) &= \Theta(d \log(d) \norm{\bm{H} \bm{b}_\lambda}^2) = \Theta(\log(d)), \\
       \gamma_{\textnormal{m-}\ell_2}(\bm{b}_\lambda) &= \Theta(d \norm{\sqrt{\bm{H}} \bm{b}_\lambda}^2) = \Theta(\sqrt{d}).
    \end{aligned}
    \end{equation}
\end{proof}

We remark that the adversarial model constructed in this section is a specific toy example meant to illustrate the advantage of modified $\ell_2$ and kernel sampling.
One can construct many such adversarial examples for which modified $\ell_2$ and kernel gives better performance than both leverage scores.
We can now translate these results into statements concerning the mean squared error for the different sampling schemes.
\begin{corollary}
    \label{cor:adversarial_mse_ratio}
    Denote $\mathcal{P}_{\ell_2^2}$, $\mathcal{P}_{\textnormal{ker}}$, and $\mathcal{P}_{\textnormal{m-}\ell_2}$ to be the sampling distributions for $\ell_2^2$-squared, kernel, and modified $\ell_2$ weights, respectively.
    Then, for the model $f(\bm{x}) = g(\sum_{i = 1}^d h(x_i))$, where $h$ is given in \cref{eqn:adversary_h} and $g$ is given in \cref{eqn:adversary_g}, baseline $\bm{y} = \bm{0}$, and explicand $\bm{x} = \bm{1}$, we have (using $m$ samples, drawn with replacement)
    \begin{equation}
    \begin{aligned}
        &\frac{\mathbb{E}[\|\bm{\phi}^{\textup{M}}_\lambda(\mathcal{P}_{\ell_2^2}) - \bm{\phi}^*\|^2]}{\mathbb{E}[\|\bm{\phi}^{\textup{M}}_\lambda(\mathcal{P}_{\textnormal{ker}}) - \bm{\phi}^*\|^2]} = \frac{\gamma_{\ell_2^2}(\bm{b}_\lambda)}{\gamma_{\textnormal{ker}}(\bm{b}_\lambda)} = \Theta\paren*{\frac{d}{\log(d)}}, \\
        &\frac{\mathbb{E}[\|\bm{\phi}^{\textup{M}}_\lambda(\mathcal{P}_{\textnormal{m-}\ell_2}) - \bm{\phi}^*\|^2]}{\mathbb{E}[\|\bm{\phi}^{\textup{M}}_\lambda(\mathcal{P}_{\textnormal{ker}}) - \bm{\phi}^*\|^2]} = \frac{\gamma_{\textnormal{m-}\ell_2}(\bm{b}_\lambda)}{\gamma_{\textnormal{ker}}(\bm{b}_\lambda)} = \Theta\paren*{\frac{\sqrt{d}}{\log(d)}}, \\
        &\frac{\mathbb{E}[\|\bm{\phi}^{\textup{M}}_\lambda(\mathcal{P}_{\ell_2^2}) - \bm{\phi}^*\|^2]}{\mathbb{E}[\|\bm{\phi}^{\textup{M}}_\lambda(\mathcal{P}_{\textnormal{m-}\ell_2}) - \bm{\phi}^*\|^2]} = \frac{\gamma_{\textnormal{m-}\ell_2}(\bm{b}_\lambda)}{\gamma_{\textnormal{ker}}(\bm{b}_\lambda)} = \Theta\paren*{\sqrt{d}}, \\
        &\frac{\mathbb{E}[\|\bm{\phi}^{\textup{R}}_\lambda(\mathcal{P}_{\ell_2^2}) - \bm{\phi}^*\|^2]}{\mathbb{E}[\|\bm{\phi}^{\textup{R}}_\lambda(\mathcal{P}_{\textnormal{ker}}) - \bm{\phi}^*\|^2]} \approx \frac{\gamma_{\ell_2^2}(\bm{b}_\lambda)}{\gamma_{\textnormal{ker}}(\bm{b}_\lambda)} = \Theta\paren*{\frac{d}{\log(d)}} \quad \textnormal{ for large enough } m, \\
        &\frac{\mathbb{E}[\|\bm{\phi}^{\textup{R}}_\lambda(\mathcal{P}_{\textnormal{m-}\ell_2}) - \bm{\phi}^*\|^2]}{\mathbb{E}[\|\bm{\phi}^{\textup{R}}_\lambda(\mathcal{P}_{\textnormal{ker}}) - \bm{\phi}^*\|^2]} \approx \frac{\gamma_{\textnormal{m-}\ell_2}(\bm{b}_\lambda)}{\gamma_{\textnormal{ker}}(\bm{b}_\lambda)} = \Theta\paren*{\frac{\sqrt{d}}{\log(d)}} \quad \textnormal{ for large enough } m, \\
        &\frac{\mathbb{E}[\|\bm{\phi}^{\textup{R}}_\lambda(\mathcal{P}_{\ell_2^2}) - \bm{\phi}^*\|^2]}{\mathbb{E}[\|\bm{\phi}^{\textup{R}}_\lambda(\mathcal{P}_{\textnormal{m-}\ell_2}) - \bm{\phi}^*\|^2]} \approx \frac{\gamma_{\ell_2^2}(\bm{b}_\lambda)}{\gamma_{\textnormal{ker}}(\bm{b}_\lambda)} = \Theta\paren*{\sqrt{d}} \quad \textnormal{ for large enough } m.
    \end{aligned}
    \end{equation}
    The expressions for the ratio of mean squared errors for the regression estimator hold under the technical assumption \cref{eqn:Shapley_reg_mse_assumption} stated in \cref{cor:Shapley_mse_ratio_replace}.
\end{corollary}
\begin{proof}
    This follows by directly substituting the results of \cref{prop:adversarial_model} in \cref{cor:Shapley_mse_ratio_replace}.
\end{proof}
This example shows that modified $\ell_2$ gives an advantage over leverage scores by a factor of $\sqrt{d}$.
On the other hand, kernel weights give a factor of $d/\log(d)$ advantage over leverage scores, while a factor of $\sqrt{d}/\log(d)$ advantage over modified $\ell_2$.
These saturate the lower bounds in \cref{cor:gamma_comparison}.
Since we have the analytical expressions for $\gamma$ for the adversarial example studied in this section, in \cref{fig:adversarial_example}, we plot the ratio of $\gamma$ for different the sampling distributions using these expressions.

