	\centering
	\input{figures/plots/dna-storage-traces}
	\caption{Performance of the \gls{npd} when decoding blocks of $128$ DNA symbols. Results are shown as a function of the number of observed traces. Each point represents $10{,}000$ Monte Carlo samples. The column labeled $K$ shows results for $K \sim \operatorname{Poisson}(5)$.}
	\label{fig:dna-traces}
