    \sigma(A_{i,j}) \times AvgP(O_{i}[t],\frac{D(O_{i}[t])}{D(I_j[t])} ),
    \label{eq: I_j[t]}
\end{align}%
\noindent where the $AvgP(O_{i}[t],\frac{D(O_{i}[t])}{D(I_j[t])} )$ denotes the average pooling that will be used for $O_{i}[t]$ with a kernel size of $\frac{D(O_{i}[t])}{D(I_j[t])} $.
