\propitemf{\propone}{\yes} 
For the two nets $W_1^{\name}$ and $W_2^{\name}$ of Figure~\ref{fig:size-examples}, we get the complexity scores $\C(W_1^{\name}) = 3 \neq 5 = \C(W_2^{\name})$.

\propitemf{\proptwo}{\yes} 
Let $c \in \mathbb{R}$.
There are only finitely many workflow nets with complexity $c$: 
Suppose we have a directed graph $G = (V,E)$ with $|V| = c$. 
Then, $|E| \leq c^2$, since all nodes may be connected to all other nodes.
If we want to choose only some of these edges, we get $\sum_{i = 0}^{c^2} \binom{c^2}{i} = 2^{c^2}$ possible edge sets $E$.
Not all graphs that we can construct in this way can be converted to workflow nets, but every workflow net of size $c$ can be interpreted as such a graph.
Therefore, $|\{M \in \mathcal{M} \mid \C(M) = c\}| < 2^{c^2} < \infty$.

\propitemf{\propthree}{\yes} 
The workflow nets $W_2^{\name}$ and $W_3^{\name}$ of Figure~\ref{fig:size-examples} are different in structure, but both get the complexity score $\C(W_2^{\name}) = 5 = \C(W_3^{\name})$.

\propitemf{\propfour}{\yes} 
Take the workflow nets $W_1^{\name}$ and $W_2^{\name}$ of Figure~\ref{fig:size-examples}. 
Their languages are $L(W_1^{\name}) = \{\varepsilon, a\} = L(W_2^{\name})$, but their complexity scores are $\C(W_1^{\name}) = 3 \neq 5 = \C(W_2^{\name})$.

\propitemf{\propfive}{\yes} 
For this claim, we use the following Theorem:
\begin{theorem}
\label{thm:size}
Let $n \geq 2$. For any workflow nets $M_1, \dots, M_n \in \mathcal{M}$, we get:
\begin{itemize}
\item $\C(\seqop(M_1, \dots, M_n)) = \C(M_1) + \dots + \C(M_n) + n-1$,
\item $\C(\parop(M_1, \dots, M_n)) = \C(M_1) + \dots + \C(M_n) + 4$,
\item $\C(\choiceop(M_1, \dots, M_n)) = \C(M_1) + \dots + \C(M_n) + 2n+2$ and
\item $\C(\loopop(M_1, \dots, M_n)) = \C(M_1) + \dots + \C(M_n) + 2n+6$.
\end{itemize}
\end{theorem}
\begin{proof}
Follows directly from Definition~\ref{def:operations}. \hfill $\square$
\end{proof}
With Theorem~\ref{thm:size}, we immediately get that 
\[\C(\oplus(M_1, \dots, M_n)) = \C(M_1) + \dots + \C(M_n) + k\]
for $\oplus \in \{\seqop, \parop, \choiceop, \loopop\}$ and some $k > 0$. 
Therefore, we can deduce that for any $M_i \in \{M_1, \dots, M_n\}$ we have:
\[\C(\oplus(M_1, \dots, M_n)) \geq \C(M_i).\]

\propitemf{\propsix}{\no}
Let $M_1, M_2, M_3 \in \mathcal{M}$ be three arbitrary workflow nets, where $\C(M_1) = \C(M_2)$.
Theorem~\ref{thm:size} gives:
\begin{itemize}
\item $\C(M_1 \seqop M_3) = \C(M_1) + \C(M_3) + 1$ \\
\phantom{$\C(M_1\seqop M_3)$ }$= \C(M_2) + \C(M_3) + 1 = \C(M_2 \seqop M_3)$,
\item $\C(M_1 \parop M_3) = \C(M_1) + \C(M_3) + 4$ \\
\phantom{$\C(M_1 \parop M_3)$ }$= \C(M_2) + \C(M_3) + 4 = \C(M_2 \parop M_3)$,
\item $\C(M_1 \choiceop M_3) = \C(M_1) + \C(M_3) + 6$ \\
\phantom{$\C(M_1 \choiceop M_3)$ }$= \C(M_2) + \C(M_3) + 6 = \C(M_2 \choiceop M_3)$ and
\item $\C(M_1 \loopop M_3) = \C(M_1) + \C(M_3) + 10$ \\
\phantom{$\C(M_1 \loopop M_3)$ }$= \C(M_2) + \C(M_3) + 10 = \C(M_2 \loopop M_3)$.
\end{itemize}
Thus, none of the operations of Definition~\ref{def:operations} are sensitive to compositions.

