\propitemf{\propnine}{\no}
Let $M_1 = (P_1, T_1, F_1, p_i^1, p_o^1)$ and $M_2 = (P_2, T_2, F_2, p_i^2, p_o^2)$ be workflow nets and let $M = M_1 \oplus M_2$ for some $\oplus \in \{\seqop, \parop, \choiceop, \loopop\}$.
We get:
\begin{align*}
MM_{\text{and}}^M &= \left| \sum_{t \in \mathcal{S}_{\text{and}}^M} |\post{t}| - \sum_{t \in \mathcal{J}_{\text{and}}^M} |\pre{t}| \right| \\
&= \left| \sum_{t \in \mathcal{S}_{\text{and}}^{M_1} \cup \mathcal{S}_{\text{and}}^{M_2}} |\post{t}| - \sum_{t \in \mathcal{J}_{\text{and}}^{M_1} \cup \mathcal{J}_{\text{and}}^{M_2}} |\pre{t}| \right| \\
&\leq \left| \sum_{t \in \mathcal{S}_{\text{and}}^{M_1}} |\post{t}| - \sum_{t \in \mathcal{J}_{\text{and}}^{M_1}} |\pre{t}| \right| +  \left| \sum_{t \in \mathcal{S}_{\text{and}}^{M_2}} |\post{t}| - \sum_{t \in \mathcal{J}_{\text{and}}^{M_2}} |\pre{t}| \right| \\
&= MM_{\text{and}}^{M_1} + MM_{\text{and}}^{M_2}
\end{align*}
where the second equality is due to the fact that $T_1 \cap T_2 = \emptyset$ by definition.
Analogously, we get $MM_{\text{xor}}^M \leq MM_{\text{xor}}^{M_1} + MM_{\text{xor}}^{M_2}$ and therefore
\begin{align*}
\C(W) &= MM_{\text{and}}^M + MM_{\text{xor}}^M \\
&\leq (MM_{\text{and}}^{M_1} + MM_{\text{and}}^{M_2}) + (MM_{\text{xor}}^{M_1} + MM_{\text{xor}}^{M_2}) \\
&= (MM_{\text{and}}^{M_1} + MM_{\text{xor}}^{M_1}) + (MM_{\text{and}}^{M_2} + MM_{\text{xor}}^{M_2}) \\
&= \C(M_1) + \C(M_2).
\end{align*}

\propitemf{\propdef}{\yes} 
Since $\mathcal{S}_{\text{and}}^W$, $\mathcal{S}_{\text{xor}}^W$, $\mathcal{J}_{\text{and}}^W$, $\mathcal{J}_{\text{xor}}^W$ are defined for all workflow nets $W \in \mathcal{M}$, $\C(W)$ is also defined for all such workflow nets.
Furthermore, since we sum only over absolute values to compute $\C(W)$, we get $\C(W) \geq 0$ for all workflow nets $W \in \mathcal{M}$.

\propitemf{\propmin}{\yes} The minimum for this metric is $0$.
A workflow net without any connectors, like $\netminwf$ of Figure~\ref{fig:netminwf}, receives this complexity score.

\propitemf{\propinf}{\yes} 
For any $c \in \mathbb{N}$, Figure~\ref{fig:mm-fin} shows how to construct a workflow net with complexity score $2c + 2$. 
Therefore, there are infinitely many possible complexity scores: \\
$|\{c \in \mathbb{R} \mid \exists M \in \mathcal{M}: \C(M) = c\}| \geq |\{n \in \mathbb{N} \mid \exists c \in \mathbb{N}: n = 2c + 2\}| = \infty$.

\propitemf{\propnotsup}{\yes} 
Consider again the workflow nets $W_2^{\name}$ and $W_3^{\name}$ in Figure~\ref{fig:mm-examples}.
Since none of the operations $\oplus \in \{\seqop, \parop, \choiceop, \loopop\}$ introduce new connector mismatches, we get $\C(W_2^{\name} \oplus W_3^{\name}) = 0 < 8 = \C(W_2^{\name}) + \C(W_3^{\name})$.

\propitemf{\propadd}{\no} 
We can use the same counter-example as for the property {\propnotsup} to see that $\C$ is not additive.
\end{description}



\def\name{\connhetname}
\def\C{\connhet}
\subsubsection{Connector Heterogeneity}
According to Mendling~\cite[pp.126-127]{Men08}, an EPC model that contains many connector types is more prone to errors, since it is more likely to contain a connector mismatch.
He therefore introduces the connector heterogeneity metric, which calculates the entropy of connectors in the model.
Since we don't have designated connectors for inclusive choices, we only calculate the entropy of concurrent and exclusive choice connectors.
Let $W = (P,T,F,\ell,p_i,p_o)$ be a workflow net.
\begin{equation}
\label{eq:c-heterogeneity}
\C(W) = - \left(\frac{|\mathcal{C}_{\text{and}}^W|}{|\mathcal{C}^W|} \cdot \log_2\left(\frac{|\mathcal{C}_{\text{and}}^W|}{|\mathcal{C}^W|}\right) + \frac{|\mathcal{C}_{\text{xor}}^W|}{|\mathcal{C}^W|} \cdot \log_2\left(\frac{|\mathcal{C}_{\text{xor}}^W|}{|\mathcal{C}^W|}\right)\right)
\end{equation}
A value near $0$ means that there are only connectors of one type present in the net, while a value near $1$ means that we have equally many parallel and choice connectors.
