\phantom{$\C(M_1 \seqop M_3)$ }$= \C(M_2) + \C(M_3) = C(M_2 \seqop M_3)$,
\item $\C(M_1 \parop M_3) = \C(M_1) + \C(M_3) + n-1$ \\
\phantom{$\C(M_1 \parop M_3)$ }$= \C(M_2) + \C(M_3) + n-1 = C(M_2 \parop M_3)$,
\item $\C(M_1 \choiceop M_3) = \C(M_1) + \C(M_3)$ \\
\phantom{$\C(M_1 \choiceop M_3)$ }$= \C(M_2) + \C(M_3) = C(M_2 \choiceop M_3)$ and
\item $\C(M_1 \loopop M_3) = \C(M_1) + \C(M_3)$ \\
\phantom{$\C(M_1 \loopop M_3)$ }$= \C(M_2) + \C(M_3) = C(M_2 \loopop M_3)$.
\end{itemize}
Therefore, $\C(M_1 \oplus M_3) = \C(M_2 \oplus M_3)$ for any $\oplus \in \{\seqop, \parop, \choiceop, \loopop\}$.

