\phantom{$\C(M_1 \seqop M_3)$ }$= \C(M_2) + \C(M_3) = \C(M_1 \seqop M_3)$,
\item $\C(M_1 \parop M_3) = \C(M_1) + \C(M_3) + 1$ \\
