\item $\C(M_1 \choiceop M_3) = \C(M_1) + \C(M_3) + n$ \\
\phantom{$\C(M_1 \choiceop M_3)$ }$= \C(M_2) + \C(M_3) + n = \C(M_1 \choiceop M_3)$,
\item $\C(M_1 \loopop M_3) = \C(M_1) + \C(M_3) + n$ \\
