\phantom{$\C(M_1 \parop M_3)$ }$= \C(M_2 \parop M_3)$,
\item $\C(M_1 \choiceop M_3) = 1 + \max \{\C(M_1),\C(M_3)\}$\\
\phantom{$\C(M_1 \choiceop M_3)$ }$= 1 + \max \{\C(M_2),\C(M_3)\}$\\ 
\phantom{$\C(M_1 \choiceop M_3)$ }$= \C(M_2 \choiceop M_3)$,
\item $\C(M_1 \loopop M_3) = \max \{\C(M_1),\C(M_3) + 1\}$\\
\phantom{$\C(M_1 \loopop M_3)$ }$= \max \{\C(M_2),\C(M_3) + 1\}$\\ 
\phantom{$\C(M_1 \loopop M_3)$ }$= \C(M_2 \parop M_3)$.
\end{itemize}
