\phantom{$\C(M_1 \choiceop M_3)$ }$= 4 + \max\{\C(M_2),\C(M_3)\} = \C(M_2 \choiceop M_3)$,
\item $\C(M_1 \loopop M_3) = 8 + \C(M_1)$\\
\phantom{$\C(M_1 \loopop M_3)$ }$= 8 + \C(M_2) = \C(M_2 \loopop M_3)$.
\end{itemize}

