\begin{theorem}
\label{thm:cnc-sub-seq}
Let $G_1$ be a graph with $n_1$ nodes and $m_1 \geq n_1 - 1$ edges, $G_2$ be a graph with $n_2$ nodes and $m_2 \geq n_2 - 1$ edges, and $G$ be a graph with $n = n_1 + n_2 + 1$ nodes and $m = m_1 + m_2 + 2$ edges.
Then, $\frac{m_1}{n_1} + \frac{m_2}{n_2} > \frac{m}{n}$.
\end{theorem}
\begin{proof}
\begin{align*}
&\frac{m_1}{n_1} + \frac{m_2}{n_2} > \frac{m_1 + m_2 + 2}{n_1 + n_2 + 1} \\
\Leftrightarrow &(m_1 n_1 + m_2 n_1) \cdot (n_1 + n_2 + 1) > (m_1 + m_2 + 2) \cdot (n_1 n_2) \\
\Leftrightarrow &\underbrace{m_1 n_2^2}_{> n_2} + \underbrace{m_2 n_1^2}_{> n_1} + \underbrace{m_1}_{\geq n_1 - 1} n_2 + \underbrace{m_2}_{\geq n_2 - 1} n_1 > 2 n_1 n_2
\end{align*}
\qed
\end{proof}
Theorem~\ref{thm:cnc-sub-seq} directly implies that $\C$ is subadditive for $\seqop$.
\begin{theorem}
\label{thm:cnc-sub}
Let $G_1$ be a graph with $n_1 \geq 3$ nodes and $m_1 \geq n_1 - 1$ edges, $G_2$ be a graph with $n_2 \geq 3$ nodes and $m_2 \geq n_2 - 1$ edges, and $G$ be a graph with $n = n_1 + n_2 + k$ nodes and $m = m_1 + m_2 + k + 2$ edges for $k \in \{4, 6, 10\}$.
Then, $\frac{m_1}{n_1} + \frac{m_2}{n_2} > \frac{m}{n}$.
\end{theorem}
\begin{proof}
\begin{align*}
&\frac{m_1}{n_1} + \frac{m_2}{n_2} > \frac{m_1 + m_2 + k + 2}{n_1 + n_2 + k} \\
\Leftrightarrow &\underbrace{m_1 n_2^2}_{\geq 6 n_2 (*)} + k \underbrace{m_1}_{\geq n_1 - 1} n_2 + \underbrace{m_2 n_1^2}_{\geq 6 n_1 (*)} + k \underbrace{m_1}_{\geq n_2 - 1} n_1 > (k + 2) n_1 n_2 \\
\end{align*}
Where $(*)$ is true because $n_1, n_2 \geq 3$ and $m_1, m_2 \geq 2$.
The lower inequality is true since
\begin{align*}
&k(n_1 - 1)n_2 + 6n_1 + k(n_2 - 1)n_1 + 6n_2 \\
=\hspace*{1mm} &2k n_1 n_2 - (k - 6)n_1 - (k - 6)n_2 \\
>\hspace*{1mm} &(2k - 2(k - 6))n_1 n_2 \\
=\hspace*{1mm} &12 n_1 n_2 \\
\overset{k \leq 10}{\geq} &(k + 2)n_1 n_2 
\end{align*}
\qed
\end{proof}

\propitemf{\propdef}{\yes} 
The coefficient of network connectivity is defined for all workflow nets, since by definition $|P| \geq 2$ and $|T| \geq 1$ in every workflow net. 
Furthermore, $|F| \geq 0$, so the measure returns only non-negative values.

