Theorem~\ref{thm:empty-add} gives:
\begin{itemize}
\item $\C(M_1 \seqop M_3) = \C(M_1) + \C(M_3)$ \\
\phantom{$\C(M_1 \seqop M_3)$ }$= \C(M_2) + \C(M_3) = \C(M_2 \seqop M_3)$,
\item $\C(M_1 \parop M_3) = \C(M_1) + \C(M_3)$ \\
\phantom{$\C(M_1 \parop M_3)$ }$= \C(M_2) + \C(M_3) = \C(M_2 \parop M_3)$,
\item $\C(M_1 \choiceop M_3) = \C(M_1) + \C(M_3)$ \\
\phantom{$\C(M_1 \choiceop M_3)$ }$= \C(M_2) + \C(M_3) = \C(M_2 \choiceop M_3)$,
\item $\C(M_1 \loopop M_3) = \C(M_1) + \C(M_3)$ \\
\phantom{$\C(M_1 \loopop M_3)$ }$= \C(M_2) + \C(M_3) = \C(M_2 \loopop M_3)$.
\end{itemize}

