\title{Language Models for Novelty Detection in System Call Traces}

\author{\IEEEauthorblockN{Quentin Fournier}
	\IEEEauthorblockA{\textit{Polytechnique Montreal} \\
		Montreal, Quebec H3T 1J4 \\
	quentin.fournier@polymtl.ca}
	\and
	\IEEEauthorblockN{Daniel Aloise}
	\IEEEauthorblockA{\textit{Polytechnique Montreal} \\
